    [Fact]
    public void RunDefaultsRoundTripAcrossBodyHeaderAndFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(new RunPropertiesDefault(
                new RunPropertiesBaseStyle(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new Bold(), new Color { Val = "336699" },
                    new Spacing { Val = 20 }, new FontSize { Val = "22" },
                    new Languages { Val = "en-CA" }))));
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new Run(new Text("Header default"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new Run(new Text("Footer default"))));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Body default"))),
                new SectionProperties(new HeaderReference
                { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header) },
                    new FooterReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var normal = Assert.Single(index.StyleDefinitions, x => x.Index == 0);
            Assert.True(normal.CharacterFormatting.Bold);
            Assert.Equal((ushort)22, normal.CharacterFormatting.SizeHalfPoints);
            Assert.Equal(0x00996633u, normal.CharacterFormatting.ColorRef);
            Assert.Equal((short)20, normal.CharacterFormatting.CharacterSpacingTwips);
            Assert.Equal((ushort)4105, normal.CharacterFormatting.LanguageId);
        }
        var projected = DxpDocToDocx.Project(binary);
        using (var stream = new MemoryStream(projected.DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var defaults = document.MainDocumentPart!.StyleDefinitionsPart!.Styles!
                .Elements<DocDefaults>().Single().Descendants<RunPropertiesBaseStyle>()
                .Single();
            Assert.True(defaults.GetFirstChild<Bold>()!.Val?.Value ?? true);
            Assert.Equal("336699", defaults.GetFirstChild<Color>()!.Val?.Value);
            Assert.Equal("22", defaults.GetFirstChild<FontSize>()!.Val?.Value);
            Assert.Equal(20, defaults.GetFirstChild<Spacing>()!.Val?.Value);
            Assert.Equal("en-CA", defaults.GetFirstChild<Languages>()!.Val?.Value);
            Assert.Single(document.MainDocumentPart.HeaderParts);
            Assert.Single(document.MainDocumentPart.FooterParts);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var output = Path.Combine(Path.GetTempPath(),
                $"docxport-run-defaults-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(output, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(output, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range.Font.Bold);
                Assert.NotEqual(0,
                    (int)opened.Sections(1).Headers(1).Range.Font.Bold);
                Assert.NotEqual(0,
                    (int)opened.Sections(1).Footers(1).Range.Font.Bold);
                Assert.Equal(1f, (float)opened.Paragraphs.Item(1).Range.Font.Spacing);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(output);
            }
        }
    }

    [Fact]
    public void WordLayeredParagraphAndCharacterStylesKeepDirectOverrideInStories()
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var sourceDoc = Path.Combine(directory, "WordStyleLayeredStories.doc");
        var sourceDocx = File.ReadAllBytes(Path.Combine(directory,
            "WordStyleLayeredStories.docx"));
        foreach (var binary in new[] { File.ReadAllBytes(sourceDoc),
            DxpDocExport.Export(sourceDocx) })
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                var baseStyle = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Visible Base");
                var derived = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Visible Derived");
                var accent = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Visible Accent");
                Assert.Equal(baseStyle.Index, derived.BasedOnIndex);
                Assert.True(derived.CharacterFormatting.Bold);
                Assert.True(derived.CharacterFormatting.Italic);
                Assert.True(accent.CharacterFormatting.Strike);
                Assert.Contains(index.CharacterFormatting, x =>
                    x.Formatting.CharacterStyleIndex == accent.Index &&
                    x.Formatting.Bold == false);
                Assert.Contains(index.ParagraphStyles, x => x.StyleIndex == derived.Index);
            }
            var projected = DxpDocToDocx.Project(binary);
            using var stream = new MemoryStream(projected.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var bodyRun = main.Document!.Body!.Descendants<Run>().First();
            Assert.False(bodyRun.RunProperties!.Bold!.Val!.Value);
            Assert.NotNull(bodyRun.RunProperties.RunStyle);
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Run>()
                .Any(r => r.RunProperties?.Bold?.Val?.Value == false));
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Run>()
                .Any(r => r.RunProperties?.RunStyle != null));
            var defaultSpacing = main.StyleDefinitionsPart!.Styles!
                .Elements<DocDefaults>().Single().Descendants<SpacingBetweenLines>()
                .Single();
            Assert.Equal("160", defaultSpacing.After?.Value);
            Assert.Equal("278", defaultSpacing.Line?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(document));
            var reexported = DxpDocExport.Export(projected.DocxBytes);
            using (var reopened = new MemoryStream(reexported))
            using (var index = new DocTextIndexWalker().Index(reopened))
            {
                var derived = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Visible Derived");
                Assert.True(derived.CharacterFormatting.Bold);
                Assert.True(derived.CharacterFormatting.Italic);
                Assert.Contains(index.CharacterFormatting, x => x.Formatting.Bold == false);
            }
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
            {
                var output = Path.Combine(Path.GetTempPath(),
                    $"docxport-layered-styles-{Guid.NewGuid():N}.doc");
                File.WriteAllBytes(output, binary);
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
                word.Visible = false;
                dynamic? opened = null;
                try
                {
                    opened = word.Documents.Open(output, ReadOnly: true,
                        AddToRecentFiles: false);
                    Assert.Equal(0, (int)opened.Paragraphs.Item(1).Range.Font.Bold);
                    Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range.Font.Italic);
                    Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range.Font.StrikeThrough);
                    Assert.Equal(0, (int)opened.Sections(1).Headers(1).Range.Font.Bold);
                    Assert.NotEqual(0, (int)opened.Sections(1).Footers(1).Range.Font.Bold);
                    Assert.Equal(8f,
                        (float)opened.Sections(1).Footers(1).Range.ParagraphFormat.SpaceAfter);
                }
                finally
                {
                    if (opened != null) opened.Close(false);
                    word.Quit();
                    File.Delete(output);
                }
            }
        }
    }

    [Fact]
    public void StyleMatchToggleKeepsInheritedBold()
    {
        // Derived from WordBoldStyleToggle.doc by changing its two 0x81 bold
        // operands to 0x80 without changing their CHPX record sizes.
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordBoldStyleMatch.doc"));
        using (var index = new DocTextIndexWalker().Index(path))
        {
            Assert.Contains(index.StyleDefinitions, x =>
                x.Name == "Normal" && x.CharacterFormatting.Bold == true);
            Assert.Contains(index.CharacterFormatting, x => x.Formatting.Bold == true);
            Assert.DoesNotContain(index.CharacterFormatting, x => x.Formatting.Bold == false);
        }
        var projection = DxpDocToDocx.Project(path);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var document = WordprocessingDocument.Open(stream, false);
        Assert.Empty(document.MainDocumentPart!.Document!.Body!
            .Descendants<Bold>().Where(x => x.Val?.Value == false));
        Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range.Font.Bold);
                Assert.NotEqual(0, (int)opened.Paragraphs.Item(2).Range.Font.Bold);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
            }
        }
    }

    [Fact]
    public void WordStyleRelativeBoldToggleResolvesAgainstBoldNormalStyle()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordBoldStyleToggle.doc"));
        using (var index = new DocTextIndexWalker().Index(path))
        {
            Assert.Contains(index.StyleDefinitions, x =>
                x.Name == "Normal" && x.CharacterFormatting.Bold == true);
            Assert.Contains(index.CharacterFormatting, x => x.Formatting.Bold == false);
        }
        var projected = DxpDocToDocx.Project(path);
        using (var stream = new MemoryStream(projected.DocxBytes))
        using (var docx = WordprocessingDocument.Open(stream, false))
        {
            Assert.Contains(docx.MainDocumentPart!.StyleDefinitionsPart!.Styles!
                .Descendants<StyleRunProperties>(), x =>
                x.GetFirstChild<Bold>()?.Val?.Value == true);
            Assert.Contains(docx.MainDocumentPart.Document!.Body!.Descendants<Run>(), x =>
                x.RunProperties?.Bold?.Val?.Value == false);
            Assert.Empty(new OpenXmlValidator().Validate(docx));
        }
        var roundTripped = DxpDocExport.Export(projected.DocxBytes);
        using (var input = new MemoryStream(roundTripped))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Contains(index.StyleDefinitions, x => x.CharacterFormatting.Bold == true);
            Assert.Contains(index.CharacterFormatting, x => x.Formatting.Bold == false);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var output = Path.Combine(Path.GetTempPath(),
                $"docxport-bold-toggle-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(output, roundTripped);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(output, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range.Font.Bold);
                Assert.Equal(0, (int)opened.Paragraphs.Item(2).Range.Font.Bold);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(output);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void RowCellSpacingOverridesTableSpacingInBothDocRoutes(bool exception)
    {
        static TableCell Cell(string value) => new(new Paragraph(new Run(new Text(value))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            DocumentFormat.OpenXml.OpenXmlElement firstRowSpacing = exception
                ? new TablePropertyExceptions(new TableCellSpacing
                { Width = "40", Type = TableWidthUnitValues.Dxa })
                : new TableRowProperties(new TableCellSpacing
                { Width = "40", Type = TableWidthUnitValues.Dxa });
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableCellSpacing
                { Width = "80", Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed }),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(firstRowSpacing,
                    Cell("A1"), Cell("B1")),
                new TableRow(Cell("A2"), Cell("B2")),
                new TableRow(new TableRowProperties(new TableCellSpacing
                { Width = "0", Type = TableWidthUnitValues.Dxa }),
                    Cell("A3"), Cell("B3")))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Equal(new ushort?[] { 40, 80, 0 }, index.ParagraphStyles
                .Where(x => x.Formatting?.TableTerminator == true)
                .Select(x => x.Formatting?.TableCellSpacingTwips));
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var table = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        Assert.Null(table.TableProperties?.GetFirstChild<TableCellSpacing>());
        Assert.Equal(new[] { "40", "80", "0" }, table.Elements<TableRow>()
            .Select(x => x.TableRowProperties?.GetFirstChild<TableCellSpacing>()?
                .Width?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-row-cell-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var savedPath = Path.ChangeExtension(sourcePath, ".saved.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(1, (int)opened.Tables.Count);
            opened.SaveAs2(savedPath, 16);
            opened.Close(false);
            opened = null;
            using (var savedStream = File.OpenRead(savedPath))
            using (var saved = WordprocessingDocument.Open(savedStream, false))
                Assert.Equal(new[] { "40", "80", "0" }, Assert.Single(saved
                    .MainDocumentPart!.Document!.Body!.Elements<Table>())
                    .Elements<TableRow>().Select(x => x.TableRowProperties?
                        .GetFirstChild<TableCellSpacing>()?.Width?.Value));
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var nativeStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            Assert.Equal(new[] { "40", "80", "0" }, Assert.Single(native
                .MainDocumentPart!.Document!.Body!.Elements<Table>())
                .Elements<TableRow>().Select(x => x.TableRowProperties?
                    .GetFirstChild<TableCellSpacing>()?.Width?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(savedPath);
        }
    }

    [Fact]
    public void IsolatedFirstColumnStyleBorderRetainsBothDocHops()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordConditionalColumnBorders.docx"));
        using var input = new MemoryStream();
        input.Write(File.ReadAllBytes(path));
        input.Position = 0;
        using (var document = WordprocessingDocument.Open(input, true))
        {
            var style = Assert.Single(document.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                x.StyleId?.Value == "ColumnBorders");
            foreach (var rule in style.Elements<TableStyleProperties>().ToArray())
                if (rule.Type?.Value != TableStyleOverrideValues.FirstColumn)
                    rule.Remove();
            document.MainDocumentPart.StyleDefinitionsPart.Styles.Save();
        }
        var source = input.ToArray();
        var generated = DxpDocExport.Export(source);
        var third = DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes);
        foreach (var binary in new[] { generated, third })
        {
            using var stream = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(stream);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Column Borders");
            Assert.Single(style.ConditionalTableBorders!);
            Assert.Equal(0x0000AA00u,
                style.ConditionalTableBorders[0x0004].Left?.ColorRgb);
            using var projected = WordprocessingDocument.Open(
                new MemoryStream(new DocToDocxProjector().Project(index).DocxBytes), false);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(source, binary, 0.001);
        }
    }
    [Theory]
    [InlineData(false, false, false)]
    [InlineData(true, false, false)]
    [InlineData(false, true, false)]
    [InlineData(true, true, false)]
    [InlineData(false, true, true)]
    [InlineData(true, true, true)]
    public void CharacterStyleKeepsConditionalTableRunEffectsInAllStories(
        bool styleOverridesColor, bool paragraphOverridesColor,
        bool inheritedParagraphColor)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new TableStyleProperties(
                    new RunPropertiesBaseStyle(new Bold(),
                        new Color { Val = "336699" }))
                { Type = TableStyleOverrideValues.FirstRow })
                { Type = StyleValues.Table, StyleId = "ConditionalText" },
                new Style(styleOverridesColor
                    ? new StyleRunProperties(new Italic(),
                        new Color { Val = "AA5500" })
                    : new StyleRunProperties(new Italic()))
                { Type = StyleValues.Character, StyleId = "EmphasisText" },
                new Style(new StyleRunProperties(new Color { Val = "669933" }))
                { Type = StyleValues.Paragraph, StyleId = "BaseHeadingText" },
                new Style(paragraphOverridesColor && !inheritedParagraphColor
                    ? new StyleRunProperties(new Color { Val = "669933" })
                    : new StyleRunProperties())
                { Type = StyleValues.Paragraph, StyleId = "HeadingText" });
            if (inheritedParagraphColor)
                styles.Styles.Elements<Style>().Last().AppendChild(
                    new BasedOn { Val = "BaseHeadingText" });
            styles.Styles.Save();
            Table StyledTable(string label) => new(
                new TableProperties(new TableStyle { Val = "ConditionalText" },
                    new TableLook { FirstRow = true },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108,
                        Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(new GridColumn { Width = "3600" }),
                new TableRow(new TableCell(new Paragraph(
                    new ParagraphProperties(new ParagraphStyleId { Val = "HeadingText" },
                        new SpacingBetweenLines { After = "0", Line = "280",
                            LineRule = LineSpacingRuleValues.Exact }), new Run(
                    new RunProperties(new RunStyle { Val = "EmphasisText" }),
                    new Text(label + " styled heading"))))),
                new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(label + " ordinary"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            var run = table.Elements<TableRow>().First().Descendants<Run>().Single();
            Assert.NotNull(run.RunProperties?.RunStyle);
            Assert.True(run.RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
            Assert.Equal(styleOverridesColor || paragraphOverridesColor ? null : "336699",
                run.RunProperties?.GetFirstChild<Color>()?.Val?.Value);
        });
        var characterStyle = Assert.Single(projected.MainDocumentPart!
            .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                x.Type?.Value == StyleValues.Character);
        Assert.Equal(styleOverridesColor ? "AA5500" : null,
            characterStyle.StyleRunProperties?.GetFirstChild<Color>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenStream = new MemoryStream(DxpDocToDocx.Project(rewritten).DocxBytes);
        using var rewrittenDocx = WordprocessingDocument.Open(rewrittenStream, false);
        var rewrittenTables = rewrittenDocx.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(rewrittenDocx.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(rewrittenDocx.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, rewrittenTables.Length);
        Assert.All(rewrittenTables, table =>
        {
            var run = table.Elements<TableRow>().First().Descendants<Run>().Single();
            Assert.NotNull(run.RunProperties?.RunStyle);
            Assert.True(run.RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
            Assert.Equal(styleOverridesColor || paragraphOverridesColor ? null : "336699",
                run.RunProperties?.GetFirstChild<Color>()?.Val?.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(rewrittenDocx));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-paragraph-table-style-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var nativeProjectedPath = Path.ChangeExtension(sourcePath, ".native.projected.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyTables = new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                };
                var color = styleOverridesColor ? 0x0055AA :
                    paragraphOverridesColor ? 0x339966 : 0x996633;
                foreach (dynamic table in storyTables)
                {
                    dynamic first = table.Cell(1, 1).Range.Characters.Item(1).Font;
                    Assert.True((int)first.Bold != 0);
                    Assert.True((int)first.Italic != 0);
                    Assert.Equal(color, (int)first.Color & 0xFFFFFF);
                    Assert.False((int)table.Cell(2, 1).Range.Characters.Item(1)
                        .Font.Bold != 0);
                }
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            using var nativeStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            var nativeTables = native.MainDocumentPart!.Document.Body!.Elements<Table>()
                .Concat(native.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Table>()))
                .Concat(native.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(3, nativeTables.Length);
            Assert.Contains(nativeTables, x => x.InnerText.Contains("Body styled heading"));
            Assert.Contains(nativeTables, x => x.InnerText.Contains("Header styled heading"));
            Assert.Contains(nativeTables, x => x.InnerText.Contains("Footer styled heading"));
            Assert.Empty(new OpenXmlValidator().Validate(native));
            File.WriteAllBytes(nativeProjectedPath, nativeStream.ToArray());
            (bool Bold, bool Italic, int Color)[]? nativeState = null;
            foreach (var path in new[] { nativePath, nativeProjectedPath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyTables = new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                };
                var state = storyTables.Select(table =>
                {
                    dynamic font = table.Cell(1, 1).Range.Characters.Item(1).Font;
                    return ((int)font.Bold != 0, (int)font.Italic != 0,
                        (int)font.Color & 0xFFFFFF);
                }).ToArray();
                if (nativeState == null) nativeState = state;
                else Assert.Equal(nativeState, state);
                opened.Close(false);
                opened = null;
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(nativeProjectedPath);
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void FirstRowTableStyleParagraphAlignmentReachesAllStories(
        bool directOverride, bool styleOverride)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new TableStyleProperties(new StyleParagraphProperties(
                    new Justification { Val = JustificationValues.Center }))
                { Type = TableStyleOverrideValues.FirstRow })
                { Type = StyleValues.Table, StyleId = "CenteredHeader" },
                new Style(new StyleParagraphProperties(
                    new Justification { Val = JustificationValues.Right }))
                { Type = StyleValues.Paragraph, StyleId = "RightParagraph" });
            styles.Styles.Save();
            ParagraphProperties HeadingProperties()
            {
                var properties = new ParagraphProperties();
                if (styleOverride)
                    properties.AppendChild(new ParagraphStyleId
                    { Val = "RightParagraph" });
                properties.AppendChild(new SpacingBetweenLines
                { After = "0", Line = "280", LineRule = LineSpacingRuleValues.Exact });
                if (directOverride)
                    properties.AppendChild(new Justification
                    { Val = JustificationValues.Left });
                return properties;
            }
            Table StyledTable(string label) => new(
                new TableProperties(new TableStyle { Val = "CenteredHeader" },
                    new TableIndentation { Width = 108,
                        Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa }),
                    new TableLook { Val = "0020" }),
                new TableGrid(new GridColumn { Width = "3600" }),
                new TableRow(new TableCell(new Paragraph(
                    HeadingProperties(),
                    new Run(new Text(label + " heading"))))),
                new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(label + " ordinary"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
        {
            var errors = new OpenXmlValidator().Validate(original).ToArray();
            Assert.True(errors.Length == 0, string.Join("\n", errors.Select(x =>
                $"{x.Description}: {x.Node?.OuterXml}")));
        }
        void AssertAlignment(byte[] bytes)
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Table>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                var rows = table.Elements<TableRow>().ToArray();
                Assert.Equal(directOverride && styleOverride ? JustificationValues.Left :
                    styleOverride ? (JustificationValues?)null :
                    JustificationValues.Center, rows[0].Descendants<Paragraph>()
                    .Single().ParagraphProperties?.Justification?.Val?.Value);
                var projectedStyleId = rows[0].Descendants<Paragraph>().Single()
                    .ParagraphProperties?.ParagraphStyleId?.Val?.Value;
                if (styleOverride)
                {
                    Assert.NotEqual("DocStyle0", projectedStyleId);
                    var projectedStyle = Assert.Single(projected.MainDocumentPart!
                        .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                            x.StyleId?.Value == projectedStyleId);
                    Assert.Equal(JustificationValues.Right,
                        projectedStyle.StyleParagraphProperties?
                            .Justification?.Val?.Value);
                }
                Assert.Null(rows[1].Descendants<Paragraph>().Single()
                    .ParagraphProperties?.Justification);
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertAlignment(binary);
        AssertAlignment(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-conditional-paragraph-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyTables = new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                };
                foreach (dynamic table in storyTables)
                {
                    var actual = (int)table.Cell(1, 1).Range.Characters.Item(1)
                        .ParagraphFormat.Alignment;
                    var expected = directOverride && styleOverride ? 0 :
                        styleOverride ? 2 : 1;
                    Assert.True(actual == expected,
                        $"{path}: expected {expected}, actual {actual}");
                }
                opened.Close(false);
                opened = null;
            }
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
        }
    }

    [Theory]
    [InlineData(false, false, false, 0)]
    [InlineData(true, false, false, 0)]
    [InlineData(false, true, false, 0)]
    [InlineData(true, true, false, 0)]
    [InlineData(false, false, true, 0)]
    [InlineData(true, false, true, 0)]
    [InlineData(false, true, true, 0)]
    [InlineData(true, true, true, 0)]
    [InlineData(false, false, false, 1)]
    [InlineData(true, false, false, 1)]
    [InlineData(false, true, false, 1)]
    [InlineData(true, true, false, 1)]
    [InlineData(false, false, true, 1)]
    [InlineData(true, false, true, 1)]
    [InlineData(false, true, true, 1)]
    [InlineData(true, true, true, 1)]
    [InlineData(false, false, false, 2)]
    [InlineData(true, false, false, 2)]
    [InlineData(false, true, false, 2)]
    [InlineData(true, true, false, 2)]
    [InlineData(false, false, true, 2)]
    [InlineData(true, false, true, 2)]
    [InlineData(false, true, true, 2)]
    [InlineData(true, true, true, 2)]
    public void FirstRowTableStyleParagraphDecorationsReachAllStories(
        bool directOverride, bool styleOverride, bool hanging,
        int lineMode)
    {
        var lineRule = lineMode switch
        {
            0 => LineSpacingRuleValues.Exact,
            1 => LineSpacingRuleValues.Auto,
            2 => LineSpacingRuleValues.AtLeast,
            _ => throw new ArgumentOutOfRangeException(nameof(lineMode))
        };
        Indentation MakeIndentation(string left, string right, string offset) =>
            hanging
                ? new Indentation { Left = left, Right = right, Hanging = offset }
                : new Indentation { Left = left, Right = right, FirstLine = offset };
        ParagraphBorders MakeBorders(string top, string left, string bottom,
            string right) => new(
                new TopBorder { Val = BorderValues.Single, Size = 16, Space = 2,
                    Color = top },
                new LeftBorder { Val = BorderValues.Single, Size = 16, Space = 2,
                    Color = left },
                new BottomBorder { Val = BorderValues.Single, Size = 16, Space = 2,
                    Color = bottom },
                new RightBorder { Val = BorderValues.Single, Size = 16, Space = 2,
                    Color = right });
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0",
                        Line = lineMode == 1 ? "240" : "280",
                        LineRule = lineRule }))),
                new Style(new TableStyleProperties(new StyleParagraphProperties(
                    MakeBorders("993366", "339966", "336699", "996633"),
                    new Shading { Val = ShadingPatternValues.Clear,
                        Fill = "CCEEDD" },
                    new SpacingBetweenLines { Before = "160", After = "240",
                        Line = lineMode == 1 ? "240" : "280",
                        LineRule = lineRule },
                    MakeIndentation("360", "180", "120")))
                { Type = TableStyleOverrideValues.FirstRow })
                { Type = StyleValues.Table, StyleId = "SpacedHeader" },
                new Style(new StyleParagraphProperties(
                    MakeBorders("8844AA", "44AA88", "663399", "AA8844"),
                    new Shading { Val = ShadingPatternValues.Clear,
                        Fill = "DDEEFF" },
                    new SpacingBetweenLines { Before = "100", After = "200",
                        Line = lineMode == 1 ? "360" : "320",
                        LineRule = lineRule },
                    MakeIndentation("240", "120", "80")))
                { Type = StyleValues.Paragraph, StyleId = "DecoratedText" });
            styles.Styles.Save();
            ParagraphProperties HeadingProperties()
            {
                var properties = new ParagraphProperties();
                if (styleOverride)
                    properties.AppendChild(new ParagraphStyleId
                    { Val = "DecoratedText" });
                if (directOverride)
                {
                    properties.AppendChild(MakeBorders("AA2200", "00AA22",
                        "AA5500", "2200AA"));
                    properties.AppendChild(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "FFCC99" });
                    properties.AppendChild(new SpacingBetweenLines
                    { Before = "40", After = "80",
                        Line = lineMode == 1 ? "480" : "240",
                        LineRule = lineRule });
                    properties.AppendChild(MakeIndentation("120", "60", "40"));
                }
                return properties;
            }
            Table StyledTable(string label) => new(
                new TableProperties(new TableStyle { Val = "SpacedHeader" },
                    new TableIndentation { Width = 108,
                        Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa }),
                    new TableLook { Val = "0020" }),
                new TableGrid(new GridColumn { Width = "3600" }),
                new TableRow(new TableCell(new Paragraph(
                    HeadingProperties(),
                    new Run(new Text(label + " heading"))))),
                new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(label + " ordinary"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
            Assert.Empty(new OpenXmlValidator().Validate(original));
        void AssertSpacing(byte[] bytes, bool nativeWordSave = false)
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Table>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                var paragraph = table.Elements<TableRow>().First()
                    .Descendants<Paragraph>().Single();
                var properties = paragraph.ParagraphProperties;
                var styleId = properties?.ParagraphStyleId?.Val?.Value;
                var styleProperties = projected.MainDocumentPart!
                    .StyleDefinitionsPart!.Styles!.Elements<Style>()
                    .FirstOrDefault(x => x.StyleId?.Value == styleId)?
                    .StyleParagraphProperties;
                if (styleOverride)
                    Assert.NotNull(styleProperties);
                var spacing = properties?.SpacingBetweenLines ??
                    styleProperties?.SpacingBetweenLines;
                Assert.Equal(directOverride ? "40" : styleOverride ? "100" : "160",
                    spacing?.Before?.Value);
                Assert.Equal(directOverride ? "80" : styleOverride ? "200" : "240",
                    spacing?.After?.Value);
                var defaultSpacing = projected.MainDocumentPart!.StyleDefinitionsPart!
                    .Styles!.DocDefaults?.ParagraphPropertiesDefault?
                    .ParagraphPropertiesBaseStyle?.SpacingBetweenLines;
                var effectiveLine = spacing?.Line?.Value ?? defaultSpacing?.Line?.Value;
                var effectiveLineRule = spacing?.LineRule?.Value ??
                    defaultSpacing?.LineRule?.Value;
                if (nativeWordSave && lineMode == 1 && !directOverride &&
                    !styleOverride && effectiveLine == null)
                {
                    // Word's native DOC save uses implicit single spacing here.
                    effectiveLine = "240";
                    effectiveLineRule = LineSpacingRuleValues.Auto;
                }
                Assert.Equal(lineMode == 1
                    ? directOverride ? "480" : styleOverride ? "360" : "240"
                    : directOverride ? "240" : styleOverride ? "320" : "280",
                    effectiveLine);
                Assert.Equal(lineRule, effectiveLineRule);
                var indentation = properties?.Indentation ?? styleProperties?.Indentation;
                Assert.Equal(directOverride ? "120" : styleOverride ? "240" : "360",
                    indentation?.Left?.Value);
                Assert.Equal(directOverride ? "60" : styleOverride ? "120" : "180",
                    indentation?.Right?.Value);
                var expectedOffset = directOverride ? "40" : styleOverride ? "80" : "120";
                Assert.Equal(expectedOffset,
                    hanging ? indentation?.Hanging?.Value : indentation?.FirstLine?.Value);
                Assert.Equal(directOverride ? "FFCC99" :
                    styleOverride ? "DDEEFF" : "CCEEDD",
                    (properties?.Shading ?? styleProperties?.Shading)?.Fill?.Value);
                var borders = properties?.ParagraphBorders ??
                    styleProperties?.ParagraphBorders;
                Assert.Equal(directOverride ? "AA2200" :
                    styleOverride ? "8844AA" : "993366",
                    borders?.TopBorder?.Color?.Value);
                Assert.Equal(directOverride ? "00AA22" :
                    styleOverride ? "44AA88" : "339966",
                    borders?.LeftBorder?.Color?.Value);
                Assert.Equal(directOverride ? "AA5500" :
                    styleOverride ? "663399" : "336699",
                    borders?.BottomBorder?.Color?.Value);
                Assert.Equal(directOverride ? "2200AA" :
                    styleOverride ? "AA8844" : "996633",
                    borders?.RightBorder?.Color?.Value);
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertSpacing(binary);
        AssertSpacing(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-conditional-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyTables = new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                };
                foreach (dynamic table in storyTables)
                {
                    dynamic firstCharacter = table.Cell(1, 1).Range.Characters.Item(1);
                    Assert.Equal(12d, Convert.ToDouble(firstCharacter.Font.Size));
                    dynamic spacing = firstCharacter.ParagraphFormat;
                    Assert.Equal(directOverride ? 2d : styleOverride ? 5d : 8d,
                        Convert.ToDouble(spacing.SpaceBefore));
                    Assert.Equal(directOverride ? 4d : styleOverride ? 10d : 12d,
                        Convert.ToDouble(spacing.SpaceAfter));
                    if (lineMode == 1)
                        Assert.Equal(directOverride ? 2 : styleOverride ? 1 : 0,
                            Convert.ToInt32(spacing.LineSpacingRule));
                    else
                    {
                        Assert.Equal(lineMode == 0 ? 4 : 3,
                            Convert.ToInt32(spacing.LineSpacingRule));
                        Assert.Equal(directOverride ? 12d : styleOverride ? 16d : 14d,
                            Convert.ToDouble(spacing.LineSpacing));
                    }
                    Assert.Equal(directOverride ? 6d : styleOverride ? 12d : 18d,
                        Convert.ToDouble(spacing.LeftIndent));
                    Assert.Equal(directOverride ? 3d : styleOverride ? 6d : 9d,
                        Convert.ToDouble(spacing.RightIndent));
                    Assert.Equal((hanging ? -1d : 1d) *
                        (directOverride ? 2d : styleOverride ? 4d : 6d),
                        Convert.ToDouble(spacing.FirstLineIndent));
                }
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertSpacing(File.ReadAllBytes(nativePath), nativeWordSave: true);
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void BandTableStyleParagraphAlignmentReachesAllStories(
        bool vertical, bool useBand)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))),
                new Style(
                    new StyleTableProperties(vertical
                        ? (DocumentFormat.OpenXml.OpenXmlElement)
                            new TableStyleColumnBandSize { Val = 1 }
                        : new TableStyleRowBandSize { Val = 1 }),
                    new TableStyleProperties(new StyleParagraphProperties(
                        new Justification { Val = JustificationValues.Center }))
                    { Type = vertical ? TableStyleOverrideValues.Band1Vertical
                        : TableStyleOverrideValues.Band1Horizontal },
                    new TableStyleProperties(new StyleParagraphProperties(
                        new Justification { Val = JustificationValues.Right }))
                    { Type = vertical ? TableStyleOverrideValues.Band2Vertical
                        : TableStyleOverrideValues.Band2Horizontal })
                { Type = StyleValues.Table, StyleId = "BandParagraphs" });
            styles.Styles.Save();
            Table StyledTable(string label)
            {
                var table = new Table(
                new TableProperties(new TableStyle { Val = "BandParagraphs" },
                    new TableIndentation { Width = 108,
                        Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa }),
                    new TableLook { Val = !useBand
                        ? vertical ? "0400" : "0200" : "0000" }),
                new TableGrid(Enumerable.Range(0, vertical ? 4 : 1)
                    .Select(_ => new GridColumn { Width = vertical ? "900" : "3600" })));
                if (vertical)
                    table.AppendChild(new TableRow(Enumerable.Range(0, 4)
                        .Select(i => new TableCell(new Paragraph(new Run(
                            new Text(label + " col " + i)))))));
                else
                    foreach (var i in Enumerable.Range(0, 4))
                        table.AppendChild(new TableRow(new TableCell(new Paragraph(
                            new Run(new Text(label + " row " + i))))));
                return table;
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
        {
            Assert.Equal(1, original.MainDocumentPart!.StyleDefinitionsPart!.Styles!
                .Elements<Style>().Single().StyleTableProperties?
                .GetFirstChild<TableStyleRowBandSize>()?.Val?.Value ??
                original.MainDocumentPart.StyleDefinitionsPart!.Styles!
                    .Elements<Style>().Single().StyleTableProperties?
                    .GetFirstChild<TableStyleColumnBandSize>()?.Val?.Value);
            Assert.Equal(2, original.MainDocumentPart.StyleDefinitionsPart!.Styles!
                .Elements<Style>().Single().Elements<TableStyleProperties>().Count());
            Assert.Empty(new OpenXmlValidator().Validate(original));
        }
        void AssertBands(byte[] bytes)
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Table>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                Assert.Equal(!useBand ? vertical ? "0400" : "0200" : "0000",
                    table.TableProperties?.GetFirstChild<TableLook>()?.Val?.Value);
                Assert.Equal(Enumerable.Range(0, 4).Select(i => useBand
                    ? i % 2 == 0 ? JustificationValues.Center : JustificationValues.Right
                    : (JustificationValues?)null),
                    table.Descendants<TableCell>().Take(4).Select(cell =>
                        cell.Descendants<Paragraph>().Single().ParagraphProperties?
                            .Justification?.Val?.Value));
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertBands(binary);
        AssertBands(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-paragraph-bands-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyTables = new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                };
                foreach (dynamic table in storyTables)
                    for (var position = 1; position <= 4; position++)
                        Assert.Equal(useBand ? position % 2 == 1 ? 1 : 2 : 0,
                            (int)table.Cell(vertical ? 1 : position,
                                vertical ? position : 1).Range.ParagraphFormat.Alignment);
                opened.Close(false);
                opened = null;
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void CornerTableStyleRunColorsAndParagraphAlignmentReachAllStories(
        bool directCorner)
    {
        static TableStyleProperties Conditional(TableStyleOverrideValues kind,
            string color, JustificationValues? alignment = null) => alignment is null
            ? new TableStyleProperties(new RunPropertiesBaseStyle(
                new Color { Val = color })) { Type = kind }
            : new TableStyleProperties(
                new StyleParagraphProperties(new Justification { Val = alignment }),
                new RunPropertiesBaseStyle(new Color { Val = color })) { Type = kind };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))),
                new Style(
                    new TableStyleProperties(
                        new StyleParagraphProperties(new Justification
                        { Val = JustificationValues.Center }),
                        new RunPropertiesBaseStyle(new Bold(),
                            new Color { Val = "111111" }))
                    { Type = TableStyleOverrideValues.FirstRow },
                    Conditional(TableStyleOverrideValues.LastRow, "444444"),
                    Conditional(TableStyleOverrideValues.FirstColumn, "222222",
                        JustificationValues.Right),
                    Conditional(TableStyleOverrideValues.LastColumn, "333333"),
                    Conditional(TableStyleOverrideValues.NorthWestCell, "CC0000",
                        JustificationValues.Both),
                    Conditional(TableStyleOverrideValues.NorthEastCell, "00AA00",
                        JustificationValues.Right),
                    Conditional(TableStyleOverrideValues.SouthWestCell, "0000CC",
                        JustificationValues.Center),
                    Conditional(TableStyleOverrideValues.SouthEastCell, "CC00CC",
                        JustificationValues.Both))
                { Type = StyleValues.Table, StyleId = "CornerRuns" });
            styles.Styles.Save();
            Table CornerTable(string label)
            {
                var table = new Table(
                    new TableProperties(new TableStyle { Val = "CornerRuns" },
                        new TableIndentation { Width = 108,
                            Type = TableWidthUnitValues.Dxa },
                        new TableLayout { Type = TableLayoutValues.Fixed },
                        new TableCellMarginDefault(
                            new TableCellLeftMargin { Width = 108,
                                Type = TableWidthValues.Dxa },
                            new TableCellRightMargin { Width = 108,
                                Type = TableWidthValues.Dxa }),
                        new TableLook { Val = "01E0" }),
                    new TableGrid(Enumerable.Range(0, 3)
                        .Select(_ => new GridColumn { Width = "1600" })));
                for (var rowIndex = 0; rowIndex < 3; rowIndex++)
                {
                    var row = new TableRow();
                    for (var columnIndex = 0; columnIndex < 3; columnIndex++)
                    {
                        var run = directCorner && rowIndex == 2 && columnIndex == 2
                            ? new Run(new RunProperties(new Color { Val = "FFAA00" }),
                                new Text(label + rowIndex + columnIndex))
                            : new Run(new Text(label + rowIndex + columnIndex));
                        row.Append(new TableCell(new Paragraph(run)));
                    }
                    table.Append(row);
                }
                return table;
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(CornerTable("H"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(CornerTable("F"));
            footer.Footer.Save();
            main.Document = new Document(new Body(CornerTable("B"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
            Assert.Empty(new OpenXmlValidator().Validate(original));
        var expected = new[]
        {
            "CC0000", "111111", "00AA00",
            "222222", null, "333333",
            "0000CC", "444444", directCorner ? "FFAA00" : "CC00CC"
        };
        JustificationValues?[] expectedAlignment =
        [
            JustificationValues.Both, JustificationValues.Center,
            JustificationValues.Right,
            JustificationValues.Right, null, null,
            JustificationValues.Center, null, JustificationValues.Both
        ];
        void AssertColors(byte[] bytes)
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Table>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                Assert.Equal(expected, table.Descendants<TableCell>().Select(cell =>
                    cell.Descendants<Run>().Single().RunProperties?
                        .GetFirstChild<Color>()?.Val?.Value));
                Assert.Equal(expectedAlignment, table.Descendants<TableCell>()
                    .Select(cell => cell.Descendants<Paragraph>().Single()
                        .ParagraphProperties?.Justification?.Val?.Value));
                Assert.All(table.Elements<TableRow>().First().Descendants<Run>(), run =>
                    Assert.True(run.RunProperties?
                        .GetFirstChild<Bold>()?.Val?.Value ?? false));
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertColors(binary);
        AssertColors(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-corner-run-colors-{Guid.NewGuid():N}.docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
            var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            bool[][]? sourceBold = null;
            try
            {
                foreach (var path in new[] { sourcePath, generatedPath })
                {
                    opened = word.Documents.Open(path, ReadOnly: true,
                        AddToRecentFiles: false);
                    var storyTables = new dynamic[]
                    {
                        opened.Tables.Item(1),
                        opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                        opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                    };
                    var actualBold = new bool[storyTables.Length][];
                    for (var storyIndex = 0; storyIndex < storyTables.Length; storyIndex++)
                    {
                        dynamic table = storyTables[storyIndex];
                        actualBold[storyIndex] = Enumerable.Range(1, 3).Select(i =>
                            (int)table.Cell(1, i).Range.Font.Bold != 0).ToArray();
                        for (var rowIndex = 0; rowIndex < 3; rowIndex++)
                            for (var columnIndex = 0; columnIndex < 3; columnIndex++)
                            {
                                var color = expected[rowIndex * 3 + columnIndex];
                                if (color == null) continue;
                                var rgb = int.Parse(color, NumberStyles.HexNumber,
                                    CultureInfo.InvariantCulture);
                                var wordColor = (rgb & 0xFF) << 16 |
                                    rgb & 0xFF00 | (rgb >> 16) & 0xFF;
                                Assert.Equal(wordColor, (int)table.Cell(rowIndex + 1,
                                    columnIndex + 1).Range.Font.Color & 0xFFFFFF);
                            }
                        for (var rowIndex = 0; rowIndex < 3; rowIndex++)
                            for (var columnIndex = 0; columnIndex < 3; columnIndex++)
                            {
                                var expectedValue = expectedAlignment[rowIndex * 3 + columnIndex];
                                Assert.Equal(expectedValue == JustificationValues.Both ? 3 :
                                    expectedValue == JustificationValues.Center ? 1 :
                                    expectedValue == JustificationValues.Right ? 2 : 0,
                                    (int)table.Cell(rowIndex + 1, columnIndex + 1)
                                        .Range.Characters.Item(1).ParagraphFormat.Alignment);
                            }
                    }
                    if (path == sourcePath) sourceBold = actualBold;
                    else
                        for (var i = 0; i < actualBold.Length; i++)
                            Assert.True(sourceBold![i].SequenceEqual(actualBold[i]),
                                $"story {i}: source={string.Join(',', sourceBold[i])}, generated={string.Join(',', actualBold[i])}");
                    if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                    opened.Close(false);
                    opened = null;
                }
                AssertColors(File.ReadAllBytes(nativePath));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                File.Delete(nativePath);
            }
        }
    }

