            word.Visible = false;
            dynamic? opened = null;
            try
            {
                foreach (var path in new[] { sourcePath, generatedPath })
                {
                    opened = word.Documents.Open(path, ReadOnly: true,
                        AddToRecentFiles: false);
                    for (var i = 1; i <= 3; i++)
                    {
                        Assert.Equal(useBand && i % 2 == 1,
                            (int)opened.Tables.Item(1).Cell(1, i).Range.Font.Bold != 0);
                        Assert.Equal(useBand && i % 2 == 0,
                            (int)opened.Tables.Item(1).Cell(1, i).Range.Font.Italic != 0);
