                {
                    Assert.Equal(!noBand && i % 2 == 0,
                        runs[i].RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
                    Assert.Equal(!noBand && i % 2 != 0,
                        runs[i].RunProperties?.GetFirstChild<Italic>()?.Val?.Value ?? false);
                    Assert.Equal(noBand ? null : i % 2 == 0 ? "336699" : "669933",
                        runs[i].RunProperties?.GetFirstChild<Color>()?.Val?.Value);
                }
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        AssertBands(binary);
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        AssertBands(DxpDocExport.Export(projectedBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-table-band-runs-{Guid.NewGuid():N}.docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
            var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                foreach (var path in new[] { sourcePath, generatedPath })
                {
                    opened = word.Documents.Open(path, ReadOnly: true,
                        AddToRecentFiles: false);
                    foreach (dynamic table in new dynamic[]
                    {
                        opened.Tables.Item(1),
                        opened.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                        opened.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                    })
                    {
                        for (var i = 1; i <= 4; i++)
                        {
                            Assert.Equal(!noBand && i % 2 == 1, (int)table.Cell(i, 1)
                                .Range.Font.Bold != 0);
                            Assert.Equal(!noBand && i % 2 == 0, (int)table.Cell(i, 1)
                                .Range.Font.Italic != 0);
                            if (!noBand)
                                Assert.Equal(i % 2 == 1 ? 0x996633 : 0x339966,
                                    (int)table.Cell(i, 1).Range.Font.Color & 0xFFFFFF);
                        }
                    }
                    if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                    opened.Close(false);
                    opened = null;
                }
                AssertBands(File.ReadAllBytes(nativePath));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void SingleRowTableStyleUsesWordConditionalRunPrecedence()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(
                new TableStyleProperties(new RunPropertiesBaseStyle(new Bold(),
                    new Color { Val = "CC3300" }))
                { Type = TableStyleOverrideValues.FirstRow },
                new TableStyleProperties(new RunPropertiesBaseStyle(new Italic(),
                    new Color { Val = "336699" }))
                { Type = TableStyleOverrideValues.LastRow })
            { Type = StyleValues.Table, StyleId = "OverlappingRowStyle" });
            styles.Styles.Save();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableStyle { Val = "OverlappingRowStyle" },
                    new TableLook { FirstRow = true, LastRow = true },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa }),
                new TableGrid(new GridColumn { Width = "3600" }),
                new TableRow(new TableCell(new Paragraph(new Run(
                    new Text("Overlapping row"))))))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var run = Assert.Single(projected.MainDocumentPart!.Document.Body!
            .Elements<Table>()).Descendants<Run>().Single();
        Assert.True(run.RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
        Assert.Null(run.RunProperties?.GetFirstChild<Italic>());
        Assert.Equal("CC3300", run.RunProperties?.GetFirstChild<Color>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenStream = new MemoryStream(DxpDocToDocx.Project(rewritten).DocxBytes);
        using var rewrittenDocx = WordprocessingDocument.Open(rewrittenStream, false);
        var rewrittenRun = Assert.Single(rewrittenDocx.MainDocumentPart!.Document.Body!
            .Elements<Table>()).Descendants<Run>().Single();
        Assert.True(rewrittenRun.RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
        Assert.Null(rewrittenRun.RunProperties?.GetFirstChild<Italic>());
        Assert.Equal("CC3300", rewrittenRun.RunProperties?
            .GetFirstChild<Color>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(rewrittenDocx));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-single-row-style-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.NotEqual(0, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Range.Font.Bold);
                Assert.Equal(0, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Range.Font.Italic);
                Assert.Equal(0x0033CC, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Range.Font.Color & 0xFFFFFF);
                opened.Close(false);
                opened = null;
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
        }
    }

    [Fact]
    public void FirstAndLastRowTableStyleRunFormattingReachesAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))), new Style(
                new TableStyleProperties(
                    new RunPropertiesBaseStyle(new Bold(),
                        new Color { Val = "336699" }))
                { Type = TableStyleOverrideValues.FirstRow },
                new TableStyleProperties(
                    new RunPropertiesBaseStyle(new Italic(),
                        new Color { Val = "669933" }))
                { Type = TableStyleOverrideValues.LastRow },
                new TableStyleProperties(
                    new RunPropertiesBaseStyle(new Underline
                    { Val = UnderlineValues.Single },
                        new Color { Val = "AA5500" }))
                { Type = TableStyleOverrideValues.FirstColumn },
                new TableStyleProperties(
                    new RunPropertiesBaseStyle(new Strike(),
                        new Color { Val = "00AA55" }))
                { Type = TableStyleOverrideValues.LastColumn })
            { Type = StyleValues.Table, StyleId = "BoldFirstRow" });
            styles.Styles.Save();
            Table StyledTable(string label) => new(
                new TableProperties(new TableStyle { Val = "BoldFirstRow" },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableLook { FirstRow = true, LastRow = true,
                        FirstColumn = true, LastColumn = true },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(new GridColumn { Width = "2400" },
                    new GridColumn { Width = "2400" }),
                new TableRow(new TableCell(new Paragraph(
                    new Run(new Text(label + " heading")))),
                    new TableCell(new Paragraph(new Run(
                        new RunProperties(new Bold { Val = false },
                            new Color { Val = "CC3300" }),
                        new Text(label + " direct off"))))),
                new TableRow(new TableCell(new Paragraph(
                    new Run(new Text(label + " first column")))),
                    new TableCell(new Paragraph(new Run(
                        new Text(label + " last column"))))),
                new TableRow(new TableCell(new Paragraph(
                    new Run(new Text(label + " detail")))),
                    new TableCell(new Paragraph(new Run(
                        new RunProperties(new Italic { Val = false },
                            new Color { Val = "9966CC" }),
                        new Text("ordinary"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            var rows = table.Elements<TableRow>().ToArray();
            var headingRuns = rows[0].Descendants<Run>().ToArray();
            Assert.True(headingRuns[0]
                .RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
            Assert.Equal("336699", headingRuns[0]
                .RunProperties?.GetFirstChild<Color>()?.Val?.Value);
            Assert.False(headingRuns[1]
                .RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? true);
            Assert.Equal("CC3300", headingRuns[1]
                .RunProperties?.GetFirstChild<Color>()?.Val?.Value);
            var middleRuns = rows[1].Descendants<Run>().ToArray();
            Assert.Equal(UnderlineValues.Single, middleRuns[0].RunProperties?
                .GetFirstChild<Underline>()?.Val?.Value);
            Assert.Equal("AA5500", middleRuns[0].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.True(middleRuns[1].RunProperties?
                .GetFirstChild<Strike>()?.Val?.Value ?? false);
            Assert.Equal("00AA55", middleRuns[1].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.Null(rows[2].Descendants<Run>().First()
                .RunProperties?.GetFirstChild<Bold>());
            var detailRuns = rows[2].Descendants<Run>().ToArray();
            Assert.True(detailRuns[0].RunProperties?
                .GetFirstChild<Italic>()?.Val?.Value ?? false);
            Assert.Equal("669933", detailRuns[0].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.False(detailRuns[1].RunProperties?
                .GetFirstChild<Italic>()?.Val?.Value ?? true);
            Assert.Equal("9966CC", detailRuns[1].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenStream = new MemoryStream(DxpDocToDocx.Project(rewritten).DocxBytes);
        using var rewrittenDocx = WordprocessingDocument.Open(rewrittenStream, false);
        var rewrittenTables = rewrittenDocx.MainDocumentPart!.Document.Body!
            .Elements<Table>().Concat(rewrittenDocx.MainDocumentPart
                .HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
            .Concat(rewrittenDocx.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, rewrittenTables.Length);
        Assert.All(rewrittenTables, table =>
        {
            var runs = table.Elements<TableRow>().First().Descendants<Run>().ToArray();
            Assert.True(runs[0].RunProperties?
                .GetFirstChild<Bold>()?.Val?.Value ?? false);
            Assert.Equal("336699", runs[0].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.False(runs[1].RunProperties?
                .GetFirstChild<Bold>()?.Val?.Value ?? true);
            Assert.Equal("CC3300", runs[1].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            var middleRuns = table.Elements<TableRow>().ElementAt(1)
                .Descendants<Run>().ToArray();
            Assert.Equal(UnderlineValues.Single, middleRuns[0].RunProperties?
                .GetFirstChild<Underline>()?.Val?.Value);
            Assert.Equal("AA5500", middleRuns[0].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.True(middleRuns[1].RunProperties?
                .GetFirstChild<Strike>()?.Val?.Value ?? false);
            Assert.Equal("00AA55", middleRuns[1].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            var lastRuns = table.Elements<TableRow>().Last().Descendants<Run>().ToArray();
            Assert.True(lastRuns[0].RunProperties?
                .GetFirstChild<Italic>()?.Val?.Value ?? false);
            Assert.Equal("669933", lastRuns[0].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.False(lastRuns[1].RunProperties?
                .GetFirstChild<Italic>()?.Val?.Value ?? true);
            Assert.Equal("9966CC", lastRuns[1].RunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(rewrittenDocx));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-table-style-run-{Guid.NewGuid():N}.docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
            var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                foreach (var path in new[] { sourcePath, generatedPath })
                {
                    opened = word.Documents.Open(path, ReadOnly: true,
                        AddToRecentFiles: false);
                    Assert.NotEqual(0, (int)opened.Tables.Item(1).Cell(1, 1)
                        .Range.Font.Bold);
                    Assert.Equal(0x996633, (int)opened.Tables.Item(1).Cell(1, 1)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.Equal(0, (int)opened.Tables.Item(1).Cell(1, 2)
                        .Range.Font.Bold);
                    Assert.Equal(0x0033CC, (int)opened.Tables.Item(1).Cell(1, 2)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.NotEqual(0, (int)opened.Tables.Item(1).Cell(2, 1)
                        .Range.Font.Underline);
                    Assert.Equal(0x0055AA, (int)opened.Tables.Item(1).Cell(2, 1)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.NotEqual(0, (int)opened.Tables.Item(1).Cell(2, 2)
                        .Range.Font.StrikeThrough);
                    Assert.Equal(0x55AA00, (int)opened.Tables.Item(1).Cell(2, 2)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.NotEqual(0, (int)opened.Tables.Item(1).Cell(3, 1)
                        .Range.Font.Italic);
                    Assert.Equal(0x339966, (int)opened.Tables.Item(1).Cell(3, 1)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.Equal(0, (int)opened.Tables.Item(1).Cell(3, 2)
                        .Range.Font.Italic);
                    Assert.Equal(0xCC6699, (int)opened.Tables.Item(1).Cell(3, 2)
                        .Range.Font.Color & 0xFFFFFF);
                    Assert.NotEqual(0, (int)opened.Sections.Item(1).Headers.Item(1)
                        .Range.Tables.Item(1).Cell(1, 1).Range.Font.Bold);
                    Assert.NotEqual(0, (int)opened.Sections.Item(1).Footers.Item(1)
                        .Range.Tables.Item(1).Cell(1, 1).Range.Font.Bold);
                    if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                    opened.Close(false);
                    opened = null;
                }
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                var nativeTables = nativeProjection.MainDocumentPart!.Document.Body!
                    .Elements<Table>().Concat(nativeProjection.MainDocumentPart
                        .HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeProjection.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
                Assert.Equal(3, nativeTables.Length);
                Assert.All(nativeTables, table =>
                {
                    Assert.True(table.Elements<TableRow>().First().Descendants<Run>()
                        .First().RunProperties?.GetFirstChild<Bold>()?.Val?.Value ?? false);
                    Assert.True(table.Elements<TableRow>().Last().Descendants<Run>()
                        .First().RunProperties?.GetFirstChild<Italic>()?.Val?.Value ?? false);
                    var middle = table.Elements<TableRow>().ElementAt(1)
                        .Descendants<Run>().ToArray();
                    Assert.Equal(UnderlineValues.Single, middle[0].RunProperties?
                        .GetFirstChild<Underline>()?.Val?.Value);
                    Assert.True(middle[1].RunProperties?
                        .GetFirstChild<Strike>()?.Val?.Value ?? false);
                });
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                File.Delete(nativePath);
            }
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void TableStyleCellShadingSurvivesBothDocRoutes(bool firstRow,
        bool lastRow)
    {
        static TableCell Cell(string value, string? directFill = null) =>
            new(directFill == null ? new TableCellProperties() :
                new TableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = directFill }),
                new Paragraph(new Run(new Text(value))));
        using var source = new MemoryStream();
        var expectedFills = new[]
        { firstRow ? "99DD99" : "DDEEFF", "FFCC99",
            lastRow ? "FFDDAA" : "DDEEFF", lastRow ? "FFDDAA" : "DDEEFF" };
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleTableProperties(
                    new TableJustification { Val = TableRowAlignmentValues.Center },
                    new TableIndentation { Width = 720,
                        Type = TableWidthUnitValues.Dxa }),
                    new StyleTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = "DDEEFF" }))
                { Type = StyleValues.Table, StyleId = "ShadedBase" },
                new Style(new BasedOn { Val = "ShadedBase" },
                    new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new Shading
                            { Val = ShadingPatternValues.Clear, Fill = "99DD99" }))
                    { Type = TableStyleOverrideValues.FirstRow },
                    new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new Shading
                            { Val = ShadingPatternValues.Clear, Fill = "FFDDAA" }))
                    { Type = TableStyleOverrideValues.LastRow })
                { Type = StyleValues.Table, StyleId = "ShadedDerived" });
            styles.Styles.Save();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableStyle { Val = "ShadedDerived" },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableLook { FirstRow = firstRow, LastRow = lastRow }),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(Cell("A1"), Cell("B1", "FFCC99")),
                new TableRow(Cell("A2"), Cell("B2")))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var normal = Assert.Single(index.StyleDefinitions, x => x.Name == "Normal");
            Assert.Equal((ushort)24, normal.CharacterFormatting.SizeHalfPoints);
            Assert.Equal((ushort)160, normal.ParagraphFormatting.AfterTwips);
            Assert.Equal((short)278, normal.ParagraphFormatting.LineValue);
            var baseStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "ShadedBase");
            Assert.Equal((short)720, baseStyle.TableFormatting?.TableIndentTwips);
            Assert.Equal((byte)1, baseStyle.TableFormatting?.TableJustification);
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(2, rows.Length);
            Assert.All(rows, x => Assert.Equal((short)720,
                x.Formatting.TableIndentTwips));
            Assert.All(rows, x => Assert.Equal((byte)1,
                x.Formatting.TableJustification));
            Assert.All(rows, x => Assert.All(x.Formatting!.TableCellShadings!,
                shading => Assert.NotNull(shading)));
            Assert.NotEqual(rows[0].Formatting!.TableCellShadings![0]!.FillRgb,
                rows[0].Formatting.TableCellShadings[1]!.FillRgb);
        }
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var projectedCells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal(expectedFills,
            projectedCells.Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
        var projectedBase = Assert.Single(projected.MainDocumentPart
            .StyleDefinitionsPart!.Styles!.Elements<Style>(),
            x => x.StyleName?.Val?.Value == "ShadedBase");
        Assert.Equal(720, projectedBase.StyleTableProperties?
            .GetFirstChild<TableIndentation>()?.Width?.Value);
        Assert.Equal(TableRowAlignmentValues.Center, projectedBase.StyleTableProperties?
            .GetFirstChild<TableJustification>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-cell-shading-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var savedPath = Path.ChangeExtension(sourcePath, ".saved.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(1, (int)opened.Tables.Count);
            Assert.Equal(1, (int)opened.Tables[1].Rows.Alignment);
            Assert.Equal(36f, (float)opened.Tables[1].Rows.LeftIndent);
            Assert.Equal(12.0, (double)opened.Tables[1].Cell(1, 1).Range.Font.Size, 1);
            Assert.Equal(8.0, (double)opened.Tables[1].Cell(1, 1)
                .Range.ParagraphFormat.SpaceAfter, 1);
            opened.SaveAs2(savedPath, 16);
            opened.Close(false);
            opened = null;
            using (var savedStream = File.OpenRead(savedPath))
            using (var saved = WordprocessingDocument.Open(savedStream, false))
            {
                string? EffectiveFill(Table table, TableCell cell)
                {
                    if (cell.TableCellProperties?.Shading?.Fill?.Value is string direct)
                        return direct;
                    var styleId = table.TableProperties?.TableStyle?.Val?.Value;
                    var visited = new HashSet<string>(StringComparer.Ordinal);
                    while (styleId != null && visited.Add(styleId))
                    {
                        var style = saved.MainDocumentPart!.StyleDefinitionsPart?
                            .Styles?.Elements<Style>().FirstOrDefault(x =>
                                x.StyleId?.Value == styleId);
                        if (style?.StyleTableCellProperties?.Shading?.Fill?.Value is string fill)
                            return fill;
                        styleId = style?.BasedOn?.Val?.Value;
                    }
                    return null;
                }
                var savedTable = Assert.Single(saved.MainDocumentPart!.Document!.Body!
                    .Elements<Table>());
                Assert.Equal(expectedFills,
                    savedTable.Descendants<TableCell>()
                        .Select(x => EffectiveFill(savedTable, x)));
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var nativeStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            var nativeTable = Assert.Single(native.MainDocumentPart!.Document!.Body!
                .Elements<Table>());
            Assert.Equal(expectedFills, nativeTable.Descendants<TableCell>()
                .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Equal(TableRowAlignmentValues.Center, nativeTable.TableProperties?
                .GetFirstChild<TableJustification>()?.Val?.Value);
            Assert.Equal(720, nativeTable.TableProperties?
                .GetFirstChild<TableIndentation>()?.Width?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(savedPath);
        }
    }

    [Theory]
    [InlineData(false, 1, false, false, false)]
    [InlineData(true, 1, false, false, false)]
    [InlineData(false, 2, false, false, false)]
    [InlineData(false, 0, false, false, false)]
    [InlineData(false, -1, false, false, false)]
    [InlineData(false, 1, true, false, false)]
    [InlineData(false, 2, true, false, false)]
    [InlineData(false, 1, false, true, false)]
    [InlineData(true, 1, false, true, false)]
    [InlineData(false, 2, false, true, false)]
    [InlineData(false, 0, false, true, false)]
    [InlineData(false, -1, false, true, false)]
    [InlineData(false, 1, true, true, false)]
    [InlineData(false, 2, true, true, false)]
    [InlineData(false, 1, false, false, true)]
    [InlineData(false, 1, true, true, true)]
    public void TableStyleBandsRespectTableLook(bool noBand,
        int bandSize, bool firstAndLastRow, bool vertical, bool directOverride)
    {
        TableCell Cell(char c) => new(
            directOverride && c == 'B'
                ? new TableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "FFCC99" })
                : new TableCellProperties(),
            new Paragraph(new Run(new Text(c.ToString()))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var style = new Style(
                new StyleTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = "DDEEFF" }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "99DD99" }))
                { Type = TableStyleOverrideValues.Band1Horizontal },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "FFDDAA" }))
                { Type = TableStyleOverrideValues.Band2Horizontal },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "99DD99" }))
                { Type = TableStyleOverrideValues.Band1Vertical },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "FFDDAA" }))
                { Type = TableStyleOverrideValues.Band2Vertical },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "BB99EE" }))
                { Type = TableStyleOverrideValues.FirstRow },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "EE9999" }))
                { Type = TableStyleOverrideValues.LastRow },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "BB99EE" }))
                { Type = TableStyleOverrideValues.FirstColumn },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "EE9999" }))
                { Type = TableStyleOverrideValues.LastColumn })
            { Type = StyleValues.Table, StyleId = "Banded" };
            if (bandSize >= 0)
                style.PrependChild(new StyleTableProperties(
                    vertical ? new TableStyleColumnBandSize { Val = bandSize } :
                        new TableStyleRowBandSize { Val = bandSize }));
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var table = new Table(
                new TableProperties(new TableStyle { Val = "Banded" },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    vertical ? firstAndLastRow ? new TableLook
                        { FirstColumn = true, LastColumn = true,
                            FirstRow = false, LastRow = false,
                            NoVerticalBand = false } :
                        new TableLook { Val = noBand ? "0400" : "0200" } :
                    noBand ? new TableLook { Val = "0200" } :
                        firstAndLastRow ? new TableLook { FirstRow = true,
                            LastRow = true, NoHorizontalBand = false } :
                        new TableLook { Val = "0400" }),
                vertical ? new TableGrid(Enumerable.Range(0, 4)
                    .Select(_ => new GridColumn { Width = "1200" })) :
                    new TableGrid(new GridColumn { Width = "2400" }));
            if (vertical)
                table.AppendChild(new TableRow("ABCD".Select(Cell)));
            else
                foreach (var c in "ABCD")
                    table.AppendChild(new TableRow(Cell(c)));
            main.Document = new Document(new Body(table));
            main.Document.Save();
        }
        var expected = noBand || bandSize <= 0
            ? new[] { "DDEEFF", "DDEEFF", "DDEEFF", "DDEEFF" }
            : bandSize == 2
                ? new[] { "99DD99", "99DD99", "FFDDAA", "FFDDAA" }
                : new[] { "99DD99", "FFDDAA", "99DD99", "FFDDAA" };
        if (firstAndLastRow)
        {
            expected[0] = "BB99EE";
            expected[1] = vertical ? "99DD99" : "BB99EE";
            expected[2] = vertical
                ? bandSize == 2 ? "99DD99" : "FFDDAA"
                : "BB99EE";
            expected[3] = "EE9999";
        }
        if (directOverride) expected[1] = "FFCC99";
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Equal(expected.Select(x => x == "DDEEFF" ? 0x00FFEEDDu :
                x == "99DD99" ? 0x0099DD99u :
                x == "BB99EE" ? 0x00EE99BBu :
                x == "EE9999" ? 0x009999EEu :
                x == "FFCC99" ? 0x0099CCFFu : 0x00AADDFFu),
                index.ParagraphStyles.Where(x => x.Formatting?.TableTerminator == true)
                    .SelectMany(x => x.Formatting!.TableCellShadings!
                        .Select(shading => shading!.FillRgb!.Value)));
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        Assert.Equal(expected, Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>()
            .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-banded-source-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? sourceWord = null, generatedWord = null, nativeWord = null;
        try
        {
            sourceWord = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            generatedWord = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            for (var position = 1; position <= 4; position++)
                Assert.Equal((int)sourceWord.Tables[1].Cell(
                    vertical ? 1 : position, vertical ? position : 1).Shading
                    .BackgroundPatternColor,
                    (int)generatedWord.Tables[1].Cell(
                        vertical ? 1 : position, vertical ? position : 1).Shading
                    .BackgroundPatternColor);
            sourceWord.SaveAs2(nativePath, 0);
            sourceWord.Close(false);
            sourceWord = null;
            nativeWord = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            for (var position = 1; position <= 4; position++)
                Assert.Equal((int)generatedWord.Tables[1].Cell(
                    vertical ? 1 : position, vertical ? position : 1).Shading
                    .BackgroundPatternColor,
                    (int)nativeWord.Tables[1].Cell(
                        vertical ? 1 : position, vertical ? position : 1).Shading
                    .BackgroundPatternColor);
            nativeWord.Close(false);
            nativeWord = null;
            using var nativeStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            Assert.Equal(expected, Assert.Single(native.MainDocumentPart!.Document!.Body!
                .Elements<Table>()).Descendants<TableCell>()
                .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (sourceWord != null) sourceWord.Close(false);
            if (generatedWord != null) generatedWord.Close(false);
            if (nativeWord != null) nativeWord.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void WordBandedHMergeStoriesProjectAndWriteBack()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordBandedHMergeStories.doc"));
        var nativeBytes = File.ReadAllBytes(path);
        using (var nativeInput = new MemoryStream(nativeBytes))
        using (var index = new DocTextIndexWalker().Index(nativeInput))
            Assert.Equal(new byte?[] { 2, 1, null }, index.ParagraphStyles
                .First(x => x.Formatting?.TableTerminator == true).Formatting!
                .TableCellHorizontalMerges);

        static void Check(WordprocessingDocument document)
        {
            var main = document.MainDocumentPart!;
            var tables = main.Document!.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()))
                .ToArray();
            Assert.Equal(3, tables.Length);
            foreach (var table in tables)
            {
                Assert.Equal(new[] { "99BBEE", "99BBEE", "99BBEE", "EEBB99",
                    "99BBEE" }, table.Descendants<TableCell>()
                    .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
                var firstRow = table.Elements<TableRow>().First();
                var span = firstRow.Elements<TableCell>().First()
                    .TableCellProperties?.GetFirstChild<GridSpan>()?.Val?.Value;
                Assert.True(span is >= 2,
                    $"Missing span in {table.InnerText}; span {span}, first row has " +
                    $"{firstRow.Elements<TableCell>().Count()} cells.");
                Assert.Equal("3200", firstRow.Elements<TableCell>().First()
                    .TableCellProperties?.TableCellWidth?.Width?.Value);
                Assert.Equal(3, table.Elements<TableRow>().Last()
                    .Elements<TableCell>().Count());
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }

        var projectedBytes = DxpDocToDocx.Project(nativeBytes).DocxBytes;
        using (var stream = new MemoryStream(projectedBytes))
        using (var projected = WordprocessingDocument.Open(stream, false))
            Check(projected);
        var writtenBytes = DxpDocExport.Export(projectedBytes);
        using var writtenStream = new MemoryStream(
            DxpDocToDocx.Project(writtenBytes).DocxBytes);
        using var written = WordprocessingDocument.Open(writtenStream, false);
        Check(written);
    }

    [Theory]
    [InlineData(false, 0)]
    [InlineData(true, 0)]
    [InlineData(false, 1)]
    [InlineData(false, 2)]
    [InlineData(false, 3)]
    [InlineData(true, 3)]
    [InlineData(false, 4)]
    [InlineData(true, 4)]
    public void HorizontalAndVerticalTableBandsPreserveVisibleIntersection(bool stories,
        int edgeMode)
    {
        static TableStyleProperties Band(TableStyleOverrideValues kind, string fill) =>
            new(new TableStyleConditionalFormattingTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = fill })) { Type = kind };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(new RunPropertiesDefault(
                new RunPropertiesBaseStyle(new RunFonts
                    { Ascii = "Times New Roman", HighAnsi = "Times New Roman" })),
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "160", Line = "276",
                        LineRule = LineSpacingRuleValues.Auto }))),
                new Style(
                new StyleTableProperties(new TableStyleRowBandSize { Val = 1 },
                    new TableStyleColumnBandSize { Val = 1 }),
                Band(TableStyleOverrideValues.Band1Horizontal, "99DD99"),
                Band(TableStyleOverrideValues.Band2Horizontal, "FFDDAA"),
                Band(TableStyleOverrideValues.Band1Vertical, "99BBEE"),
                Band(TableStyleOverrideValues.Band2Vertical, "EEBB99"),
                Band(TableStyleOverrideValues.FirstRow, "4477CC"),
                Band(TableStyleOverrideValues.FirstColumn, "77CC44"),
                Band(TableStyleOverrideValues.LastRow, "CC7744"),
                Band(TableStyleOverrideValues.LastColumn, "44CC77"))
                { Type = StyleValues.Table, StyleId = "CrossBands" });
            styles.Styles.Save();
            static TableCell Cell(string text) =>
                new(new Paragraph(new Run(new Text(text))));
            var table = new Table(
                new TableProperties(new TableStyle { Val = "CrossBands" },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    edgeMode != 0 ? new TableLook { FirstRow = edgeMode == 1,
                        FirstColumn = edgeMode == 1, LastRow = edgeMode == 2,
                        LastColumn = edgeMode == 2,
                        NoHorizontalBand = false, NoVerticalBand = false } :
                        new TableLook { Val = "0000" }),
                edgeMode >= 3
                    ? new TableGrid(new GridColumn { Width = "1600" },
                        new GridColumn { Width = "1600" },
                        new GridColumn { Width = "1600" })
                    : new TableGrid(new GridColumn { Width = "1600" },
                        new GridColumn { Width = "1600" }),
                edgeMode == 4
                    ? new TableRow(
                        new TableCell(new TableCellProperties(new HorizontalMerge
                            { Val = MergedCellValues.Restart }),
                            new Paragraph(new Run(new Text("A")))),
                        new TableCell(new TableCellProperties(new HorizontalMerge
                            { Val = MergedCellValues.Continue }), new Paragraph()),
                        Cell("B"))
                    : edgeMode == 3
                    ? new TableRow(new TableCell(
                        new TableCellProperties(new GridSpan { Val = 2 }),
                        new Paragraph(new Run(new Text("A")))), Cell("B"))
                    : new TableRow(Cell("A"), Cell("B")),
                edgeMode >= 3
                    ? new TableRow(Cell("C"), Cell("D"), Cell("E"))
                    : new TableRow(Cell("C"), Cell("D")));
            var body = new Body(table);
            if (stories)
            {
                var header = main.AddNewPart<HeaderPart>();
                header.Header = new Header((Table)table.CloneNode(true));
                header.Header.Save();
                var footer = main.AddNewPart<FooterPart>();
                footer.Footer = new Footer((Table)table.CloneNode(true));
                footer.Footer.Save();
                body.AppendChild(new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) }));
            }
            main.Document = new Document(body);
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var expectedFills = edgeMode switch
        {
            1 => new[] { "4477CC", "4477CC", "77CC44", "99BBEE" },
            2 => new[] { "99BBEE", "44CC77", "CC7744", "CC7744" },
            3 => new[] { "99BBEE", "EEBB99", "99BBEE", "EEBB99", "99BBEE" },
            4 => new[] { "99BBEE", "99BBEE", "99BBEE", "EEBB99", "99BBEE" },
            _ => new[] { "99BBEE", "EEBB99", "99BBEE", "EEBB99" }
        };
        Assert.Equal(expectedFills,
            Assert.Single(projected.MainDocumentPart!.Document!.Body!
                .Elements<Table>()).Descendants<TableCell>()
                .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
        if (edgeMode >= 3)
            Assert.Equal(2, projected.MainDocumentPart.Document.Body!
                .Elements<Table>().Single().Elements<TableRow>().First()
                .Elements<TableCell>().First().TableCellProperties?
                .GetFirstChild<GridSpan>()?.Val?.Value);
        if (stories)
        {
            foreach (var storyTable in projected.MainDocumentPart.HeaderParts
                .SelectMany(x => x.Header!.Elements<Table>())
                .Concat(projected.MainDocumentPart.FooterParts
                    .SelectMany(x => x.Footer!.Elements<Table>())))
                Assert.Equal(expectedFills,
                    storyTable.Descendants<TableCell>()
                        .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Single(projected.MainDocumentPart.HeaderParts);
            Assert.Single(projected.MainDocumentPart.FooterParts);
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-cross-bands-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? original = null, generated = null;
        try
        {
            original = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            generated = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            foreach (var row in new[] { 1, 2 })
            for (var column = 1; column <= (edgeMode >= 3 && row == 2 ? 3 : 2);
                column++)
            {
                // Word exposes hMerge restart/continuation as two source cells
                // with automatic shading; the DOC contains one merged cell.
                if (edgeMode == 4) continue;
                var sourceColumn = edgeMode == 4 && row == 1 ? 3 : column;
                Assert.True((int)original.Tables[1].Rows[row].Cells[sourceColumn].Shading
                    .BackgroundPatternColor == (int)generated.Tables[1].Rows[row]
                    .Cells[column].Shading.BackgroundPatternColor,
                    $"Different Word fill at row {row}, column {column}.");
            }
            if (stories)
                foreach (var sectionKind in new[] { 0, 1 })
                foreach (var row in new[] { 1, 2 })
                for (var column = 1; column <= (edgeMode >= 3 && row == 2 ? 3 : 2);
                    column++)
                {
                    dynamic originalStory = sectionKind == 0
                        ? original.Sections[1].Headers[1]
                        : original.Sections[1].Footers[1];
                    dynamic generatedStory = sectionKind == 0
                        ? generated.Sections[1].Headers[1]
                        : generated.Sections[1].Footers[1];
                    if (edgeMode == 4) continue;
                    var sourceColumn = edgeMode == 4 && row == 1 ? 3 : column;
                    Assert.Equal((int)originalStory.Range.Tables[1].Rows[row]
                        .Cells[sourceColumn].Shading.BackgroundPatternColor,
                        (int)generatedStory.Range.Tables[1].Rows[row]
                            .Cells[column].Shading.BackgroundPatternColor);
                }
            original.SaveAs2(nativePath, 0);
            original.Close(false);
            original = null;
            using var nativeStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            Assert.Equal(expectedFills,
                Assert.Single(native.MainDocumentPart!.Document!.Body!
                    .Elements<Table>()).Descendants<TableCell>()
                    .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
            if (edgeMode >= 3)
                Assert.Equal(2, native.MainDocumentPart.Document.Body!
                    .Elements<Table>().Single().Elements<TableRow>().First()
                    .Elements<TableCell>().First().TableCellProperties?
                    .GetFirstChild<GridSpan>()?.Val?.Value);
            if (stories)
                foreach (var storyTable in native.MainDocumentPart.HeaderParts
                    .SelectMany(x => x.Header!.Elements<Table>())
                    .Concat(native.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>())))
                    Assert.Equal(expectedFills,
                        storyTable.Descendants<TableCell>()
                            .Select(x => x.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (original != null) original.Close(false);
            if (generated != null) generated.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocNormalStyleHighlightProjectsAcrossUnstyledStories()
    {
        const string text = "Normal highlight\r";
        var normal = new DocStyleDefinition(0, "Normal", 1, null, null,
            new DocCharacterFormatting(null, null, null, HighlightCode: 7));
        var story = new DocPlainTextStory(text, [], [])
        {
            Paragraphs = [new DocStoryParagraphRange(0, text.Length,
                DocParagraphEnd.ParagraphMark)]
        };
        using var binary = new MemoryStream();
        DocPlainTextWriter.Write(binary, new DocPlainTextDocument(story,
            [new DocPlainTextSection(text.Length,
                [null, story, null, story, null, null])], Styles: [normal]));
        binary.Position = 0;
        using var index = new DocTextIndexWalker().Index(binary);
        Assert.Equal((byte)7, Assert.Single(index.StyleDefinitions,
            x => x.Index == 0).CharacterFormatting.HighlightCode);
        var projected = DxpDocToDocx.Project(binary.ToArray()).DocxBytes;
        using (var docx = WordprocessingDocument.Open(new MemoryStream(projected), false))
        {
            Assert.Empty(new OpenXmlValidator().Validate(docx));
            var main = docx.MainDocumentPart!;
            foreach (var paragraph in new[]
            {
                main.Document!.Body!.Elements<Paragraph>().First(),
                main.HeaderParts.Single().Header!.Elements<Paragraph>().First(),
                main.FooterParts.Single().Footer!.Elements<Paragraph>().First()
            })
                Assert.Equal(HighlightColorValues.Yellow,
                    paragraph.Elements<Run>().First(x => x.InnerText.Contains("Normal"))
                        .RunProperties?.Highlight?.Val?.Value);
        }
        var rewritten = DxpDocExport.Export(projected);
        using var reopenedStream = new MemoryStream(rewritten);
        using var reopened = new DocTextIndexWalker().Index(reopenedStream);
        Assert.Contains(reopened.ReadStory("Main").Runs,
            x => x.Formatting.HighlightCode == 7);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(binary.ToArray(), projected, 0.04, 1,
                ".docx", ".doc");
            AssertWordPageRenderClose(binary.ToArray(), rewritten, 0.04, 1,
                ".doc", ".doc");
        }
    }

    [Fact]
    public void DocParagraphStyleHighlightProjectsToValidVisibleRunFormatting()
    {
        const string text = "One Two Three\r";
        var style = new DocStyleDefinition(20, "Highlight Style", 1, 0, null,
            new DocCharacterFormatting(null, null, null, HighlightCode: 7));
        var characterStyle = new DocStyleDefinition(21, "Cyan Character", 2, null,
            null, new DocCharacterFormatting(null, null, null, HighlightCode: 3));
        var runs = new DocPlainTextFormatRun[]
        {
            new(0, 3, new DocCharacterFormatting(null, null, null,
                CharacterStyleIndex: 21)),
            new(4, 7, new DocCharacterFormatting(null, null, null,
                CharacterStyleIndex: 21, HighlightCode: 0))
        };
        var paragraphStyle = new DocPlainTextParagraphStyleRun(0, text.Length, 20);
        var story = new DocPlainTextStory(text,
            runs.Select(x => new DocStoryCharacterRun(x.Start, x.End,
                x.Formatting)).ToArray(),
            [new DocStoryParagraphStyleRun(paragraphStyle.Start,
                paragraphStyle.End, paragraphStyle.StyleIndex)])
        {
            Paragraphs = [new DocStoryParagraphRange(0, text.Length,
                DocParagraphEnd.ParagraphMark)]
        };
        using var binary = new MemoryStream();
        DocPlainTextWriter.Write(binary, new DocPlainTextDocument(story,
            [new DocPlainTextSection(text.Length,
                [null, story, null, story, null, null])],
            Styles: [style, characterStyle]));
        binary.Position = 0;
        using var index = new DocTextIndexWalker().Index(binary);
        Assert.Equal((byte)7, Assert.Single(index.StyleDefinitions,
            x => x.Index == 20).CharacterFormatting.HighlightCode);
        var projected = DxpDocToDocx.Project(binary.ToArray()).DocxBytes;
        using (var docx = WordprocessingDocument.Open(new MemoryStream(projected), false))
        {
            Assert.Empty(new OpenXmlValidator().Validate(docx));
            var main = docx.MainDocumentPart!;
            var paragraphs = new[]
            {
                main.Document!.Body!.Elements<Paragraph>().First(),
                main.HeaderParts.Single().Header!.Elements<Paragraph>().First(),
                main.FooterParts.Single().Footer!.Elements<Paragraph>().First()
            };
            foreach (var paragraph in paragraphs)
            {
                Assert.Equal("DocStyle20",
                    paragraph.ParagraphProperties?.ParagraphStyleId?.Val?.Value);
                var visible = paragraph.Elements<Run>()
                    .Where(x => !string.IsNullOrEmpty(x.InnerText)).ToArray();
                Assert.Equal(HighlightColorValues.Cyan,
                    visible.First(x => x.InnerText.Contains("One"))
                        .RunProperties?.Highlight?.Val?.Value);
                Assert.Equal(HighlightColorValues.None,
                    visible.First(x => x.InnerText.Contains("Two"))
                        .RunProperties?.Highlight?.Val?.Value);
                Assert.Equal(HighlightColorValues.Yellow,
                    visible.First(x => x.InnerText.Contains("Three"))
                        .RunProperties?.Highlight?.Val?.Value);
            }
            Assert.Null(docx.MainDocumentPart.StyleDefinitionsPart!.Styles!
                .Elements<Style>().Single(x => x.StyleId?.Value == "DocStyle20")
                .StyleRunProperties?.GetFirstChild<Highlight>());
        }
        var rewritten = DxpDocExport.Export(projected);
        using var reopenedStream = new MemoryStream(rewritten);
        using var reopened = new DocTextIndexWalker().Index(reopenedStream);
        Assert.Contains(reopened.ReadStory("Main").Runs,
            x => x.Formatting.HighlightCode == 7);
        Assert.Contains(reopened.ReadStory("Main").Runs,
            x => x.Formatting.HighlightCode == 3);
        Assert.Contains(reopened.ReadStory("Main").Runs,
            x => x.Formatting.HighlightCode == 0);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(binary.ToArray(), projected, 0.04, 1,
                ".docx", ".doc");
            AssertWordPageRenderClose(binary.ToArray(), rewritten, 0.04, 1,
                ".doc", ".doc");
        }
    }

    [Fact]
