            void AssertMixedCellOrientations(dynamic opened)
            {
                dynamic body = opened.Tables.Item(1);
                dynamic header = opened.Sections.Item(1).Headers.Item(1)
                    .Range.Tables.Item(1);
                dynamic footer = opened.Sections.Item(1).Footers.Item(1)
                    .Range.Tables.Item(1);
                Assert.Equal(new[] { 3, 2, 4, 1 }, new[]
                {
                    (int)body.Cell(1, 1).Range.Orientation,
                    (int)body.Cell(1, 2).Range.Orientation,
                    (int)body.Cell(2, 1).Range.Orientation,
                    (int)body.Cell(2, 2).Range.Orientation
                });
                Assert.Equal(new[] { 2, 1 }, new[]
                {
                    (int)header.Cell(1, 1).Range.Orientation,
                    (int)header.Cell(1, 2).Range.Orientation
                });
                Assert.Equal(new[] { 4, 3 }, new[]
                {
                    (int)footer.Cell(1, 1).Range.Orientation,
                    (int)footer.Cell(1, 2).Range.Orientation
                });
            }
            if (fixtureName == "WordMixedRotatedCellsAllStories.docx")
            {
                dynamic native = word.Documents.Open(Path.ChangeExtension(fixture, ".doc"),
                    ReadOnly: true, AddToRecentFiles: false);
                try { AssertMixedCellOrientations(native); }
                finally { native.Close(false); }
            }
            void AssertInheritedStyledRotatedOrientations(dynamic opened)
