    [Fact]
    public void WordTwoFloatingPicturesSurviveDocxToDocAndBack()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordTwoFloatingPicturesBody.docx"));
        var sourceHashes = new Dictionary<string, string>();
        using (var source = WordprocessingDocument.Open(path, false))
            foreach (var image in source.MainDocumentPart!.ImageParts)
            {
                using var data = image.GetStream();
                sourceHashes.Add(image.ContentType,
                    Convert.ToHexString(SHA256.HashData(data)));
            }
        var binary = DxpDocExport.Export(File.ReadAllBytes(path));
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var pictures = DocFloatingPictureReader.ReadMain(index.Structure);
            Assert.Equal(2, pictures.Count);
            Assert.Equal(new uint[] { 0, 1 }, pictures.Select(x => x.Cp));
            Assert.Equal(new[] { "image/jpeg", "image/png" },
                pictures.Select(x => x.ContentType));
            foreach (var picture in pictures)
                Assert.Equal(sourceHashes[picture.ContentType],
                    Convert.ToHexString(SHA256.HashData(picture.Bytes)));
            Assert.NotEqual(Convert.ToHexString(SHA256.HashData(pictures[0].Bytes)),
                Convert.ToHexString(SHA256.HashData(pictures[1].Bytes)));
        }
        var projected = DxpDocToDocx.Project(binary);
        Assert.False(projected.Coverage.OmittedCharacters.ContainsKey(8));
        using var stream = new MemoryStream(projected.DocxBytes);
        using var document = WordprocessingDocument.Open(stream, false);
        Assert.Equal(2, document.MainDocumentPart!.Document!.Body!.Descendants<
            DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>().Count());
        Assert.Equal(2, document.MainDocumentPart.ImageParts.Count());
        foreach (var image in document.MainDocumentPart.ImageParts)
        {
            using var data = image.GetStream();
            Assert.Equal(sourceHashes[image.ContentType],
                Convert.ToHexString(SHA256.HashData(data)));
        }
        Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-two-floating-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(2, (int)opened.Shapes.Count);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

