    [Fact]
    public void WordFloatingPicturesInAllStoriesSurviveDocxToDocAndBack()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordFloatingPngAllStories.docx"));
        string sourceImageHash;
        using (var source = WordprocessingDocument.Open(path, false))
        using (var image = Assert.Single(source.MainDocumentPart!.ImageParts).GetStream())
            sourceImageHash = Convert.ToHexString(SHA256.HashData(image));
        var binary = DxpDocExport.Export(File.ReadAllBytes(path));
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(3, index.CharacterFormatting.Count(x =>
                x.Formatting.Special == true &&
                x.Formatting.PictureDataOffset == 0));
            var bodyPicture = Assert.Single(DocFloatingPictureReader.ReadMain(index.Structure));
            var headerPictures = DocFloatingPictureReader.ReadHeaders(index.Structure);
            Assert.Equal(2, headerPictures.Count);
            Assert.All(headerPictures, x => Assert.Equal("image/png", x.ContentType));
            var floatingStories = new[]
            {
                index.ReadStory("Main"),
                index.HeaderStories[7].ReadIndexedContent(),
                index.HeaderStories[9].ReadIndexedContent()
            };
            foreach (var story in floatingStories)
            {
                var entry = Assert.Single(story.FloatingPictures);
                var picture = Assert.Single(entry.Value);
                Assert.Equal(entry.Key, picture.Cp);
                Assert.Equal(story.Text.CpStart + (uint)picture.Cp, picture.SourceCp);
                Assert.Equal(index.GetTextOffset(picture.SourceCp!.Value),
                    picture.SourceTextOffset);
                Assert.True(picture.WidthEmu > 0);
                Assert.True(picture.HeightEmu > 0);
                Assert.Equal(sourceImageHash,
                    Convert.ToHexString(SHA256.HashData(picture.Bytes)));
            }
            Assert.Empty(index.HeaderStories[7].ReadIndexedContent().Bookmarks);
            foreach (var picture in headerPictures.Prepend(bodyPicture))
                Assert.Equal(sourceImageHash,
                    Convert.ToHexString(SHA256.HashData(picture.Bytes)));
        }
        var projected = DxpDocToDocx.Project(binary);
        Assert.False(projected.Coverage.OmittedCharacters.ContainsKey(8));
        using var stream = new MemoryStream(projected.DocxBytes);
        using var document = WordprocessingDocument.Open(stream, false);
        Assert.Single(document.MainDocumentPart!.Document!.Body!.Descendants<
            DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
        Assert.Contains(document.MainDocumentPart.HeaderParts,
            x => x.Header!.Descendants<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>().Count() == 1);
        Assert.Contains(document.MainDocumentPart.FooterParts,
            x => x.Footer!.Descendants<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>().Count() == 1);
        Assert.Contains(document.MainDocumentPart.HeaderParts,
            x => x.Header!.InnerText.Contains("Header floating picture"));
        Assert.Contains(document.MainDocumentPart.FooterParts,
            x => x.Footer!.InnerText.Contains("Footer floating picture"));
        Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-floating-all-stories-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(1, (int)opened.Shapes.Count);
                Assert.Equal(1, (int)opened.Sections(1).Headers(1).Range.ShapeRange.Count);
                Assert.Equal(1, (int)opened.Sections(1).Footers(1).Range.ShapeRange.Count);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

    [Fact]
    public void FloatingPicturesKeepDistinctFourSidedCropsAcrossStories()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordFloatingPngAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var stories = new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!, Assert.Single(main.HeaderParts,
                    x => x.Header!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Header!,
                Assert.Single(main.FooterParts,
                    x => x.Footer!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Footer!
            };
            for (var i = 0; i < stories.Length; i++)
            {
                var fill = Assert.Single(stories[i].Descendants<
                    DocumentFormat.OpenXml.Drawing.Pictures.BlipFill>());
                var crop = new DocumentFormat.OpenXml.Drawing.SourceRectangle
                {
                    Left = 10000 + i * 1000, Top = 5000 + i * 1000,
                    Right = 7000 + i * 1000, Bottom = 3000 + i * 1000
                };
                fill.InsertAfter(crop, fill.GetFirstChild<
                    DocumentFormat.OpenXml.Drawing.Blip>()!);
                if (stories[i] is DocumentFormat.OpenXml.Wordprocessing.Document body)
                    body.Save();
                else if (stories[i] is Header header) header.Save();
                else ((Footer)stories[i]).Save();
            }
        }
        var sourceBytes = source.ToArray();
        var binary = DxpDocExport.Export(sourceBytes);
        static void Check(DocTextIndex index)
        {
            var pictures = DocFloatingPictureReader.ReadMain(index.Structure)
                .Concat(DocFloatingPictureReader.ReadHeaders(index.Structure))
                .OrderBy(x => x.Crop!.Left).ToArray();
            Assert.Equal(3, pictures.Length);
            for (var i = 0; i < pictures.Length; i++)
            {
                var crop = pictures[i].Crop!;
                Assert.InRange(crop.Left, .10 + i * .01 - .0001,
                    .10 + i * .01 + .0001);
                Assert.InRange(crop.Top, .05 + i * .01 - .0001,
                    .05 + i * .01 + .0001);
                Assert.InRange(crop.Right, .07 + i * .01 - .0001,
                    .07 + i * .01 + .0001);
                Assert.InRange(crop.Bottom, .03 + i * .01 - .0001,
                    .03 + i * .01 + .0001);
            }
        }
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        var projected = DxpDocToDocx.Project(binary);
        static void CheckProjectedCrops(WordprocessingDocument document)
        {
            var main = document.MainDocumentPart!;
            var crops = main.Document!.Descendants<
                    DocumentFormat.OpenXml.Drawing.SourceRectangle>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Descendants<
                    DocumentFormat.OpenXml.Drawing.SourceRectangle>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Descendants<
                    DocumentFormat.OpenXml.Drawing.SourceRectangle>()))
                .OrderBy(x => x.Left!.Value).ToArray();
            Assert.Equal(3, crops.Length);
            for (var i = 0; i < crops.Length; i++)
            {
                Assert.InRange(crops[i].Left!.Value, 10000 + i * 1000 - 10,
                    10000 + i * 1000 + 10);
                Assert.InRange(crops[i].Top!.Value, 5000 + i * 1000 - 10,
                    5000 + i * 1000 + 10);
                Assert.InRange(crops[i].Right!.Value, 7000 + i * 1000 - 10,
                    7000 + i * 1000 + 10);
                Assert.InRange(crops[i].Bottom!.Value, 3000 + i * 1000 - 10,
                    3000 + i * 1000 + 10);
            }
        }
        using (var stream = new MemoryStream(projected.DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            CheckProjectedCrops(document);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var rewritten = DxpDocExport.Export(projected.DocxBytes);
        using (var input = new MemoryStream(rewritten))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(sourceBytes, binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var nativePath = Path.Combine(Path.GetTempPath(),
                $"docxport-cropped-stories-{Guid.NewGuid():N}.doc");
            var sourcePath = Path.ChangeExtension(nativePath, ".docx");
            File.WriteAllBytes(sourcePath, sourceBytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var native = new DocTextIndexWalker().Index(nativePath);
                Check(native);
                using var nativeProjection = new MemoryStream(
                    new DocToDocxProjector().Project(native).DocxBytes);
                using var projectedNative = WordprocessingDocument.Open(
                    nativeProjection, false);
                CheckProjectedCrops(projectedNative);
                Assert.Empty(new OpenXmlValidator().Validate(projectedNative));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void FloatingPictureAlignmentSurvivesWordDocAndDocxRoutes(
        bool insideOutside)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordFloatingPngAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var stories = new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!, Assert.Single(main.HeaderParts,
                    x => x.Header!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Header!,
                Assert.Single(main.FooterParts,
                    x => x.Footer!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Footer!
            };
            var horizontalNames = insideOutside
                ? new[] { "inside", "outside", "inside" }
                : new[] { "center", "right", "left" };
            var verticalNames = insideOutside
                ? new[] { "outside", "inside", "outside" }
                : new[] { "top", "center", "bottom" };
            for (var i = 0; i < stories.Length; i++)
            {
                var anchor = Assert.Single(stories[i].Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
                var horizontal = anchor.HorizontalPosition!;
                horizontal.RemoveAllChildren<DocumentFormat.OpenXml.Drawing.Wordprocessing.PositionOffset>();
                horizontal.AppendChild(new DocumentFormat.OpenXml.Drawing.Wordprocessing.HorizontalAlignment
                { Text = horizontalNames[i] });
                var vertical = anchor.VerticalPosition!;
                vertical.RemoveAllChildren<DocumentFormat.OpenXml.Drawing.Wordprocessing.PositionOffset>();
                vertical.AppendChild(new DocumentFormat.OpenXml.Drawing.Wordprocessing.VerticalAlignment
                { Text = verticalNames[i] });
                if (stories[i] is DocumentFormat.OpenXml.Wordprocessing.Document body)
                    body.Save();
                else if (stories[i] is Header header) header.Save();
                else ((Footer)stories[i]).Save();
            }
            if (insideOutside)
            {
                main.Document!.Body!.PrependChild(new Paragraph(new Run(
                    new Break { Type = BreakValues.Page })));
                main.Document.Save();
            }
        }
        var sourceBytes = source.ToArray();
        var binary = DxpDocExport.Export(sourceBytes);
        void Check(DocTextIndex index)
        {
            var picture = Assert.Single(DocFloatingPictureReader.ReadMain(index.Structure));
            Assert.Equal(insideOutside ? (byte)4 : (byte)2,
                picture.HorizontalAlignment);
            Assert.Equal(insideOutside ? (byte)5 : (byte)1,
                picture.VerticalAlignment);
            var storyPictures = DocFloatingPictureReader.ReadHeaders(index.Structure);
            Assert.Contains(storyPictures, x =>
                x.HorizontalAlignment == (insideOutside ? 5 : 3) &&
                x.VerticalAlignment == (insideOutside ? 4 : 2));
            Assert.Contains(storyPictures, x =>
                x.HorizontalAlignment == (insideOutside ? 4 : 1) &&
                x.VerticalAlignment == (insideOutside ? 5 : 3));
        }
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        var projected = DxpDocToDocx.Project(binary);
        using (var input = new MemoryStream(projected.DocxBytes))
        using (var document = WordprocessingDocument.Open(input, false))
        {
            var anchor = Assert.Single(document.MainDocumentPart!.Document!
                .Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
            Assert.Equal(insideOutside ? "inside" : "center", anchor.HorizontalPosition?.GetFirstChild<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.HorizontalAlignment>()?.Text);
            Assert.Equal(insideOutside ? "outside" : "top", anchor.VerticalPosition?.GetFirstChild<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.VerticalAlignment>()?.Text);
            Assert.Contains(document.MainDocumentPart.HeaderParts,
                x => x.Header!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.HorizontalAlignment>()
                    .Any(a => a.Text == (insideOutside ? "outside" : "right")));
            Assert.Contains(document.MainDocumentPart.FooterParts,
                x => x.Footer!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.VerticalAlignment>()
                    .Any(a => a.Text == (insideOutside ? "outside" : "bottom")));
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var rewritten = DxpDocExport.Export(projected.DocxBytes);
        using (var input = new MemoryStream(rewritten))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(sourceBytes, binary, 0.04);
            if (insideOutside)
                AssertWordPageRenderClose(sourceBytes, binary, 0.047, 2);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-aligned-picture-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, sourceBytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var native = new DocTextIndexWalker().Index(nativePath);
            Check(native);
            using var nativeProjection = new MemoryStream(
                new DocToDocxProjector().Project(native).DocxBytes);
            using var projectedNative = WordprocessingDocument.Open(nativeProjection, false);
            var nativeAnchor = Assert.Single(projectedNative.MainDocumentPart!
                .Document!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
            Assert.Equal(insideOutside ? "inside" : "center", nativeAnchor.HorizontalPosition?.GetFirstChild<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.HorizontalAlignment>()?.Text);
            Assert.Equal(insideOutside ? "outside" : "top", nativeAnchor.VerticalPosition?.GetFirstChild<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.VerticalAlignment>()?.Text);
            Assert.Empty(new OpenXmlValidator().Validate(projectedNative));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
    }

    [Fact]
    public void FloatingPictureWrapDistancesSurviveAllStoriesAndWordDoc()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordFloatingPngAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var stories = new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!, Assert.Single(main.HeaderParts,
                    x => x.Header!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Header!,
                Assert.Single(main.FooterParts,
                    x => x.Footer!.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                        .Any()).Footer!
            };
            for (var i = 0; i < stories.Length; i++)
            {
                var anchor = Assert.Single(stories[i].Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
                anchor.DistanceFromTop = checked((uint)(12700 * (i + 1)));
                anchor.DistanceFromBottom = checked((uint)(25400 * (i + 1)));
                anchor.DistanceFromLeft = checked((uint)(38100 * (i + 1)));
                anchor.DistanceFromRight = checked((uint)(50800 * (i + 1)));
                if (stories[i] is DocumentFormat.OpenXml.Wordprocessing.Document body)
                    body.Save();
                else if (stories[i] is Header header) header.Save();
                else ((Footer)stories[i]).Save();
            }
        }
        var sourceBytes = source.ToArray();
        var binary = DxpDocExport.Export(sourceBytes);
        static void Check(DocTextIndex index)
        {
            var pictures = DocFloatingPictureReader.ReadMain(index.Structure)
                .Concat(DocFloatingPictureReader.ReadHeaders(index.Structure))
                .OrderBy(x => x.DistanceLeftEmu).ToArray();
            Assert.Equal(3, pictures.Length);
            for (var i = 0; i < pictures.Length; i++)
            {
                Assert.Equal(12700 * (i + 1), pictures[i].DistanceTopEmu);
                Assert.Equal(25400 * (i + 1), pictures[i].DistanceBottomEmu);
                Assert.Equal(38100 * (i + 1), pictures[i].DistanceLeftEmu);
                Assert.Equal(50800 * (i + 1), pictures[i].DistanceRightEmu);
            }
        }
        static void CheckProjection(WordprocessingDocument document)
        {
            var main = document.MainDocumentPart!;
            var anchors = main.Document!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Descendants<
                    DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>()))
                .OrderBy(x => x.DistanceFromLeft!.Value).ToArray();
            Assert.Equal(3, anchors.Length);
            for (var i = 0; i < anchors.Length; i++)
            {
                Assert.Equal(checked((uint)(12700 * (i + 1))),
                    anchors[i].DistanceFromTop!.Value);
                Assert.Equal(checked((uint)(25400 * (i + 1))),
                    anchors[i].DistanceFromBottom!.Value);
                Assert.Equal(checked((uint)(38100 * (i + 1))),
                    anchors[i].DistanceFromLeft!.Value);
                Assert.Equal(checked((uint)(50800 * (i + 1))),
                    anchors[i].DistanceFromRight!.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        var projected = DxpDocToDocx.Project(binary);
        using (var input = new MemoryStream(projected.DocxBytes))
        using (var document = WordprocessingDocument.Open(input, false))
            CheckProjection(document);
        var rewritten = DxpDocExport.Export(projected.DocxBytes);
        using (var input = new MemoryStream(rewritten))
        using (var index = new DocTextIndexWalker().Index(input)) Check(index);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(sourceBytes, binary, 0.043);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-wrap-distance-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, sourceBytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var native = new DocTextIndexWalker().Index(nativePath);
            Check(native);
            using var nativeProjection = new MemoryStream(
                new DocToDocxProjector().Project(native).DocxBytes);
            using var projectedNative = WordprocessingDocument.Open(nativeProjection, false);
            CheckProjection(projectedNative);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData("WordCroppedFloatingPngBody", 0d, 0d)]
    [InlineData("WordFourSidedCroppedFloatingPngBody", 0.06666d, 0.08888d)]
    public void WordCroppedFloatingPicturePreservesCropBothDirections(
        string fixtureName, double expectedRight, double expectedBottom)
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var nativePath = Path.Combine(directory, fixtureName + ".doc");
        using (var native = new DocTextIndexWalker().Index(nativePath))
        {
            var picture = Assert.Single(DocFloatingPictureReader.ReadMain(native.Structure));
            Assert.NotNull(picture.Crop);
            Assert.InRange(picture.Crop.Left, 0.1332, 0.1334);
            Assert.InRange(picture.Crop.Top, 0.0999, 0.1001);
            Assert.InRange(picture.Crop.Right, expectedRight - 0.0001,
                expectedRight + 0.0001);
            Assert.InRange(picture.Crop.Bottom, expectedBottom - 0.0001,
                expectedBottom + 0.0001);
            var projected = new DocToDocxProjector().Project(native);
            using var stream = new MemoryStream(projected.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var crop = Assert.Single(document.MainDocumentPart!.Document!.Descendants<
                DocumentFormat.OpenXml.Drawing.SourceRectangle>());
            Assert.InRange(crop.Left!.Value, 13320, 13340);
            Assert.InRange(crop.Top!.Value, 9990, 10010);
            Assert.InRange(crop.Right?.Value ?? 0, (int)(expectedRight * 100000) - 10,
                (int)(expectedRight * 100000) + 10);
            Assert.InRange(crop.Bottom?.Value ?? 0, (int)(expectedBottom * 100000) - 10,
                (int)(expectedBottom * 100000) + 10);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }

        var binary = DxpDocExport.Export(File.ReadAllBytes(Path.Combine(directory,
            fixtureName + ".docx")));
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var picture = Assert.Single(DocFloatingPictureReader.ReadMain(index.Structure));
            Assert.NotNull(picture.Crop);
            Assert.InRange(picture.Crop.Left, 0.1332, 0.1334);
            Assert.InRange(picture.Crop.Top, 0.0999, 0.1001);
            Assert.InRange(picture.Crop.Right, expectedRight - 0.0001,
                expectedRight + 0.0001);
            Assert.InRange(picture.Crop.Bottom, expectedBottom - 0.0001,
                expectedBottom + 0.0001);
        }
        var roundTrip = DxpDocToDocx.Project(binary);
        using (var stream = new MemoryStream(roundTrip.DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var crop = Assert.Single(document.MainDocumentPart!.Document!.Descendants<
                DocumentFormat.OpenXml.Drawing.SourceRectangle>());
            Assert.InRange(crop.Left!.Value, 13320, 13340);
            Assert.InRange(crop.Top!.Value, 9990, 10010);
            Assert.InRange(crop.Right?.Value ?? 0, (int)(expectedRight * 100000) - 10,
                (int)(expectedRight * 100000) + 10);
            Assert.InRange(crop.Bottom?.Value ?? 0, (int)(expectedBottom * 100000) - 10,
                (int)(expectedBottom * 100000) + 10);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-cropped-floating-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(1, (int)opened.Shapes.Count);
                Assert.InRange((double)opened.Shapes[1].PictureFormat.CropLeft, 11.8, 12.2);
                Assert.InRange((double)opened.Shapes[1].PictureFormat.CropTop, 8.8, 9.2);
                Assert.InRange((double)opened.Shapes[1].PictureFormat.CropRight,
                    expectedRight == 0 ? -0.2 : 5.8, expectedRight == 0 ? 0.2 : 6.2);
                Assert.InRange((double)opened.Shapes[1].PictureFormat.CropBottom,
                    expectedBottom == 0 ? -0.2 : 7.8, expectedBottom == 0 ? 0.2 : 8.2);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

