                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

    [Theory]
    [InlineData("WordPagePositionedFloatingPngBody", (byte)1, (byte)1,
        "page", "page", 2400, 3200)]
    [InlineData("WordParagraphPositionedFloatingPngBody", (byte)0, (byte)2,
        "margin", "paragraph", 1600, 600)]
    [InlineData("WordColumnPositionedFloatingPngBody", (byte)2, (byte)0,
        "column", "margin", 1400, 1800)]
    public void WordFloatingPictureOriginsSurviveBothDirections(string fixtureName,
        byte horizontalOrigin, byte verticalOrigin, string horizontalXml, string verticalXml,
        int leftTwips, int topTwips)
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        using (var native = new DocTextIndexWalker().Index(
            Path.Combine(directory, fixtureName + ".doc")))
        {
            var picture = Assert.Single(DocFloatingPictureReader.ReadMain(native.Structure));
            Assert.Equal(horizontalOrigin, picture.HorizontalOrigin);
            Assert.Equal(verticalOrigin, picture.VerticalOrigin);
            Assert.Equal(leftTwips, picture.LeftTwips);
            Assert.Equal(topTwips, picture.TopTwips);
            var projected = new DocToDocxProjector().Project(native);
            using var stream = new MemoryStream(projected.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var anchor = Assert.Single(document.MainDocumentPart!.Document!.Descendants<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
            Assert.Equal(horizontalXml, anchor.HorizontalPosition!.RelativeFrom!.InnerText);
            Assert.Equal(verticalXml, anchor.VerticalPosition!.RelativeFrom!.InnerText);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var binary = DxpDocExport.Export(File.ReadAllBytes(Path.Combine(directory,
            fixtureName + ".docx")));
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var picture = Assert.Single(DocFloatingPictureReader.ReadMain(index.Structure));
            Assert.Equal(horizontalOrigin, picture.HorizontalOrigin);
            Assert.Equal(verticalOrigin, picture.VerticalOrigin);
            Assert.InRange(picture.LeftTwips, leftTwips - 1, leftTwips + 1);
            Assert.InRange(picture.TopTwips, topTwips - 1, topTwips + 1);
        }
        var roundTrip = DxpDocToDocx.Project(binary);
        using (var stream = new MemoryStream(roundTrip.DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var anchor = Assert.Single(document.MainDocumentPart!.Document!.Descendants<
                DocumentFormat.OpenXml.Drawing.Wordprocessing.Anchor>());
            Assert.Equal(horizontalXml, anchor.HorizontalPosition!.RelativeFrom!.InnerText);
            Assert.Equal(verticalXml, anchor.VerticalPosition!.RelativeFrom!.InnerText);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-origins-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal((int)horizontalOrigin,
                    (int)opened.Shapes[1].RelativeHorizontalPosition);
                Assert.Equal((int)verticalOrigin,
                    (int)opened.Shapes[1].RelativeVerticalPosition);
                Assert.InRange((double)opened.Shapes[1].Left,
                    leftTwips / 20d - 0.1, leftTwips / 20d + 0.1);
                Assert.InRange((double)opened.Shapes[1].Top,
                    topTwips / 20d - 0.1, topTwips / 20d + 0.1);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

