    [Fact]
    public void InheritedDisplayStyleSurvivesBodyHeaderFooterRoundTrips()
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var sourceDocx = File.ReadAllBytes(Path.Combine(directory,
            "WordInheritedDisplayStyleStories.docx"));
        var nativeDoc = File.ReadAllBytes(Path.Combine(directory,
            "WordInheritedDisplayStyleStories.doc"));
        var generatedDoc = DxpDocExport.Export(sourceDocx);
        foreach (var binary in new[] { nativeDoc, generatedDoc })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var baseStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "BaseDisplay");
            var derived = Assert.Single(index.StyleDefinitions,
                x => x.Name == "DerivedDisplay");
            Assert.Equal(baseStyle.Index, derived.BasedOnIndex);
            Assert.Equal((ushort)28, baseStyle.CharacterFormatting.SizeHalfPoints);
            Assert.Equal("Arial", baseStyle.CharacterFormatting.AsciiFontName);
            Assert.Equal((short)20, baseStyle.CharacterFormatting.CharacterSpacingTwips);
            Assert.Equal(0x00784F23u, baseStyle.CharacterFormatting.ColorRef);
            Assert.Equal((ushort)160, baseStyle.ParagraphFormatting!.AfterTwips);
            Assert.True(derived.CharacterFormatting.Italic);
            Assert.Equal((ushort)28, derived.CharacterFormatting.SizeHalfPoints);
            Assert.Equal("Arial", derived.CharacterFormatting.AsciiFontName);
            Assert.Equal((short)20,
                derived.CharacterFormatting.CharacterSpacingTwips);
            Assert.Equal(0x00784F23u, derived.CharacterFormatting.ColorRef);
            Assert.Equal((ushort)160, derived.ParagraphFormatting!.AfterTwips);
            var projected = new DocToDocxProjector().Project(index);
            using var stream = new MemoryStream(projected.DocxBytes);
            using var docx = WordprocessingDocument.Open(stream, false);
            var styles = docx.MainDocumentPart!.StyleDefinitionsPart!.Styles!;
            var parent = Assert.Single(styles.Elements<Style>(),
                x => x.StyleId == baseStyle.StyleId);
            var child = Assert.Single(styles.Elements<Style>(),
                x => x.StyleId == derived.StyleId);
            Assert.Equal(parent.StyleId, child.BasedOn!.Val!.Value);
            Assert.Equal("28", parent.StyleRunProperties!.FontSize!.Val!.Value);
            Assert.Equal("Arial", parent.StyleRunProperties.RunFonts!.Ascii!.Value);
            Assert.True(child.StyleRunProperties!.Italic!.Val!.Value);
            Assert.Null(child.StyleRunProperties.FontSize);
            Assert.Null(child.StyleRunProperties.RunFonts);
            Assert.Null(child.StyleRunProperties.Color);
            Assert.Null(child.StyleParagraphProperties?
                .GetFirstChild<SpacingBetweenLines>());
            Assert.Contains(docx.MainDocumentPart.Document!.Body!.Descendants<Paragraph>(),
                x => x.ParagraphProperties?.ParagraphStyleId?.Val?.Value == derived.StyleId);
            Assert.Contains(docx.MainDocumentPart.HeaderParts,
                x => x.Header!.Descendants<Paragraph>().Any(p =>
                    p.ParagraphProperties?.ParagraphStyleId?.Val?.Value == derived.StyleId));
            Assert.Contains(docx.MainDocumentPart.FooterParts,
                x => x.Footer!.Descendants<Paragraph>().Any(p =>
                    p.ParagraphProperties?.ParagraphStyleId?.Val?.Value == derived.StyleId));
            Assert.Empty(new OpenXmlValidator().Validate(docx));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-inherited-style-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, generatedDoc);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                foreach (dynamic text in new[]
                {
                    opened.Paragraphs.Item(1).Range,
                    opened.Sections(1).Headers(1).Range,
                    opened.Sections(1).Footers(1).Range
                })
                {
                    Assert.Equal("DerivedDisplay", (string)text.Style.NameLocal);
                    Assert.Equal("Arial", (string)text.Characters(1).Font.Name);
                    Assert.Equal(14f, (float)text.Characters(1).Font.Size);
                    Assert.Equal(0x00784F23, (int)text.Characters(1).Font.Color);
                    Assert.NotEqual(0, (int)text.Characters(1).Font.Italic);
                    Assert.InRange((double)text.Characters(1).Font.Spacing, 0.9, 1.1);
                    Assert.InRange((double)text.ParagraphFormat.SpaceAfter, 7.9, 8.1);
                }
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

    [Fact]
    public void ThreeLevelStyleAndDirectOverridesSurviveAllStories()
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var sourceDocx = File.ReadAllBytes(Path.Combine(directory,
            "WordThreeLevelStyleOverrides.docx"));
        var generatedDoc = DxpDocExport.Export(sourceDocx);
        foreach (var binary in new[]
            { File.ReadAllBytes(Path.Combine(directory, "WordThreeLevelStyleOverrides.doc")),
                generatedDoc })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var root = Assert.Single(index.StyleDefinitions, x => x.Name == "BaseDisplay");
            var child = Assert.Single(index.StyleDefinitions, x => x.Name == "DerivedDisplay");
            var grandchild = Assert.Single(index.StyleDefinitions,
                x => x.Name == "GrandchildDisplay");
            Assert.Equal(root.Index, child.BasedOnIndex);
            Assert.Equal(child.Index, grandchild.BasedOnIndex);
            Assert.Equal("Arial", root.CharacterFormatting.AsciiFontName);
            Assert.Equal((ushort)28, root.CharacterFormatting.SizeHalfPoints);
            Assert.True(child.CharacterFormatting.Italic);
            Assert.Equal((byte)1, grandchild.CharacterFormatting.UnderlineCode);
            Assert.Equal("Arial", grandchild.CharacterFormatting.AsciiFontName);
            Assert.Equal((ushort)28, grandchild.CharacterFormatting.SizeHalfPoints);
            Assert.True(grandchild.CharacterFormatting.Italic);
            var projected = new DocToDocxProjector().Project(index);
            using var stream = new MemoryStream(projected.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var styles = document.MainDocumentPart!.StyleDefinitionsPart!.Styles!;
            var outputGrandchild = Assert.Single(styles.Elements<Style>(),
                x => x.StyleId == grandchild.StyleId);
            Assert.Equal(child.StyleId, outputGrandchild.BasedOn!.Val!.Value);
            Assert.Null(outputGrandchild.StyleRunProperties?.RunFonts);
            Assert.Null(outputGrandchild.StyleRunProperties?.FontSize);
            Assert.Null(outputGrandchild.StyleRunProperties?.Italic);
            Assert.Equal(UnderlineValues.Single,
                outputGrandchild.StyleRunProperties!.Underline!.Val!.Value);
            var firstRun = document.MainDocumentPart.Document!.Body!
                .Descendants<Run>().First(x => x.InnerText == "Derived");
            Assert.False(firstRun.RunProperties!.Italic!.Val!.Value);
            Assert.Equal("20", firstRun.RunProperties.FontSize!.Val!.Value);
            Assert.Equal("FF0000", firstRun.RunProperties.Color!.Val!.Value);
            Assert.Contains(document.MainDocumentPart.HeaderParts,
                x => x.Header!.Descendants<Run>().Any(r =>
                    r.InnerText == "Derived" && r.RunProperties?.Bold != null));
            Assert.Contains(document.MainDocumentPart.FooterParts,
                x => x.Footer!.InnerText.Contains("Derived footer"));
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-three-level-style-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, generatedDoc);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                dynamic body = opened.Paragraphs.Item(1).Range;
                Assert.Equal("GrandchildDisplay", (string)body.Style.NameLocal);
                Assert.Equal(10f, (float)body.Characters(1).Font.Size);
                Assert.Equal(255, (int)body.Characters(1).Font.Color);
                Assert.Equal(0, (int)body.Characters(1).Font.Italic);
                Assert.Equal("Arial", (string)body.Characters(9).Font.Name);
                Assert.Equal(14f, (float)body.Characters(9).Font.Size);
                Assert.NotEqual(0, (int)body.Characters(9).Font.Italic);
                Assert.NotEqual(0, (int)body.Characters(9).Font.Underline);
                dynamic header = opened.Sections(1).Headers(1).Range;
                Assert.Equal("GrandchildDisplay", (string)header.Style.NameLocal);
                Assert.NotEqual(0, (int)header.Characters(1).Font.Bold);
                dynamic footer = opened.Sections(1).Footers(1).Range;
                Assert.Equal("GrandchildDisplay", (string)footer.Style.NameLocal);
                Assert.Equal("Arial", (string)footer.Characters(1).Font.Name);
                Assert.NotEqual(0, (int)footer.Characters(1).Font.Italic);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void InheritedStyleRunShadingSurvivesAllStories(bool patterned)
    {
        var stylePattern = patterned ? ShadingPatternValues.Percent25 :
            ShadingPatternValues.Clear;
        var directPattern = patterned ? ShadingPatternValues.Percent50 :
            ShadingPatternValues.Clear;
        ushort stylePatternCode = patterned ? (ushort)5 : (ushort)0;
        ushort directPatternCode = patterned ? (ushort)8 : (ushort)0;
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(Path.Combine(directory,
            "WordThreeLevelStyleOverrides.docx")));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            Assert.Contains(document.MainDocumentPart!.Document.Body!
                .Descendants<Paragraph>(), x =>
                x.ParagraphProperties?.ParagraphStyleId?.Val?.Value == "GrandchildDisplay");
            Assert.Contains(document.MainDocumentPart.HeaderParts, x =>
                x.Header!.Descendants<Paragraph>().Any(p =>
                    p.ParagraphProperties?.ParagraphStyleId?.Val?.Value == "GrandchildDisplay"));
            Assert.Contains(document.MainDocumentPart.FooterParts, x =>
                x.Footer!.Descendants<Paragraph>().Any(p =>
                    p.ParagraphProperties?.ParagraphStyleId?.Val?.Value == "GrandchildDisplay"));
            var style = Assert.Single(document.MainDocumentPart!.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), x => x.StyleId == "GrandchildDisplay");
            var properties = style.StyleRunProperties ?? new StyleRunProperties();
            properties.AddChild(new Shading
            { Val = stylePattern, Fill = "DDEEFF", Color = "335577" }, true);
            style.StyleRunProperties = properties;
            var directRun = Assert.Single(document.MainDocumentPart.Document.Body!
                .Descendants<Run>(), x => x.InnerText == "Derived");
            var directProperties = directRun.RunProperties ?? new RunProperties();
            directProperties.AddChild(new Shading
            { Val = directPattern, Fill = "FFDDCC", Color = "775533" }, true);
            directRun.RunProperties = directProperties;
            document.MainDocumentPart.Document.Save();
            document.MainDocumentPart.StyleDefinitionsPart.Styles.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(generated);
        using var index = new DocTextIndexWalker().Index(input);
        var inherited = Assert.Single(index.StyleDefinitions,
            x => x.Name == "GrandchildDisplay");
        Assert.Equal(0xFFEEDDu, inherited.CharacterFormatting.Shading?.FillRgb);
        Assert.Equal(stylePatternCode, inherited.CharacterFormatting.Shading?.Pattern);
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.Shading?.Pattern == directPatternCode &&
            x.Formatting.Shading.FillRgb == 0xCCDDFFu);
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(generated).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var outputStyle = Assert.Single(projected.MainDocumentPart!.StyleDefinitionsPart!
            .Styles!.Elements<Style>(), x => x.StyleId == inherited.StyleId);
        Assert.Equal("DDEEFF", outputStyle.StyleRunProperties!
            .GetFirstChild<Shading>()!.Fill!.Value);
        Assert.Equal(stylePattern, outputStyle.StyleRunProperties!
            .GetFirstChild<Shading>()!.Val!.Value);
        var projectedDirect = Assert.Single(projected.MainDocumentPart.Document.Body!
            .Descendants<Run>(), x => x.InnerText == "Derived");
        Assert.Equal("FFDDCC", projectedDirect.RunProperties!
            .GetFirstChild<Shading>()!.Fill!.Value);
        Assert.Equal(directPattern, projectedDirect.RunProperties!
            .GetFirstChild<Shading>()!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using (var rewrittenInput = new MemoryStream(rewritten))
        using (var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput))
            Assert.Equal(0xFFEEDDu, Assert.Single(rewrittenIndex.StyleDefinitions,
                x => x.Name == "GrandchildDisplay").CharacterFormatting.Shading?.FillRgb);
        using var rewrittenStream = new MemoryStream(DxpDocToDocx.Project(rewritten).DocxBytes);
        using var rewrittenDocx = WordprocessingDocument.Open(rewrittenStream, false);
        var rewrittenStyle = Assert.Single(rewrittenDocx.MainDocumentPart!
            .StyleDefinitionsPart!.Styles!.Elements<Style>(),
            x => x.StyleName?.Val?.Value == "GrandchildDisplay");
        Assert.True(rewrittenStyle.StyleRunProperties?.GetFirstChild<Shading>() != null,
            rewrittenStyle.OuterXml);
        Assert.Equal("DDEEFF", rewrittenStyle.StyleRunProperties!
            .GetFirstChild<Shading>()!.Fill!.Value);
        Assert.Equal(stylePattern, rewrittenStyle.StyleRunProperties!
            .GetFirstChild<Shading>()!.Val!.Value);
        var rewrittenDirect = Assert.Single(rewrittenDocx.MainDocumentPart.Document.Body!
            .Descendants<Run>(), x => x.InnerText == "Derived");
        Assert.Equal("FFDDCC", rewrittenDirect.RunProperties!
            .GetFirstChild<Shading>()!.Fill!.Value);
        Assert.Equal(directPattern, rewrittenDirect.RunProperties!
            .GetFirstChild<Shading>()!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(rewrittenDocx));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-run-shading-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
            var nativeStyle = Assert.Single(nativeIndex.StyleDefinitions,
                x => x.Name == "GrandchildDisplay");
            Assert.Equal(0xFFEEDDu, nativeStyle.CharacterFormatting.Shading?.FillRgb);
            Assert.Equal(stylePatternCode,
                nativeStyle.CharacterFormatting.Shading?.Pattern);
            Assert.Contains(nativeIndex.CharacterFormatting, x =>
                x.Formatting.Shading?.Pattern == directPatternCode &&
                x.Formatting.Shading.FillRgb == 0xCCDDFFu);
            using var nativeProjectionStream = new MemoryStream(
                DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            using var nativeProjection = WordprocessingDocument.Open(
                nativeProjectionStream, false);
            var nativeProjectedStyle = Assert.Single(nativeProjection.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "GrandchildDisplay");
            Assert.Equal("DDEEFF", nativeProjectedStyle.StyleRunProperties!
                .GetFirstChild<Shading>()!.Fill!.Value);
            Assert.Equal(stylePattern, nativeProjectedStyle.StyleRunProperties!
                .GetFirstChild<Shading>()!.Val!.Value);
            var nativeDirect = Assert.Single(nativeProjection.MainDocumentPart.Document.Body!
                .Descendants<Run>(), x => x.InnerText == "Derived");
            Assert.Equal("FFDDCC", nativeDirect.RunProperties!
                .GetFirstChild<Shading>()!.Fill!.Value);
            Assert.Equal(directPattern, nativeDirect.RunProperties!
                .GetFirstChild<Shading>()!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

