        using var index = new DocTextIndexWalker().Index(input);
        var footerStory = Assert.Single(index.HeaderStories,
            x => x.Kind == DocHeaderStoryKind.OddFooter);
        Assert.Contains(index.CharacterFormatting, x =>
            x.CpStart >= footerStory.CpStart && x.CpStart < footerStory.CpEnd &&
            x.Formatting.UnderlineCode == 0);
        var projected = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projected.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var outputRun = Assert.Single(output.MainDocumentPart!.FooterParts
            .SelectMany(x => x.Footer!.Descendants<Run>()),
            x => x.InnerText.Contains("Derived footer"));
        Assert.Equal(UnderlineValues.None,
            outputRun.RunProperties!.Underline!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(output));

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-footer-underline-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(generatedPath, writtenDoc);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            dynamic footer = opened.Sections(1).Footers(1).Range;
            Assert.Equal("GrandchildDisplay", (string)footer.Style.NameLocal);
            Assert.Equal(0, (int)footer.Characters(1).Font.Underline);
            Assert.NotEqual(0, (int)opened.Paragraphs.Item(1).Range
                .Characters(9).Font.Underline);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(generatedPath);
        }
    }

