            main.StyleDefinitionsPart.Styles.Save();
            var runs = new[]
            {
                main.Document!.Body!.Descendants<Run>().First(x => x.InnerText == "Derived"),
                main.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>())
                    .First(x => x.InnerText == "Derived"),
                main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                    .First(x => x.InnerText.Contains("Derived footer"))
            };
            var colors = new[] { "FF0000", "00AA00", "AA00AA" };
            for (var i = 0; i < runs.Length; i++)
            {
                runs[i].RunProperties ??= new RunProperties();
                runs[i].RunProperties.Underline = new Underline
                    { Val = UnderlineValues.Single, Color = colors[i] };
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }

        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var styleInDoc = Assert.Single(index.StyleDefinitions,
            x => x.Name == "GrandchildDisplay");
        Assert.Equal(0x00FF8000u, styleInDoc.CharacterFormatting.UnderlineColorRef);
        foreach (var color in new[] { 0x000000FFu, 0x0000AA00u, 0x00AA00AAu })
            Assert.Contains(index.CharacterFormatting,
                x => x.Formatting.UnderlineColorRef == color);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var styleInDocx = Assert.Single(output.MainDocumentPart!.StyleDefinitionsPart!
            .Styles!.Elements<Style>(), x => x.StyleId == styleInDoc.StyleId);
        Assert.Equal("0080FF",
            styleInDocx.StyleRunProperties!.GetFirstChild<Underline>()!.Color!.Value);
        var mainOut = output.MainDocumentPart;
        foreach (var (runs, color) in new[]
        {
            (mainOut.Document!.Body!.Descendants<Run>(), "FF0000"),
            (mainOut.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>()), "00AA00"),
            (mainOut.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>()), "AA00AA")
        })
            Assert.Contains(runs, x => x.RunProperties?.Underline?.Color?.Value == color);
        Assert.Empty(new OpenXmlValidator().Validate(output));

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-underline-color-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(255, (int)opened.Paragraphs.Item(1).Range
                .Characters(1).Font.UnderlineColor);
            Assert.Equal(0x0000AA00, (int)opened.Sections(1).Headers(1).Range
                .Characters(1).Font.UnderlineColor);
            Assert.Equal(0x00AA00AA, (int)opened.Sections(1).Footers(1).Range
                .Characters(1).Font.UnderlineColor);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(generatedPath);
        }
    }

    [Theory]
    [InlineData(false, 0)]
    [InlineData(true, 0)]
    [InlineData(false, 1)]
    [InlineData(false, 2)]
    public void ThemeRunAndUnderlineColorsResolveBeforeDocWriting(
        bool transformed, int remapDepth)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            if (remapDepth > 0)
            {
                var mapping = main.DocumentSettingsPart!.Settings!
                    .GetFirstChild<ColorSchemeMapping>()!;
                mapping.Accent1 = ColorSchemeIndexValues.Accent2;
                if (remapDepth > 1)
                    mapping.Accent2 = ColorSchemeIndexValues.Accent3;
                main.DocumentSettingsPart.Settings.Save();
            }
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleId == "GrandchildDisplay");
            var styleUnderline = style.StyleRunProperties!.GetFirstChild<Underline>()!;
            styleUnderline.Color = "FFFFFF";
            styleUnderline.ThemeColor = ThemeColorValues.Accent4;
            if (transformed) styleUnderline.ThemeTint = "80";
            main.StyleDefinitionsPart.Styles.Save();
            var body = main.Document!.Body!.Descendants<Run>()
                .First(x => x.InnerText == "Derived");
            body.RunProperties!.Color = new Color
                { Val = "FFFFFF", ThemeColor = ThemeColorValues.Accent1 };
            if (transformed)
            {
                body.RunProperties.Color.ThemeTint = "80";
                body.RunProperties.Color.ThemeShade = "20";
            }
            main.Document.Save();
            var header = main.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>())
                .First(x => x.InnerText == "Derived");
            header.RunProperties ??= new RunProperties();
            header.RunProperties.Underline = new Underline
                { Val = UnderlineValues.Single, Color = "FFFFFF",
                    ThemeColor = ThemeColorValues.Accent2 };
            if (transformed) header.RunProperties.Underline.ThemeShade = "BF";
            foreach (var part in main.HeaderParts) part.Header?.Save();
            var footer = main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                .First(x => x.InnerText.Contains("Derived footer"));
            footer.RunProperties ??= new RunProperties();
            footer.RunProperties.Color = new Color
                { Val = "FFFFFF", ThemeColor = ThemeColorValues.Accent3 };
            if (transformed) footer.RunProperties.Color.ThemeShade = "80";
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }

        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var styleInDoc = Assert.Single(index.StyleDefinitions,
            x => x.Name == "GrandchildDisplay");
        Assert.Equal(transformed ? 0x00F6D47Bu : 0x00D59E0Fu,
            styleInDoc.CharacterFormatting.UnderlineColorRef);
        Assert.Contains(index.CharacterFormatting,
            x => x.Formatting.ColorRef ==
                (transformed ? 0x00E6BD64u : remapDepth == 2 ? 0x00246B19u :
                    remapDepth == 1 ? 0x003271E9u : 0x00826015u));
        Assert.Contains(index.CharacterFormatting,
            x => x.Formatting.UnderlineColorRef ==
                (transformed ? 0x00154FBFu : remapDepth == 2 ? 0x00246B19u :
                    0x003271E9u));
        Assert.Contains(index.CharacterFormatting,
            x => x.Formatting.ColorRef ==
                (transformed ? 0x0012360Du : 0x00246B19u));
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        Assert.Contains(output.MainDocumentPart!.Document!.Body!.Descendants<Run>(),
            x => x.RunProperties?.Color?.Val?.Value ==
                (transformed ? "64BDE6" : remapDepth == 2 ? "196B24" :
                    remapDepth == 1 ? "E97132" : "156082"));
        Assert.Contains(output.MainDocumentPart.HeaderParts.SelectMany(
            x => x.Header!.Descendants<Run>()),
            x => x.RunProperties?.Underline?.Color?.Value ==
                (transformed ? "BF4F15" : remapDepth == 2 ? "196B24" : "E97132"));
        Assert.Contains(output.MainDocumentPart.FooterParts.SelectMany(
            x => x.Footer!.Descendants<Run>()),
            x => x.RunProperties?.Color?.Val?.Value ==
                (transformed ? "0D3612" : "196B24"));
        Assert.Empty(new OpenXmlValidator().Validate(output));

        var verifyRender = Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1";
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1" &&
            !verifyRender) return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-theme-source-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-theme-colors-{Guid.NewGuid():N}.doc");
        var renderDirectory = Path.Combine(Path.GetTempPath(),
            $"docxport-theme-render-{Guid.NewGuid():N}");
        if (verifyRender) Directory.CreateDirectory(renderDirectory);
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            if (verifyRender)
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.ExportAsFixedFormat(Path.Combine(renderDirectory, "source.pdf"), 17);
                opened.Close(false);
                opened = null;
            }
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(transformed ? 0x00E6BD64 : remapDepth == 2 ? 0x00246B19 :
                remapDepth == 1 ? 0x003271E9 : 0x00826015,
                (int)opened.Paragraphs.Item(1).Range
                .Characters(1).Font.Color);
            Assert.Equal(transformed ? 0x00F6D47B : 0x00D59E0F,
                (int)opened.Paragraphs.Item(1).Range
                .Characters(9).Font.UnderlineColor);
            Assert.Equal(transformed ? 0x00154FBF : remapDepth == 2 ? 0x00246B19 :
                0x003271E9,
                (int)opened.Sections(1).Headers(1).Range
                .Characters(1).Font.UnderlineColor);
            Assert.Equal(transformed ? 0x0012360D : 0x00246B19,
                (int)opened.Sections(1).Footers(1).Range
                .Characters(1).Font.Color);
            if (verifyRender)
                opened.ExportAsFixedFormat(Path.Combine(renderDirectory, "generated.pdf"), 17);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
        }
        if (!verifyRender) return;
        static string Run(string executable, params string[] arguments)
        {
            var start = new ProcessStartInfo(executable)
            {
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true
            };
            foreach (var argument in arguments) start.ArgumentList.Add(argument);
            using var process = Process.Start(start)!;
            if (!process.WaitForExit(30000))
            {
                process.Kill();
                throw new TimeoutException($"Rendering timed out: {executable}");
            }
            var result = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
            if (process.ExitCode != 0 && !Path.GetFileName(executable)
                .StartsWith("magick", StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException(result);
            return result;
        }
        var ghostscript = Environment.GetEnvironmentVariable("DOCXPORT_GHOSTSCRIPT_PATH") ??
            @"C:\Program Files\gs\gs10.06.0\bin\gswin64c.exe";
        var imageMagick = Environment.GetEnvironmentVariable("DOCXPORT_IMAGEMAGICK_PATH") ??
            @"C:\Program Files\ImageMagick-7.1.2-Q16-HDRI\magick.exe";
        try
        {
            foreach (var name in new[] { "source", "generated" })
                Run(ghostscript, "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=png16m",
                    "-r96", "-dFirstPage=1", "-dLastPage=1",
                    "-sOutputFile=" + Path.Combine(renderDirectory, name + ".png"),
                    Path.Combine(renderDirectory, name + ".pdf"));
            var metric = Run(imageMagick, "compare", "-metric", "RMSE",
                Path.Combine(renderDirectory, "source.png"),
                Path.Combine(renderDirectory, "generated.png"), "null:");
            var match = Regex.Match(metric, @"\(([0-9.]+)\)");
            Assert.True(match.Success, "ImageMagick did not report normalized RMSE: " + metric);
            var error = double.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture);
            Assert.True(error < 0.02,
                $"Theme color pages render RMSE {error}; files: {renderDirectory}");
        }
        finally
        {
            if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                Directory.Delete(renderDirectory, true);
        }
    }

