                .First(x => x.InnerText == "Derived");
            var footer = main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                .First(x => x.InnerText.Contains("Derived footer"));
            foreach (var run in new[] { body, header, footer })
            {
                run.RunProperties ??= new RunProperties();
                run.RunProperties.Highlight = new Highlight { Val = highlight };
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.True(index.CharacterFormatting.Count(x =>
            x.Formatting.HighlightCode == docCode) >= 3);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var mainOut = output.MainDocumentPart!;
        foreach (var runs in new[]
        {
            mainOut.Document!.Body!.Descendants<Run>(),
            mainOut.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>()),
            mainOut.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
        })
            Assert.Contains(runs, x => x.RunProperties?.Highlight?.Val?.Value == highlight);
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (colorName is "darkRed" or "lightGray" &&
            Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.02);
        if (colorName != "darkRed" ||
            Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-highlight-source-{Guid.NewGuid():N}.docx");
        var wordDocPath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(wordDocPath, 0);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(wordDocPath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            Assert.True(nativeIndex.CharacterFormatting.Count(x =>
                x.Formatting.HighlightCode == docCode) >= 3);
            var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            Assert.Contains(nativeDocx.MainDocumentPart!.HeaderParts
                .SelectMany(x => x.Header!.Descendants<Run>()),
                x => x.RunProperties?.Highlight?.Val?.Value == highlight);
            Assert.Contains(nativeDocx.MainDocumentPart.FooterParts
                .SelectMany(x => x.Footer!.Descendants<Run>()),
                x => x.RunProperties?.Highlight?.Val?.Value == highlight);
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(wordDocPath);
        }
    }

    [Fact]
    public void WidowControlSurvivesStyleInheritanceAndAllDocStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Widow base" },
                    new StyleParagraphProperties(new WidowControl { Val = false }))
                { Type = StyleValues.Paragraph, StyleId = "WidowBase" },
                new Style(new StyleName { Val = "Widow child" },
                    new BasedOn { Val = "WidowBase" })
                { Type = StyleValues.Paragraph, StyleId = "WidowChild" });
            styles.Styles.Save();
            Paragraph Text(string value, bool? direct) => new(
                new ParagraphProperties(new ParagraphStyleId { Val = "WidowChild" },
                    direct is bool enabled ? new WidowControl { Val = enabled } : null),
                new Run(new Text(value)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Text("Header widow", true));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Text("Footer widow", false));
            footer.Footer.Save();
            main.Document = new Document(new Body(Text("Body widow", null),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var baseStyle = Assert.Single(index.StyleDefinitions, x => x.Name == "Widow base");
        var childStyle = Assert.Single(index.StyleDefinitions, x => x.Name == "Widow child");
        Assert.False(baseStyle.ParagraphFormatting!.WidowControl);
        Assert.False(childStyle.ParagraphFormatting!.WidowControl);
        Assert.Contains(index.ParagraphStyles, x => x.Formatting.WidowControl == true);
        Assert.Contains(index.ParagraphStyles, x => x.Formatting.WidowControl == false);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var projectedStyle = Assert.Single(output.MainDocumentPart!
            .StyleDefinitionsPart!.Styles!.Elements<Style>(),
            x => x.StyleId == baseStyle.StyleId);
        Assert.False(projectedStyle.StyleParagraphProperties!
            .GetFirstChild<WidowControl>()!.Val!.Value);
        Assert.True(Assert.Single(output.MainDocumentPart.HeaderParts)
            .Header!.Descendants<Paragraph>().Single().ParagraphProperties!
            .GetFirstChild<WidowControl>()!.Val!.Value);
        Assert.False(Assert.Single(output.MainDocumentPart.FooterParts)
            .Footer!.Descendants<Paragraph>().Single().ParagraphProperties!
            .GetFirstChild<WidowControl>()!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(output));
        using (var pieceInput = new MemoryStream(binary))
        using (var pieceIndex = new DocTextIndexWalker().Index(pieceInput))
        {
            var piece = Assert.Single(pieceIndex.Pieces);
            using var edited = new MemoryStream();
            edited.Write(binary, 0, binary.Length);
            edited.Position = 0;
            using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
            using (var table = compound.OpenStream(piece.Node.StreamName!))
            {
                table.Position = piece.Node.Offset!.Value + 6;
                table.WriteByte(0x66); // Prm0 isprm 0x33: sprmPFWidowControl
                table.WriteByte(1);
                compound.Flush();
            }
            using var modified = new MemoryStream(edited.ToArray());
            using var modifiedIndex = new DocTextIndexWalker().Index(modified);
            Assert.Contains(modifiedIndex.ParagraphStyles, x =>
                x.Formatting.WidowControl == true && x.CpStart == 0);
            var modifiedProjection = new DocToDocxProjector().Project(modifiedIndex);
            using var modifiedStream = new MemoryStream(modifiedProjection.DocxBytes);
            using var modifiedDocx = WordprocessingDocument.Open(modifiedStream, false);
            Assert.True(Assert.Single(modifiedDocx.MainDocumentPart!.Document!.Body!
                .Elements<Paragraph>()).ParagraphProperties!
                .GetFirstChild<WidowControl>()!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(modifiedDocx));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-widow-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(0, (int)opened.Paragraphs.Item(1).Range.ParagraphFormat.WidowControl);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Headers.Item(1)
                .Range.ParagraphFormat.WidowControl);
            Assert.Equal(0, (int)opened.Sections.Item(1).Footers.Item(1)
                .Range.ParagraphFormat.WidowControl);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            Assert.False(Assert.Single(nativeIndex.StyleDefinitions,
                x => x.Name == "Widow base").ParagraphFormatting!.WidowControl);
            Assert.Contains(nativeIndex.ParagraphStyles,
                x => x.Formatting.WidowControl == true);
            using var nativeProjectionStream = new MemoryStream(
                new DocToDocxProjector().Project(nativeIndex).DocxBytes);
            using var nativeProjection = WordprocessingDocument.Open(
                nativeProjectionStream, false);
            var nativePart = nativeProjection.MainDocumentPart!;
            var nativeTables = new[]
            {
                Assert.Single(nativePart.Document!.Body!.Elements<Table>()),
                Assert.Single(Assert.Single(nativePart.HeaderParts).Header!.Elements<Table>()),
                Assert.Single(Assert.Single(nativePart.FooterParts).Footer!.Elements<Table>())
            };
            Assert.Equal(new[] { TableRowAlignmentValues.Center,
                TableRowAlignmentValues.Right, TableRowAlignmentValues.Center },
                nativeTables.Select(x => x.TableProperties!
                    .GetFirstChild<TableJustification>()!.Val!.Value));
            Assert.Equal(new[] { 720, 1440, 720 }, nativeTables.Select(x =>
                x.TableProperties!.GetFirstChild<TableIndentation>()!.Width!.Value));
            Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
            File.Delete(generatedPath);
        }
    }

    [Fact]
    public void CharacterShadingSurvivesStyleAndAllDocStories()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleId == "GrandchildDisplay");
            style.StyleRunProperties!.AppendChild(new Shading
                { Val = ShadingPatternValues.Clear, Fill = "FFF2CC" });
            main.StyleDefinitionsPart.Styles.Save();
            var body = main.Document!.Body!.Descendants<Run>()
                .First(x => x.InnerText == "Derived");
            var header = main.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>())
                .First(x => x.InnerText == "Derived");
            var footer = main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                .First(x => x.InnerText.Contains("Derived footer"));
            var runs = new[] { body, header, footer };
            var fills = new[] { "CCFFFF", "FFE5CC", "E2F0D9" };
            for (var i = 0; i < runs.Length; i++)
            {
                runs[i].RunProperties ??= new RunProperties();
                runs[i].RunProperties.Shading = new Shading
                    { Val = ShadingPatternValues.Clear, Fill = fills[i] };
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var styleInDoc = Assert.Single(index.StyleDefinitions,
            x => x.Name == "GrandchildDisplay");
        Assert.Equal(0x00CCF2FFu, styleInDoc.CharacterFormatting.Shading?.FillRgb);
        foreach (var fill in new[] { 0x00FFFFCCu, 0x00CCE5FFu, 0x00D9F0E2u })
            Assert.Contains(index.CharacterFormatting,
                x => x.Formatting.Shading?.FillRgb == fill);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var styleInDocx = Assert.Single(output.MainDocumentPart!.StyleDefinitionsPart!
            .Styles!.Elements<Style>(), x => x.StyleId == styleInDoc.StyleId);
        Assert.Equal("FFF2CC", styleInDocx.StyleRunProperties!
            .GetFirstChild<Shading>()?.Fill?.Value);
        var mainOut = output.MainDocumentPart;
        foreach (var (runs, fill) in new[]
        {
            (mainOut.Document!.Body!.Descendants<Run>(), "CCFFFF"),
            (mainOut.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>()), "FFE5CC"),
            (mainOut.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>()), "E2F0D9")
        })
            Assert.Contains(runs, x => x.RunProperties?.Shading?.Fill?.Value == fill);
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.02);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-character-shading-{Guid.NewGuid():N}.docx");
        var wordDocPath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(wordDocPath, 0);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(wordDocPath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            var nativeStyle = Assert.Single(nativeIndex.StyleDefinitions,
                x => x.Name == "GrandchildDisplay");
            Assert.Equal(0x00CCF2FFu, nativeStyle.CharacterFormatting.Shading?.FillRgb);
            foreach (var fill in new[] { 0x00FFFFCCu, 0x00CCE5FFu, 0x00D9F0E2u })
                Assert.Contains(nativeIndex.CharacterFormatting,
                    x => x.Formatting.Shading?.FillRgb == fill);
            var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            Assert.Contains(nativeDocx.MainDocumentPart!.HeaderParts
                .SelectMany(x => x.Header!.Descendants<Run>()),
                x => x.RunProperties?.Shading?.Fill?.Value == "FFE5CC");
            Assert.Contains(nativeDocx.MainDocumentPart.FooterParts
                .SelectMany(x => x.Footer!.Descendants<Run>()),
                x => x.RunProperties?.Shading?.Fill?.Value == "E2F0D9");
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(wordDocPath);
        }
    }

    [Fact]
    public void PatternedCharacterShadingRetainsForegroundAndFillInStories()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        var patterns = new[] { ShadingPatternValues.Percent50,
            ShadingPatternValues.HorizontalStripe, ShadingPatternValues.DiagonalCross };
        var fills = new[] { "FFFF00", "FFE5CC", "E2F0D9" };
        var foregrounds = new[] { "0000FF", "008000", "800080" };
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var runs = new[]
            {
                main.Document!.Body!.Descendants<Run>().First(x => x.InnerText == "Derived"),
                main.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>())
                    .First(x => x.InnerText == "Derived"),
                main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                    .First(x => x.InnerText.Contains("Derived footer"))
            };
            for (var i = 0; i < runs.Length; i++)
            {
                runs[i].RunProperties ??= new RunProperties();
                runs[i].RunProperties.Shading = new Shading
                    { Val = patterns[i], Fill = fills[i], Color = foregrounds[i] };
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        foreach (var pattern in new ushort[] { 8, 14, 19 })
            Assert.Contains(index.CharacterFormatting,
                x => x.Formatting.Shading?.Pattern == pattern);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var mainOut = output.MainDocumentPart!;
        var storyRuns = new[]
        {
            mainOut.Document!.Body!.Descendants<Run>(),
            mainOut.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>()),
            mainOut.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
        };
        for (var i = 0; i < storyRuns.Length; i++)
        {
            var expectedPattern = patterns[i];
            var expectedFill = fills[i];
            var expectedForeground = foregrounds[i];
            Assert.Contains(storyRuns[i], x =>
                x.RunProperties?.Shading?.Val?.Value == expectedPattern &&
                x.RunProperties.Shading.Fill?.Value == expectedFill &&
                x.RunProperties.Shading.Color?.Value == expectedForeground);
        }
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.02);
    }

    [Fact]
    public void ThemeShadingColorsResolveAcrossStylesAndStories()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        static Shading ThemeShade(ThemeColorValues fill, ThemeColorValues foreground) =>
            new Shading { Val = ShadingPatternValues.Percent50,
                Fill = "FFFFFF", ThemeFill = fill,
                Color = "FFFFFF", ThemeColor = foreground };
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleId == "GrandchildDisplay");
            style.StyleRunProperties!.AppendChild(ThemeShade(
                ThemeColorValues.Accent1, ThemeColorValues.Accent2));
            style.StyleRunProperties.GetFirstChild<Shading>()!.ThemeFillTint = "80";
            style.StyleParagraphProperties ??= new StyleParagraphProperties();
            style.StyleParagraphProperties.Shading = ThemeShade(
                ThemeColorValues.Accent4, ThemeColorValues.Accent5);
            main.StyleDefinitionsPart.Styles.Save();
            var runs = new[]
            {
                main.Document!.Body!.Descendants<Run>().First(x => x.InnerText == "Derived"),
                main.HeaderParts.SelectMany(x => x.Header!.Descendants<Run>())
                    .First(x => x.InnerText == "Derived"),
                main.FooterParts.SelectMany(x => x.Footer!.Descendants<Run>())
                    .First(x => x.InnerText.Contains("Derived footer"))
            };
            var fills = new[] { ThemeColorValues.Accent2,
                ThemeColorValues.Accent3, ThemeColorValues.Accent4 };
            var foregrounds = new[] { ThemeColorValues.Accent3,
                ThemeColorValues.Accent4, ThemeColorValues.Accent1 };
            for (var i = 0; i < runs.Length; i++)
            {
                runs[i].RunProperties ??= new RunProperties();
                runs[i].RunProperties.Shading = ThemeShade(fills[i], foregrounds[i]);
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var styleInDoc = Assert.Single(index.StyleDefinitions,
            x => x.Name == "GrandchildDisplay");
        Assert.Equal(0x00E6BD64u, styleInDoc.CharacterFormatting.Shading?.FillRgb);
        Assert.Equal(0x003271E9u, styleInDoc.CharacterFormatting.Shading?.ForegroundRgb);
        Assert.Equal(0x00D59E0Fu, styleInDoc.ParagraphFormatting?.FillRgb);
        Assert.Equal(0x00932BA0u, styleInDoc.ParagraphFormatting?.ShadingForegroundRgb);
        foreach (var fill in new[] { 0x003271E9u, 0x00246B19u, 0x00D59E0Fu })
            Assert.Contains(index.CharacterFormatting,
                x => x.Formatting.Shading?.FillRgb == fill);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var styleInDocx = Assert.Single(output.MainDocumentPart!.StyleDefinitionsPart!
            .Styles!.Elements<Style>(), x => x.StyleId == styleInDoc.StyleId);
        Assert.Equal("64BDE6", styleInDocx.StyleRunProperties!
            .GetFirstChild<Shading>()?.Fill?.Value);
        Assert.Equal("0F9ED5", styleInDocx.StyleParagraphProperties?
            .GetFirstChild<Shading>()?.Fill?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.02);
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void ThemeTableCellShadingResolvesBeforeDocWriting(bool fixedLayout)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var body = document.MainDocumentPart!.Document!.Body!;
            var table = new Table(
                new TableProperties(new TableLayout
                { Type = fixedLayout ? TableLayoutValues.Fixed :
                    TableLayoutValues.Autofit }, new TableBorders(new BottomBorder
                {
                    Val = BorderValues.DotDotDash, Size = 8,
                    Color = "FFFFFF", ThemeColor = ThemeColorValues.Accent2
                })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new Shading
                    {
                        Val = ShadingPatternValues.Clear,
                        Fill = "FFFFFF", ThemeFill = ThemeColorValues.Accent1
                    }, new TableCellBorders(new TopBorder
                    {
                        Val = BorderValues.Triple, Size = 8,
                        Color = "FFFFFF", ThemeColor = ThemeColorValues.Accent4
                    })), new Paragraph(new Run(new Text("Theme cell one")))),
                    new TableCell(new TableCellProperties(new Shading
                    {
                        Val = ShadingPatternValues.Percent50,
                        Fill = "FFFFFF", ThemeFill = ThemeColorValues.Accent3,
                        ThemeFillShade = "80",
                        Color = "FFFFFF", ThemeColor = ThemeColorValues.Accent2
                    }), new Paragraph(new Run(new Text("Theme cell two"))))));
            body.InsertBefore(table, body.GetFirstChild<SectionProperties>());
            document.MainDocumentPart.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var row = Assert.Single(index.ParagraphStyles,
            x => x.Formatting?.TableTerminator == true);
        Assert.Equal(!fixedLayout, row.Formatting?.TableAutoFit);
        Assert.Equal(0x00826015u, row.Formatting!.TableCellShadings![0]!.FillRgb);
        Assert.Equal(0x0012360Du, row.Formatting.TableCellShadings[1]!.FillRgb);
        Assert.Equal(0x003271E9u, row.Formatting.TableCellShadings[1]!.ForegroundRgb);
        Assert.Equal(0x00D59E0Fu, row.Formatting.TableCellBorders![0]!.Top!.ColorRgb);
        Assert.Equal((byte)10, row.Formatting.TableCellBorders[0]!.Top!.Type);
        Assert.All(row.Formatting.TableCellBorders,
            x =>
            {
                Assert.Equal(0x003271E9u, x!.Bottom!.ColorRgb);
                Assert.Equal((byte)9, x.Bottom.Type);
            });
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var cells = Assert.Single(output.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal(fixedLayout ? TableLayoutValues.Fixed : TableLayoutValues.Autofit,
            cells[0].Ancestors<Table>().Single().TableProperties?.TableLayout?.Type?.Value);
        Assert.All(cells, cell =>
        {
            var width = cell.TableCellProperties?.GetFirstChild<TableCellWidth>();
            Assert.NotNull(width);
            Assert.Equal(fixedLayout ? TableWidthUnitValues.Dxa :
                TableWidthUnitValues.Auto, width.Type?.Value);
            if (!fixedLayout) Assert.Equal("0", width.Width?.Value);
        });
        Assert.Equal("156082", cells[0].TableCellProperties?.GetFirstChild<Shading>()?
            .Fill?.Value);
        Assert.Equal("0D3612", cells[1].TableCellProperties?.GetFirstChild<Shading>()?
            .Fill?.Value);
        Assert.Equal("E97132", cells[1].TableCellProperties?.GetFirstChild<Shading>()?
            .Color?.Value);
        Assert.Equal("0F9ED5", cells[0].TableCellProperties?
            .GetFirstChild<TableCellBorders>()?.TopBorder?.Color?.Value);
        Assert.Equal(BorderValues.Triple, cells[0].TableCellProperties?
            .GetFirstChild<TableCellBorders>()?.TopBorder?.Val?.Value);
        Assert.All(cells, x => Assert.Equal("E97132", x.TableCellProperties?
            .GetFirstChild<TableCellBorders>()?.BottomBorder?.Color?.Value));
        Assert.All(cells, x => Assert.Equal(BorderValues.DotDotDash,
            x.TableCellProperties?.GetFirstChild<TableCellBorders>()?
                .BottomBorder?.Val?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (fixedLayout && Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-table-layout-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            if (!fixedLayout)
            {
                Assert.Contains(nativeIndex.ParagraphStyles,
                    x => x.Formatting?.TableAutoFit == true);
                var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
                Assert.Contains(nativeDocx.MainDocumentPart!.Document!.Body!
                    .Elements<Table>(), x => x.TableProperties?.TableLayout?
                    .Type?.Value == TableLayoutValues.Autofit);
                Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData((byte)1, (ushort)0)]
    [InlineData((byte)2, (ushort)2500)]
    [InlineData((byte)3, (ushort)4000)]
    public void TablePreferredWidthRoundTripsThroughDoc(byte unit, ushort value)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        var widthType = unit switch
        {
            1 => TableWidthUnitValues.Auto,
            2 => TableWidthUnitValues.Pct,
            _ => TableWidthUnitValues.Dxa
        };
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var body = document.MainDocumentPart!.Document!.Body!;
            var table = new Table(
                new TableProperties(new TableWidth
                {
                    Type = widthType, Width = value.ToString(CultureInfo.InvariantCulture)
                }),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(new TableCell(new TableCellProperties(new TableCellWidth
                {
                    Type = widthType,
                    Width = (value / 2).ToString(CultureInfo.InvariantCulture)
                }), new Paragraph(new Run(new Text("First")))),
                    new TableCell(new TableCellProperties(new TableCellWidth
                    {
                        Type = widthType,
                        Width = (value / 2).ToString(CultureInfo.InvariantCulture)
                    }), new Paragraph(new Run(new Text("Second"))))));
            body.InsertBefore(table, body.GetFirstChild<SectionProperties>());
            document.MainDocumentPart.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Contains(index.ParagraphStyles, x =>
            x.Formatting?.TablePreferredWidth == new DocTablePreferredWidth(unit, value) &&
            x.Formatting.TableCellPreferredWidths?.Count == 2 &&
            x.Formatting.TableCellPreferredWidths.All(w =>
                w == new DocTablePreferredWidth(unit, (ushort)(value / 2))));
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var projected = Assert.Single(output.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        Assert.Equal(widthType, projected.TableProperties?.TableWidth?.Type?.Value);
        Assert.Equal(value.ToString(CultureInfo.InvariantCulture),
            projected.TableProperties?.TableWidth?.Width?.Value);
        foreach (var cell in projected.Descendants<TableCell>())
        {
            Assert.Equal(widthType, cell.TableCellProperties?.TableCellWidth?.Type?.Value);
            Assert.Equal((value / 2).ToString(CultureInfo.InvariantCulture),
                cell.TableCellProperties?.TableCellWidth?.Width?.Value);
        }
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (unit == 1 || Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-table-width-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            Assert.Contains(nativeIndex.ParagraphStyles,
                x => x.Formatting?.TablePreferredWidth ==
                    new DocTablePreferredWidth(unit, value));
            var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            Assert.Contains(nativeDocx.MainDocumentPart!.Document!.Body!
                .Elements<Table>(), x => x.TableProperties?.TableWidth?
                .Type?.Value == widthType && x.TableProperties.TableWidth.Width?.Value ==
                    value.ToString(CultureInfo.InvariantCulture));
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void TableDefaultAndCellMarginsRoundTripThroughDoc(bool logicalSides)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var table = new Table(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableCellMarginDefault(
                    new TopMargin { Width = "120", Type = TableWidthUnitValues.Dxa },
                    logicalSides
                        ? new StartMargin { Width = "180", Type = TableWidthUnitValues.Dxa }
                        : new TableCellLeftMargin { Width = 180, Type = TableWidthValues.Dxa },
                    new BottomMargin { Width = "60", Type = TableWidthUnitValues.Dxa },
                    logicalSides
                        ? new EndMargin { Width = "180", Type = TableWidthUnitValues.Dxa }
                        : new TableCellRightMargin { Width = 180, Type = TableWidthValues.Dxa })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new TableCellMargin(
                        new TopMargin { Width = "40", Type = TableWidthUnitValues.Dxa },
                        logicalSides
                            ? new StartMargin { Width = "360", Type = TableWidthUnitValues.Dxa }
                            : new LeftMargin { Width = "360", Type = TableWidthUnitValues.Dxa },
                        new BottomMargin { Width = "80", Type = TableWidthUnitValues.Dxa },
                        logicalSides
                            ? new EndMargin { Width = "220", Type = TableWidthUnitValues.Dxa }
                            : new RightMargin { Width = "220", Type = TableWidthUnitValues.Dxa })),
                        new Paragraph(new Run(new Text("Margin one")))),
                    new TableCell(new TableCellProperties(new TableCellMargin(
                        new TopMargin { Width = "240", Type = TableWidthUnitValues.Dxa })),
                        new Paragraph(new Run(new Text("Margin two"))))));
            var body = document.MainDocumentPart!.Document!.Body!;
            body.InsertBefore(table, body.GetFirstChild<SectionProperties>());
            document.MainDocumentPart.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var row = Assert.Single(index.ParagraphStyles,
            x => x.Formatting?.TableTerminator == true);
        Assert.Equal(new DocCellMargins(120, 180, 60, 180),
            row.Formatting!.TableDefaultCellMargins);
        Assert.Equal(new DocCellMargins(40, 360, 80, 220),
            row.Formatting.TableCellMargins?[0]);
        Assert.Equal(new DocCellMargins(Top: 240),
            row.Formatting.TableCellMargins?[1]);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var tableOut = Assert.Single(output.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        Assert.Equal((short)180, tableOut.TableProperties?.TableCellMarginDefault?
            .TableCellLeftMargin?.Width?.Value);
        var cells = tableOut.Descendants<TableCell>().ToArray();
        Assert.Equal("360", cells[0].TableCellProperties?.TableCellMargin?
            .LeftMargin?.Width?.Value);
        Assert.Equal("80", cells[0].TableCellProperties?.TableCellMargin?
            .BottomMargin?.Width?.Value);
        Assert.Equal("220", cells[0].TableCellProperties?.TableCellMargin?
            .RightMargin?.Width?.Value);
        Assert.Equal("240", cells[1].TableCellProperties?.TableCellMargin?
            .TopMargin?.Width?.Value);
        var validationErrors = new OpenXmlValidator().Validate(output).ToArray();
        Assert.True(validationErrors.Length == 0,
            string.Join("; ", validationErrors.Select(x => x.Description + " at " +
                x.Path?.XPath)));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-cell-margins-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var native = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            Assert.Contains(nativeIndex.ParagraphStyles,
                x => x.Formatting?.TableDefaultCellMargins ==
                    new DocCellMargins(120, 180, 60, 180));
            Assert.Contains(nativeIndex.ParagraphStyles,
                x => x.Formatting?.TableCellMargins?.Any(m =>
                    m?.Left == 360 || m?.Top == 240) == true);
            var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            var nativeTable = Assert.Single(nativeDocx.MainDocumentPart!.Document!
                .Body!.Elements<Table>());
            Assert.Equal((short)180, nativeTable.TableProperties?
                .TableCellMarginDefault?.TableCellLeftMargin?.Width?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false, false, false, false)]
    [InlineData(true, false, false, false)]
    [InlineData(true, true, false, false)]
    [InlineData(true, false, true, false)]
    [InlineData(true, false, false, true)]
    public void TableCellSpacingSurvivesBothDocRoutes(bool inherited,
        bool directOverride, bool marginOverride, bool derivedMargin)
    {
        static TableCell Cell(string value) => new(new Paragraph(new Run(new Text(value))));
        var expectedSpacing = directOverride ? "80" : "120";
        var expectedTopMargin = marginOverride ? "200" : "100";
        var expectedRightMargin = derivedMargin ? (short)40 : (short)0;
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            if (inherited)
            {
                var styles = main.AddNewPart<StyleDefinitionsPart>();
                var derivedStyle = new Style(new BasedOn { Val = "BaseTable" })
                { Type = StyleValues.Table, StyleId = "DerivedTable" };
                if (derivedMargin) derivedStyle.AppendChild(new StyleTableProperties(
                    new TableCellMarginDefault(new RightMargin
                    { Width = "40", Type = TableWidthUnitValues.Dxa })));
                styles.Styles = new Styles(
                    new Style(new StyleTableProperties(
                        new TableCellSpacing
                        { Width = "120", Type = TableWidthUnitValues.Dxa },
                        new TableBorders(new TopBorder
                        { Val = BorderValues.Single, Size = 8, Color = "CC3300" }),
                        new TableCellMarginDefault(new TopMargin
                        { Width = "100", Type = TableWidthUnitValues.Dxa })))
                    { Type = StyleValues.Table, StyleId = "BaseTable" },
                    derivedStyle);
                styles.Styles.Save();
            }
            var tableProperties = inherited
                ? new TableProperties(new TableStyle { Val = "DerivedTable" },
                    new TableLayout { Type = TableLayoutValues.Fixed })
                : new TableProperties(new TableCellSpacing
                { Width = "120", Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed });
            if (directOverride) tableProperties.InsertBefore(new TableCellSpacing
                { Width = "80", Type = TableWidthUnitValues.Dxa },
                tableProperties.GetFirstChild<TableLayout>());
            if (marginOverride) tableProperties.InsertBefore(
                new TableCellMarginDefault(new TopMargin
                { Width = "200", Type = TableWidthUnitValues.Dxa }),
                tableProperties.GetFirstChild<TableLayout>());
            main.Document = new Document(new Body(new Table(
                tableProperties,
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(Cell("A1"), Cell("B1")),
                new TableRow(Cell("A2"), Cell("B2")))));
            main.Document.Save();
        }
        if (inherited)
        {
            using var inspect = WordprocessingDocument.Open(new MemoryStream(source.ToArray()), false);
            var style = inspect.MainDocumentPart!.StyleDefinitionsPart!.Styles!
                .Elements<Style>().First();
            Assert.True(style.StyleTableProperties?.GetFirstChild<TableBorders>() != null,
                style.OuterXml);
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.All(index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true), x =>
            {
                Assert.Equal((ushort)(directOverride ? 80 : 120),
                    x.Formatting?.TableCellSpacingTwips);
                if (inherited)
                {
                    Assert.Equal((ushort)(marginOverride ? 200 : 100),
                        x.Formatting?.TableDefaultCellMargins?.Top);
                    Assert.Equal((ushort)expectedRightMargin,
                        x.Formatting?.TableDefaultCellMargins?.Right);
                    Assert.False(x.Formatting?.TableAutoFit);
                }
            });
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        Assert.Equal(expectedSpacing, Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).TableProperties?.GetFirstChild<TableCellSpacing>()?
            .Width?.Value);
        if (inherited) Assert.Equal(expectedTopMargin, Assert.Single(projected.MainDocumentPart!
            .Document!.Body!.Elements<Table>()).TableProperties?
            .TableCellMarginDefault?.TopMargin?.Width?.Value);
        if (inherited) Assert.Equal(expectedRightMargin, Assert.Single(projected.MainDocumentPart!
            .Document!.Body!.Elements<Table>()).TableProperties?
            .TableCellMarginDefault?.GetFirstChild<TableCellRightMargin>()?
            .Width?.Value);
        if (inherited)
        {
            var table = Assert.Single(projected.MainDocumentPart!.Document!.Body!
                .Elements<Table>());
            Assert.Equal(TableLayoutValues.Fixed,
                table.TableProperties?.TableLayout?.Type?.Value);
            Assert.Equal("CC3300", table.Elements<TableRow>().First()
                .Elements<TableCell>().First().TableCellProperties?
                .TableCellBorders?.TopBorder?.Color?.Value);
        }
        var errors = new OpenXmlValidator().Validate(projected).ToArray();
        Assert.True(errors.Length == 0, string.Join("; ", errors.Select(x =>
            x.Description + " at " + x.Path?.XPath)));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary,
                inherited ? 0.04 : 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-cell-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var savedPath = Path.ChangeExtension(sourcePath, ".saved.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(1, (int)opened.Tables.Count);
            var generatedRightPadding = inherited
                ? (double)opened.Tables[1].Cell(1, 1).RightPadding : 0;
            opened.SaveAs2(savedPath, 16);
            opened.Close(false);
            using (var savedStream = File.OpenRead(savedPath))
            using (var savedDocx = WordprocessingDocument.Open(savedStream, false))
            {
                Assert.Equal(expectedSpacing, Assert.Single(savedDocx.MainDocumentPart!
                    .Document!.Body!.Elements<Table>()).TableProperties?
                    .GetFirstChild<TableCellSpacing>()?.Width?.Value);
                if (inherited) Assert.Equal(expectedTopMargin, Assert.Single(savedDocx
                    .MainDocumentPart!.Document!.Body!.Elements<Table>())
                    .TableProperties?.TableCellMarginDefault?.TopMargin?.Width?.Value);
                if (derivedMargin) Assert.Equal(expectedRightMargin,
                    Assert.Single(savedDocx.MainDocumentPart!.Document!.Body!
                        .Elements<Table>()).TableProperties?.TableCellMarginDefault?
                        .GetFirstChild<TableCellRightMargin>()?.Width?.Value);
                if (inherited) Assert.Equal("CC3300", Assert.Single(savedDocx
                    .MainDocumentPart!.Document!.Body!.Elements<Table>())
                    .Elements<TableRow>().First().Elements<TableCell>().First()
                    .TableCellProperties?.TableCellBorders?.TopBorder?.Color?.Value);
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            if (inherited) Assert.Equal((double)opened.Tables[1].Cell(1, 1)
                .RightPadding, generatedRightPadding, 1);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var nativeStream = new MemoryStream(
                DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            Assert.Equal(expectedSpacing, Assert.Single(native.MainDocumentPart!.Document!
                .Body!.Elements<Table>()).TableProperties?
                .GetFirstChild<TableCellSpacing>()?.Width?.Value);
            if (inherited) Assert.Equal(expectedTopMargin, Assert.Single(native.MainDocumentPart!
                .Document!.Body!.Elements<Table>()).TableProperties?
                .TableCellMarginDefault?.TopMargin?.Width?.Value);
            if (derivedMargin) Assert.Equal(expectedRightMargin,
                Assert.Single(native.MainDocumentPart!.Document!.Body!
                    .Elements<Table>()).TableProperties?.TableCellMarginDefault?
                    .GetFirstChild<TableCellRightMargin>()?.Width?.Value);
            if (inherited) Assert.Equal("CC3300", Assert.Single(native.MainDocumentPart!
                .Document!.Body!.Elements<Table>()).Elements<TableRow>().First()
                .Elements<TableCell>().First().TableCellProperties?
                .TableCellBorders?.TopBorder?.Color?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(savedPath);
        }
    }

    [Theory]
    [InlineData(false, false, false, false, false)]
    [InlineData(true, false, false, false, false)]
    [InlineData(false, true, false, false, false)]
    [InlineData(true, true, false, false, false)]
    [InlineData(false, true, true, false, false)]
    [InlineData(true, true, true, false, false)]
    [InlineData(false, false, false, true, false)]
    [InlineData(false, false, false, false, true)]
    [InlineData(true, false, false, true, true)]
    [InlineData(false, true, true, true, false)]
    [InlineData(true, true, true, true, true)]
    [InlineData(false, false, false, true, false, true)]
    public void TableCellMarginsSurviveHeaderAndFooterStories(
        bool verticalMerge, bool logicalSides, bool rightToLeft, bool styled,
        bool rowSpacing, bool firstColumnBorder = false)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        var storyTableCount = 0;
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            if (styled)
            {
                var styles = main.StyleDefinitionsPart!.Styles!;
                styles.Append(new Style(new StyleTableProperties(
                    new TableCellSpacing
                    { Width = "120", Type = TableWidthUnitValues.Dxa },
                    new TableBorders(new TopBorder
                    { Val = BorderValues.Single, Size = 8, Color = "0055AA" }),
                    new TableCellMarginDefault(new TopMargin
                    { Width = "100", Type = TableWidthUnitValues.Dxa })),
                    new StyleTableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "DDEEFF" }),
                    new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new TableCellBorders(new TopBorder
                            { Val = BorderValues.Double, Size = 8, Color = "CC3300" }),
                            new Shading
                            { Val = ShadingPatternValues.Clear, Fill = "99DD99" }))
                    { Type = TableStyleOverrideValues.FirstRow },
                    new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new Shading
                            { Val = ShadingPatternValues.Clear, Fill = "FFCC99" }))
                    { Type = TableStyleOverrideValues.LastRow })
                { Type = StyleValues.Table, StyleId = "StoryTableBase" });
                styles.Append(new Style(new BasedOn { Val = "StoryTableBase" })
                { Type = StyleValues.Table, StyleId = "StoryTableDerived" });
                if (firstColumnBorder)
                    styles.Elements<Style>().First(x =>
                        x.StyleId?.Value == "StoryTableBase").Append(
                        new TableStyleProperties(
                            new TableStyleConditionalFormattingTableCellProperties(
                                new TableCellBorders(new LeftBorder
                                { Val = BorderValues.Single, Size = 8,
                                    Color = "00AA00" })))
                        { Type = TableStyleOverrideValues.FirstColumn });
                styles.Save();
            }
            foreach (var story in main.HeaderParts.Select(x =>
                (DocumentFormat.OpenXml.OpenXmlElement)x.Header!)
                .Concat(main.FooterParts.Select(x =>
                    (DocumentFormat.OpenXml.OpenXmlElement)x.Footer!)))
            {
                storyTableCount++;
                var defaults = new TableCellMarginDefault(new TopMargin
                { Width = "100", Type = TableWidthUnitValues.Dxa });
                if (logicalSides)
                {
                    defaults.AppendChild(new StartMargin
                    { Width = "108", Type = TableWidthUnitValues.Dxa });
                    defaults.AppendChild(new EndMargin
                    { Width = "108", Type = TableWidthUnitValues.Dxa });
                }
                var properties = styled
                    ? new TableProperties(new TableStyle { Val = "StoryTableDerived" },
                        new TableLayout { Type = TableLayoutValues.Fixed },
                        new TableLook { FirstRow = true, LastRow = rowSpacing,
                            FirstColumn = firstColumnBorder })
                    : new TableProperties(new TableLayout
                        { Type = TableLayoutValues.Fixed }, defaults);
                if (rightToLeft)
                {
                    if (styled) properties.InsertAfter(new BiDiVisual(),
                        properties.GetFirstChild<TableStyle>()!);
                    else properties.PrependChild(new BiDiVisual());
                }
                if (rightToLeft) properties.InsertBefore(new TableCellSpacing
                { Width = "120", Type = TableWidthUnitValues.Dxa },
                    properties.GetFirstChild<TableLayout>());
                if (rowSpacing) properties.InsertBefore(new TableCellSpacing
                { Width = "80", Type = TableWidthUnitValues.Dxa },
                    properties.GetFirstChild<TableLayout>());
                var margin = new TableCellMargin(logicalSides
                    ? new StartMargin
                    { Width = "200", Type = TableWidthUnitValues.Dxa }
                    : new LeftMargin
                    { Width = "200", Type = TableWidthUnitValues.Dxa });
                var table = verticalMerge
                    ? new Table(properties,
                        new TableGrid(new GridColumn { Width = "1000" },
                            new GridColumn { Width = "1000" }),
                        new TableRow(new TableCell(new TableCellProperties(
                            (TableCellMargin)margin.CloneNode(true),
                            new VerticalMerge { Val = MergedCellValues.Restart }),
                            new Paragraph(new Run(new Text("Story margin")))),
                            new TableCell(new Paragraph(new Run(new Text("Top"))))),
                        new TableRow(new TableCell(new TableCellProperties(
                            new VerticalMerge { Val = MergedCellValues.Continue }),
                            new Paragraph()),
                            new TableCell(new Paragraph(new Run(new Text("Bottom"))))))
                    : rowSpacing
                    ? new Table(properties,
                        new TableGrid(new GridColumn { Width = "2000" },
                            new GridColumn { Width = "2000" }),
                        new TableRow(new TableCell(new TableCellProperties(margin),
                            new Paragraph(new Run(new Text("Story margin")))),
                            new TableCell(new Paragraph(new Run(new Text("Top"))))),
                        new TableRow(new TableCell(new Paragraph(new Run(new Text("Bottom")))),
                            new TableCell(new Paragraph(new Run(new Text("End"))))))
                    : new Table(properties,
                        new TableGrid(new GridColumn { Width = "2000" }),
                        new TableRow(new TableCell(new TableCellProperties(margin),
                            new Paragraph(new Run(new Text("Story margin"))))));
                if (rowSpacing)
                {
                    var rows = table.Elements<TableRow>().ToArray();
                    rows[0].PrependChild(new TableRowProperties(new TableCellSpacing
                    { Width = "40", Type = TableWidthUnitValues.Dxa }));
                    rows[1].PrependChild(new TablePropertyExceptions(new TableCellSpacing
                    { Width = "0", Type = TableWidthUnitValues.Dxa }));
                }
                story.PrependChild(table);
            }
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        if (firstColumnBorder)
            Assert.Equal(0x0000AA00u, Assert.Single(index.StyleDefinitions,
                x => x.Name == "StoryTableBase").ConditionalTableBorders![0x0004]
                .Left?.ColorRgb);
        Assert.Equal(storyTableCount, index.ParagraphStyles.Count(x =>
            x.Formatting?.TableTerminator == true &&
            x.Formatting.TableDefaultCellMargins?.Top == 100 &&
            x.Formatting.TableCellMargins?[0]?.Left == 200));
        Assert.Equal(storyTableCount * (verticalMerge || rowSpacing ? 2 : 1),
            index.ParagraphStyles.Count(x => x.Formatting?.TableTerminator == true &&
                x.Formatting.TableRightToLeft == rightToLeft));
        if ((rightToLeft || styled) && !rowSpacing)
            Assert.Equal(storyTableCount * (verticalMerge ? 2 : 1),
                index.ParagraphStyles.Count(x => x.Formatting?.TableTerminator == true &&
                    x.Formatting.TableCellSpacingTwips == 120));
        if (rowSpacing)
        {
            Assert.Equal(storyTableCount, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellSpacingTwips == 40));
            Assert.Equal(storyTableCount, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellSpacingTwips == 0));
        }
        if (verticalMerge)
        {
            Assert.Equal(storyTableCount, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellVerticalMerges?[0] == 3));
            Assert.Equal(storyTableCount, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellVerticalMerges?[0] == 1));
        }
        var projection = new DocToDocxProjector().Project(index);
        if (styled) Assert.Contains(index.StyleDefinitions, x => x.Type == 3 &&
            x.TableFormatting?.TableBorders?.Top?.ColorRgb == 0x00AA5500u);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var storyTables = output.MainDocumentPart!.HeaderParts
            .SelectMany(x => x.Header!.Elements<Table>())
            .Concat(output.MainDocumentPart.FooterParts
                .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(storyTableCount, storyTables.Length);
        foreach (var table in storyTables)
        {
            Assert.Equal(rightToLeft,
                table.TableProperties?.GetFirstChild<BiDiVisual>() != null);
            Assert.Equal((rightToLeft || styled) && !rowSpacing ? "120" : null,
                table.TableProperties?.GetFirstChild<TableCellSpacing>()?.Width?.Value);
            Assert.Equal("100", table.TableProperties?.TableCellMarginDefault?
                .TopMargin?.Width?.Value);
            Assert.Equal((short)(styled ? 0 : 108), table.TableProperties?.TableCellMarginDefault?
                .GetFirstChild<TableCellLeftMargin>()?.Width?.Value);
            Assert.Equal((short)(styled ? 0 : 108), table.TableProperties?.TableCellMarginDefault?
                .GetFirstChild<TableCellRightMargin>()?.Width?.Value);
            var rows = table.Elements<TableRow>().ToArray();
            Assert.Equal(verticalMerge || rowSpacing ? 2 : 1, rows.Length);
            if (rowSpacing) Assert.Equal(new[] { "40", "0" }, rows.Select(x =>
                x.TableRowProperties?.GetFirstChild<TableCellSpacing>()?
                    .Width?.Value));
            Assert.Equal("200", rows[0].Elements<TableCell>().First()
                .TableCellProperties?.TableCellMargin?.LeftMargin?.Width?.Value);
            if (firstColumnBorder)
            {
                Assert.Null(rows[0].Elements<TableCell>().First()
                    .TableCellProperties?.TableCellWidth);
            }
            if (styled)
            {
                Assert.Equal(rows.SelectMany((row, index) =>
                    row.Elements<TableCell>().Select(_ => index == 0 ? "99DD99" :
                        rowSpacing ? "FFCC99" : "DDEEFF")),
                    table.Descendants<TableCell>().Select(cell => cell.TableCellProperties?
                        .Shading?.Fill?.Value));
                Assert.Equal("CC3300", rows[0].Elements<TableCell>().First()
                    .TableCellProperties?.TableCellBorders?.TopBorder?.Color?.Value);
            }
            if (verticalMerge)
            {
                Assert.Equal(MergedCellValues.Restart, rows[0].Elements<TableCell>()
                    .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
                Assert.Equal(MergedCellValues.Continue, rows[1].Elements<TableCell>()
                    .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
            }
        }
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (firstColumnBorder)
        {
            var baseStyle = Assert.Single(output.MainDocumentPart.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), style => style.StyleName?.Val?.Value == "StoryTableBase");
            Assert.Single(baseStyle.StyleTableProperties!.TableBorders!.ChildElements);
            Assert.Equal("0055AA", baseStyle.StyleTableProperties.TableBorders!
                .TopBorder?.Color?.Value);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary,
                styled || rowSpacing ? 0.03 : rightToLeft ? 0.03 : verticalMerge ? 0.025 : 0.015);
        if (firstColumnBorder)
        {
            var rewritten = DxpDocExport.Export(projection.DocxBytes);
            using var repeat = new MemoryStream(rewritten);
            using var repeatIndex = new DocTextIndexWalker().Index(repeat);
            Assert.Contains(repeatIndex.StyleDefinitions, style =>
                style.ConditionalTableBorders?.TryGetValue(0x0004, out var border) == true &&
                border.Left?.ColorRgb == 0x0000AA00u);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                    0.032, 1, ".docx");
                AssertWordFirstPageRenderClose(source.ToArray(), rewritten, 0.04);
            }
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-header-table-source-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var wordSavedPath = Path.ChangeExtension(sourcePath, ".word-saved.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? sourceWord = null, generatedWord = null;
        try
        {
            sourceWord = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            generatedWord = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            for (var slot = 1; slot <= 3; slot++)
            {
                Assert.Equal((int)sourceWord.Sections[1].Headers[slot].Range.Tables.Count,
                    (int)generatedWord.Sections[1].Headers[slot].Range.Tables.Count);
                Assert.Equal((int)sourceWord.Sections[1].Footers[slot].Range.Tables.Count,
                    (int)generatedWord.Sections[1].Footers[slot].Range.Tables.Count);
                if (rightToLeft)
                {
                    // Word's wdTableDirectionRtl is 0.
                    Assert.Equal(0, (int)sourceWord.Sections[1].Headers[slot]
                        .Range.Tables[1].TableDirection);
                    Assert.Equal(0, (int)generatedWord.Sections[1].Headers[slot]
                        .Range.Tables[1].TableDirection);
                    Assert.Equal(0, (int)sourceWord.Sections[1].Footers[slot]
                        .Range.Tables[1].TableDirection);
                    Assert.Equal(0, (int)generatedWord.Sections[1].Footers[slot]
                        .Range.Tables[1].TableDirection);
                }
                Assert.Contains("Story margin", (string)generatedWord.Sections[1]
                    .Headers[slot].Range.Text);
                Assert.Contains("Story margin", (string)generatedWord.Sections[1]
                    .Footers[slot].Range.Text);
            }
            if (styled)
            {
                Assert.Equal((int)sourceWord.Sections[1].Headers[1]
                    .Range.Tables[1].Cell(1, 1).Borders.Item(-1).Color,
                    (int)generatedWord.Sections[1].Headers[1]
                    .Range.Tables[1].Cell(1, 1).Borders.Item(-1).Color);
                Assert.Equal((int)sourceWord.Sections[1].Footers[1]
                    .Range.Tables[1].Cell(1, 1).Borders.Item(-1).Color,
                    (int)generatedWord.Sections[1].Footers[1]
                    .Range.Tables[1].Cell(1, 1).Borders.Item(-1).Color);
                Assert.Equal((double)sourceWord.Sections[1].Headers[1]
                    .Range.Tables[1].Cell(1, 1).RightPadding,
                    (double)generatedWord.Sections[1].Headers[1]
                    .Range.Tables[1].Cell(1, 1).RightPadding, 1);
                Assert.Equal((double)sourceWord.Sections[1].Footers[1]
                    .Range.Tables[1].Cell(1, 1).RightPadding,
                    (double)generatedWord.Sections[1].Footers[1]
                    .Range.Tables[1].Cell(1, 1).RightPadding, 1);
            }
            if (rightToLeft || styled || rowSpacing)
            {
                generatedWord.SaveAs2(wordSavedPath, 16);
                generatedWord.Close(false);
                generatedWord = null;
                using var savedStream = File.OpenRead(wordSavedPath);
                using var savedDocx = WordprocessingDocument.Open(savedStream, false);
                var savedTables = savedDocx.MainDocumentPart!.HeaderParts
                    .SelectMany(x => x.Header!.Elements<Table>())
                    .Concat(savedDocx.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
                string? EffectiveFill(Table table, TableCell cell)
                {
                    var direct = cell.TableCellProperties?.Shading?.Fill?.Value;
                    if (direct != null) return direct;
                    var styleId = table.TableProperties?.TableStyle?.Val?.Value;
                    var visited = new HashSet<string>(StringComparer.Ordinal);
                    while (styleId != null && visited.Add(styleId))
                    {
                        var style = savedDocx.MainDocumentPart.StyleDefinitionsPart?
                            .Styles?.Elements<Style>().FirstOrDefault(x =>
                                x.StyleId?.Value == styleId);
                        if (style?.StyleTableCellProperties?.Shading?.Fill?.Value is string fill)
                            return fill;
                        styleId = style?.BasedOn?.Val?.Value;
                    }
                    return null;
                }
                string? EffectiveSpacing(Table table)
                {
                    var direct = table.TableProperties?
                        .GetFirstChild<TableCellSpacing>()?.Width?.Value;
                    if (direct != null) return direct;
                    var styleId = table.TableProperties?.TableStyle?.Val?.Value;
                    var visited = new HashSet<string>(StringComparer.Ordinal);
                    while (styleId != null && visited.Add(styleId))
                    {
                        var style = savedDocx.MainDocumentPart.StyleDefinitionsPart?
                            .Styles?.Elements<Style>().FirstOrDefault(x =>
                                x.StyleId?.Value == styleId);
                        if (style?.StyleTableProperties?
                            .GetFirstChild<TableCellSpacing>()?.Width?.Value is string spacing)
                            return spacing;
                        styleId = style?.BasedOn?.Val?.Value;
                    }
                    return null;
                }
                Assert.Equal(storyTableCount, savedTables.Length);
                Assert.All(savedTables, x =>
                {
                    Assert.Equal(rightToLeft,
                        x.TableProperties?.GetFirstChild<BiDiVisual>() != null);
                    if (styled && !rowSpacing) Assert.Equal("120", EffectiveSpacing(x));
                    if (styled) Assert.Equal(x.Elements<TableRow>()
                        .SelectMany((row, index) => row.Elements<TableCell>()
                            .Select(_ => index == 0 ? "99DD99" :
                                rowSpacing ? "FFCC99" : "DDEEFF")),
                        x.Descendants<TableCell>().Select(cell => EffectiveFill(x, cell)));
                    if (rowSpacing) Assert.Equal(new[] { "40", "0" },
                        x.Elements<TableRow>().Select(row => row.TableRowProperties?
                            .GetFirstChild<TableCellSpacing>()?.Width?.Value));
                });
            }
            sourceWord.SaveAs2(nativePath, 0);
            sourceWord.Close(false);
            sourceWord = null;
            if (styled)
            {
                using var nativeStyleStream = File.OpenRead(nativePath);
                using var nativeStyleIndex = new DocTextIndexWalker().Index(nativeStyleStream);
                Assert.Contains(nativeStyleIndex.StyleDefinitions, x => x.Type == 3 &&
                    x.TableFormatting?.TableStyleShading?.FillRgb == 0x00FFEEDDu &&
                    x.TableFormatting.TableCellSpacingTwips == 120 &&
                    x.TableFormatting.TableDefaultCellMargins?.Top == 100);
            }
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            var nativeTables = nativeDocx.MainDocumentPart!.HeaderParts
                .SelectMany(x => x.Header!.Elements<Table>())
                .Concat(nativeDocx.MainDocumentPart.FooterParts
                    .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
            Assert.Equal(storyTableCount, nativeTables.Length);
            foreach (var table in nativeTables)
            {
                Assert.Equal(rightToLeft,
                    table.TableProperties?.GetFirstChild<BiDiVisual>() != null);
                Assert.Equal((rightToLeft || styled) && !rowSpacing ? "120" : null,
                    table.TableProperties?.GetFirstChild<TableCellSpacing>()?.Width?.Value);
                if (rowSpacing) Assert.Equal(new[] { "40", "0" },
                    table.Elements<TableRow>().Select(row => row.TableRowProperties?
                        .GetFirstChild<TableCellSpacing>()?.Width?.Value));
                Assert.Equal("100", table.TableProperties?.TableCellMarginDefault?
                    .TopMargin?.Width?.Value);
                Assert.Equal("200", table.Elements<TableRow>().First()
                    .Elements<TableCell>().First().TableCellProperties?
                    .TableCellMargin?.LeftMargin?.Width?.Value);
                // Word's DOC save loses the conditional fill in four story tables;
                // this native fixture cannot establish a green first-row oracle.
                if (!verticalMerge) continue;
                var rows = table.Elements<TableRow>().ToArray();
                Assert.Equal(MergedCellValues.Restart, rows[0].Elements<TableCell>()
                    .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
                Assert.Equal(MergedCellValues.Continue, rows[1].Elements<TableCell>()
                    .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (sourceWord != null) sourceWord.Close(false);
            if (generatedWord != null) generatedWord.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(wordSavedPath);
        }
    }

    [Fact]
    public void ThemeParagraphShadingResolvesInBodyHeaderAndFooter()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        var fills = new[] { ThemeColorValues.Accent1, ThemeColorValues.Accent2,
            ThemeColorValues.Accent3 };
        var foregrounds = new[] { ThemeColorValues.Accent4,
            ThemeColorValues.Accent5, ThemeColorValues.Accent1 };
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var paragraphs = new[]
            {
                main.Document!.Body!.Elements<Paragraph>().First(),
                main.HeaderParts.SelectMany(x => x.Header!.Elements<Paragraph>())
                    .First(x => x.InnerText.Contains("Derived")),
                main.FooterParts.SelectMany(x => x.Footer!.Elements<Paragraph>())
                    .First(x => x.InnerText.Contains("Derived"))
            };
            for (var i = 0; i < paragraphs.Length; i++)
            {
                paragraphs[i].ParagraphProperties ??= new ParagraphProperties();
                paragraphs[i].ParagraphProperties.Shading = new Shading
                {
                    Val = ShadingPatternValues.Percent50,
                    Fill = "FFFFFF", ThemeFill = fills[i],
                    Color = "FFFFFF", ThemeColor = foregrounds[i]
                };
                paragraphs[i].ParagraphProperties.ParagraphBorders =
                    new ParagraphBorders(new BottomBorder
                    {
                        Val = i == 0 ? BorderValues.DotDash :
                            i == 1 ? BorderValues.Wave : BorderValues.DashSmallGap,
                        Size = 8,
                        Color = "FFFFFF", ThemeColor = fills[i]
                    });
            }
            main.Document.Save();
            foreach (var part in main.HeaderParts) part.Header?.Save();
            foreach (var part in main.FooterParts) part.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        foreach (var fill in new[] { 0x00826015u, 0x003271E9u, 0x00246B19u })
            Assert.Contains(index.ParagraphStyles,
                x => x.Formatting?.FillRgb == fill &&
                    x.Formatting.ShadingPattern == 8 &&
                    x.Formatting.BottomBorder?.ColorRgb == fill);
        foreach (var type in new byte[] { 8, 20, 22 })
            Assert.Contains(index.ParagraphStyles,
                x => x.Formatting?.BottomBorder?.Type == type);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var projected = new[]
        {
            output.MainDocumentPart!.Document!.Body!.Elements<Paragraph>().First(),
            output.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()).First(x => x.InnerText.Contains("Derived")),
            output.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>()).First(x => x.InnerText.Contains("Derived"))
        };
        Assert.Equal(new[] { "156082", "E97132", "196B24" },
            projected.Select(x => x.ParagraphProperties?.Shading?.Fill?.Value));
        Assert.Equal(new[] { "0F9ED5", "A02B93", "156082" },
            projected.Select(x => x.ParagraphProperties?.Shading?.Color?.Value));
        Assert.Equal(new[] { "156082", "E97132", "196B24" },
            projected.Select(x => x.ParagraphProperties?.ParagraphBorders?
                .BottomBorder?.Color?.Value));
        Assert.Equal(new BorderValues?[] { BorderValues.DotDash, BorderValues.Wave,
            BorderValues.DashSmallGap }, projected.Select(x =>
            x.ParagraphProperties?.ParagraphBorders?.BottomBorder?.Val?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(output));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-theme-paragraph-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var nativeBytes = File.ReadAllBytes(nativePath);
            using var native = new MemoryStream(nativeBytes);
            using var nativeIndex = new DocTextIndexWalker().Index(native);
            foreach (var fill in new[] { 0x00826015u, 0x003271E9u, 0x00246B19u })
                Assert.Contains(nativeIndex.ParagraphStyles,
                    x => x.Formatting?.FillRgb == fill);
            foreach (var type in new byte[] { 8, 20, 22 })
                Assert.Contains(nativeIndex.ParagraphStyles,
                    x => x.Formatting?.BottomBorder?.Type == type);
            var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            var nativeMain = nativeDocx.MainDocumentPart!;
            Assert.Contains(nativeMain.Document!.Body!.Elements<Paragraph>(),
                x => x.ParagraphProperties?.Shading?.Fill?.Value == "156082");
            Assert.Contains(nativeMain.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()),
                x => x.ParagraphProperties?.Shading?.Fill?.Value == "E97132");
            Assert.Contains(nativeMain.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>()),
                x => x.ParagraphProperties?.Shading?.Fill?.Value == "196B24");
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void StandardDocBorderLineStylesRoundTripWithoutDisappearing()
    {
        var styles = new[]
        {
            BorderValues.DotDash, BorderValues.DotDotDash, BorderValues.Triple,
            BorderValues.ThinThickSmallGap, BorderValues.ThickThinSmallGap,
            BorderValues.ThinThickThinSmallGap, BorderValues.ThinThickMediumGap,
            BorderValues.ThickThinMediumGap, BorderValues.ThinThickThinMediumGap,
            BorderValues.ThinThickLargeGap, BorderValues.ThickThinLargeGap,
            BorderValues.ThinThickThinLargeGap, BorderValues.Wave,
            BorderValues.DoubleWave, BorderValues.DashSmallGap,
            BorderValues.DashDotStroked, BorderValues.ThreeDEmboss,
            BorderValues.ThreeDEngrave, BorderValues.Outset, BorderValues.Inset
        };
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var body = document.MainDocumentPart!.Document!.Body!;
            for (var i = 0; i < styles.Length; i++)
                body.InsertBefore(new Paragraph(
                    new ParagraphProperties(new ParagraphBorders(new BottomBorder
                    {
                        Val = styles[i], Size = 8, Color = "123456"
                    })), new Run(new Text($"Border style {i}"))),
                    body.GetFirstChild<SectionProperties>());
            document.MainDocumentPart.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        for (var i = 0; i < styles.Length; i++)
            Assert.Contains(index.ParagraphStyles, x =>
                x.Formatting?.BottomBorder?.Type == i + 8);
        var projection = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var output = WordprocessingDocument.Open(stream, false);
        var projected = output.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>().Where(x => x.InnerText.StartsWith("Border style "))
            .ToArray();
        Assert.Equal(styles.Length, projected.Length);
        for (var i = 0; i < styles.Length; i++)
            Assert.Equal(styles[i], projected[i].ParagraphProperties?
                .ParagraphBorders?.BottomBorder?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(output));
    }

