    [Fact]
    public void IndexedTableRowsKeepStoryPositionsAndPhysicalOffsets()
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var source = File.ReadAllBytes(Path.Combine(directory, "WordTablesAllStories.docx"));
        foreach (var binary in new[]
        {
            File.ReadAllBytes(Path.Combine(directory, "WordTablesAllStories.doc")),
            DxpDocExport.Export(source)
        })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            foreach (var story in new[] { index.ReadStory("Main"),
                index.HeaderStories[7].ReadIndexedContent(),
                index.HeaderStories[9].ReadIndexedContent() })
            {
                Assert.NotEmpty(story.TableRows);
                Assert.DoesNotContain(story.StoryParagraphStyles,
                    x => DocStoryTableRow.IsRow(x.Formatting));
                Assert.NotEmpty(story.ParagraphRanges);
                Assert.Contains(story.ParagraphRanges,
                    x => x.EndKind == DocParagraphEnd.CellMark);
                Assert.Contains(story.ParagraphRanges,
                    x => x.EndKind == DocParagraphEnd.RowMark);
                Assert.Equal(0, story.ParagraphRanges[0].Start);
                Assert.Equal(checked((int)(story.Text.CpEnd - story.Text.CpStart)),
                    story.ParagraphRanges[^1].End);
                for (var i = 0; i < story.ParagraphRanges.Count; i++)
                {
                    var paragraph = story.ParagraphRanges[i];
                    if (i > 0) Assert.Equal(story.ParagraphRanges[i - 1].End,
                        paragraph.Start);
                    Assert.Equal(story.Text.CpStart + (uint)paragraph.Start,
                        paragraph.SourceCpStart);
                    Assert.Equal(story.Text.CpStart + (uint)paragraph.End,
                        paragraph.SourceCpEnd);
                    Assert.Equal(index.GetTextOffset(paragraph.SourceCpStart!.Value),
                        paragraph.SourceTextOffsetStart);
                    Assert.NotNull(paragraph.SourceTextOffsetEnd);
                }
                foreach (var row in story.TableRows)
                {
                    Assert.True(row.Start >= 0 && row.End <=
                        story.Text.CpEnd - story.Text.CpStart);
                    Assert.Equal(story.Text.CpStart + (uint)row.Start,
                        row.SourceCpStart);
                    Assert.Equal(story.Text.CpStart + (uint)row.End,
                        row.SourceCpEnd);
                    Assert.Equal(index.GetTextOffset(row.SourceCpStart!.Value),
                        row.SourceTextOffset);
                    Assert.NotNull(row.Formatting.TableCellEdges);
                }
            }
            var projected = DxpDocToDocx.Project(binary);
            using var projectedStream = new MemoryStream(projected.DocxBytes);
            using var document = WordprocessingDocument.Open(projectedStream, false);
            Assert.NotEmpty(document.MainDocumentPart!.Document!.Body!
                .Descendants<Table>());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
    }

    [Fact]
    public void AdjacentDocRowsWithDifferentTableStylesProjectAsSeparateTables()
    {
        const string text = "One\u0007\u0007Two\u0007\u0007\r";
        var inTable = new DocParagraphFormatting(null, null, null, InTable: true);
        var firstRow = inTable with
        {
            TableTerminator = true,
            TableCellEdges = new short[] { 0, 2000 },
            TableStyleIndex = 11
        };
        var secondRow = firstRow with { TableStyleIndex = 46 };
        var runs = new[]
        {
            new DocPlainTextParagraphStyleRun(0, 4, 0, inTable),
            new DocPlainTextParagraphStyleRun(4, 5, 0, firstRow),
            new DocPlainTextParagraphStyleRun(5, 9, 0, inTable),
            new DocPlainTextParagraphStyleRun(9, 10, 0, secondRow)
        };
        var tableStyle = new DocStyleDefinition(46, "Blue Table", 3, 11, null,
            DocCharacterFormatting.Empty,
            TableFormatting: new DocParagraphFormatting(null, null, null,
                TableStyleShading: new DocCellShading(0x00FFEEDDu, null, 0),
                TableCellSpacingTwips: 120,
                TableDefaultCellMargins: new DocCellMargins(Top: 100),
                TableBorders: new DocTableBorders(
                    new DocParagraphBorder(1, 8, 0, 0x00AA5500u),
                    null, null, null, null, null)));
        var story = new DocPlainTextStory(text, [], runs.Select(x =>
            new DocStoryParagraphStyleRun(x.Start, x.End, x.StyleIndex,
                x.Formatting)).ToArray())
        {
            Paragraphs = DocStoryParagraphRange.Capture(text, runs)
        };
        using var binary = new MemoryStream();
        DocPlainTextWriter.Write(binary, new DocPlainTextDocument(story,
            [new DocPlainTextSection(text.Length, new DocPlainTextStory?[6])],
            Styles: [tableStyle]));
        binary.Position = 0;
        using var index = new DocTextIndexWalker().Index(binary);
        Assert.Equal(new ushort?[] { 11, 46 }, index.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).Select(x =>
                x.Formatting?.TableStyleIndex));
        Assert.Equal(0x00FFEEDDu, Assert.Single(index.StyleDefinitions,
            x => x.Index == 46).TableFormatting?.TableStyleShading?.FillRgb);
        Assert.Equal((ushort)120, Assert.Single(index.StyleDefinitions,
            x => x.Index == 46).TableFormatting?.TableCellSpacingTwips);
        Assert.Equal(0x00AA5500u, Assert.Single(index.StyleDefinitions,
            x => x.Index == 46).TableFormatting?.TableBorders?.Top?.ColorRgb);
        using var stream = new MemoryStream(new DocToDocxProjector().Project(index).DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var tables = projected.MainDocumentPart!.Document!.Body!.Elements<Table>().ToArray();
        Assert.Equal(new[] { "One", "Two" }, tables.Select(x => x.InnerText));
        Assert.Equal("DocStyle46", tables[1].TableProperties?.TableStyle?.Val?.Value);
        Assert.Equal("DDEEFF", projected.MainDocumentPart.StyleDefinitionsPart?.Styles?
            .Elements<Style>().Single(x => x.StyleId == "DocStyle46")
            .StyleTableCellProperties?.Shading?.Fill?.Value);
        Assert.Equal("120", projected.MainDocumentPart.StyleDefinitionsPart?.Styles?
            .Elements<Style>().Single(x => x.StyleId == "DocStyle46")
            .StyleTableProperties?.GetFirstChild<TableCellSpacing>()?.Width?.Value);
        Assert.Equal("100", projected.MainDocumentPart.StyleDefinitionsPart?.Styles?
            .Elements<Style>().Single(x => x.StyleId == "DocStyle46")
            .StyleTableProperties?.TableCellMarginDefault?.TopMargin?.Width?.Value);
        Assert.Equal("0055AA", projected.MainDocumentPart.StyleDefinitionsPart?.Styles?
            .Elements<Style>().Single(x => x.StyleId == "DocStyle46")
            .StyleTableProperties?.TableBorders?.TopBorder?.Color?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var reverse = DxpDocExport.Export(stream.ToArray());
        using (var reverseIndexStream = new MemoryStream(reverse))
        using (var reverseIndex = new DocTextIndexWalker().Index(reverseIndexStream))
        {
            var retainedStyle = Assert.Single(reverseIndex.StyleDefinitions,
                x => x.Name == "Blue Table");
            Assert.Equal((ushort)120, retainedStyle.TableFormatting?.TableCellSpacingTwips);
            Assert.Equal((ushort)100, retainedStyle.TableFormatting?
                .TableDefaultCellMargins?.Top);
            Assert.Equal(0x00AA5500u, retainedStyle.TableFormatting?
                .TableBorders?.Top?.ColorRgb);
        }
        using var reverseStream = new MemoryStream(DxpDocToDocx.Project(reverse).DocxBytes);
        using var reversed = WordprocessingDocument.Open(reverseStream, false);
        Assert.Equal(new[] { "One", "Two" }, reversed.MainDocumentPart!.Document!.Body!
            .Elements<Table>().Select(x => x.InnerText));
        Assert.Equal("DDEEFF", reversed.MainDocumentPart!.Document!.Body!
            .Elements<Table>().Last().Descendants<TableCell>().Single()
            .TableCellProperties?.Shading?.Fill?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(reversed));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(stream.ToArray(), binary.ToArray(), 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-applied-table-style-{Guid.NewGuid():N}.doc");
        var savedPath = Path.ChangeExtension(path, ".saved.docx");
        File.WriteAllBytes(path, binary.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true, AddToRecentFiles: false);
            Assert.Equal(2, (int)opened.Tables.Count);
            Assert.Equal("Blue Table", (string)opened.Tables[2].Style.NameLocal);
            opened.SaveAs2(savedPath, 16);
            opened.Close(false);
            opened = null;
            using var savedStream = File.OpenRead(savedPath);
            using var saved = WordprocessingDocument.Open(savedStream, false);
            var savedTables = saved.MainDocumentPart!.Document!.Body!
                .Elements<Table>().ToArray();
            var savedStyleId = savedTables[1].TableProperties?.TableStyle?.Val?.Value;
            Assert.False(string.IsNullOrEmpty(savedStyleId));
            Assert.Equal("DDEEFF", saved.MainDocumentPart.StyleDefinitionsPart?.Styles?
                .Elements<Style>().Single(x => x.StyleId == savedStyleId)
                .StyleTableCellProperties?.Shading?.Fill?.Value);
            Assert.Equal("120", saved.MainDocumentPart.StyleDefinitionsPart?.Styles?
                .Elements<Style>().Single(x => x.StyleId == savedStyleId)
                .StyleTableProperties?.GetFirstChild<TableCellSpacing>()?.Width?.Value);
            Assert.Equal("100", saved.MainDocumentPart.StyleDefinitionsPart?.Styles?
                .Elements<Style>().Single(x => x.StyleId == savedStyleId)
                .StyleTableProperties?.TableCellMarginDefault?.TopMargin?.Width?.Value);
            Assert.Equal("0055AA", saved.MainDocumentPart.StyleDefinitionsPart?.Styles?
                .Elements<Style>().Single(x => x.StyleId == savedStyleId)
                .StyleTableProperties?.TableBorders?.TopBorder?.Color?.Value);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
            File.Delete(savedPath);
        }
    }

    [Fact]
    public void AdjacentTablesWithSameStyleKeepTheirDocGroupBoundary()
    {
        static Table TableFor(string text) => new(
            new TableProperties(new TableStyle { Val = "BlueTable" },
                new TableLayout { Type = TableLayoutValues.Fixed }),
            new TableGrid(new GridColumn { Width = "2200" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(TableFor("First"), TableFor("Second")));
            main.Document.Save();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(
                new StyleTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = "DDEEFF" }))
            { Type = StyleValues.Table, StyleId = "BlueTable" });
            styles.Styles.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).Select(x => x.Formatting!).ToArray();
            Assert.Equal(2, rows.Length);
            Assert.Equal(new uint?[] { 1, 2 }, rows.Select(x => x.TableGroupId));
            Assert.All(rows, x => Assert.Equal(x.TableGroupId, x.ParagraphGroupId));
            var pageProperties = Assert.Single(index.Structure.Locations,
                x => x.Name == "PageProperties");
            var groupRecords = index.Structure.ReadRange(pageProperties.StreamName!,
                pageProperties.Offset, checked((int)pageProperties.Length));
            Assert.Equal(30, groupRecords.Length);
            Assert.Equal((ushort)2, BinaryPrimitives.ReadUInt16LittleEndian(groupRecords));
            Assert.Equal(1u, BinaryPrimitives.ReadUInt32LittleEndian(groupRecords.AsSpan(2)));
            Assert.Equal(2u, BinaryPrimitives.ReadUInt32LittleEndian(groupRecords.AsSpan(16)));
        }
        using var stream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        Assert.Equal(new[] { "First", "Second" }, projected.MainDocumentPart!
            .Document!.Body!.Elements<Table>().Select(x => x.InnerText));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var secondBinary = DxpDocExport.Export(stream.ToArray());
        using var secondStream = new MemoryStream(DxpDocToDocx.Project(secondBinary).DocxBytes);
        using var secondProjection = WordprocessingDocument.Open(secondStream, false);
        Assert.Equal(new[] { "First", "Second" }, secondProjection.MainDocumentPart!
            .Document!.Body!.Elements<Table>().Select(x => x.InnerText));
        Assert.Empty(new OpenXmlValidator().Validate(secondProjection));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-adjacent-same-style-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true, AddToRecentFiles: false);
            Assert.Equal(2, (int)opened.Tables.Count);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void AdjacentSameStyleTablesStaySeparateInHeaderAndFooterStories(
        bool activateAllSlots)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeLevelStyleOverrides.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(path));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            main.StyleDefinitionsPart!.Styles!.AppendChild(new Style(
                new StyleTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = "DDEEFF" }))
            { Type = StyleValues.Table, StyleId = "AdjacentStoryStyle" });
            main.StyleDefinitionsPart.Styles.Save();
            if (activateAllSlots)
            {
                var settings = main.DocumentSettingsPart ??
                    main.AddNewPart<DocumentSettingsPart>();
                settings.Settings ??= new Settings();
                settings.Settings.AppendChild(new EvenAndOddHeaders());
                settings.Settings.Save();
                main.Document!.Body!.Descendants<SectionProperties>().First()
                    .AppendChild(new TitlePage());
                main.Document.Body.PrependChild(new Paragraph(new Run(new Break
                    { Type = BreakValues.Page })));
                main.Document.Body.PrependChild(new Paragraph(new Run(new Break
                    { Type = BreakValues.Page })));
                main.Document.Save();
            }
            foreach (var story in main.HeaderParts.Select(x =>
                (DocumentFormat.OpenXml.OpenXmlCompositeElement)x.Header!)
                .Concat(main.FooterParts.Select(x =>
                    (DocumentFormat.OpenXml.OpenXmlCompositeElement)x.Footer!)))
            {
                Table Create(string label) => new(
                    new TableProperties(new TableStyle { Val = "AdjacentStoryStyle" },
                        new TableLayout { Type = TableLayoutValues.Fixed }),
                    new TableGrid(new GridColumn { Width = "1800" }),
                    new TableRow(new TableCell(new Paragraph(new Run(new Text(label))))));
                story.PrependChild(Create("Second adjacent"));
                story.PrependChild(Create("First adjacent"));
            }
            foreach (var header in main.HeaderParts) header.Header?.Save();
            foreach (var footer in main.FooterParts) footer.Footer?.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableGroupId is > 0).ToArray();
            Assert.Equal(12, rows.Length);
            Assert.All(rows, x => Assert.Equal(
                new DocCellMargins(Top: 0, Left: 0, Bottom: 0, Right: 0),
                x.Formatting!.TableDefaultCellMargins));
        }
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var storyTables = projected.MainDocumentPart!.HeaderParts
            .SelectMany(x => x.Header!.Elements<Table>())
            .Concat(projected.MainDocumentPart.FooterParts
                .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(12, storyTables.Length);
        Assert.Equal(6, storyTables.Count(x => x.InnerText == "First adjacent"));
        Assert.Equal(6, storyTables.Count(x => x.InnerText == "Second adjacent"));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var reverse = DxpDocExport.Export(projectedStream.ToArray());
        using var reverseStream = new MemoryStream(DxpDocToDocx.Project(reverse).DocxBytes);
        using var reversed = WordprocessingDocument.Open(reverseStream, false);
        Assert.Equal(12, reversed.MainDocumentPart!.HeaderParts
            .SelectMany(x => x.Header!.Elements<Table>())
            .Concat(reversed.MainDocumentPart.FooterParts
                .SelectMany(x => x.Footer!.Elements<Table>())).Count());
        Assert.Empty(new OpenXmlValidator().Validate(reversed));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
            if (activateAllSlots)
            {
                AssertWordPageRenderClose(source.ToArray(), binary, 0.06, 2);
                AssertWordPageRenderClose(source.ToArray(), binary, 0.06, 3);
            }
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var docPath = Path.Combine(Path.GetTempPath(),
            $"docxport-adjacent-story-tables-{Guid.NewGuid():N}.doc");
        var sourcePath = Path.ChangeExtension(docPath, ".source.docx");
        var nativePath = Path.ChangeExtension(docPath, ".native.doc");
        File.WriteAllBytes(docPath, binary);
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            opened = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            for (var slot = 1; slot <= 3; slot++)
            {
                Assert.Equal(1, (int)opened.Sections[1].Headers[slot].Range.Tables.Count);
                Assert.Equal(1, (int)opened.Sections[1].Footers[slot].Range.Tables.Count);
            }
            opened.Close(false);
            opened = null;
            opened = word.Documents.Open(docPath, ReadOnly: true, AddToRecentFiles: false);
            var counts = new List<int>();
            for (var slot = 1; slot <= 3; slot++)
            {
                counts.Add((int)opened.Sections[1].Headers[slot].Range.Tables.Count);
                counts.Add((int)opened.Sections[1].Footers[slot].Range.Tables.Count);
            }
            Assert.True(counts.SequenceEqual(activateAllSlots
                ? new[] { 2, 2, 2, 2, 2, 2 }
                : new[] { 2, 2, 1, 1, 1, 1 }),
                string.Join(",", counts));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(docPath);
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void LegacyParagraphBorderOperandsDecodePaletteAndModernOverride()
    {
        var legacy = new byte[]
        {
            0x24, 0x64, 8, 8, 2, 0x61,
            0x25, 0x64, 8, 20, 6, 0,
            0x26, 0x64, 8, 22, 11, 0,
            0x27, 0x64, 8, 3, 16, 0,
            0x28, 0x64, 8, 1, 0, 0
        };
        var decoded = DocParagraphFormatting.Parse(legacy);
        Assert.Equal(new DocParagraphBorder(8, 8, 1, 0xFF0000u,
            Shadow: true, Frame: true), decoded.TopBorder);
        Assert.Equal((byte)20, decoded.LeftBorder?.Type);
        Assert.Equal(0x0000FFu, decoded.LeftBorder?.ColorRgb);
        Assert.Equal((byte)22, decoded.BottomBorder?.Type);
        Assert.Equal(0x008000u, decoded.BottomBorder?.ColorRgb);
        Assert.Equal(0xC0C0C0u, decoded.RightBorder?.ColorRgb);
        Assert.Null(decoded.BetweenBorder?.ColorRgb);
        var modern = new byte[]
        {
            0x4E, 0xC6, 8, 0x56, 0x34, 0x12, 0, 8, 1, 0, 0
        };
        var combined = new byte[legacy.Length + modern.Length];
        legacy.CopyTo(combined, 0);
        modern.CopyTo(combined, legacy.Length);
        Assert.Equal(0x123456u,
            DocParagraphFormatting.Parse(combined).TopBorder?.ColorRgb);
        var written = new DocParagraphFormatting(null, null, null,
            TopBorder: new DocParagraphBorder(8, 8, 1, 0xFF0000u)).Encode();
        Assert.Equal(new byte[] { 0x24, 0x64, 8, 8, 2, 1 },
            written.AsSpan(0, 6).ToArray());
        Assert.Equal(new byte[] { 0x4E, 0xC6 },
            written.AsSpan(6, 2).ToArray());
        Assert.Equal(0xFF0000u,
            DocParagraphFormatting.Parse(written).TopBorder?.ColorRgb);
        var nonPalette = new DocParagraphFormatting(null, null, null,
            TopBorder: new DocParagraphBorder(8, 8, 1, 0x563412u)).Encode();
        Assert.Equal((byte)0, nonPalette[4]);
        Assert.Equal(0x563412u,
            DocParagraphFormatting.Parse(nonPalette).TopBorder?.ColorRgb);
    }

    [Fact]
    public void LegacyBorderPaletteMatchesDocIcoColors()
    {
        uint?[] expected =
        [
            null, 0x000000u, 0xFF0000u, 0xFFFF00u, 0x00FF00u,
            0xFF00FFu, 0x0000FFu, 0x00FFFFu, 0xFFFFFFu,
            0x800000u, 0x808000u, 0x008000u, 0x800080u,
            0x800080u, 0x008080u, 0x808080u, 0xC0C0C0u
        ];
        for (byte code = 0; code < expected.Length; code++)
        {
            var border = DocParagraphBorder.Parse80([8, 1, code, 0]);
            Assert.Equal(expected[code], border?.ColorRgb);
            Assert.Equal(code == 13 ? (byte)12 : code,
                border!.Encode80()![2]);
        }
    }

    [Fact]
    public void LegacyOnlyParagraphBorderColorMatchesWord()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Paragraph(
                new ParagraphProperties(new ParagraphBorders(new TopBorder
                    { Val = BorderValues.Single, Size = 8, Color = "0000FF" })),
                new Run(new Text("Legacy blue border")))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            using (var original = new MemoryStream(bytes))
            using (var index = new DocTextIndexWalker().Index(original))
            {
                var papx = index.FormattingPages.Where(x => !x.IsCharacterFormatting)
                    .SelectMany(x => x.Runs).SelectMany(x => x.Children)
                    .First(x => x.Kind == "PapxInFkp");
                var data = index.Structure.ReadRange("WordDocument",
                    papx.Offset!.Value, checked((int)papx.Length!.Value));
                var modern = data.AsSpan().IndexOf(new byte[] { 0x4E, 0xC6, 8 });
                Assert.True(modern >= 0);
                Assert.True(data.AsSpan().IndexOf(new byte[]
                    { 0x24, 0x64, 8, 1, 2 }) >= 0);
                using var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen);
                using var word = compound.OpenStream("WordDocument");
                word.Position = papx.Offset.Value + modern;
                word.WriteByte(0x7F); // unsupported variable-length paragraph SPRM
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Contains(index.ParagraphStyles, x =>
                x.CpStart == 0 && x.Formatting?.TopBorder?.ColorRgb == 0xFF0000u);
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        Assert.Equal("0000FF", projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>().First().ParagraphProperties!
            .ParagraphBorders!.TopBorder!.Color!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-legacy-border-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic app = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        app.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = app.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(16711680, (int)opened.Paragraphs.Item(1)
                .Borders.Item(-1).Color);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            app.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void LegacyOnlyTableBordersMatchWord()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableBorders(new TopBorder
                    { Val = BorderValues.Single, Size = 8, Color = "0000FF" })),
                new TableGrid(new GridColumn { Width = "3000" }),
                new TableRow(new TableCell(
                    new TableCellProperties(new TableCellBorders(new BottomBorder
                        { Val = BorderValues.Single, Size = 8, Color = "FF0000" })),
                    new Paragraph(new Run(new Text("Legacy table"))))))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            var changes = new List<long>();
            using (var original = new MemoryStream(bytes))
            using (var index = new DocTextIndexWalker().Index(original))
                foreach (var papx in index.FormattingPages
                    .Where(x => !x.IsCharacterFormatting)
                    .SelectMany(x => x.Runs).SelectMany(x => x.Children)
                    .Where(x => x.Kind == "PapxInFkp"))
                {
                    var data = index.Structure.ReadRange("WordDocument",
                        papx.Offset!.Value, checked((int)papx.Length!.Value));
                    for (var i = 0; i < data.Length - 2; i++)
                        if (data[i + 1] == 0xD6 &&
                            (data[i] == 0x13 && data[i + 2] == 48 ||
                             data[i] == 0x2F && data[i + 2] == 11))
                            changes.Add(papx.Offset.Value + i);
                }
            Assert.True(changes.Count >= 2);
            using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
            using (var word = compound.OpenStream("WordDocument"))
            {
                foreach (var offset in changes)
                {
                    word.Position = offset;
                    word.WriteByte(0x7F); // keep legacy BRC80 operands only
                }
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Contains(index.ParagraphStyles, x =>
                x.Formatting?.TableCellBorders?.FirstOrDefault()?.Top?.ColorRgb == 0xFF0000u &&
                x.Formatting.TableCellBorders?.FirstOrDefault()?.Bottom?.ColorRgb == 0x0000FFu);
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var table = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        var cellBorders = table.Descendants<TableCell>().First()
            .TableCellProperties!.TableCellBorders!;
        Assert.Equal("0000FF", cellBorders.TopBorder!.Color!.Value);
        Assert.Equal("FF0000", cellBorders.BottomBorder!.Color!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-legacy-table-border-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic app = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        app.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = app.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(16711680, (int)opened.Tables.Item(1)
                .Cell(1, 1).Borders.Item(-1).Color);
            Assert.Equal(255, (int)opened.Tables.Item(1)
                .Cell(1, 1).Borders.Item(-3).Color);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            app.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void LegacyTableBorderOperandsDecodeAndModernColorsTakePrecedence()
    {
        var legacy = new List<byte> { 0x05, 0xD6, 24, 8, 8, 2, 0 };
        for (var i = 0; i < 5; i++)
            legacy.AddRange(new byte[] { 0xFF, 0xFF, 0xFF, 0xFF });
        legacy.AddRange(new byte[] { 0x20, 0xD6, 7, 0, 1, 1, 8, 20, 6, 0 });
        var decoded = DocParagraphFormatting.Parse(legacy.ToArray());
        Assert.Equal(0xFF0000u, decoded.TableBorders?.Top?.ColorRgb);
        Assert.Equal((byte)8, decoded.TableBorders?.Top?.Type);
        Assert.Equal(0x0000FFu, decoded.TableCellBorders?[0]?.Top?.ColorRgb);
        Assert.Equal((byte)20, decoded.TableCellBorders?[0]?.Top?.Type);

        var modern = new DocParagraphFormatting(null, null, null,
            TableBorders: new DocTableBorders(
                new DocParagraphBorder(8, 8, 0, 0x563412u),
                null, null, null, null, null),
            TableCellBorders: new[] { new DocCellBorders(
                Top: new DocParagraphBorder(20, 8, 0, 0x123456u)) });
        var encoded = modern.Encode();
        Assert.True(encoded.AsSpan().IndexOf(new byte[] { 0x05, 0xD6, 24 }) >= 0);
        Assert.True(encoded.AsSpan().IndexOf(new byte[] { 0x13, 0xD6, 48 }) >= 0);
        Assert.True(encoded.AsSpan().IndexOf(new byte[] { 0x20, 0xD6, 7 }) >= 0);
        Assert.True(encoded.AsSpan().IndexOf(new byte[] { 0x2F, 0xD6, 11 }) >= 0);
        var roundTrip = DocParagraphFormatting.Parse(encoded);
        Assert.Equal(0x563412u, roundTrip.TableBorders?.Top?.ColorRgb);
        Assert.Equal(0x123456u, roundTrip.TableCellBorders?[0]?.Top?.ColorRgb);
    }


