    [Theory]
    [InlineData("WordInlinePngBody.doc", false, false,
        "8C2623A303FD0A0B520F1E9F41012E370746B9D7D567304ED0233B7E163C243E")]
    [InlineData("WordInlineJpegHeader.doc", true, false,
        "942642EDB5D720088E64364313F0A4FD4AD01ED4676CC1BFDC891A5603CA650A")]
    [InlineData("WordInlinePngFooter.doc", false, true,
        "8C2623A303FD0A0B520F1E9F41012E370746B9D7D567304ED0233B7E163C243E")]
    public void InlineImageSurvivesDocxToDocInBodyOrHeader(string fixture,
        bool inHeader, bool inFooter, string expectedHash)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            fixture));
        var sourceDocx = DxpDocToDocx.Project(path).DocxBytes;
        var binary = DxpDocExport.Export(sourceDocx);
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var atoms = inHeader || inFooter
                ? index.HeaderStories.SelectMany(x => x.ReadContent().Paragraphs)
                    .SelectMany(x => x.Atoms)
                : DocStoryTextReader.Read(index, "Main").Paragraphs
                    .SelectMany(x => x.Atoms);
            Assert.Contains(atoms, x => x.Kind == DocStoryAtomKind.InlinePicture);
        }
        var result = DxpDocToDocx.Project(binary);
        Assert.False(result.Coverage.OmittedCharacters.ContainsKey(1));
        using var stream = new MemoryStream(result.DocxBytes);
        using var document = WordprocessingDocument.Open(stream, false);
        var host = inHeader
            ? (OpenXmlPart)Assert.Single(document.MainDocumentPart!.HeaderParts)
            : inFooter
            ? Assert.Single(document.MainDocumentPart!.FooterParts,
                part => part.ImageParts.Any())
            : document.MainDocumentPart!;
        var image = Assert.Single(host.Parts.Select(x => x.OpenXmlPart).OfType<ImagePart>());
        using (var imageStream = image.GetStream())
            Assert.Equal(expectedHash, Convert.ToHexString(SHA256.HashData(imageStream)));
        Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-written-image-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                dynamic shapes = inHeader || inFooter
                    ? inHeader
                        ? opened.Sections(1).Headers(1).Range.InlineShapes
                        : opened.Sections(1).Footers(1).Range.InlineShapes
                    : opened.InlineShapes;
                Assert.Equal(1, (int)shapes.Count);
                Assert.Equal(3, (int)shapes.Item(1).Type); // wdInlineShapePicture
                Assert.InRange((float)shapes.Item(1).Width,
                    inHeader || inFooter ? 460f : 70f,
                    inHeader || inFooter ? 475f : 74f);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

    [Fact]
    public void DistinctInlineImagesKeepTheirOwnBinaryDataRecords()
    {
        var fixtureDirectory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        var pngDocx = DxpDocToDocx.Project(Path.Combine(fixtureDirectory,
            "WordInlinePngBody.doc")).DocxBytes;
        var jpegDocx = DxpDocToDocx.Project(Path.Combine(fixtureDirectory,
            "WordInlineJpegHeader.doc")).DocxBytes;
        using var pngStream = new MemoryStream(pngDocx);
        using var pngSource = WordprocessingDocument.Open(pngStream, false);
        using var jpegStream = new MemoryStream(jpegDocx);
        using var jpegSource = WordprocessingDocument.Open(jpegStream, false);
        var pngDrawing = (Drawing)pngSource.MainDocumentPart!.Document!.Body!
            .Descendants<Drawing>().Single().CloneNode(true);
        var jpegDrawing = (Drawing)jpegSource.MainDocumentPart!.HeaderParts.Single()
            .Header!.Descendants<Drawing>().Single().CloneNode(true);
        var pngImage = pngSource.MainDocumentPart.ImageParts.Single();
        var jpegImage = jpegSource.MainDocumentPart.HeaderParts.Single().ImageParts.Single();

        using var target = new MemoryStream();
        using (var docx = WordprocessingDocument.Create(target,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = docx.AddMainDocumentPart();
            var first = main.AddNewPart<ImagePart>("image/png");
            using (var source = pngImage.GetStream()) first.FeedData(source);
            var second = main.AddNewPart<ImagePart>("image/jpeg");
            using (var source = jpegImage.GetStream()) second.FeedData(source);
            pngDrawing.Descendants<DocumentFormat.OpenXml.Drawing.Blip>().Single()
                .Embed = main.GetIdOfPart(first);
            jpegDrawing.Descendants<DocumentFormat.OpenXml.Drawing.Blip>().Single()
                .Embed = main.GetIdOfPart(second);
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("One "), pngDrawing, new Text(" two "),
                    jpegDrawing, new Text(" end")))));
            main.Document.Save();
        }

        var binary = DxpDocExport.Export(target.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var pictures = DocStoryTextReader.Read(index, "Main").Paragraphs
                .SelectMany(x => x.Atoms)
                .Where(x => x.Kind == DocStoryAtomKind.InlinePicture).ToArray();
            Assert.Equal(2, pictures.Length);
            Assert.Equal(2, index.CharacterFormatting.Where(x =>
                x.Formatting.Special == true && x.Formatting.PictureDataOffset != null)
                .Select(x => x.Formatting.PictureDataOffset).Distinct().Count());
        }
        var projected = DxpDocToDocx.Project(binary);
        using var resultStream = new MemoryStream(projected.DocxBytes);
        using var result = WordprocessingDocument.Open(resultStream, false);
        Assert.Equal(2, result.MainDocumentPart!.Document!.Body!
            .Descendants<Drawing>().Count());
        var hashes = result.MainDocumentPart.ImageParts.Select(image =>
        {
            using var data = image.GetStream();
            return Convert.ToHexString(SHA256.HashData(data));
        }).ToHashSet();
        Assert.Contains("8C2623A303FD0A0B520F1E9F41012E370746B9D7D567304ED0233B7E163C243E",
            hashes);
        Assert.Contains("942642EDB5D720088E64364313F0A4FD4AD01ED4676CC1BFDC891A5603CA650A",
            hashes);
        Assert.Empty(new OpenXmlValidator().Validate(result));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-written-images-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(generatedPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(2, (int)opened.InlineShapes.Count);
                Assert.InRange((float)opened.InlineShapes.Item(1).Width, 70f, 74f);
                Assert.InRange((float)opened.InlineShapes.Item(2).Width, 460f, 475f);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(generatedPath);
            }
        }
    }

