    [Trait("Category", "LocalOnly")]
    [Fact]
    public void WordTrackedListEditsProjectAsEditableRevisions()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "samples", "TestLists.doc"));
        using var index = new DocTextIndexWalker().Index(path);
        Assert.Contains(index.CharacterFormatting, x => x.Formatting.DeletedRevision == true);
        Assert.Contains(index.CharacterFormatting, x => x.Formatting.InsertedRevision == true);
        Assert.Contains("Gaspard Petit", index.RevisionAuthors);
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.DeletedRevision == true &&
            x.Formatting.DeletedRevisionAuthor == "Gaspard Petit" &&
            x.Formatting.DeletedRevisionAt == new DateTime(2025, 12, 21, 2, 40, 0,
                DateTimeKind.Utc));

        var result = new DocToDocxProjector().Project(index);
        using var stream = new MemoryStream(result.DocxBytes);
        using var document = WordprocessingDocument.Open(stream, false);
        var paragraphs = document.MainDocumentPart!.Document!.Body!.Elements<Paragraph>();
        var deleted = Assert.Single(paragraphs.Where(x => x.InnerText.Contains("Deleted 4")));
        Assert.NotNull(deleted.Descendants<DeletedRun>().SingleOrDefault());
        Assert.Equal("Gaspard Petit", deleted.Descendants<DeletedRun>().Single().Author?.Value);
        Assert.NotNull(deleted.ParagraphProperties?.ParagraphMarkRunProperties?
            .GetFirstChild<Deleted>());
        var inserted = Assert.Single(paragraphs.Where(x => x.InnerText.Contains("Added 5")));
        Assert.NotNull(inserted.Descendants<InsertedRun>().SingleOrDefault());
        Assert.Equal("Gaspard Petit", inserted.Descendants<InsertedRun>().Single().Author?.Value);
        var errors = new OpenXmlValidator().Validate(document).ToArray();
        Assert.True(errors.Length == 0, string.Join("\n", errors.Select(x =>
            $"{x.Description} at {x.Path?.XPath}: {x.Node?.OuterXml}")));

        var binary = DxpDocExport.Export(result.DocxBytes);
        using var binaryStream = new MemoryStream(binary);
        using var reopened = new DocTextIndexWalker().Index(binaryStream);
        Assert.Contains(reopened.CharacterFormatting,
            x => x.Formatting.DeletedRevision == true);
        Assert.Contains(reopened.CharacterFormatting,
            x => x.Formatting.InsertedRevision == true);
        Assert.Contains("Gaspard Petit", reopened.RevisionAuthors);
        Assert.Contains(reopened.CharacterFormatting, x =>
            x.Formatting.DeletedRevision == true &&
            x.Formatting.DeletedRevisionAuthor == "Gaspard Petit" &&
            x.Formatting.DeletedRevisionAt == new DateTime(2025, 12, 21, 2, 40, 0,
                DateTimeKind.Utc));
        Assert.Contains(reopened.CharacterFormatting, x =>
            x.Formatting.InsertedRevision == true &&
            x.Formatting.InsertedRevisionAuthor == "Gaspard Petit" &&
            x.Formatting.InsertedRevisionAt == new DateTime(2025, 12, 21, 2, 40, 0,
                DateTimeKind.Utc));
        var roundTripped = new DocToDocxProjector().Project(reopened);
        using var outputStream = new MemoryStream(roundTripped.DocxBytes);
        using var output = WordprocessingDocument.Open(outputStream, false);
        Assert.Contains(output.MainDocumentPart!.Document!.Body!.Descendants<DeletedRun>(),
            x => x.InnerText.Contains("Deleted 4") &&
                x.Author?.Value == "Gaspard Petit");
        Assert.Contains(output.MainDocumentPart.Document.Body.Descendants<InsertedRun>(),
            x => x.InnerText.Contains("Added 5"));
        Assert.Empty(new OpenXmlValidator().Validate(output));
    }

    [Fact]
    public void TrackedEditsWithDifferentAuthorsSurviveBodyHeaderAndFooter()
    {
        var at = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new ParagraphProperties(new ParagraphMarkRunProperties(new Deleted
                    { Id = "2", Author = "Header Editor", Date = at })),
                new DeletedRun(new Run(new DeletedText("Header removed")))
                    { Id = "3", Author = "Header Editor", Date = at }));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(
                new ParagraphProperties(new ParagraphMarkRunProperties(new Inserted
                    { Id = "4", Author = "Footer Editor", Date = at.AddMinutes(1) })),
                new InsertedRun(new Run(new Text("Footer added")))
                    { Id = "5", Author = "Footer Editor", Date = at.AddMinutes(1) }));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(new DeletedRun(new Run(new DeletedText("Body removed")))
                    { Id = "1", Author = "Body Editor", Date = at.AddMinutes(2) }),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }

        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Equal(new[] { "Unknown", "Body Editor", "Header Editor", "Footer Editor" },
            index.RevisionAuthors);
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.DeletedRevisionAuthor == "Body Editor" &&
            x.Formatting.DeletedRevisionAt == at.AddMinutes(2));
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.DeletedRevisionAuthor == "Header Editor" &&
            x.Formatting.DeletedRevisionAt == at);
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.InsertedRevisionAuthor == "Footer Editor" &&
            x.Formatting.InsertedRevisionAt == at.AddMinutes(1));

        var projected = new DocToDocxProjector().Project(index);
        using var outputStream = new MemoryStream(projected.DocxBytes);
        using var output = WordprocessingDocument.Open(outputStream, false);
        var mainPart = output.MainDocumentPart!;
        Assert.Contains(mainPart.Document!.Body!.Descendants<DeletedRun>(), x =>
            x.InnerText.Contains("Body removed") && x.Author?.Value == "Body Editor");
        Assert.Contains(mainPart.HeaderParts.Single().Header!.Descendants<DeletedRun>(), x =>
            x.InnerText.Contains("Header removed") && x.Author?.Value == "Header Editor");
        Assert.Contains(mainPart.FooterParts.Single().Footer!.Descendants<InsertedRun>(), x =>
            x.InnerText.Contains("Footer added") && x.Author?.Value == "Footer Editor");
        Assert.Empty(new OpenXmlValidator().Validate(output));

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                $"docxport-revision-stories-{Guid.NewGuid():N}.doc");
            var nativePath = Path.Combine(Path.GetTempPath(),
                $"docxport-revision-stories-native-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(path, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(1, (int)opened.Sections(1).Headers(1).Range.Revisions.Count);
                Assert.Equal(1, (int)opened.Sections(1).Footers(1).Range.Revisions.Count);
                Assert.Equal("Header Editor",
                    (string)opened.Sections(1).Headers(1).Range.Revisions(1).Author);
                Assert.Equal("Footer Editor",
                    (string)opened.Sections(1).Footers(1).Range.Revisions(1).Author);
                opened.SaveAs2(nativePath, 0);
                var nativeProjection = DxpDocToDocx.Project(nativePath);
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                Assert.Contains(native.MainDocumentPart!.HeaderParts.SelectMany(x =>
                    x.Header!.Descendants<DeletedRun>()),
                    x => x.Author?.Value == "Header Editor" && x.Date?.Value == at);
                Assert.Contains(native.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Descendants<InsertedRun>()),
                    x => x.Author?.Value == "Footer Editor" &&
                        x.Date?.Value == at.AddMinutes(1));
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void AdjacentTrackedEditsRetainDirectRunFormatting()
    {
        var at = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("Start ")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new DeletedRun(new Run(new RunProperties(new Bold()),
                    new DeletedText("old")))
                    { Id = "1", Author = "Editor A", Date = at },
                new InsertedRun(new Run(new RunProperties(new Italic()),
                    new Text("new")))
                    { Id = "2", Author = "Editor B", Date = at.AddMinutes(1) },
                new Run(new Text(" end")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }))));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }

        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.DeletedRevision == true && x.Formatting.Bold == true &&
            x.Formatting.DeletedRevisionAuthor == "Editor A");
        Assert.Contains(index.CharacterFormatting, x =>
            x.Formatting.InsertedRevision == true && x.Formatting.Italic == true &&
            x.Formatting.InsertedRevisionAuthor == "Editor B");

        var projected = new DocToDocxProjector().Project(index);
        using var outputStream = new MemoryStream(projected.DocxBytes);
        using var output = WordprocessingDocument.Open(outputStream, false);
        var paragraph = Assert.Single(output.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>());
        var deletion = Assert.Single(paragraph.Descendants<DeletedRun>());
        Assert.Equal("old", deletion.InnerText);
        Assert.NotNull(deletion.Descendants<RunProperties>().Single().GetFirstChild<Bold>());
        var insertion = Assert.Single(paragraph.Descendants<InsertedRun>());
        Assert.Equal("new", insertion.InnerText);
        Assert.NotNull(insertion.Descendants<RunProperties>().Single().GetFirstChild<Italic>());
        Assert.Equal("Start  end", string.Concat(paragraph.Elements<Run>()
            .Select(x => x.InnerText)));
        Assert.Empty(new OpenXmlValidator().Validate(output));

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                $"docxport-adjacent-revisions-{Guid.NewGuid():N}.doc");
            var nativePath = Path.Combine(Path.GetTempPath(),
                $"docxport-adjacent-revisions-native-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(path, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(2, (int)opened.Revisions.Count);
                Assert.Equal("Editor A", (string)opened.Revisions(1).Author);
                Assert.NotEqual(0, (int)opened.Revisions(1).Range.Font.Bold);
                Assert.Equal("Editor B", (string)opened.Revisions(2).Author);
                Assert.NotEqual(0, (int)opened.Revisions(2).Range.Font.Italic);
                opened.SaveAs2(nativePath, 0);
                var nativeProjection = DxpDocToDocx.Project(nativePath);
                using (var nativeStream = new MemoryStream(nativeProjection.DocxBytes))
                using (var native = WordprocessingDocument.Open(nativeStream, false))
                {
                    var nativeParagraph = native.MainDocumentPart!.Document!.Body!
                        .Elements<Paragraph>().Single();
                    Assert.NotNull(nativeParagraph.Descendants<DeletedRun>().Single()
                        .Descendants<RunProperties>().Single().GetFirstChild<Bold>());
                    Assert.NotNull(nativeParagraph.Descendants<InsertedRun>().Single()
                        .Descendants<RunProperties>().Single().GetFirstChild<Italic>());
                    Assert.Empty(new OpenXmlValidator().Validate(native));
                }
                opened.Revisions.AcceptAll();
                Assert.Contains("Start new end", (string)opened.Content.Text);
                opened.Close(false);
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.Revisions.RejectAll();
                Assert.Contains("Start old end", (string)opened.Content.Text);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(nativePath);
            }
        }
    }

    [Trait("Category", "LocalOnly")]
    [Fact]
    public void DocListRoundTripWritesEditableBinaryNumbering()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "samples", "TestLists.doc"));
        var sourceDocx = DxpDocToDocx.Project(File.ReadAllBytes(path)).DocxBytes;
        var binary = DxpDocExport.Export(sourceDocx);
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.NotEmpty(index.Lists.Definitions);
            Assert.NotEmpty(index.Lists.Instances);
            Assert.Contains(index.ParagraphStyles, x =>
                x.Formatting?.ListOverrideIndex > 0);
        }
        var output = DxpDocToDocx.Project(binary).DocxBytes;
        using var stream = new MemoryStream(output);
        using var document = WordprocessingDocument.Open(stream, false);
        Assert.NotEmpty(document.MainDocumentPart!.Document!.Body!
            .Descendants<NumberingProperties>());
        Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var wordPath = Path.Combine(Path.GetTempPath(),
                $"docxport-list-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(wordPath, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(wordPath, ReadOnly: true,
                    AddToRecentFiles: false);
                var labels = new List<string>();
                foreach (dynamic paragraph in opened.Paragraphs)
                    if ((int)paragraph.Range.ListFormat.ListType != 0)
                        labels.Add((string)paragraph.Range.ListFormat.ListString);
                Assert.NotEmpty(labels);
                var sourceDocxPath = Path.Combine(Path.GetTempPath(),
                    $"docxport-list-source-{Guid.NewGuid():N}.docx");
                File.WriteAllBytes(sourceDocxPath, sourceDocx);
                try
                {
                    dynamic projectedSource = word.Documents.Open(sourceDocxPath,
                        ReadOnly: true, AddToRecentFiles: false);
                    try
                    {
                        var intermediate = new List<string>();
                        foreach (dynamic paragraph in projectedSource.Paragraphs)
                            if ((int)paragraph.Range.ListFormat.ListType != 0)
                                intermediate.Add((string)paragraph.Range.ListFormat.ListString);
                        Assert.Equal(intermediate, labels);
                        dynamic original = word.Documents.Open(path, ReadOnly: true,
                            AddToRecentFiles: false);
                        try
                        {
                            var expectedPairs = new List<(string Text, string Label)>();
                            foreach (dynamic paragraph in original.Paragraphs)
                                if ((int)paragraph.Range.ListFormat.ListType != 0)
                                    expectedPairs.Add((((string)paragraph.Range.Text).Trim(),
                                        (string)paragraph.Range.ListFormat.ListString));
                            var actualPairs = new List<(string Text, string Label)>();
                            foreach (dynamic paragraph in projectedSource.Paragraphs)
                                if ((int)paragraph.Range.ListFormat.ListType != 0)
                                    actualPairs.Add((((string)paragraph.Range.Text).Trim(),
                                        (string)paragraph.Range.ListFormat.ListString));
                            Assert.True(expectedPairs.Count > 82 && actualPairs.Count > 82);
                            Assert.Contains(("Deleted 4", "1:"), expectedPairs);
                            Assert.Contains(("Added 5", "4:"), expectedPairs);
                            Assert.Equal(expectedPairs, actualPairs);
                        }
                        finally { original.Close(false); }
                    }
                    finally { projectedSource.Close(false); }
                }
                finally { File.Delete(sourceDocxPath); }
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(wordPath);
            }
        }
    }

    [Fact]
    public void TrackedListRevisionViewsKeepWordLabelsAcrossDocHops()
    {
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var nativePath = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "samples", "TestLists.doc"));
        var native = File.ReadAllBytes(nativePath);
        var projected = DxpDocToDocx.Project(native).DocxBytes;
        var generated = DxpDocExport.Export(projected);
        var temporary = Path.Combine(Path.GetTempPath(),
            $"docxport-tracked-lists-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporary);
        var paths = new[]
        {
            Path.Combine(temporary, "native.doc"),
            Path.Combine(temporary, "projected.docx"),
            Path.Combine(temporary, "generated.doc")
        };
        File.WriteAllBytes(paths[0], native);
        File.WriteAllBytes(paths[1], projected);
        File.WriteAllBytes(paths[2], generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var accept in new[] { true, false })
            {
                var results = new List<(string Text, string Label)>[paths.Length];
                for (var i = 0; i < paths.Length; i++)
                {
                    dynamic document = word.Documents.Open(paths[i], ReadOnly: true,
                        AddToRecentFiles: false);
                    try
                    {
                        Assert.True((int)document.Revisions.Count > 0);
                        if (accept) document.Revisions.AcceptAll();
                        else document.Revisions.RejectAll();
                        var pairs = new List<(string Text, string Label)>();
                        foreach (dynamic paragraph in document.Paragraphs)
                            if ((int)paragraph.Range.ListFormat.ListType != 0)
                                pairs.Add((((string)paragraph.Range.Text).Trim(),
                                    (string)paragraph.Range.ListFormat.ListString));
                        results[i] = pairs;
                    }
                    finally { document.Close(false); }
                }
                Assert.NotEmpty(results[0]);
                if (accept)
                {
                    Assert.DoesNotContain(results[0], pair => pair.Text == "Deleted 4");
                    Assert.Contains(results[0], pair => pair.Text == "Added 5");
                }
                else
                {
                    Assert.Contains(results[0], pair => pair.Text == "Deleted 4");
                    Assert.DoesNotContain(results[0], pair => pair.Text == "Added 5");
                }
                Assert.Equal(results[0], results[1]);
                Assert.Equal(results[0], results[2]);
            }
        }
        finally
        {
            word.Quit(false);
            foreach (var path in paths) File.Delete(path);
            Directory.Delete(temporary);
        }
    }

    [Fact]
    public void TrackedListTextAndMarksKeepRevisionViewsInAllStories()
    {
        var at = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc);
        Paragraph Item(string text, bool deleted, int level = 0)
        {
            var revision = deleted
                ? (DocumentFormat.OpenXml.OpenXmlElement)new Deleted
                    { Id = "1", Author = "Editor", Date = at }
                : new Inserted { Id = "2", Author = "Editor", Date = at };
            DocumentFormat.OpenXml.OpenXmlElement content = deleted
                ? new DeletedRun(new Run(new DeletedText(text)))
                    { Id = "3", Author = "Editor", Date = at }
                : new InsertedRun(new Run(new Text(text)))
                    { Id = "4", Author = "Editor", Date = at };
            return new Paragraph(new ParagraphProperties(
                    new NumberingProperties(new NumberingLevelReference { Val = level },
                        new NumberingId { Val = deleted ? 1 : 2 }),
                    new ParagraphMarkRunProperties(revision)),
                content);
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            numbering.Numbering = new Numbering(
                new AbstractNum(new Level(new StartNumberingValue { Val = 1 },
                    new NumberingFormat { Val = NumberFormatValues.Decimal },
                    new LevelText { Val = "%1." }) { LevelIndex = 0 },
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelText { Val = "%1.%2." }) { LevelIndex = 1 })
                    { AbstractNumberId = 0 },
                new NumberingInstance(new AbstractNumId { Val = 0 }) { NumberID = 1 },
                new NumberingInstance(new AbstractNumId { Val = 0 },
                    new LevelOverride(new StartOverrideNumberingValue { Val = 5 })
                        { LevelIndex = 0 }) { NumberID = 2 });
            numbering.Numbering.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Item("Header removed", true),
                Item("Header added", false), Item("Header child", false, 1));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Item("Footer removed", true),
                Item("Footer added", false), Item("Footer child", false, 1));
            footer.Footer.Save();
            main.Document = new Document(new Body(Item("Body removed", true),
                Item("Body added", false), Item("Body child", false, 1),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var firstDoc = DxpDocExport.Export(source.ToArray());
        var firstProjection = DxpDocToDocx.Project(firstDoc).DocxBytes;
        var thirdProjection = DxpDocToDocx.Project(
            DxpDocExport.Export(firstProjection)).DocxBytes;
        var projections = new List<byte[]> { firstProjection, thirdProjection };
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), firstDoc, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(), firstProjection, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(), thirdProjection, 0.04);
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-list-story-revisions-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                var generatedPath = Path.Combine(directory, "generated.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                File.WriteAllBytes(generatedPath, firstDoc);
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                    string[] Labels(string path)
                    {
                        dynamic document = word.Documents.Open(path, ReadOnly: true,
                            AddToRecentFiles: false);
                        try
                        {
                            dynamic section = document.Sections.Item(1);
                            var stories = new[]
                            {
                                document.Paragraphs,
                                section.Headers.Item(1).Range.Paragraphs,
                                section.Footers.Item(1).Range.Paragraphs
                            };
                            var labels = new List<string>();
                            foreach (dynamic paragraphs in stories)
                                for (var i = 1; i <= 3; i++)
                                    labels.Add((string)paragraphs.Item(i).Range
                                        .ListFormat.ListString);
                            return labels.ToArray();
                        }
                        finally { document.Close(false); }
                    }
                    var expectedLabels = Labels(sourcePath);
                    Assert.All(expectedLabels, label => Assert.NotEmpty(label));
                    Assert.Equal(expectedLabels, Labels(nativePath));
                    Assert.Equal(expectedLabels, Labels(generatedPath));
                    string[] RevisionView(string path, bool accept)
                    {
                        dynamic document = word.Documents.Open(path, ReadOnly: true,
                            AddToRecentFiles: false);
                        try
                        {
                            if (accept) document.Revisions.AcceptAll();
                            else document.Revisions.RejectAll();
                            dynamic section = document.Sections.Item(1);
                            dynamic headerRange = section.Headers.Item(1).Range;
                            dynamic footerRange = section.Footers.Item(1).Range;
                            if (accept)
                            {
                                headerRange.Revisions.AcceptAll();
                                footerRange.Revisions.AcceptAll();
                            }
                            else
                            {
                                headerRange.Revisions.RejectAll();
                                footerRange.Revisions.RejectAll();
                            }
                            var stories = new[]
                            {
                                document.Paragraphs,
                                headerRange.Paragraphs,
                                footerRange.Paragraphs
                            };
                            var entries = new List<string>();
                            foreach (dynamic paragraphs in stories)
                                foreach (dynamic paragraph in paragraphs)
                                {
                                    var value = ((string)paragraph.Range.Text).Trim();
                                    if (value.Length == 0 ||
                                        (int)paragraph.Range.ListFormat.ListType == 0) continue;
                                    entries.Add((string)paragraph.Range.ListFormat.ListString +
                                        "|" + value);
                                }
                            return entries.ToArray();
                        }
                        finally { document.Close(false); }
                    }
                    foreach (var accept in new[] { true, false })
                    {
                        var expected = RevisionView(sourcePath, accept);
                        Assert.Equal(accept ? 6 : 3, expected.Length);
                        Assert.Contains(expected, x => x == (accept
                            ? "5.|Body added" : "1.|Body removed"));
                        if (accept)
                            Assert.Contains("5.1.|Body child", expected);
                        Assert.Equal(expected, RevisionView(nativePath, accept));
                        Assert.Equal(expected, RevisionView(generatedPath, accept));
                    }
                }
                finally { word.Quit(false); }
                var native = File.ReadAllBytes(nativePath);
                var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;

                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    nativeProjection, 0.04);
                projections.Add(nativeProjection);
            }
            finally { Directory.Delete(directory, true); }
        }
        foreach (var bytes in projections)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var restartNumberId = Assert.Single(main.NumberingDefinitionsPart!
                .Numbering!.Elements<NumberingInstance>().Where(x =>
                    x.GetFirstChild<LevelOverride>()?
                        .GetFirstChild<StartOverrideNumberingValue>()?.Val?.Value == 5))
                .NumberID!.Value;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var items = story.Elements<Paragraph>().Take(3).ToArray();
                Assert.Equal(3, items.Length);
                Assert.All(items, item => Assert.NotNull(
                    item.ParagraphProperties?.NumberingProperties?.NumberingId?.Val));
                Assert.Equal(restartNumberId, items[1].ParagraphProperties?
                    .NumberingProperties?.NumberingId?.Val?.Value);
                Assert.Equal(restartNumberId, items[2].ParagraphProperties?
                    .NumberingProperties?.NumberingId?.Val?.Value);
                Assert.Equal(1, items[2].ParagraphProperties?
                    .NumberingProperties?.NumberingLevelReference?.Val?.Value);
                Assert.NotNull(items[0].ParagraphProperties?.ParagraphMarkRunProperties?
                    .GetFirstChild<Deleted>());
                Assert.NotNull(items[1].ParagraphProperties?.ParagraphMarkRunProperties?
                    .GetFirstChild<Inserted>());
                Assert.NotNull(items[2].ParagraphProperties?.ParagraphMarkRunProperties?
                    .GetFirstChild<Inserted>());
                Assert.NotNull(items[0].GetFirstChild<DeletedRun>());
                Assert.NotNull(items[1].GetFirstChild<InsertedRun>());
                Assert.NotNull(items[2].GetFirstChild<InsertedRun>());
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
    }

