    [InlineData("WordFloatingBmpAllStories")]
    public void WordBmpImagesRoundTripThroughAllStories(string name)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            name + ".docx"));
        var source = File.ReadAllBytes(path);
        byte[] expected;
        using (var sourceStream = new MemoryStream(source))
        using (var document = WordprocessingDocument.Open(sourceStream, false))
        using (var image = Assert.Single(document.MainDocumentPart!.ImageParts).GetStream())
        using (var copy = new MemoryStream())
        {
            image.CopyTo(copy);
            expected = copy.ToArray();
        }
        var storedBitmap = DocDibBitmap.ToBmp(DocDibBitmap.ToDib(expected));
        if (name.StartsWith("WordBmpRle4", StringComparison.Ordinal) ||
            name.StartsWith("WordBmpV", StringComparison.Ordinal))
            Assert.NotEqual(expected, storedBitmap);
        else Assert.Equal(expected, storedBitmap);
        var generated = DxpDocExport.Export(source);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var third = DxpDocExport.Export(projected);
        foreach (var binary in new[] { generated, third })
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            Assert.Single(main.Document!.Body!.Descendants<Drawing>());
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Drawing>().Any());
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Drawing>().Any());
            var images = main.ImageParts.Concat(main.HeaderParts.SelectMany(x => x.ImageParts))
                .Concat(main.FooterParts.SelectMany(x => x.ImageParts)).ToArray();
            Assert.Equal(3, images.Length);
            foreach (var part in images)
            {
                Assert.Equal("image/bmp", part.ContentType);
                using var image = part.GetStream();
                using var copy = new MemoryStream();
                image.CopyTo(copy);
                Assert.Equal(storedBitmap, copy.ToArray());
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var native = File.ReadAllBytes(Path.ChangeExtension(path, ".doc"));
        var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
        using (var stream = new MemoryStream(nativeProjection))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            Assert.Single(main.Document!.Body!.Descendants<Drawing>());
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Drawing>().Any());
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Drawing>().Any());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var nativeThird = DxpDocExport.Export(nativeProjection);
        using (var stream = new MemoryStream(
            DxpDocToDocx.Project(nativeThird).DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            Assert.Single(main.Document!.Body!.Descendants<Drawing>());
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Drawing>().Any());
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Drawing>().Any());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source, generated, 0.04, 1);
            AssertWordPageRenderClose(source, projected, 0.04, 1, ".docx");
            AssertWordPageRenderClose(source, third, 0.04, 1);
            AssertWordPageRenderClose(source, native, 0.06, 1);
            AssertWordPageRenderClose(source, nativeProjection, 0.06, 1, ".docx");
            AssertWordPageRenderClose(source, nativeThird, 0.06, 1);
        }
    }

    [Fact]
    public void WordTiffImagesRoundTripThroughAllStories()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordTiffAllStories.docx"));
        var source = File.ReadAllBytes(path);
        byte[] sourceTiff;
        using (var stream = new MemoryStream(source))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            Assert.Equal(3, main.ImageParts.Count() +
                main.HeaderParts.Sum(x => x.ImageParts.Count()) +
                main.FooterParts.Sum(x => x.ImageParts.Count()));
            using var image = Assert.Single(main.ImageParts).GetStream();
            using var bytes = new MemoryStream();
            image.CopyTo(bytes);
            sourceTiff = bytes.ToArray();
        }
        var generatedDoc = DxpDocExport.Export(source);
        var projected = DxpDocToDocx.Project(generatedDoc).DocxBytes;
        var thirdDoc = DxpDocExport.Export(projected);
        foreach (var binary in new[] { generatedDoc, thirdDoc })
        {
            var bytes = DxpDocToDocx.Project(binary).DocxBytes;
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            Assert.Single(main.Document!.Body!.Descendants<Drawing>());
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Drawing>().Any());
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Drawing>().Any());
            var images = main.ImageParts.Concat(main.HeaderParts.SelectMany(x => x.ImageParts))
                .Concat(main.FooterParts.SelectMany(x => x.ImageParts)).ToArray();
            Assert.Equal(3, images.Length);
            Assert.All(images, x => Assert.Equal("image/tiff", x.ContentType));
            foreach (var part in images)
            {
                using var image = part.GetStream();
                using var copy = new MemoryStream();
                image.CopyTo(copy);
                Assert.Equal(sourceTiff, copy.ToArray());
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var native = File.ReadAllBytes(Path.ChangeExtension(path, ".doc"));
        var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
        using (var stream = new MemoryStream(nativeProjection))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            Assert.Single(main.Document!.Body!.Descendants<Drawing>());
            Assert.Contains(main.HeaderParts, x => x.Header!.Descendants<Drawing>().Any());
            Assert.Contains(main.FooterParts, x => x.Footer!.Descendants<Drawing>().Any());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var nativeError = AssertWordPageRenderClose(source, native, 0.05, 1);
            foreach (var (label, output, extension) in new[]
            {
                ("generated DOC", generatedDoc, ".doc"),
                ("projected DOCX", projected, ".docx"),
                ("third DOC", thirdDoc, ".doc"),
                ("native projection", nativeProjection, ".docx")
            })
            {
                var error = AssertWordPageRenderClose(source, output, 0.08, 1, extension);
                if (label == "native projection")
                    Assert.InRange(Math.Abs(error - nativeError), 0, 0.005);
                else
                    Assert.True(error < 0.04, $"{label} renders RMSE {error}.");
            }
        }
    }

