    [Fact]
    public void NestedTrackedListEditsKeepWordLabelsInBothRevisionViews()
    {
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var at = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc);
        static Paragraph Item(int level,
            DocumentFormat.OpenXml.OpenXmlElement content,
            DocumentFormat.OpenXml.OpenXmlElement? mark = null,
            int numberId = 1)
        {
            var properties = new ParagraphProperties(new NumberingProperties(
                new NumberingLevelReference { Val = level },
                new NumberingId { Val = numberId }));
            if (mark != null)
                properties.Append(new ParagraphMarkRunProperties(mark));
            return new Paragraph(properties, content);
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            var abstractNum = new AbstractNum { AbstractNumberId = 0 };
            for (var level = 0; level < 9; level++)
                abstractNum.Append(new Level(
                    new StartNumberingValue { Val = 1 },
                    new NumberingFormat { Val = NumberFormatValues.Decimal },
                    new LevelSuffix { Val = LevelSuffixValues.Space },
                    new LevelText { Val = level == 0 ? "%1." : "%1.%2." })
                    { LevelIndex = level });
            numbering.Numbering = new Numbering(abstractNum,
                new NumberingInstance(new AbstractNumId { Val = 0 })
                    { NumberID = 1 },
                new NumberingInstance(new AbstractNumId { Val = 0 },
                    new LevelOverride(new StartOverrideNumberingValue { Val = 2 })
                        { LevelIndex = 0 },
                    new LevelOverride(new StartOverrideNumberingValue { Val = 5 })
                        { LevelIndex = 1 }) { NumberID = 2 });
            numbering.Numbering.Save();
            main.Document = new Document(new Body(
                Item(0, new Run(new Text("Parent one"))),
                Item(1, new Run(new Text("Child one"))),
                Item(1,
                    new DeletedRun(new Run(new DeletedText("Removed child")))
                    { Id = "1", Author = "List Editor", Date = at },
                    new Deleted { Id = "2", Author = "List Editor", Date = at }),
                Item(1,
                    new InsertedRun(new Run(new Text("Added child")))
                    { Id = "3", Author = "List Editor", Date = at },
                    new Inserted { Id = "4", Author = "List Editor", Date = at }),
                Item(0, new Run(new Text("Parent two")), numberId: 2),
                Item(1, new Run(new Text("Restart child")), numberId: 2)));
            main.Document.Save();
            var errors = new OpenXmlValidator().Validate(document).ToArray();
            Assert.True(errors.Length == 0, string.Join("\n", errors.Select(x =>
                $"{x.Description} at {x.Path?.XPath}: {x.Node?.OuterXml}")));
        }
        var temporary = Path.Combine(Path.GetTempPath(),
            $"docxport-nested-revisions-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporary);
        var paths = new[]
        {
            Path.Combine(temporary, "source.docx"),
            Path.Combine(temporary, "native.doc"),
            Path.Combine(temporary, "native-projected.docx"),
            Path.Combine(temporary, "generated.doc"),
            Path.Combine(temporary, "rewritten-native.doc")
        };
        File.WriteAllBytes(paths[0], source.ToArray());
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            dynamic authored = word.Documents.Open(paths[0], ReadOnly: true,
                AddToRecentFiles: false);
            try { authored.SaveAs2(paths[1], 0); }
            finally { authored.Close(false); }
            File.WriteAllBytes(paths[2],
                DxpDocToDocx.Project(File.ReadAllBytes(paths[1])).DocxBytes);
            File.WriteAllBytes(paths[3], DxpDocExport.Export(source.ToArray()));
            File.WriteAllBytes(paths[4], DxpDocExport.Export(File.ReadAllBytes(paths[2])));
            foreach (var accept in new[] { true, false })
            {
                var results = new List<(string Text, string Label)>[paths.Length];
                for (var i = 0; i < paths.Length; i++)
                {
                    dynamic document = word.Documents.Open(paths[i], ReadOnly: true,
                        AddToRecentFiles: false);
                    try
                    {
                        Assert.True((int)document.Revisions.Count > 0);
                        if (accept) document.Revisions.AcceptAll();
                        else document.Revisions.RejectAll();
                        var pairs = new List<(string Text, string Label)>();
                        foreach (dynamic paragraph in document.Paragraphs)
                            if ((int)paragraph.Range.ListFormat.ListType != 0)
                                pairs.Add((((string)paragraph.Range.Text).Trim(),
                                    (string)paragraph.Range.ListFormat.ListString));
                        results[i] = pairs;
                    }
                    finally { document.Close(false); }
                }
                Assert.Equal(5, results[0].Count);
                Assert.Contains(results[0], pair => pair.Text == "Parent one" &&
                    pair.Label == "1.");
                Assert.Contains(results[0], pair => pair.Text == "Child one" &&
                    pair.Label == "1.1.");
                Assert.Contains(results[0], pair => pair.Text == "Parent two" &&
                    pair.Label == "2.");
                Assert.Contains(results[0], pair => pair.Text == "Restart child" &&
                    pair.Label == "2.5.");
                if (accept)
                {
                    Assert.Contains(results[0], pair => pair.Text == "Added child");
                    Assert.DoesNotContain(results[0], pair => pair.Text == "Removed child");
                }
                else
                {
                    Assert.Contains(results[0], pair => pair.Text == "Removed child");
                    Assert.DoesNotContain(results[0], pair => pair.Text == "Added child");
                }
                Assert.Equal(results[0], results[1]);
                Assert.Equal(results[0], results[2]);
                Assert.Equal(results[0], results[3]);
                Assert.Equal(results[0], results[4]);
            }
        }
        finally
        {
            word.Quit(false);
            foreach (var path in paths) File.Delete(path);
            Directory.Delete(temporary);
        }
    }

    [Fact]
    public void DocRoundTripPreservesNeverRestartingNestedListInAllStories()
    {
        static Paragraph Item(string text, int level) => new(
            new ParagraphProperties(new NumberingProperties(
                new NumberingLevelReference { Val = level },
                new NumberingId { Val = 1 })),
            new Run(new Text(text)));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            numbering.Numbering = new Numbering(
                new AbstractNum(
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelText { Val = "%1." },
                        new PreviousParagraphProperties(
                            new Tabs(new TabStop { Val = TabStopValues.Number,
                                Position = 720 }),
                            new Indentation { Left = "720", Hanging = "360" }))
                        { LevelIndex = 0 },
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelRestart { Val = 0 },
                        new LevelText { Val = "%2)" },
                        new PreviousParagraphProperties(
                            new Tabs(new TabStop { Val = TabStopValues.Number,
                                Position = 1440 }),
                            new Indentation { Left = "1440", Hanging = "360" }))
                        { LevelIndex = 1 })
                    { AbstractNumberId = 0 },
                new NumberingInstance(new AbstractNumId { Val = 0 }) { NumberID = 1 });
            numbering.Numbering.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Item("Header parent one", 0),
                Item("Header child one", 1), Item("Header parent two", 0),
                Item("Header child two", 1));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Item("Footer parent one", 0),
                Item("Footer child one", 1), Item("Footer parent two", 0),
                Item("Footer child two", 1));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                Item("Body parent one", 0), Item("Body child one", 1),
                Item("Body parent two", 0), Item("Body child two", 1),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        static void CheckDoc(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(stream);
            Assert.Equal((byte)0, index.Lists.Definitions[0].Levels[1].RestartLimit);
        }
        CheckDoc(binary);
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        using (var stream = new MemoryStream(projectedBytes))
        using (var projected = WordprocessingDocument.Open(stream, false))
        {
            var level = projected.MainDocumentPart!.NumberingDefinitionsPart!
                .Numbering!.Descendants<Level>().Single(x => x.LevelIndex == 1);
            Assert.Equal(0, level.GetFirstChild<LevelRestart>()?.Val?.Value);
            Assert.Equal(4, projected.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().Count(x => x.ParagraphProperties?.NumberingProperties != null));
            Assert.Equal(4, projected.MainDocumentPart.HeaderParts.Single().Header!
                .Elements<Paragraph>().Count(x => x.ParagraphProperties?.NumberingProperties != null));
            Assert.Equal(4, projected.MainDocumentPart.FooterParts.Single().Footer!
                .Elements<Paragraph>().Count(x => x.ParagraphProperties?.NumberingProperties != null));
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var thirdHop = DxpDocExport.Export(projectedBytes);
        CheckDoc(thirdHop);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projectedBytes,
                0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), thirdHop, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var prefix = Path.Combine(Path.GetTempPath(),
                $"docxport-list-restart-{Guid.NewGuid():N}");
            var paths = new[] { prefix + ".docx", prefix + ".doc",
                prefix + "-projected.docx", prefix + "-native.doc",
                prefix + "-third.doc" };
            File.WriteAllBytes(paths[0], source.ToArray());
            File.WriteAllBytes(paths[1], binary);
            File.WriteAllBytes(paths[2], projectedBytes);
            File.WriteAllBytes(paths[4], thirdHop);
            dynamic word = Activator.CreateInstance(
                Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            try
            {
                var labels = new List<string[]>();
                var layouts = new List<string[]>();
                for (var i = 0; i < paths.Length; i++)
                {
                    dynamic opened = word.Documents.Open(paths[i], ReadOnly: true,
                        AddToRecentFiles: false);
                    try
                    {
                        if (i == 0) opened.SaveAs2(paths[3], 0);
                        static string[] Story(dynamic paragraphs)
                        {
                            var result = new List<string>();
                            foreach (dynamic paragraph in paragraphs)
                                if ((int)paragraph.Range.ListFormat.ListType != 0)
                                    result.Add((string)paragraph.Range.ListFormat.ListString);
                            return result.ToArray();
                        }
                        labels.Add(Story(opened.Paragraphs));
                        labels.Add(Story(opened.Sections(1).Headers(1).Range.Paragraphs));
                        labels.Add(Story(opened.Sections(1).Footers(1).Range.Paragraphs));
                        static string[] Layout(dynamic paragraphs)
                        {
                            var result = new List<string>();
                            foreach (dynamic paragraph in paragraphs)
                                if ((int)paragraph.Range.ListFormat.ListType != 0)
                                    result.Add(string.Join("/",
                                        (string)paragraph.Range.Font.Name,
                                        Convert.ToDouble(paragraph.Range.Font.Size)
                                            .ToString("F2", CultureInfo.InvariantCulture),
                                        Convert.ToDouble(paragraph.Format.LeftIndent)
                                            .ToString("F2", CultureInfo.InvariantCulture),
                                        Convert.ToDouble(paragraph.Format.FirstLineIndent)
                                            .ToString("F2", CultureInfo.InvariantCulture),
                                        Convert.ToDouble(paragraph.Format.SpaceAfter)
                                            .ToString("F2", CultureInfo.InvariantCulture),
                                        Convert.ToDouble(paragraph.Format.LineSpacing)
                                            .ToString("F2", CultureInfo.InvariantCulture),
                                        (int)paragraph.Format.LineSpacingRule,
                                        (string)paragraph.Range.ListFormat.ListTemplate
                                            .ListLevels((int)paragraph.Range.ListFormat.ListLevelNumber)
                                            .Font.Name,
                                        Convert.ToDouble(paragraph.Range.Information(6))
                                            .ToString("F2", CultureInfo.InvariantCulture)));
                            return result.ToArray();
                        }
                        layouts.Add(Layout(opened.Paragraphs));
                        layouts.Add(Layout(opened.Sections(1).Headers(1).Range.Paragraphs));
                        layouts.Add(Layout(opened.Sections(1).Footers(1).Range.Paragraphs));
                    }
                    finally { opened.Close(false); }
                }
                for (var i = 0; i < labels.Count; i++)
                    Assert.Equal(labels[i % 3], labels[i]);
                for (var i = 0; i < layouts.Count; i++)
                    Assert.Equal(layouts[i % 3], layouts[i]);
                Assert.Equal(new[] { "1.", "1)", "2.", "2)" }, labels[0]);
                CheckDoc(File.ReadAllBytes(paths[3]));
            }
            finally
            {
                word.Quit();
                foreach (var path in paths) File.Delete(path);
            }
        }
    }

    [Fact]
    public void DeepListRestartsOnlyAfterSpecifiedAncestor()
    {
        static Paragraph Item(int level, string text) => new(
            new ParagraphProperties(new NumberingProperties(
                new NumberingLevelReference { Val = level },
                new NumberingId { Val = 1 })), new Run(new Text(text)));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            numbering.Numbering = new Numbering(
                new AbstractNum(
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelText { Val = "%1." }) { LevelIndex = 0 },
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelText { Val = "%2)" }) { LevelIndex = 1 },
                    new Level(new StartNumberingValue { Val = 1 },
                        new NumberingFormat { Val = NumberFormatValues.Decimal },
                        new LevelRestart { Val = 1 },
                        new LevelText { Val = "%3]" }) { LevelIndex = 2 })
                    { AbstractNumberId = 0 },
                new NumberingInstance(new AbstractNumId { Val = 0 }) { NumberID = 1 });
            numbering.Numbering.Save();
            main.Document = new Document(new Body(
                Item(0, "Parent one"), Item(1, "Middle one"),
                Item(2, "Deep one"), Item(1, "Middle two"),
                Item(2, "Deep two"), Item(0, "Parent two"),
                Item(2, "Deep reset")));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        static void CheckDoc(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Equal((byte)1, index.Lists.Definitions[0].Levels[2].RestartLimit);
        }
        CheckDoc(generated);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        using (var input = new MemoryStream(projected))
        using (var document = WordprocessingDocument.Open(input, false))
        {
            Assert.Equal(1, document.MainDocumentPart!.NumberingDefinitionsPart!
                .Numbering!.Descendants<Level>().Single(x => x.LevelIndex == 2)
                .GetFirstChild<LevelRestart>()?.Val?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var third = DxpDocExport.Export(projected);
        CheckDoc(third);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), third, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var prefix = Path.Combine(Path.GetTempPath(),
            $"docxport-deep-restart-{Guid.NewGuid():N}");
        var paths = new[] { prefix + ".docx", prefix + ".doc",
            prefix + "-projected.docx", prefix + "-third.doc",
            prefix + "-native.doc" };
        File.WriteAllBytes(paths[0], source.ToArray());
        File.WriteAllBytes(paths[1], generated);
        File.WriteAllBytes(paths[2], projected);
        File.WriteAllBytes(paths[3], third);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            var labels = new List<string[]>();
            for (var i = 0; i < paths.Length; i++)
            {
                dynamic opened = word.Documents.Open(paths[i], ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    if (i == 0) opened.SaveAs2(paths[4], 0);
                    var story = new List<string>();
                    foreach (dynamic paragraph in opened.Paragraphs)
                        if ((int)paragraph.Range.ListFormat.ListType != 0)
                            story.Add((string)paragraph.Range.ListFormat.ListString);
                    labels.Add(story.ToArray());
                }
                finally { opened.Close(false); }
            }
            Assert.Equal(new[] { "1.", "1)", "1]", "2)", "2]", "2.", "1]" },
                labels[0]);
            foreach (var actual in labels.Skip(1)) Assert.Equal(labels[0], actual);
            CheckDoc(File.ReadAllBytes(paths[4]));
        }
        finally
        {
            word.Quit();
            foreach (var path in paths) File.Delete(path);
        }
    }

    [Fact]
    public void NumberedListContinuesAcrossNextPageSection()
    {
        static Paragraph Item(string text, bool sectionBreak = false)
        {
            var properties = new ParagraphProperties(new NumberingProperties(
                new NumberingLevelReference { Val = 0 },
                new NumberingId { Val = 1 }));
            if (sectionBreak)
                properties.Append(new SectionProperties(
                    new SectionType { Val = SectionMarkValues.NextPage }));
            return new Paragraph(properties, new Run(new Text(text)));
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            numbering.Numbering = new Numbering(
                new AbstractNum(new Level(new StartNumberingValue { Val = 1 },
                    new NumberingFormat { Val = NumberFormatValues.Decimal },
                    new LevelText { Val = "%1." }) { LevelIndex = 0 })
                    { AbstractNumberId = 0 },
                new NumberingInstance(new AbstractNumId { Val = 0 }) { NumberID = 1 });
            numbering.Numbering.Save();
            main.Document = new Document(new Body(Item("First"),
                Item("Second", sectionBreak: true), Item("Third"), Item("Fourth"),
                new SectionProperties()));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var third = DxpDocExport.Export(projected);
        static void Check(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Single(index.Lists.Instances);
            Assert.Single(index.Lists.Definitions);
            Assert.Equal(2, index.Sections.Count);
        }
        Check(generated);
        Check(third);
        using (var input = new MemoryStream(projected))
        using (var document = WordprocessingDocument.Open(input, false))
        {
            var body = document.MainDocumentPart!.Document!.Body!;
            Assert.Equal(4, body.Elements<Paragraph>().Count(x =>
                x.ParagraphProperties?.NumberingProperties != null));
            Assert.Equal(2, body.Descendants<SectionProperties>().Count());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            foreach (var page in new[] { 1, 2 })
            {
                AssertWordPageRenderClose(source.ToArray(), generated, 0.04, page);
                AssertWordPageRenderClose(source.ToArray(), projected,
                    0.04, page, ".docx");
                AssertWordPageRenderClose(source.ToArray(), third, 0.04, page);
            }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var prefix = Path.Combine(Path.GetTempPath(),
            $"docxport-list-sections-{Guid.NewGuid():N}");
        var paths = new[] { prefix + ".docx", prefix + ".doc",
            prefix + "-projected.docx", prefix + "-third.doc",
            prefix + "-native.doc" };
        File.WriteAllBytes(paths[0], source.ToArray());
        File.WriteAllBytes(paths[1], generated);
        File.WriteAllBytes(paths[2], projected);
        File.WriteAllBytes(paths[3], third);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            for (var i = 0; i < paths.Length; i++)
            {
                dynamic opened = word.Documents.Open(paths[i], ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    if (i == 0) opened.SaveAs2(paths[4], 0);
                    Assert.Equal(2, (int)opened.Sections.Count);
                    var labels = new List<string>();
                    foreach (dynamic paragraph in opened.Paragraphs)
                        if ((int)paragraph.Range.ListFormat.ListType != 0)
                            labels.Add((string)paragraph.Range.ListFormat.ListString);
                    Assert.Equal(new[] { "1.", "2.", "3.", "4." }, labels);
                }
                finally { opened.Close(false); }
            }
            Check(File.ReadAllBytes(paths[4]));
        }
        finally
        {
            word.Quit();
            foreach (var path in paths) File.Delete(path);
        }
    }

    [Fact]
    public void DocRoundTripPreservesListRestartInBodyHeaderAndFooter()
    {
        static Paragraph Item(string text, int numberId) => new(
            new ParagraphProperties(new NumberingProperties(
                new NumberingLevelReference { Val = 0 },
                new NumberingId { Val = numberId })),
            new Run(new Text(text)));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var numbering = main.AddNewPart<NumberingDefinitionsPart>();
            numbering.Numbering = new Numbering(
                new AbstractNum(new Level(
                    new StartNumberingValue { Val = 1 },
                    new NumberingFormat { Val = NumberFormatValues.Decimal },
                    new LevelSuffix { Val = LevelSuffixValues.Space },
                    new LevelText { Val = "%1." },
                    new LevelJustification { Val = LevelJustificationValues.Right },
                    new PreviousParagraphProperties(
                        new Tabs(new TabStop { Val = TabStopValues.Number,
                            Position = 720 }),
                        new Indentation { Left = "720", Hanging = "360" }),
                    new NumberingSymbolRunProperties(
                        new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                        new Bold(), new Italic(),
                        new Color { Val = "3366CC" },
                        new Underline { Val = UnderlineValues.Single },
                        new FontSize { Val = "24" })) { LevelIndex = 0 })
                    { AbstractNumberId = 0 },
                new NumberingInstance(new AbstractNumId { Val = 0 }) { NumberID = 1 },
                new NumberingInstance(new AbstractNumId { Val = 0 },
                    new LevelOverride(new StartOverrideNumberingValue { Val = 5 })
                        { LevelIndex = 0 }) { NumberID = 2 });
            numbering.Numbering.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Item("Header item", 1));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Item("Footer item", 1));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                Item("One", 1), Item("Two", 1), Item("Five", 2),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(2, index.Lists.Instances.Count);
            Assert.Equal(5, index.Lists.Instances[1].StartOverrides[0]);
            Assert.Equal("Arial", index.Lists.Definitions[0].Levels[0]
                .LabelFormatting?.AsciiFontName);
            Assert.True(index.Lists.Definitions[0].Levels[0]
                .LabelFormatting?.Bold);
            Assert.True(index.Lists.Definitions[0].Levels[0]
                .LabelFormatting?.Italic);
            Assert.Equal(0x00CC6633u, index.Lists.Definitions[0].Levels[0]
                .LabelFormatting?.ColorRef);
            Assert.Equal((byte)1, index.Lists.Definitions[0].Levels[0]
                .LabelFormatting?.UnderlineCode);
            var levelParagraph = index.Lists.Definitions[0].Levels[0].ParagraphFormatting;
            Assert.Equal((short)720, levelParagraph?.LeftTwips);
            Assert.Equal((byte)2, index.Lists.Definitions[0].Levels[0]
                .LabelJustification);
            Assert.Equal((short)-360, levelParagraph?.FirstLineTwips);
            Assert.Contains(levelParagraph!.TabStops!, x =>
                x.PositionTwips == 720 && x.Alignment == 6);
            Assert.Contains(index.ParagraphStyles, x =>
                x.Formatting?.ListOverrideIndex == 2);
        }
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        using var projectedStream = new MemoryStream(projectedBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        Assert.Equal(3, projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>().Count(x => x.ParagraphProperties?.NumberingProperties != null));
        Assert.NotEmpty(projected.MainDocumentPart.HeaderParts.Single().Header!
            .Descendants<NumberingProperties>());
        Assert.NotEmpty(projected.MainDocumentPart.FooterParts.Single().Footer!
            .Descendants<NumberingProperties>());
        var labelProperties = projected.MainDocumentPart.NumberingDefinitionsPart!
            .Numbering!.Descendants<NumberingSymbolRunProperties>().ToArray();
        Assert.Equal(2, labelProperties.Length);
        Assert.All(labelProperties, properties =>
        {
            Assert.Equal("Arial", properties.GetFirstChild<RunFonts>()?.Ascii?.Value);
            Assert.NotNull(properties.GetFirstChild<Bold>());
            Assert.NotNull(properties.GetFirstChild<Italic>());
            Assert.Equal("3366CC", properties.GetFirstChild<Color>()?.Val?.Value);
            Assert.Equal(UnderlineValues.Single,
                properties.GetFirstChild<Underline>()?.Val?.Value);
        });
        var levelProperties = projected.MainDocumentPart.NumberingDefinitionsPart!
            .Numbering!.Descendants<PreviousParagraphProperties>().ToArray();
        Assert.Equal(2, levelProperties.Length);
        Assert.All(levelProperties, properties =>
        {
            Assert.Equal("720", properties.GetFirstChild<Indentation>()?.Left?.Value);
            Assert.Equal("360", properties.GetFirstChild<Indentation>()?.Hanging?.Value);
            Assert.Contains(properties.GetFirstChild<Tabs>()!.Elements<TabStop>(),
                x => x.Position?.Value == 720 && x.Val?.Value == TabStopValues.Number);
        });
        Assert.All(projected.MainDocumentPart.NumberingDefinitionsPart!.Numbering!
            .Descendants<Level>(), level =>
                Assert.Equal(LevelJustificationValues.Right,
                    level.LevelJustification?.Val?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                $"docxport-list-stories-{Guid.NewGuid():N}.doc");
            var sourcePath = Path.ChangeExtension(path, ".docx");
            var nativePath = Path.Combine(Path.GetDirectoryName(path)!,
                Path.GetFileNameWithoutExtension(path) + "-native.doc");
            File.WriteAllBytes(path, binary);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var labels = new List<string>();
                foreach (dynamic paragraph in opened.Paragraphs)
                    if ((int)paragraph.Range.ListFormat.ListType != 0)
                        labels.Add((string)paragraph.Range.ListFormat.ListString);
                Assert.Equal(new[] { "1.", "2.", "5." }, labels);
                dynamic labelFont = opened.Paragraphs(1).Range.ListFormat
                    .ListTemplate.ListLevels(1).Font;
                Assert.Equal("Arial", (string)labelFont.Name);
                Assert.True(Convert.ToBoolean(labelFont.Bold));
                Assert.True(Convert.ToBoolean(labelFont.Italic));
                Assert.Equal(0x00CC6633, (int)labelFont.Color);
                Assert.NotEqual(0, (int)labelFont.Underline);
                Assert.Equal(12f, (float)labelFont.Size);
                Assert.Equal(36f, (float)opened.Paragraphs(1).Range.ListFormat
                    .ListTemplate.ListLevels(1).TextPosition);
                Assert.Equal(2, (int)opened.Paragraphs(1).Range.ListFormat
                    .ListTemplate.ListLevels(1).Alignment);
                Assert.NotEqual(0, (int)opened.Sections(1).Headers(1)
                    .Range.Paragraphs(1).Range.ListFormat.ListType);
                Assert.NotEqual(0, (int)opened.Sections(1).Footers(1)
                    .Range.Paragraphs(1).Range.ListFormat.ListType);
                foreach (dynamic storyParagraph in new[]
                {
                    opened.Sections(1).Headers(1).Range.Paragraphs(1),
                    opened.Sections(1).Footers(1).Range.Paragraphs(1)
                })
                {
                    dynamic storyLabelFont = storyParagraph.Range.ListFormat
                        .ListTemplate.ListLevels(1).Font;
                    Assert.Equal(0x00CC6633, (int)storyLabelFont.Color);
                    Assert.True(Convert.ToBoolean(storyLabelFont.Italic));
                    Assert.NotEqual(0, (int)storyLabelFont.Underline);
                }
                opened.Close(false);
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var nativeStream = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeStream);
                Assert.Contains(nativeIndex.Lists.Definitions.SelectMany(x => x.Levels),
                    x => x.LabelFormatting?.Italic == true &&
                        x.LabelFormatting.ColorRef == 0x00CC6633u &&
                        x.LabelFormatting.UnderlineCode == 1);
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                Assert.Contains(nativeProjection.MainDocumentPart!
                    .NumberingDefinitionsPart!.Numbering!
                    .Descendants<NumberingSymbolRunProperties>(), x =>
                        x.GetFirstChild<Italic>() != null &&
                        x.GetFirstChild<Color>()?.Val?.Value == "3366CC" &&
                        x.GetFirstChild<Underline>()?.Val?.Value == UnderlineValues.Single);
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void WalksContainerFibAndEnvelopeWithScopes(bool tableOne)
    {
        using var input = CreateDoc(tableOne);
        using var output = new StringWriter();
        var walker = new DocStructureWalker();
        var visitor = new DocStructurePrintVisitor(output);
        using var structure = walker.Accept(input, visitor);

        Assert.Equal(tableOne ? "1Table" : "0Table", structure.FibBase.TableStreamName);
        Assert.Equal(600u, structure.FindLocation("EmailEnvelope")!.Offset);
        Assert.Equal(20u, structure.FindLocation("EmailEnvelope")!.Length);
        var lines = output.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries);
        Assert.StartsWith("Document DOC", lines[0]);
        Assert.Contains(lines, line => line.Contains("Stream WordDocument") && line.Contains("path=WordDocument"));
        Assert.Contains(lines, line => line.Contains("Stream \\u0005SummaryInformation"));
        Assert.All(lines, line => Assert.All(line.TrimEnd('\r'), character => Assert.InRange((int)character, 0x20, 0x7E)));
        Assert.Contains(lines, line => line.Contains("FibBase FibBase") && line.Contains("tableStream="));
        Assert.Contains(lines, line => line.Contains("FibLocation EmailEnvelope") && line.Contains("offset=600"));
        Assert.Contains(lines, line => line.Contains("Dop2000 EnvelopeVisibility") && line.Contains("length=1"));
        Assert.Contains(lines, line => line.Contains("MsoEnvelopeCLSID EmailEnvelopeHeader") && line.Contains("length=20"));
        var headerNodes = structure.Root.Children.SelectMany(x => x.Children)
            .SelectMany(x => x.Children).SelectMany(x => x.Children).SelectMany(x => x.Children).ToList();
        var visibility = headerNodes.Single(x => x.Name == "EnvelopeVisibility");
        var envelopeHeader = headerNodes.Single(x => x.Name == "EmailEnvelopeHeader");
        Assert.True(((DocDopVisibility)visibility.Payload!).Visible);
        Assert.Equal(8u, ((DocEnvelopeHeader)envelopeHeader.Payload!).Version);
        Assert.Same(envelopeHeader.Payload, envelopeHeader.Payload);
        Assert.True(Array.FindIndex(lines, x => x.Contains("FibDirectory")) <
                    Array.FindIndex(lines, x => x.Contains("FibLocation EmailEnvelope")));
    }

