    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void PieceCrossingMainAndHeaderStoriesSurvivesBothDocRoutes(bool compressed)
    {
        using var source = CreateDocWithStoryPlcs(withPieceTable: true,
            compressedStoryPiece: compressed);
        using var index = new DocTextIndexWalker().Index(source);
        var main = Assert.Single(index.GetPartSpans("Main"));
        var headers = Assert.Single(index.GetPartSpans("Headers"));
        Assert.Same(main.Piece, headers.Piece);
        Assert.Equal(compressed ? "compressed" : "utf16",
            main.Piece.Node.Attributes["encoding"]);
        Assert.Equal(1100L, main.Piece.TextOffset);
        Assert.Equal(1100L, index.GetTextOffset(main.CpStart));
        Assert.Equal(1100L, main.TextOffsetStart);
        Assert.Equal(compressed ? 1108L : 1116L, headers.TextOffsetStart);
        Assert.Equal(headers.Piece.GetTextOffset(headers.CpEnd), headers.TextOffsetEnd);
        Assert.Equal(compressed ? 1108L : 1116L,
            index.GetTextOffset(headers.CpStart));
        Assert.Equal(headers.CpStart, headers.Piece.GetCharacterPosition(
            index.GetTextOffset(headers.CpStart)));
        if (!compressed)
            Assert.Throws<ArgumentOutOfRangeException>(() =>
                headers.Piece.GetCharacterPosition(index.GetTextOffset(headers.CpStart) + 1));
        Assert.Throws<ArgumentOutOfRangeException>(() =>
            index.GetTextOffset(index.Pieces[^1].CpEnd));
        Assert.True(main.Piece.CpStart < main.CpEnd);
        Assert.True(main.Piece.CpEnd > headers.CpStart);
        Assert.Equal("Body", main.Text);
        Assert.StartsWith("H", headers.Text);

        var projected = new DocToDocxProjector().Project(index);
        var rewritten = DxpDocExport.Export(projected.DocxBytes);
        var roundTrip = DxpDocToDocx.Project(rewritten);
        using var projectedStream = new MemoryStream(projected.DocxBytes);
        using var roundTripStream = new MemoryStream(roundTrip.DocxBytes);
        using var projectedDocx = WordprocessingDocument.Open(projectedStream, false);
        using var roundTripDocx = WordprocessingDocument.Open(roundTripStream, false);
        Assert.Equal("Body", projectedDocx.MainDocumentPart!.Document!.Body!.InnerText);
        Assert.Equal("Body", roundTripDocx.MainDocumentPart!.Document!.Body!.InnerText);
        Assert.Equal("H", Assert.Single(projectedDocx.MainDocumentPart.HeaderParts)
            .Header!.InnerText);
        Assert.Equal("H", Assert.Single(roundTripDocx.MainDocumentPart.HeaderParts)
            .Header!.InnerText);
        Assert.Empty(new OpenXmlValidator().Validate(roundTripDocx));
    }

