        Assert.Equal("CAPI", Assert.Single(Assert.Single(locations["Captions"].Children)
            .Children.Single().Children.Single().Children.Where(x => x.Kind == "CAPI")).Kind);
        Assert.Equal("FNIF", Assert.Single(Assert.Single(locations["ExternalFileNames"].Children)
            .Children.Single().Children.Single().Children.Where(x => x.Kind == "FNIF")).Kind);
