    [Fact]
    public void DocVisitorWritesPlainTextDocumentFromDocx()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Hello"), new TabChar(), new Text("Ω"),
                    new Break(), new Text("World"))),
                new Paragraph(new Run(new Text("Next")))));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var compoundInput = new MemoryStream(docBytes, false))
        using (var compound = RootStorage.Open(compoundInput))
        using (var word = compound.OpenStream("WordDocument"))
        {
            var fib = new byte[68];
            Assert.Equal(fib.Length, word.Read(fib, 0, fib.Length));
            Assert.Equal(word.Length, BinaryPrimitives.ReadUInt32LittleEndian(fib.AsSpan(64)));
        }
        using var docStream = new MemoryStream(docBytes);
        using var index = new DocTextIndexWalker().Index(docStream);
        Assert.Equal("Hello\tΩ\vWorld\rNext\r",
            string.Concat(index.GetPartSpans("Main").Select(x => x.Text)));
    }

    [Fact]
    public void FieldInstructionRunFormattingSurvivesAllStoriesAndThirdHop()
    {
        static Paragraph Field() => new(
            new Run(new RunProperties(new Bold(), new Color { Val = "AA0000" }),
                new FieldChar { FieldCharType = FieldCharValues.Begin }),
            new Run(new RunProperties(new Bold(), new Color { Val = "006699" }),
                new FieldCode(" PA")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
            new Run(new RunProperties(new Italic(), new Color { Val = "AA4400" }),
                new FieldCode("GE ")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
            new Run(new RunProperties(new Italic(), new Color { Val = "0000AA" }),
                new FieldChar { FieldCharType = FieldCharValues.Separate }),
            new Run(new Text("1")),
            new Run(new RunProperties(new Strike(), new Color { Val = "008800" }),
                new FieldChar { FieldCharType = FieldCharValues.End }));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Field());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Field());
            footer.Footer.Save();
            main.Document = new Document(new Body(Field(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var doc = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(doc).DocxBytes;
        var evaluated = DxpExport.ExportToBytes(projected,
            new DocxportNet.Visitors.Docx.DxpDocxVisitor());
        var noEval = DxpDocToDocx.Project(DxpDocExport.Export(evaluated,
            new DxpExportOptions { FieldEvalMode = DxpFieldEvalExportMode.None })).DocxBytes;
        var evaluatedDoc = DxpDocExport.Export(evaluated);
        using (var indexedStream = new MemoryStream(evaluatedDoc))
        using (var index = new DocTextIndexWalker().Index(indexedStream))
        {
            var bodyText = string.Concat(index.GetPartSpans("Main").Select(x => x.Text));
            var endCp = checked((uint)bodyText.IndexOf('\u0015'));
            Assert.Contains(index.CharacterFormatting, x => x.CpStart <= endCp &&
                endCp < x.CpEnd && x.Formatting.ColorRef == 0x00008800u);
        }
        foreach (var bytes in new[]
        {
            projected,
            DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes,
            evaluated,
            noEval,
            DxpDocToDocx.Project(evaluatedDoc).DocxBytes
        })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var codes = story.Descendants<FieldCode>().ToArray();
                Assert.Equal(new[] { " PA", "GE " }, codes.Select(x => x.Text));
                var first = Assert.IsType<Run>(codes[0].Parent).RunProperties;
                Assert.NotNull(first?.Bold);
                Assert.Equal("006699", first.Color?.Val?.Value);
                var second = Assert.IsType<Run>(codes[1].Parent).RunProperties;
                Assert.NotNull(second?.Italic);
                Assert.Equal("AA4400", second.Color?.Val?.Value);
                var markers = story.Descendants<FieldChar>().ToArray();
                Assert.Equal(new[] { FieldCharValues.Begin, FieldCharValues.Separate,
                    FieldCharValues.End }, markers.Select(x => x.FieldCharType!.Value));
                Assert.Equal("AA0000", Assert.IsType<Run>(markers[0].Parent)
                    .RunProperties?.Color?.Val?.Value);
                Assert.Equal("0000AA", Assert.IsType<Run>(markers[1].Parent)
                    .RunProperties?.Color?.Val?.Value);
                Assert.Equal("008800", Assert.IsType<Run>(markers[2].Parent)
                    .RunProperties?.Color?.Val?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-styled-field-code-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                using var nativeStream = new MemoryStream(
                    DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var main = native.MainDocumentPart!;
                foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    main.Document!.Body!, main.HeaderParts.Single().Header!,
                    main.FooterParts.Single().Footer!
                })
                {
                    Assert.Equal(" PAGE ", string.Concat(story.Descendants<FieldCode>()
                        .Select(x => x.Text)));
                    Assert.Contains(story.Descendants<FieldCode>(), x =>
                        x.Parent is Run run && run.RunProperties?.Bold != null);
                    Assert.Contains(story.Descendants<FieldCode>(), x =>
                        x.Parent is Run run && run.RunProperties?.Italic != null);
                    var nativeMarkers = story.Descendants<FieldChar>().ToArray();
                    Assert.Equal(new[] { FieldCharValues.Begin, FieldCharValues.Separate,
                        FieldCharValues.End }, nativeMarkers.Select(x => x.FieldCharType!.Value));
                    Assert.Equal("AA0000", Assert.IsType<Run>(nativeMarkers[0].Parent)
                        .RunProperties?.Color?.Val?.Value);
                    Assert.Equal("0000AA", Assert.IsType<Run>(nativeMarkers[1].Parent)
                        .RunProperties?.Color?.Val?.Value);
                    Assert.Equal("008800", Assert.IsType<Run>(nativeMarkers[2].Parent)
                        .RunProperties?.Color?.Val?.Value);
                }
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                    Directory.Delete(directory, true);
            }
        }
    }

    [Fact]
