    [Fact]
    public void LegacyPageNumberBlockBecomesDecimalPageFieldInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new Run(
                new Text("Header "), new PageNumber())));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new Run(
                new Text("Footer "), new PageNumber())));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Body "), new PageNumber(),
                    new Break { Type = BreakValues.Page }, new Text("next"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new PageNumberType { Start = 7,
                        Format = NumberFormatValues.LowerRoman })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Contains("PAGE \\* Arabic", string.Concat(index.ReadStory("Main").Text.Paragraphs.SelectMany(p => p.Atoms).Select(a => a.Text)));
            Assert.Equal(2, index.HeaderStories.Count(story =>
                story.ReadContent().Paragraphs.SelectMany(p => p.Atoms).Any(a => a.Text.Contains("PAGE \\* Arabic"))));
        }
        var projection = DxpDocToDocx.Project(generated).DocxBytes;
        using (var stream = new MemoryStream(projection))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator().Validate(document));
            Assert.Equal(3, document.MainDocumentPart!.Document!
                .Descendants<FieldCode>().Count() +
                document.MainDocumentPart.HeaderParts.Sum(part =>
                    part.Header!.Descendants<FieldCode>().Count()) +
                document.MainDocumentPart.FooterParts.Sum(part =>
                    part.Footer!.Descendants<FieldCode>().Count()));
            Assert.All(document.MainDocumentPart.Document.Descendants<FieldCode>()
                .Concat(document.MainDocumentPart.HeaderParts.SelectMany(part =>
                    part.Header!.Descendants<FieldCode>()))
                .Concat(document.MainDocumentPart.FooterParts.SelectMany(part =>
                    part.Footer!.Descendants<FieldCode>())),
                field => Assert.Contains("PAGE \\* Arabic", field.Text));
        }
        var third = DxpDocToDocx.Project(DxpDocExport.Export(projection)).DocxBytes;
        using (var stream = new MemoryStream(third))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator().Validate(document));
            Assert.Equal(3, document.MainDocumentPart!.Document!
                .Descendants<FieldCode>().Count() +
                document.MainDocumentPart.HeaderParts.Sum(part =>
                    part.Header!.Descendants<FieldCode>().Count()) +
                document.MainDocumentPart.FooterParts.Sum(part =>
                    part.Footer!.Descendants<FieldCode>().Count()));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 1, ".doc");
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 2, ".doc");
            AssertWordPageRenderClose(source.ToArray(), projection, 0.04, 1, ".docx");
            AssertWordPageRenderClose(source.ToArray(), projection, 0.04, 2, ".docx");
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-legacy-page-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                dynamic nativeOpened = word.Documents.Open(nativePath, ReadOnly: true,
                    AddToRecentFiles: false);
                nativeOpened.Close(false);
                var native = File.ReadAllBytes(nativePath);
                var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
                using (var input = new MemoryStream(native))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    Assert.Empty(index.GetFieldMarks("Main").Concat(
                        index.GetFieldMarks("Headers")));
                    Assert.Single(index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).Where(a =>
                            a.Kind == DocStoryAtomKind.LegacyPageNumberBlock));
                    Assert.Equal(2, index.HeaderStories.Count(story =>
                        story.ReadContent().Paragraphs.SelectMany(p => p.Atoms)
                            .Any(a => a.Kind == DocStoryAtomKind.LegacyPageNumberBlock)));
                }
                using (var stream = new MemoryStream(nativeProjection))
                using (var projectedDocument = WordprocessingDocument.Open(stream, false))
                {
                    Assert.Empty(new OpenXmlValidator().Validate(projectedDocument));
                    var main = projectedDocument.MainDocumentPart!;
                    Assert.Single(main.Document!.Descendants<PageNumber>());
                    Assert.Single(Assert.Single(main.HeaderParts).Header!
                        .Descendants<PageNumber>());
                    Assert.Single(Assert.Single(main.FooterParts).Footer!
                        .Descendants<PageNumber>());
                }
                var nativeThird = DxpDocToDocx.Project(
                    DxpDocExport.Export(nativeProjection)).DocxBytes;
                using (var thirdStream = new MemoryStream(nativeThird))
                using (var thirdDocument = WordprocessingDocument.Open(thirdStream, false))
                {
                    Assert.Empty(new OpenXmlValidator().Validate(thirdDocument));
                    var main = thirdDocument.MainDocumentPart!;
                    Assert.Equal(3, main.Document!.Descendants<FieldCode>().Count() +
                        main.HeaderParts.Sum(part => part.Header!.Descendants<FieldCode>().Count()) +
                        main.FooterParts.Sum(part => part.Footer!.Descendants<FieldCode>().Count()));
                }
                AssertWordPageRenderClose(source.ToArray(), nativeProjection, 0.04, 1, ".docx");
                AssertWordPageRenderClose(source.ToArray(), nativeProjection, 0.04, 2, ".docx");
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void LegacyDateBlocksRetainSixPicturesInAllStories()
    {
        static Paragraph DateParagraph(string label) => new(new Run(
            new Text(label + ": ") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve },
            new DayShort(), new Text("/"),
            new DayLong(), new Text("/"), new MonthShort(), new Text("/"),
            new MonthLong(), new Text("/"), new YearShort(), new Text("/"),
            new YearLong(), new Text(" !/%/#/\"")
                { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }));
        var pictures = new[] { "dd", "dddd", "MM", "MMMM", "yy", "yyyy" };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(DateParagraph("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(DateParagraph("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(DateParagraph("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projection = DxpDocToDocx.Project(generated).DocxBytes;
        foreach (var bytes in new[] { projection,
            DxpDocToDocx.Project(DxpDocExport.Export(projection)).DocxBytes })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            Assert.Empty(new OpenXmlValidator().Validate(document));
            var main = document.MainDocumentPart!;
            foreach (var story in new[] { main.Document!,
                (DocumentFormat.OpenXml.OpenXmlElement)Assert.Single(main.HeaderParts).Header!,
                Assert.Single(main.FooterParts).Footer! })
            {
                var instructions = story.Descendants<FieldCode>()
                    .Select(x => x.Text).ToArray();
                Assert.Equal(pictures.Select(x => $" DATE \\@ \"{x}\" "), instructions);
                Assert.All(story.Descendants<Text>(), text =>
                    Assert.DoesNotContain("Error!", text.Text));
                Assert.Contains(" !/%/#/\"", string.Concat(
                    story.Descendants<Text>().Select(text => text.Text)));
            }
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projection, 0.04, 1, ".docx");
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-legacy-dates-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                dynamic nativeOpened = word.Documents.Open(nativePath, ReadOnly: true,
                    AddToRecentFiles: false);
                nativeOpened.Close(false);
                using (var input = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var index = new DocTextIndexWalker().Index(input))
                    Assert.Equal(6, index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).Count(a =>
                            a.Kind == DocStoryAtomKind.LegacyDateBlock));
                var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath))
                    .DocxBytes;
                using (var stream = new MemoryStream(nativeProjection))
                using (var document = WordprocessingDocument.Open(stream, false))
                {
                    Assert.Empty(new OpenXmlValidator().Validate(document));
                    var main = document.MainDocumentPart!;
                    foreach (var story in new[] { main.Document!,
                        (DocumentFormat.OpenXml.OpenXmlElement)Assert.Single(main.HeaderParts).Header!,
                        Assert.Single(main.FooterParts).Footer! })
                    {
                        Assert.Single(story.Descendants<DayShort>());
                        Assert.Single(story.Descendants<DayLong>());
                        Assert.Single(story.Descendants<MonthShort>());
                        Assert.Single(story.Descendants<MonthLong>());
                        Assert.Single(story.Descendants<YearShort>());
                        Assert.Single(story.Descendants<YearLong>());
                        Assert.Contains(" !/%/#/\"", string.Concat(
                            story.Descendants<Text>().Select(text => text.Text)));
                    }
                }
                AssertWordPageRenderClose(source.ToArray(), nativeProjection, 0.04, 1, ".docx");
                var nativeThird = DxpDocToDocx.Project(
                    DxpDocExport.Export(nativeProjection)).DocxBytes;
                using (var stream = new MemoryStream(nativeThird))
                using (var document = WordprocessingDocument.Open(stream, false))
                {
                    Assert.Empty(new OpenXmlValidator().Validate(document));
                    var main = document.MainDocumentPart!;
                    foreach (var story in new[] { main.Document!,
                        (DocumentFormat.OpenXml.OpenXmlElement)Assert.Single(main.HeaderParts).Header!,
                        Assert.Single(main.FooterParts).Footer! })
                        Assert.Equal(pictures.Select(x => $" DATE \\@ \"{x}\" "),
                            story.Descendants<FieldCode>().Select(x => x.Text));
                }
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void LegacyPageAndDateBlocksInTablesRetainEveryStory()
    {
        static Table StoryTable(string label) => new(
            new TableProperties(
                new TableWidth { Width = "5000", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableCellMarginDefault(
                    new TableCellLeftMargin { Width = 108, Type = TableWidthValues.Dxa },
                    new TableCellRightMargin { Width = 108, Type = TableWidthValues.Dxa })),
            new TableGrid(new GridColumn { Width = "5000" }),
            new TableRow(new TableCell(new Paragraph(new Run(
                new RunProperties(new Bold(), new Color { Val = "1166AA" }),
                new Text(label + ": ")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve },
                new PageNumber(), new Text(" / ")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve },
                new MonthLong())))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new PageNumberType { Start = 7,
                        Format = NumberFormatValues.LowerRoman })));
            main.Document.Save();
        }
        static void AssertProjected(byte[] bytes, bool legacy)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            Assert.Empty(new OpenXmlValidator().Validate(document));
            var main = document.MainDocumentPart!;
            foreach (var story in new[] { main.Document!,
                (DocumentFormat.OpenXml.OpenXmlElement)Assert.Single(main.HeaderParts).Header!,
                Assert.Single(main.FooterParts).Footer! })
            {
                var table = Assert.Single(story.Descendants<Table>());
                var controls = table.Descendants<Run>().Where(run =>
                    run.Descendants<PageNumber>().Any() ||
                    run.Descendants<MonthLong>().Any() ||
                    run.Descendants<FieldCode>().Any()).ToArray();
                Assert.Equal(2, controls.Length);
                Assert.All(controls, run =>
                {
                    Assert.NotNull(run.RunProperties?.Bold);
                    Assert.Equal("1166AA", run.RunProperties?.Color?.Val?.Value);
                });
                if (legacy)
                {
                    Assert.Single(table.Descendants<PageNumber>());
                    Assert.Single(table.Descendants<MonthLong>());
                }
                else
                    Assert.Equal(new[] { " PAGE \\* Arabic ", " DATE \\@ \"MMMM\" " },
                        table.Descendants<FieldCode>().Select(x => x.Text));
            }
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertProjected(projected, false);
        AssertProjected(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes,
            false);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-legacy-table-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        try
        {
            dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            try { opened.SaveAs2(nativePath, 0); }
            finally { opened.Close(false); }
            dynamic nativeOpened = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            nativeOpened.Close(false);
            var native = File.ReadAllBytes(nativePath);
            var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
            AssertProjected(nativeProjection, true);
            AssertProjected(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjection)).DocxBytes, false);
            AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
            AssertWordPageRenderClose(source.ToArray(), nativeProjection, 0.04, 1, ".docx");
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }
    [Fact]
    public void DocRoundTripPreservesEditablePageFieldInFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(
                new Run(new Text("Page ")),
                new SimpleField(new Run(
                    new RunProperties(new Color { Val = "AA3366" },
                        new FontSize { Val = "22" }),
                    new Text("vii"))) { Instruction = " PAGE " }));
            Assert.Equal("vii", footer.Footer.Descendants<SimpleField>().Single().InnerText);
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(new Text("Body"))),
                new SectionProperties(new FooterReference
                {
                    Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer)
                }, new PageNumberType { Start = 7,
                    Format = NumberFormatValues.LowerRoman })));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var footerText = index.HeaderStories[9].ReadContent();
            Assert.Equal("Page \u0013 PAGE \u0014vii\u0015",
                string.Concat(footerText.Paragraphs.SelectMany(x => x.Atoms)
                    .Select(x => x.Text)));
            Assert.Equal(3, index.GetFieldMarks("Headers").Count);
            Assert.Contains(index.CharacterFormatting, x => x.Formatting.Special == true);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var projectedFooter = Assert.Single(projected.MainDocumentPart!.FooterParts).Footer!;
        Assert.Equal(new[] { FieldCharValues.Begin, FieldCharValues.Separate,
            FieldCharValues.End }, projectedFooter.Descendants<FieldChar>()
                .Select(x => x.FieldCharType!.Value));
        Assert.Equal(" PAGE ", Assert.Single(projectedFooter.Descendants<FieldCode>()).Text);
        Assert.Equal("Page vii", string.Concat(projectedFooter.Descendants<Text>()
            .Select(x => x.Text)));
        var resultRun = Assert.Single(projectedFooter.Descendants<Run>(), run =>
            run.Descendants<Text>().Any(text => text.Text == "vii"));
        var projectedNumbering = projected.MainDocumentPart!.Document!.Body!
            .GetFirstChild<SectionProperties>()!.GetFirstChild<PageNumberType>()!;
        Assert.Equal(7, projectedNumbering.Start!.Value);
        Assert.Equal(NumberFormatValues.LowerRoman, projectedNumbering.Format!.Value);
        Assert.Equal("AA3366", resultRun.RunProperties?.Color?.Val?.Value);
        Assert.Equal("22", resultRun.RunProperties?.FontSize?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            if (!OperatingSystem.IsWindows())
                throw new PlatformNotSupportedException("Word automation requires Windows.");
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-page-field-" + Guid.NewGuid().ToString("N") + ".doc");
            var wordSavedPath = Path.ChangeExtension(path, ".word-saved.doc");
            File.WriteAllBytes(path, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                dynamic fields = opened.Sections.Item(1).Footers.Item(1).Range.Fields;
                Assert.Equal(1, (int)fields.Count);
                Assert.Contains("PAGE", (string)fields.Item(1).Code.Text);
                fields.Item(1).Update();
                Assert.Contains("vii", ((string)fields.Item(1).Result.Text).ToLowerInvariant());
                opened.SaveAs2(wordSavedPath, 0);
                opened.Close(false);
                opened = null;
                var wordSavedProjection = DxpDocToDocx.Project(File.ReadAllBytes(wordSavedPath));
                using var wordSavedStream = new MemoryStream(wordSavedProjection.DocxBytes);
                using var wordSavedDocx = WordprocessingDocument.Open(wordSavedStream, false);
                var wordSavedFooter = Assert.Single(wordSavedDocx.MainDocumentPart!.FooterParts,
                    x => x.Footer?.Descendants<FieldCode>().Any(code =>
                        code.Text.Contains("PAGE", StringComparison.OrdinalIgnoreCase)) == true)
                    .Footer!;
                Assert.Contains("PAGE", Assert.Single(wordSavedFooter.Descendants<FieldCode>()).Text);
                Assert.Equal(3, wordSavedFooter.Descendants<FieldChar>().Count());
                Assert.Contains("vii", wordSavedFooter.InnerText.ToLowerInvariant());
                var nativeNumbering = wordSavedDocx.MainDocumentPart!.Document!.Body!
                    .GetFirstChild<SectionProperties>()!.GetFirstChild<PageNumberType>()!;
                Assert.Equal(7, nativeNumbering.Start!.Value);
                Assert.Equal(NumberFormatValues.LowerRoman, nativeNumbering.Format!.Value);
                Assert.Empty(new OpenXmlValidator().Validate(wordSavedDocx));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                if (File.Exists(wordSavedPath)) File.Delete(wordSavedPath);
            }
        }
    }

    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    public void CharacterGridModesRetainPitchAndVisibleLayoutInAllStories(byte mode)
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordSectionLineGridSnapAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var grid = main.Document.Body!.Elements<SectionProperties>().Single()
                .GetFirstChild<DocGrid>()!;
            grid.Type = mode == 1 ? DocGridValues.LinesAndChars : DocGridValues.SnapToChars;
            grid.CharacterSpace = 40960;
            var styles = main.StyleDefinitionsPart!.Styles!;
            styles.Append(new Style(new StyleName { Val = "Normal" },
                new StyleRunProperties(new RunFonts
                { Ascii = "Yu Mincho", HighAnsi = "Yu Mincho", EastAsia = "Yu Mincho" },
                    new FontSize { Val = "22" }))
            { Type = StyleValues.Paragraph, StyleId = "Normal", Default = true });
            styles.Elements<Style>().Single(x => x.StyleId?.Value == "GridBase")
                .StyleRunProperties!.RunFonts = new RunFonts
                { Ascii = "Yu Mincho", HighAnsi = "Yu Mincho", EastAsia = "Yu Mincho" };
            styles.Elements<Style>().Single(x => x.StyleId?.Value == "GridBase")
                .StyleRunProperties!.FontSize = new FontSize { Val = "24" };

            styles.Save();
            const string text = "日本語の文章を一行に並べて文字グリッドを確認します。漢字と仮名を続けて表示します。";
            foreach (var paragraph in main.Document.Body!.Elements<Paragraph>())
                paragraph.Descendants<Text>().Single().Text = text;
            var bodyRuns = main.Document.Body!.Elements<Paragraph>()
                .Select(x => x.GetFirstChild<Run>()!).ToArray();
            bodyRuns[0].RunProperties = new RunProperties(
                new SnapToGrid { Val = true });
            bodyRuns[1].RunProperties = new RunProperties(
                new SnapToGrid { Val = false });
            main.HeaderParts.Single().Header!.Descendants<Text>().Single().Text = "見出し " + text;
            main.FooterParts.Single().Footer!.Descendants<Text>().Single().Text = "脚注 " + text;
            main.HeaderParts.Single().Header!.Descendants<Run>().Single()
                .RunProperties = new RunProperties(new SnapToGrid { Val = false });
            main.FooterParts.Single().Footer!.Descendants<Run>().Single()
                .RunProperties = new RunProperties(new SnapToGrid { Val = false });
            main.Document.Save();
            main.HeaderParts.Single().Header!.Save();
            main.FooterParts.Single().Footer!.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void Check(byte[] binary)
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var section = DocSectionFormatting.Read(index, Assert.Single(index.Sections));
            Assert.Equal(mode, section.GridMode);
            Assert.Equal(40960, section.GridCharacterSpace);
            Assert.Equal((ushort)480, section.GridLinePitch);
            Assert.Contains(index.CharacterFormatting,
                x => x.Formatting.SnapToGrid == false);
            var projected = DxpDocToDocx.Project(binary);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var package = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var grid = package.MainDocumentPart!.Document.Body!
                .Elements<SectionProperties>().Single().GetFirstChild<DocGrid>()!;
            Assert.Equal(mode == 1 ? DocGridValues.LinesAndChars : DocGridValues.SnapToChars,
                grid.Type!.Value);
            Assert.Equal(40960, grid.CharacterSpace!.Value);
            Assert.False(package.MainDocumentPart.HeaderParts.Single().Header!
                .Descendants<Run>().Single().RunProperties!
                .GetFirstChild<SnapToGrid>()!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        Check(generated);
        using (var input = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.True(index.ApplyBreakingRules);
        Check(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-character-grid-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                Check(native);
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(generated).DocxBytes, 0.04);
        }
    }
    [Fact]
    public void SectionLineGridAndParagraphSnapRetainStyleAndDirectValuesInAllStories()
    {
        var roundTrip = DocSectionFormatting.FromOpenXml(new SectionProperties(
            new DocGrid { Type = DocGridValues.Lines, LinePitch = 480 }));
        Assert.Equal((ushort)480, roundTrip.GridLinePitch);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Grid base" },
                    new StyleParagraphProperties(new SnapToGrid()),
                    new StyleRunProperties(new RunFonts
                    { Ascii = "Calibri", HighAnsi = "Calibri" }))
                { Type = StyleValues.Paragraph, StyleId = "GridBase", CustomStyle = true },
                new Style(new StyleName { Val = "Grid derived" },
                    new BasedOn { Val = "GridBase" },
                    new StyleParagraphProperties(new SnapToGrid { Val = false }))
                { Type = StyleValues.Paragraph, StyleId = "GridDerived", CustomStyle = true },
                new Style(new StyleName { Val = "Grid inherited" },
                    new BasedOn { Val = "GridDerived" })
                { Type = StyleValues.Paragraph, StyleId = "GridInherited", CustomStyle = true });
            styles.Styles.Save();
            static Paragraph P(string text, string style, bool? snap = null)
            {
                var properties = new ParagraphProperties(new ParagraphStyleId { Val = style });
                if (snap is bool value) properties.Append(new SnapToGrid { Val = value });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(P("Grid header text", "GridBase"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(P("Grid footer text", "GridDerived", true));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                P("First paragraph with enough words to establish a line in the document grid.",
                    "GridBase", false),
                P("Second paragraph follows the twenty four point line pitch of the grid.",
                    "GridDerived", true),
                P("Third paragraph inherits the grid snapping reset and continues on the page.",
                    "GridInherited"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new DocGrid { Type = DocGridValues.Lines, LinePitch = 480 })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void Check(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                Assert.Equal((ushort)480, DocSectionFormatting.Read(index, Assert.Single(index.Sections)).GridLinePitch);
                Assert.True(Assert.Single(index.StyleDefinitions, x => x.Name == "Grid base")
                    .ParagraphFormatting?.SnapToGrid != false);
                var derived = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Grid derived");
                var inherited = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Grid inherited");
                Assert.False(derived.ParagraphFormatting?.SnapToGrid);
                Assert.Equal(derived.Index, inherited.BasedOnIndex);
                Assert.Null(inherited.DirectParagraphFormatting?.SnapToGrid);
                Assert.False(inherited.ParagraphFormatting?.SnapToGrid);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.SnapToGrid == false);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.SnapToGrid == true);
            }
            var projected = DxpDocToDocx.Project(binary);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var package = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var main = package.MainDocumentPart!;
            Assert.Equal(480, main.Document.Body!.Elements<SectionProperties>().Single()
                .GetFirstChild<DocGrid>()!.LinePitch!.Value);
            Assert.False(main.Document.Body!.Elements<Paragraph>().First()
                .ParagraphProperties!.GetFirstChild<SnapToGrid>()!.Val!.Value);
            Assert.True(main.FooterParts.Single().Footer!.Elements<Paragraph>().Single()
                .ParagraphProperties!.GetFirstChild<SnapToGrid>()!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        Check(generated);
        Check(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-line-grid-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                Check(native);
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(generated).DocxBytes, 0.04);
        }
    }
