    {
        var roundTrip = DocSectionFormatting.FromOpenXml(new SectionProperties(
            new DocGrid { Type = DocGridValues.LinesAndChars, LinePitch = 480, CharacterSpace = 40960 }));
        Assert.Equal((ushort)480, roundTrip.GridLinePitch);
