                    { Ascii = "Yu Mincho", HighAnsi = "Yu Mincho", EastAsia = "Yu Mincho" }))
                { Type = StyleValues.Paragraph, StyleId = "RightGridBase", CustomStyle = true },
                new Style(new StyleName { Val = "Right grid derived" },
                    new BasedOn { Val = "RightGridBase" },
