                { Type = StyleValues.Paragraph, StyleId = "RightGridDerived", CustomStyle = true });
            styles.Styles.Save();
            static Paragraph P(string text, string style, bool? adjust = null)
            {
                var properties = new ParagraphProperties(new ParagraphStyleId { Val = style });
                if (adjust is bool value) properties.Append(new AdjustRightIndent { Val = value });
                properties.Append(new Indentation { Right = "720" });
                return new Paragraph(properties, new Run(new Text(text)));
