    [Fact]
    public void EastAsianLineBreakingControlsRetainStyleAndDirectValuesInAllStories()
    {
        var formatting = DocParagraphFormatting.Empty with
        { Kinsoku = false, WordWrap = true };
        var parsed = DocParagraphFormatting.Parse(formatting.Encode());
        Assert.False(parsed.Kinsoku);
        Assert.True(parsed.WordWrap);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "CJK break base" },
                    new StyleParagraphProperties(new Kinsoku(),
                        new WordWrap { Val = false }),
                    new StyleRunProperties(new RunFonts
                    { Ascii = "Yu Mincho", HighAnsi = "Yu Mincho",
                        EastAsia = "Yu Mincho" }))
                { Type = StyleValues.Paragraph, StyleId = "CjkBreakBase",
                    CustomStyle = true },
                new Style(new StyleName { Val = "CJK break derived" },
                    new BasedOn { Val = "CjkBreakBase" },
                    new StyleParagraphProperties(new WordWrap()))
                { Type = StyleValues.Paragraph, StyleId = "CjkBreakDerived",
                    CustomStyle = true });
            styles.Styles.Save();
            static Paragraph P(string text, string style, bool? kinsoku = null,
                bool? wordWrap = null)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = style });
                if (kinsoku is bool k)
                    properties.Append(new Kinsoku { Val = k });
                if (wordWrap is bool w)
                    properties.Append(new WordWrap { Val = w });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            const string cjk = "日本語の文章で改行規則を確認します。漢字と仮名を続けて表示します。";
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(P("見出し " + cjk, "CjkBreakBase"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(P("脚注 " + cjk,
                "CjkBreakDerived", kinsoku: false));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                P("本文 " + cjk + cjk, "CjkBreakDerived", kinsoku: false),
                P("Second paragraph " + cjk, "CjkBreakBase", wordWrap: true),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void Check(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                var styles = index.StyleDefinitions;
                var baseStyle = Assert.Single(styles, x => x.Name == "CJK break base");
                Assert.True(baseStyle.ParagraphFormatting?.Kinsoku != false);
                Assert.False(baseStyle.ParagraphFormatting?.WordWrap);
                var derived = Assert.Single(styles, x => x.Name == "CJK break derived");
                if (baseStyle.ParagraphFormatting?.Kinsoku is bool kinsoku)
                    Assert.Equal(kinsoku, derived.ParagraphFormatting?.Kinsoku);
                Assert.True(derived.ParagraphFormatting?.WordWrap);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.Kinsoku == false);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.WordWrap == true);
            }
            var projection = DxpDocToDocx.Project(binary);
            Assert.Empty(projection.Coverage.OmittedCharacters);
            using var package = WordprocessingDocument.Open(
                new MemoryStream(projection.DocxBytes), false);
            var main = package.MainDocumentPart!;
            var stylesXml = main.StyleDefinitionsPart!.Styles!;
            Assert.True(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK break base")
                .StyleParagraphProperties!.Kinsoku?.Val?.Value ?? true);
            Assert.False(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK break base")
                .StyleParagraphProperties!.WordWrap!.Val!.Value);
            Assert.True(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK break derived")
                .StyleParagraphProperties!.WordWrap!.Val?.Value ?? true);
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.False(body[0].ParagraphProperties!.Kinsoku!.Val!.Value);
            Assert.True(body[1].ParagraphProperties!.WordWrap!.Val!.Value);
            Assert.Null(main.HeaderParts.Single().Header!.Elements<Paragraph>()
                .Single().ParagraphProperties!.Kinsoku);
            Assert.False(main.FooterParts.Single().Footer!.Elements<Paragraph>()
                .Single().ParagraphProperties!.Kinsoku!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        Check(generated);
        using (var binary = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(binary))
            Assert.True(index.ApplyBreakingRules);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        using (var package = WordprocessingDocument.Open(new MemoryStream(projected), false))
            Assert.NotNull(package.MainDocumentPart!.DocumentSettingsPart!.Settings!
                .GetFirstChild<Compatibility>()!.GetFirstChild<ApplyBreakingRules>());
        Check(DxpDocExport.Export(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-cjk-break-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                Check(native);
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(generated).DocxBytes, 0.04);
        }
    }

    [Fact]
    public void EastAsianAutomaticSpacingRetainsStyleAndDirectValuesInAllStories()
    {
        var formatting = DocParagraphFormatting.Empty with
        { AutoSpaceDE = false, AutoSpaceDN = true };
        var parsed = DocParagraphFormatting.Parse(formatting.Encode());
        Assert.False(parsed.AutoSpaceDE);
        Assert.True(parsed.AutoSpaceDN);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "CJK spacing base" },
                    new StyleParagraphProperties(new AutoSpaceDE(),
                        new AutoSpaceDN { Val = false }),
                    new StyleRunProperties(new RunFonts
                    { Ascii = "Yu Mincho", HighAnsi = "Yu Mincho",
                        EastAsia = "Yu Mincho" }))
                { Type = StyleValues.Paragraph, StyleId = "CjkSpacingBase",
                    CustomStyle = true },
                new Style(new StyleName { Val = "CJK spacing derived" },
                    new BasedOn { Val = "CjkSpacingBase" },
                    new StyleParagraphProperties(new AutoSpaceDN()))
                { Type = StyleValues.Paragraph, StyleId = "CjkSpacingDerived",
                    CustomStyle = true });
            styles.Styles.Save();
            static Paragraph P(string text, string style, bool? autoSpaceDE = null,
                bool? autoSpaceDN = null)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = style });
                if (autoSpaceDE is bool k)
                    properties.Append(new AutoSpaceDE { Val = k });
                if (autoSpaceDN is bool w)
                    properties.Append(new AutoSpaceDN { Val = w });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            const string cjk = "日本語Word123数字ABC漢字456文字。漢字Word789数字DEF文字。";
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(P("見出し " + cjk, "CjkSpacingBase"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(P("脚注 " + cjk,
                "CjkSpacingDerived", autoSpaceDE: false));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                P("本文 " + cjk + cjk, "CjkSpacingDerived", autoSpaceDE: false),
                P("Second paragraph " + cjk, "CjkSpacingBase", autoSpaceDN: true),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void Check(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                var styles = index.StyleDefinitions;
                var baseStyle = Assert.Single(styles, x => x.Name == "CJK spacing base");
                Assert.True(baseStyle.ParagraphFormatting?.AutoSpaceDE != false);
                Assert.False(baseStyle.ParagraphFormatting?.AutoSpaceDN);
                var derived = Assert.Single(styles, x => x.Name == "CJK spacing derived");
                if (baseStyle.ParagraphFormatting?.AutoSpaceDE is bool autoSpaceDE)
                    Assert.Equal(autoSpaceDE, derived.ParagraphFormatting?.AutoSpaceDE);
                Assert.True(derived.ParagraphFormatting?.AutoSpaceDN);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.AutoSpaceDE == false);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.AutoSpaceDN == true);
            }
            var projection = DxpDocToDocx.Project(binary);
            Assert.Empty(projection.Coverage.OmittedCharacters);
            using var package = WordprocessingDocument.Open(
                new MemoryStream(projection.DocxBytes), false);
            var main = package.MainDocumentPart!;
            var stylesXml = main.StyleDefinitionsPart!.Styles!;
            Assert.True(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK spacing base")
                .StyleParagraphProperties!.AutoSpaceDE?.Val?.Value ?? true);
            Assert.False(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK spacing base")
                .StyleParagraphProperties!.AutoSpaceDN!.Val!.Value);
            Assert.True(stylesXml.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "CJK spacing derived")
                .StyleParagraphProperties!.AutoSpaceDN!.Val?.Value ?? true);
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.False(body[0].ParagraphProperties!.AutoSpaceDE!.Val!.Value);
            Assert.True(body[1].ParagraphProperties!.AutoSpaceDN!.Val!.Value);
            Assert.Null(main.HeaderParts.Single().Header!.Elements<Paragraph>()
                .Single().ParagraphProperties!.AutoSpaceDE);
            Assert.False(main.FooterParts.Single().Footer!.Elements<Paragraph>()
                .Single().ParagraphProperties!.AutoSpaceDE!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        Check(generated);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        Check(DxpDocExport.Export(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-cjk-spacing-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                Check(native);
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(generated).DocxBytes, 0.04);
        }
    }

    [Fact]
    public void ParagraphOutlineLevelsRetainStyleAndDirectOverridesInAllStories()
    {
        var encoded = (DocParagraphFormatting.Empty with { OutlineLevel = 9 }).Encode();
        Assert.Equal((byte)9, DocParagraphFormatting.Parse(encoded).OutlineLevel);
        Assert.Throws<InvalidDataException>(() =>
            (DocParagraphFormatting.Empty with { OutlineLevel = 10 }).Encode());
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Outline base" },
                    new StyleParagraphProperties(new OutlineLevel { Val = 0 }))
                { Type = StyleValues.Paragraph, StyleId = "OutlineBase",
                    CustomStyle = true },
                new Style(new StyleName { Val = "Outline derived" },
                    new BasedOn { Val = "OutlineBase" },
                    new StyleParagraphProperties(new OutlineLevel { Val = 2 }))
                { Type = StyleValues.Paragraph, StyleId = "OutlineDerived",
                    CustomStyle = true });
            styles.Styles.Save();
            static Paragraph P(string text, string style, int? direct = null)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = style });
                if (direct is int level)
                    properties.Append(new OutlineLevel { Val = level });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(P("Header outline", "OutlineBase"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(P("Footer body", "OutlineDerived", 9));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                P("Direct level two", "OutlineDerived", 1),
                P("Derived level three", "OutlineDerived"),
                P("Direct body text", "OutlineBase", 9),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void Check(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                Assert.Equal((byte)0, Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Outline base").ParagraphFormatting?.OutlineLevel);
                Assert.Equal((byte)2, Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Outline derived").ParagraphFormatting?.OutlineLevel);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.OutlineLevel == 1);
                Assert.Contains(index.ParagraphStyles, x => x.Formatting?.OutlineLevel == 9);
            }
            var projection = DxpDocToDocx.Project(binary);
            Assert.Empty(projection.Coverage.OmittedCharacters);
            using var package = WordprocessingDocument.Open(
                new MemoryStream(projection.DocxBytes), false);
            var main = package.MainDocumentPart!;
            var styles = main.StyleDefinitionsPart!.Styles!;
            Assert.Equal(0, styles.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "Outline base").StyleParagraphProperties!
                .OutlineLevel!.Val!.Value);
            Assert.Equal(2, styles.Elements<Style>().Single(x =>
                x.StyleName?.Val?.Value == "Outline derived").StyleParagraphProperties!
                .OutlineLevel!.Val!.Value);
            var paragraphs = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.Equal(1, paragraphs[0].ParagraphProperties!.OutlineLevel!.Val!.Value);
            Assert.Null(paragraphs[1].ParagraphProperties!.OutlineLevel);
            Assert.Equal(9, paragraphs[2].ParagraphProperties!.OutlineLevel!.Val!.Value);
            Assert.Null(main.HeaderParts.Single().Header!.Elements<Paragraph>()
                .Single().ParagraphProperties!.OutlineLevel);
            Assert.Equal(9, main.FooterParts.Single().Footer!.Elements<Paragraph>()
                .Single().ParagraphProperties!.OutlineLevel!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        Check(generated);
        using (var binary = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(binary))
            Assert.False(index.ApplyBreakingRules);
        Check(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(generated).DocxBytes, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-outline-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                Check(native);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void RevisionDocumentPropertyFieldRetainsMetadataAndAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            document.PackageProperties.Revision = "7";
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new SimpleField(
                new Run(new Text("7")))
            { Instruction = " DOCPROPERTY RevisionNumber " }));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new SimpleField(
                new Run(new Text("7")))
            { Instruction = " DOCPROPERTY RevisionNumber " }));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("Revision ")),
                new SimpleField(new Run(new Text("7")))
                { Instruction = " DOCPROPERTY RevisionNumber " }),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var doc = DxpDocExport.Export(source.ToArray());
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), doc, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(doc).DocxBytes, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-revision-property-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, false, false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                string? nativeRevision;
                using (var input = new MemoryStream(native))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    nativeRevision = DocSummaryInformation.ReadRevisionNumber(index.Structure);
                    Assert.NotNull(nativeRevision);
                    Assert.Equal(3, index.GetFieldMarks("Main").Count);
                    Assert.Equal(6, index.GetFieldMarks("Headers").Count);
                    Assert.Equal((byte)85, index.ReadStory("Main").FieldMarks[0].FieldType);
                    Assert.Equal((byte)85, index.HeaderStories[7].ReadIndexedContent()
                        .FieldMarks[0].FieldType);
                    Assert.Equal((byte)85, index.HeaderStories[9].ReadIndexedContent()
                        .FieldMarks[0].FieldType);
                }
                var projectedNative = DxpDocToDocx.Project(native).DocxBytes;
                using var nativePackage = WordprocessingDocument.Open(
                    new MemoryStream(projectedNative), false);
                Assert.Equal(nativeRevision, nativePackage.PackageProperties.Revision);
                Assert.Empty(new OpenXmlValidator().Validate(nativePackage));
                Assert.Equal(3, nativePackage.MainDocumentPart!.Document!
                    .Descendants<FieldChar>().Count());
                Assert.Equal(3, nativePackage.MainDocumentPart.HeaderParts.Single()
                    .Header!.Descendants<FieldChar>().Count());
                Assert.Equal(3, nativePackage.MainDocumentPart.FooterParts.Single()
                    .Footer!.Descendants<FieldChar>().Count());
                AssertWordFirstPageRenderClose(source.ToArray(), projectedNative, 0.04);
            }
            finally
            {
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
        foreach (var bytes in new[] { doc,
            DxpDocExport.Export(DxpDocToDocx.Project(doc).DocxBytes) })
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Equal("7", DocSummaryInformation.ReadRevisionNumber(index.Structure));
            Assert.Equal(3, index.GetFieldMarks("Main").Count);
            Assert.Equal(6, index.GetFieldMarks("Headers").Count);
            foreach (var story in new[] { index.ReadStory("Main"),
                index.HeaderStories[7].ReadIndexedContent(),
                index.HeaderStories[9].ReadIndexedContent() })
            {
                Assert.Equal(new byte[] { 0x13, 0x14, 0x15 },
                    story.FieldMarks.Select(x => x.Kind));
                Assert.Equal((byte)85, story.FieldMarks[0].FieldType);
            }
            var projected = DxpDocToDocx.Project(bytes).DocxBytes;
            using var package = WordprocessingDocument.Open(new MemoryStream(projected), false);
            Assert.Equal("7", package.PackageProperties.Revision);
            Assert.Empty(new OpenXmlValidator().Validate(package));
            foreach (var part in new OpenXmlPart[] { package.MainDocumentPart!,
                package.MainDocumentPart!.HeaderParts.Single(),
                package.MainDocumentPart!.FooterParts.Single() })
            {
                var root = part.RootElement!;
                Assert.Contains("DOCPROPERTY RevisionNumber",
                    Assert.Single(root.Descendants<FieldCode>()).Text);
                Assert.Equal(3, root.Descendants<FieldChar>().Count());
                Assert.Contains("7", root.InnerText);
            }
        }
    }

    [Theory]
    [InlineData("PAGE", "1", "33")]
    [InlineData("NUMPAGES", "3", "26")]
    [InlineData("NUMWORDS", "8", "27")]
    [InlineData("NUMCHARS", "41", "28")]
    [InlineData("FILENAME", "Report.docx", "29")]
    [InlineData("CREATEDATE", "2024-01-02", "21")]
    [InlineData("SAVEDATE", "2024-03-04", "22")]
    [InlineData("PRINTDATE", "2024-05-06", "23")]
    [InlineData("DATE", "2026-09-30", "31")]
    [InlineData("TIME", "12:34", "32")]
    public void DocRoundTripPreservesCommonDisplayFieldTypes(
        string instruction, string cachedResult, string expectedType)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new SimpleField(
                new Run(new Text(cachedResult)))
            { Instruction = " " + instruction + " " }));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new SimpleField(
                new Run(new Text(cachedResult)))
            { Instruction = " " + instruction + " " }));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("Before ")),
                new SimpleField(new Run(new Text(cachedResult)))
                { Instruction = " " + instruction + " " },
                new Run(new Text(" after"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(3, index.GetFieldMarks("Main").Count);
            Assert.Equal(6, index.GetFieldMarks("Headers").Count);
            foreach (var story in new[] { index.ReadStory("Main"),
                index.HeaderStories[7].ReadIndexedContent(),
                index.HeaderStories[9].ReadIndexedContent() })
            {
                Assert.Equal(new byte[] { 0x13, 0x14, 0x15 },
                    story.FieldMarks.Select(x => x.Kind));
                Assert.Equal(byte.Parse(expectedType), story.FieldMarks[0].FieldType);
                Assert.All(story.FieldMarks, x =>
                {
                    Assert.InRange(x.Cp, 0, checked((int)(story.Text.CpEnd -
                        story.Text.CpStart - 1)));
                    Assert.Equal(checked(story.Text.CpStart + (uint)x.Cp), x.SourceCp);
                    Assert.Equal(index.GetTextOffset(x.SourceCp!.Value),
                        x.SourceTextOffset);
                });
            }
            var fieldLocation = index.Structure.Root.Children.SelectMany(x => x.Children)
                .SelectMany(x => x.Children).SelectMany(x => x.Children)
                .Single(x => x.Name == "MainFields");
            var field = Assert.Single(Assert.Single(fieldLocation.Children).Children,
                x => x.Attributes["character"] == "0x13");
            Assert.Equal(expectedType, field.Children[1].Attributes["value"]);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var body = projected.MainDocumentPart!.Document!.Body!;
        Assert.Equal(" " + instruction + " ", Assert.Single(body.Descendants<FieldCode>()).Text);
        Assert.Contains(cachedResult, string.Concat(body.Descendants<Text>().Select(x => x.Text)));
        Assert.Equal(3, body.Descendants<FieldChar>().Count());
        foreach (var story in projected.MainDocumentPart.HeaderParts
            .Select(x => (DocumentFormat.OpenXml.OpenXmlElement)x.Header!)
            .Concat(projected.MainDocumentPart.FooterParts.Select(x =>
                (DocumentFormat.OpenXml.OpenXmlElement)x.Footer!)))
        {
            Assert.Equal(" " + instruction + " ",
                Assert.Single(story.Descendants<FieldCode>()).Text);
            Assert.Equal(3, story.Descendants<FieldChar>().Count());
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (instruction is "FILENAME" or "CREATEDATE" or "SAVEDATE" or "PRINTDATE")
        {
            var thirdBytes = DxpDocExport.Export(projection.DocxBytes);
            using var thirdStream = new MemoryStream(
                DxpDocToDocx.Project(thirdBytes).DocxBytes);
            using var third = WordprocessingDocument.Open(thirdStream, false);
            Assert.Equal(3, third.MainDocumentPart!.Document.Body!
                .Descendants<FieldCode>()
                .Concat(third.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Descendants<FieldCode>()))
                .Concat(third.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Descendants<FieldCode>()))
                .Count(x => x.Text.Contains(instruction, StringComparison.OrdinalIgnoreCase)));
            Assert.Empty(new OpenXmlValidator().Validate(third));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-display-field-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(1, (int)opened.Fields.Count);
            Assert.Contains(instruction, (string)opened.Fields[1].Code.Text,
                StringComparison.OrdinalIgnoreCase);
            if (instruction == "FILENAME") Assert.Equal(29, (int)opened.Fields[1].Type);
            if (instruction is "CREATEDATE" or "SAVEDATE" or "PRINTDATE")
                Assert.Equal(int.Parse(expectedType,
                    System.Globalization.CultureInfo.InvariantCulture),
                    (int)opened.Fields[1].Type);
            Assert.Equal(1, (int)opened.Sections[1].Headers[1].Range.Fields.Count);
            Assert.Equal(1, (int)opened.Sections[1].Footers[1].Range.Fields.Count);
            opened.Close(false);
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(),
                    File.ReadAllBytes(nativePath), 0.04);
                if (instruction is "FILENAME" or "CREATEDATE" or "SAVEDATE" or "PRINTDATE")
                {
                    AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
                    AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                        0.04, 1, ".docx");
                    AssertWordFirstPageRenderClose(source.ToArray(),
                        DxpDocExport.Export(projection.DocxBytes), 0.04);
                }
            }
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1" &&
                instruction is ("FILENAME" or "CREATEDATE" or "SAVEDATE" or "PRINTDATE"))
                AssertWordPageRenderClose(source.ToArray(), nativeProjection.DocxBytes,
                    0.04, 1, ".docx");
            using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
            Assert.Contains(instruction, Assert.Single(nativeDocx.MainDocumentPart!
                .Document!.Body!.Descendants<FieldCode>()).Text,
                StringComparison.OrdinalIgnoreCase);
            Assert.Equal(3, nativeDocx.MainDocumentPart.Document.Body
                .Descendants<FieldChar>().Count());
            foreach (var story in nativeDocx.MainDocumentPart.HeaderParts
                .Select(x => (DocumentFormat.OpenXml.OpenXmlElement)x.Header!)
                .Concat(nativeDocx.MainDocumentPart.FooterParts.Select(x =>
                    (DocumentFormat.OpenXml.OpenXmlElement)x.Footer!)))
            {
                Assert.Contains(instruction, Assert.Single(story.Descendants<FieldCode>())
                    .Text, StringComparison.OrdinalIgnoreCase);
                Assert.Equal(3, story.Descendants<FieldChar>().Count());
            }
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesComplexFieldRunsInBody()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("Before ")),
                new Run(new FieldChar { FieldCharType = FieldCharValues.Begin }),
                new Run(new FieldCode(" NUMPAGES ")
                { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new FieldChar { FieldCharType = FieldCharValues.Separate }),
                new Run(new RunProperties(new Bold()), new Text("3")),
                new Run(new FieldChar { FieldCharType = FieldCharValues.End }),
                new Run(new Text(" after")))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Equal(3, index.GetFieldMarks("Main").Count);
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var body = projected.MainDocumentPart!.Document!.Body!;
        Assert.Equal(" NUMPAGES ", Assert.Single(body.Descendants<FieldCode>()).Text);
        Assert.Equal(new[] { FieldCharValues.Begin, FieldCharValues.Separate,
            FieldCharValues.End }, body.Descendants<FieldChar>()
                .Select(x => x.FieldCharType!.Value));
        var result = Assert.Single(body.Descendants<Run>(), x =>
            x.Descendants<Text>().Any(y => y.Text == "3"));
        Assert.NotNull(result.RunProperties?.Bold);
        Assert.Equal("Before 3 after", string.Concat(body.Descendants<Text>().Select(x => x.Text)));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void DocRoundTripPreservesParagraphMarkFormattingInAllStories()
    {
        static Paragraph MarkedParagraph(string? text = null)
        {
            var paragraph = new Paragraph(new ParagraphProperties(new ParagraphMarkRunProperties(
                new Bold(), new Italic(), new Strike(),
                new Color { Val = "AA3366" }, new FontSize { Val = "28" },
                new Underline { Val = UnderlineValues.Single })));
            if (text != null) paragraph.AppendChild(new Run(new Text(text)));
            return paragraph;
        }

        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MarkedParagraph("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MarkedParagraph("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(MarkedParagraph(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var bodyMark = Assert.Single(index.CharacterFormatting, range =>
                range.CpStart == 0 && range.CpEnd == 1);
            Assert.True(bodyMark.Formatting.Bold);
            Assert.True(bodyMark.Formatting.Italic);
            Assert.True(bodyMark.Formatting.Strike);
            Assert.Equal((byte)1, bodyMark.Formatting.UnderlineCode);
            Assert.Equal((ushort)28, bodyMark.Formatting.SizeHalfPoints);
            var stories = new[] { index.ReadStory("Main") }
                .Concat(index.HeaderStories.Select(x => x.ReadIndexedContent()))
                .Where(x => x.Runs.Count > 0).ToArray();
            Assert.True(stories.Length >= 3);
            foreach (var story in stories)
            foreach (var run in story.Runs)
            {
                Assert.InRange(run.Start, 0, checked((int)(story.Text.CpEnd - story.Text.CpStart)));
                Assert.InRange(run.End, run.Start + 1,
                    checked((int)(story.Text.CpEnd - story.Text.CpStart)));
                Assert.Equal(story.Text.CpStart + (uint)run.Start, run.SourceCpStart);
                Assert.Equal(story.Text.CpStart + (uint)run.End, run.SourceCpEnd);
                Assert.Equal(index.GetTextOffset(run.SourceCpStart!.Value),
                    run.SourceTextOffsetStart);
                Assert.NotNull(run.SourceTextOffsetEnd);
            }
        }
        var projection = DxpDocToDocx.Project(bytes);
        foreach (var docxBytes in new[]
        {
            projection.DocxBytes,
            DxpDocToDocx.Project(DxpDocExport.Export(projection.DocxBytes)).DocxBytes
        })
        {
            using var projectedStream = new MemoryStream(docxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream, false);
            var mainOut = projected.MainDocumentPart!;
            foreach (var paragraph in new[]
            {
                Assert.Single(mainOut.Document!.Body!.Elements<Paragraph>()),
                Assert.Single(Assert.Single(mainOut.HeaderParts).Header!.Elements<Paragraph>()),
                Assert.Single(Assert.Single(mainOut.FooterParts).Footer!.Elements<Paragraph>())
            })
            {
                var mark = paragraph.ParagraphProperties?.ParagraphMarkRunProperties;
                Assert.NotNull(mark?.GetFirstChild<Bold>());
                Assert.NotNull(mark?.GetFirstChild<Italic>());
                Assert.NotNull(mark?.GetFirstChild<Strike>());
                Assert.Equal(UnderlineValues.Single,
                    mark?.GetFirstChild<Underline>()?.Val?.Value);
                Assert.Equal("AA3366", mark!.GetFirstChild<Color>()?.Val?.Value);
                Assert.Equal("28", mark.GetFirstChild<FontSize>()?.Val?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-mark-format-" + Guid.NewGuid().ToString("N") + ".doc");
            File.WriteAllBytes(path, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                dynamic mark = opened.Paragraphs.Item(1).Range.Characters.Last;
                Assert.Equal(14f, (float)mark.Font.Size);
                Assert.Equal(-1, (int)mark.Font.Bold);
                Assert.Equal(-1, (int)mark.Font.Italic);
                Assert.Equal(-1, (int)mark.Font.StrikeThrough);
                Assert.Equal(1, (int)mark.Font.Underline);
                dynamic section = opened.Sections.Item(1);
                dynamic headerMark = section.Headers.Item(1).Range.Paragraphs.Item(1)
                    .Range.Characters.Last;
                dynamic footerMark = section.Footers.Item(1).Range.Paragraphs.Item(1)
                    .Range.Characters.Last;
                Assert.Equal(14f, (float)headerMark.Font.Size);
                Assert.Equal(14f, (float)footerMark.Font.Size);
                foreach (dynamic storyMark in new[] { headerMark, footerMark })
                {
                    Assert.Equal(-1, (int)storyMark.Font.Bold);
                    Assert.Equal(-1, (int)storyMark.Font.Italic);
                    Assert.Equal(-1, (int)storyMark.Font.StrikeThrough);
                    Assert.Equal(1, (int)storyMark.Font.Underline);
                }
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
            }
        }
    }

    [Fact]
    public void StyledEmptyParagraphMarksKeepInheritedAndDirectFormattingInAllStories()
    {
        static Paragraph EmptyMark(bool? bold = null, string? size = null,
            string? color = null)
        {
            var properties = new ParagraphProperties(new ParagraphStyleId
                { Val = "MarkChild" });
            if (bold != null || size != null || color != null)
            {
                var mark = new ParagraphMarkRunProperties();
                if (bold != null) mark.AppendChild(new Bold { Val = bold.Value });
                if (color != null) mark.AppendChild(new Color { Val = color });
                if (size != null) mark.AppendChild(new FontSize { Val = size });
                properties.AppendChild(mark);
            }
            return new Paragraph(properties);
        }

        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Mark base" },
                    new StyleRunProperties(new Bold(), new FontSize { Val = "28" }))
                { Type = StyleValues.Paragraph, StyleId = "MarkBase" },
                new Style(new StyleName { Val = "Mark child" },
                    new BasedOn { Val = "MarkBase" },
                    new StyleRunProperties(new Italic()))
                { Type = StyleValues.Paragraph, StyleId = "MarkChild" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(EmptyMark());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(EmptyMark(color: "008000"));
            footer.Footer.Save();
            main.Document = new Document(new Body(EmptyMark(bold: false, size: "36"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        static void AssertProjectedMarks(byte[] binary)
        {
            var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
            using var stream = new MemoryStream(projectedBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            var body = Assert.Single(main.Document!.Body!.Elements<Paragraph>());
            var header = Assert.Single(Assert.Single(main.HeaderParts).Header!
                .Elements<Paragraph>());
            var footer = Assert.Single(Assert.Single(main.FooterParts).Footer!
                .Elements<Paragraph>());
            var markChild = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), style => style.StyleName?.Val?.Value == "Mark child");
            foreach (var paragraph in new[] { body, header, footer })
                Assert.Equal(markChild.StyleId?.Value, paragraph.ParagraphProperties?
                    .ParagraphStyleId?.Val?.Value);
            Assert.False(body.ParagraphProperties?.ParagraphMarkRunProperties?
                .GetFirstChild<Bold>()?.Val?.Value);
            Assert.Equal("36", body.ParagraphProperties?.ParagraphMarkRunProperties?
                .GetFirstChild<FontSize>()?.Val?.Value);
            Assert.Null(header.ParagraphProperties?.ParagraphMarkRunProperties);
            Assert.Equal("008000", footer.ParagraphProperties?.ParagraphMarkRunProperties?
                .GetFirstChild<Color>()?.Val?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }

        var firstDoc = DxpDocExport.Export(source.ToArray());
        AssertProjectedMarks(firstDoc);
        AssertProjectedMarks(DxpDocExport.Export(
            DxpDocToDocx.Project(firstDoc).DocxBytes));

        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-styled-marks-" + Guid.NewGuid().ToString("N") + ".doc");
            var sourcePath = Path.ChangeExtension(path, ".docx");
            var nativePath = Path.Combine(Path.GetTempPath(),
                "docxport-styled-marks-native-" + Guid.NewGuid().ToString("N") + ".doc");
            File.WriteAllBytes(path, firstDoc);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                dynamic bodyMark = opened.Paragraphs.Item(1).Range.Characters.Last;
                dynamic section = opened.Sections.Item(1);
                dynamic headerMark = section.Headers.Item(1).Range.Paragraphs.Item(1)
                    .Range.Characters.Last;
                dynamic footerMark = section.Footers.Item(1).Range.Paragraphs.Item(1)
                    .Range.Characters.Last;
                Assert.Equal(18f, (float)bodyMark.Font.Size);
                Assert.Equal(0, (int)bodyMark.Font.Bold);
                Assert.Equal(-1, (int)bodyMark.Font.Italic);
                Assert.Equal(14f, (float)headerMark.Font.Size);
                Assert.Equal(-1, (int)headerMark.Font.Bold);
                Assert.Equal(-1, (int)headerMark.Font.Italic);
                Assert.Equal(14f, (float)footerMark.Font.Size);
                Assert.Equal(-1, (int)footerMark.Font.Bold);
                Assert.Equal(-1, (int)footerMark.Font.Italic);
                Assert.Equal(0x008000, (int)footerMark.Font.Color);
                dynamic nativeSource = word.Documents.Open(sourcePath, false, false);
                try { nativeSource.SaveAs2(nativePath, 0); }
                finally { nativeSource.Close(false); }
                var native = File.ReadAllBytes(nativePath);
                AssertProjectedMarks(native);
                AssertProjectedMarks(DxpDocExport.Export(
                    DxpDocToDocx.Project(native).DocxBytes));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesMergedTablesInHeaderAndFooter()
    {
        static TableCell Cell(string text, bool restart = false,
            bool continuation = false, int span = 1)
        {
            var properties = new TableCellProperties();
            if (restart) properties.AppendChild(new HorizontalMerge
                { Val = MergedCellValues.Restart });
            if (continuation) properties.AppendChild(new HorizontalMerge
                { Val = MergedCellValues.Continue });
            if (span > 1) properties.AppendChild(new GridSpan { Val = span });
            return new TableCell(properties, new Paragraph(new Run(new Text(text))));
        }
        static Table TableWithMergedFirstCell(bool legacy) => new(
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            legacy
                ? new TableRow(Cell("Merged", restart: true),
                    Cell("", continuation: true), Cell("Right"))
                : new TableRow(Cell("Merged", span: 2), Cell("Right")),
            new TableRow(Cell("A"), Cell("B"), Cell("C")));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TableWithMergedFirstCell(true), new Paragraph());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TableWithMergedFirstCell(false), new Paragraph());
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(new Text("Body"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var headerTable = Assert.Single(projected.MainDocumentPart!.HeaderParts.Single()
            .Header!.Elements<Table>());
        var footerTable = Assert.Single(projected.MainDocumentPart.FooterParts.Single()
            .Footer!.Elements<Table>());
        foreach (var table in new[] { headerTable, footerTable })
        {
            Assert.Equal(2, table.Elements<TableRow>().First().Elements<TableCell>()
                .First().TableCellProperties?.GetFirstChild<GridSpan>()?.Val?.Value);
            Assert.Equal(new[] { "Merged", "Right", "A", "B", "C" },
                table.Descendants<TableCell>().Select(x => x.InnerText));
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                $"docxport-story-merge-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(path, binary);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(1, (int)opened.Sections(1).Headers(1).Range.Tables.Count);
                Assert.Equal(1, (int)opened.Sections(1).Footers(1).Range.Tables.Count);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
            }
        }
    }

