    [Fact]
    public void DocRoundTripPreservesHorizontalMergeContinuationText()
    {
        static TableCell Cell(string text, MergedCellValues? merge = null) => new(
            merge is MergedCellValues value
                ? new TableCellProperties(new HorizontalMerge { Val = value })
                : new TableCellProperties(),
            new Paragraph(new Run(new Text(text))));
        static Table MergeTable(string prefix) => new(
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(Cell(prefix + "START", MergedCellValues.Restart),
                Cell(prefix + "CONTINUATION", MergedCellValues.Continue)),
            new TableRow(Cell(prefix + "LEFT"), Cell(prefix + "RIGHT")));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MergeTable("HEADER-"), new Paragraph());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MergeTable("FOOTER-"), new Paragraph());
            footer.Footer.Save();
            main.Document = new Document(new Body(MergeTable(""),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var structureInput = new MemoryStream(binary))
        using (var structure = new DocStructureWalker().Accept(structureInput,
            new DocStructurePrintVisitor(TextWriter.Null)))
        {
            static IEnumerable<DocStructureNode> Descendants(DocStructureNode node) =>
                node.Children.SelectMany(child =>
                    new[] { child }.Concat(Descendants(child)));
            var modernRows = Descendants(structure.Root).Where(node =>
                node.Kind == "PrcData" && node.Name == "TableProperties").ToArray();
            Assert.Equal(6, modernRows.Length);
            Assert.Equal(3, modernRows.Count(row => Descendants(row).Any(node =>
                node.Kind == "Sprm" && node.Attributes["code"] == "0x5624")));
        }
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            foreach (var label in new[] { "CONTINUATION", "HEADER-CONTINUATION",
                "FOOTER-CONTINUATION" })
                Assert.Contains(label, string.Concat(index.Pieces.Select(piece => piece.Text)));
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        using (var projectedStream = new MemoryStream(projectedBytes))
        using (var projected = WordprocessingDocument.Open(projectedStream, false))
        {
            var row = Assert.Single(projected.MainDocumentPart!.Document.Body!
                .Elements<Table>()).Elements<TableRow>().First();
            var cells = row.Elements<TableCell>().ToArray();
            Assert.Equal(2, cells.Length);
            Assert.Equal(new[] { "START", "CONTINUATION" },
                cells.Select(cell => cell.InnerText));
            Assert.Equal(MergedCellValues.Restart,
                cells[0].TableCellProperties!.GetFirstChild<HorizontalMerge>()!.Val!.Value);
            Assert.Equal(MergedCellValues.Continue,
                cells[1].TableCellProperties!.GetFirstChild<HorizontalMerge>()!.Val!.Value);
            Assert.Contains("HEADER-CONTINUATION",
                projected.MainDocumentPart.HeaderParts.Single().Header!.InnerText);
            Assert.Contains("FOOTER-CONTINUATION",
                projected.MainDocumentPart.FooterParts.Single().Footer!.InnerText);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var repeated = DxpDocExport.Export(projectedBytes);
        using (var repeatedInput = new MemoryStream(repeated))
        using (var repeatedIndex = new DocTextIndexWalker().Index(repeatedInput))
            foreach (var label in new[] { "CONTINUATION", "HEADER-CONTINUATION",
                "FOOTER-CONTINUATION" })
                Assert.Contains(label, string.Concat(repeatedIndex.Pieces.Select(piece => piece.Text)));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.075);
            var docxPath = Path.Combine(Path.GetTempPath(),
                "docxport-hmerge-" + Guid.NewGuid().ToString("N") + ".docx");
            var docPath = Path.ChangeExtension(docxPath, ".doc");
            File.WriteAllBytes(docxPath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                opened = word.Documents.Open(docxPath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(docPath, FileFormat: 0);
                opened.Close(false);
                opened = null;
                var native = File.ReadAllBytes(docPath);
                using var nativeInput = new MemoryStream(native);
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                foreach (var label in new[] { "CONTINUATION", "HEADER-CONTINUATION",
                    "FOOTER-CONTINUATION" })
                    Assert.Contains(label,
                        string.Concat(nativeIndex.Pieces.Select(piece => piece.Text)));
                Assert.Equal(3, nativeIndex.ParagraphStyles.Count(range =>
                    range.Formatting?.TableCellHorizontalMerges is { } merges &&
                    merges.SequenceEqual(new byte?[] { 2, 1 })));
                var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;

                using var nativeStream = new MemoryStream(nativeProjection);
                using var nativeDocx = WordprocessingDocument.Open(nativeStream, false);
                Assert.Contains("CONTINUATION",
                    nativeDocx.MainDocumentPart!.Document.Body!.InnerText);
                Assert.Contains("HEADER-CONTINUATION",
                    nativeDocx.MainDocumentPart.HeaderParts.Single().Header!.InnerText);
                Assert.Contains("FOOTER-CONTINUATION",
                    nativeDocx.MainDocumentPart.FooterParts.Single().Footer!.InnerText);
                Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
                AssertWordPageRenderClose(source.ToArray(), nativeProjection,
                    0.04, 1, ".docx");
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(docxPath);
                if (File.Exists(docPath)) File.Delete(docPath);
            }
        }
    }

