                            new TableCellRightMargin { Width = 700,
                                Type = TableWidthValues.Dxa },
                            new StartMargin { Width = "200",
                                Type = TableWidthUnitValues.Dxa },
                            new EndMargin { Width = "400",
                                Type = TableWidthUnitValues.Dxa })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new TableCellMargin(
                        new LeftMargin { Width = "100", Type = TableWidthUnitValues.Dxa },
                        new RightMargin { Width = "700", Type = TableWidthUnitValues.Dxa },
                        new StartMargin { Width = "300", Type = TableWidthUnitValues.Dxa },
                        new EndMargin { Width = "500", Type = TableWidthUnitValues.Dxa }),
                        new TableCellBorders(
                            new LeftBorder { Val = BorderValues.Single, Size = 8,
                                Color = "CC0000" },
                            new RightBorder { Val = BorderValues.Single, Size = 8,
                                Color = "CCCC00" },
                            new StartBorder { Val = BorderValues.Double, Size = 8,
                                Color = "008800" },
                            new EndBorder { Val = BorderValues.Double, Size = 8,
                                Color = "0000CC" })),
                        new Paragraph(new Run(new Text("First")))),
                    new TableCell(new Paragraph(new Run(new Text("Second")))))),
                new SectionProperties(new PageSize { Width = 12240, Height = 15840 },
                    new PageMargin { Left = 1440, Right = 1440, Top = 1440,
                        Bottom = 1440, Header = 720, Footer = 720 })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var row = Assert.Single(index.ParagraphStyles,
                x => x.Formatting?.TableTerminator == true).Formatting!;
            Assert.True(row.TableRightToLeft);
            Assert.Equal(new DocCellMargins(Left: 200, Right: 400),
                row.TableDefaultCellMargins);
            Assert.Equal(new DocCellMargins(Left: 300, Right: 500),
                row.TableCellMargins?[0]);
            Assert.Equal(0x008800u, row.TableCellBorders?[0]?.Left?.ColorRgb);
            Assert.Equal(0xCC0000u, row.TableCellBorders?[0]?.Right?.ColorRgb);
            if (!styled)
                Assert.Equal(0xAA0000u, row.TableCellBorders?[1]?.Right?.ColorRgb);
        }
        var projection = DxpDocToDocx.Project(binary);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var table = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        Assert.NotNull(table.TableProperties?.GetFirstChild<BiDiVisual>());
        Assert.Equal((short)200, table.TableProperties?.TableCellMarginDefault?
            .GetFirstChild<TableCellLeftMargin>()?.Width?.Value);
        Assert.Equal((short)400, table.TableProperties?.TableCellMarginDefault?
            .GetFirstChild<TableCellRightMargin>()?.Width?.Value);
        Assert.Equal("300", table.Descendants<TableCell>().First()
            .TableCellProperties?.TableCellMargin?.LeftMargin?.Width?.Value);
        Assert.Equal("500", table.Descendants<TableCell>().First()
            .TableCellProperties?.TableCellMargin?.RightMargin?.Width?.Value);
        Assert.Equal("008800", table.Descendants<TableCell>().First()
