        Assert.Equal("0000CC", table.Descendants<TableCell>().First()
            .TableCellProperties?.TableCellBorders?.RightBorder?.Color?.Value);
        if (!styled)
            Assert.Equal("0000AA", table.Descendants<TableCell>().Last()
                .TableCellProperties?.TableCellBorders?.RightBorder?.Color?.Value);
        Assert.Equal(new[] { "First", "Second" }, table.Descendants<TableCell>()
            .Select(x => x.InnerText));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        using (var thirdStream = new MemoryStream(DxpDocToDocx.Project(
            DxpDocExport.Export(projection.DocxBytes)).DocxBytes))
        using (var third = WordprocessingDocument.Open(thirdStream, false))
        {
            var thirdTable = Assert.Single(third.MainDocumentPart!.Document!.Body!
                .Elements<Table>());
            Assert.Equal((short)200, thirdTable.TableProperties?
                .TableCellMarginDefault?.GetFirstChild<TableCellLeftMargin>()?
                .Width?.Value);
            Assert.Equal((short)400, thirdTable.TableProperties?
                .TableCellMarginDefault?.GetFirstChild<TableCellRightMargin>()?
                .Width?.Value);
            Assert.Equal("300", thirdTable.Descendants<TableCell>().First()
                .TableCellProperties?.TableCellMargin?.LeftMargin?.Width?.Value);
            Assert.Equal("500", thirdTable.Descendants<TableCell>().First()
                .TableCellProperties?.TableCellMargin?.RightMargin?.Width?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(third));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-rtl-table-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var wordSavedPath = Path.ChangeExtension(sourcePath, ".word-saved.docx");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
