            opened.SaveAs2(wordSavedPath, 16);
            opened.Close(false);
            opened = null;
            using (var savedStream = File.OpenRead(wordSavedPath))
            using (var saved = WordprocessingDocument.Open(savedStream, false))
            {
                var savedTable = Assert.Single(saved.MainDocumentPart!.Document!.Body!
                    .Elements<Table>());
                Assert.NotNull(savedTable.TableProperties?.GetFirstChild<BiDiVisual>());
                Assert.Equal(new[] { "2000", "2000" }, savedTable.TableGrid!
                    .Elements<GridColumn>().Select(x => x.Width?.Value));
                Assert.Equal(new[] { "2000", "2000" }, savedTable.Descendants<TableCell>()
                    .Select(x => x.TableCellProperties?.TableCellWidth?.Width?.Value));
                var savedLeft = savedTable.TableProperties?.TableCellMarginDefault?
                    .GetFirstChild<TableCellLeftMargin>()?.Width?.Value ??
                    saved.MainDocumentPart.StyleDefinitionsPart?.Styles?
                        .Elements<Style>().FirstOrDefault(x => x.StyleId?.Value ==
                            savedTable.TableProperties?.TableStyle?.Val?.Value)?
