    [Fact]
    public void ConflictingLogicalBordersKeepVisibleEdgesInAllStories()
    {
        static Table StoryTable(string text) => new(
            new TableProperties(new BiDiVisual(),
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableBorders(
                    new LeftBorder { Val = BorderValues.Single, Size = 8,
                        Color = "AA0000" },
                    new RightBorder { Val = BorderValues.Single, Size = 8,
                        Color = "AAAA00" },
                    new StartBorder { Val = BorderValues.Double, Size = 8,
                        Color = "00AA00" },
                    new EndBorder { Val = BorderValues.Double, Size = 8,
                        Color = "0000AA" })),
            new TableGrid(new GridColumn { Width = "2000" },
                new GridColumn { Width = "2000" }),
            new TableRow(
                new TableCell(new TableCellProperties(new TableCellBorders(
                    new LeftBorder { Val = BorderValues.Single, Size = 8,
                        Color = "CC0000" },
                    new RightBorder { Val = BorderValues.Single, Size = 8,
                        Color = "CCCC00" },
                    new StartBorder { Val = BorderValues.Double, Size = 8,
                        Color = "008800" },
                    new EndBorder { Val = BorderValues.Double, Size = 8,
                        Color = "0000CC" })),
                    new Paragraph(new Run(new Text(text + " first")))),
                new TableCell(new Paragraph(new Run(new Text(text + " second"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generatedDoc = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(generatedDoc))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(3, rows.Length);
            Assert.All(rows, row => Assert.Equal((short)0,
                row.Formatting!.TableCellEdges![0]));
        }
        var projected = DxpDocToDocx.Project(generatedDoc).DocxBytes;
        var third = DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes;
        var projections = new List<byte[]> { projected, third };
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generatedDoc, 0.004);
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-logical-story-borders-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                var nativeDoc = File.ReadAllBytes(nativePath);
                AssertWordFirstPageRenderClose(source.ToArray(), nativeDoc, 0.05);
                projections.Add(DxpDocToDocx.Project(nativeDoc).DocxBytes);
            }
            finally { Directory.Delete(directory, true); }
        }
        foreach (var bytes in projections)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var table = Assert.Single(story.Elements<Table>());
                Assert.NotNull(table.TableProperties?.GetFirstChild<BiDiVisual>());
                var cells = Assert.Single(table.Elements<TableRow>())
                    .Elements<TableCell>().ToArray();
                Assert.Equal(2, cells.Length);
                Assert.Equal("008800", cells[0].TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Color?.Value);
                Assert.Equal(BorderValues.Double, cells[0].TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Val?.Value);
                Assert.Equal((uint)8, cells[0].TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Size?.Value);
                Assert.Equal("0000CC", cells[0].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Color?.Value);
                Assert.Equal(BorderValues.Double, cells[0].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Val?.Value);
                Assert.Equal((uint)8, cells[0].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Size?.Value);
                Assert.Equal("0000AA", cells[1].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Color?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
    }

    [Fact]
    public void ConditionalLogicalBordersWinInRightToLeftStories()
    {
        static Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "LogicalFirstRow" },
                new BiDiVisual(), new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0020", FirstRow = true }),
            new TableGrid(new GridColumn { Width = "2400" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName
            { Val = "Logical first row" },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellBorders(
                            new LeftBorder { Val = BorderValues.Single, Size = 8,
                                Color = "CC0000" },
                            new RightBorder { Val = BorderValues.Single, Size = 8,
                                Color = "CCCC00" },
                            new StartBorder { Val = BorderValues.Double, Size = 8,
                                Color = "008800" },
                            new EndBorder { Val = BorderValues.Double, Size = 8,
                                Color = "0000CC" })))
                { Type = TableStyleOverrideValues.FirstRow })
            { Type = StyleValues.Table, StyleId = "LogicalFirstRow" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        static void AssertEffectiveEdges(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var cell = Assert.Single(story.Descendants<TableCell>());
                Assert.Equal("008800", cell.TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Color?.Value);
                Assert.Equal("0000CC", cell.TableCellProperties?
                    .TableCellBorders?.RightBorder?.Color?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var third = DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes;
        foreach (var bytes in new[] { projected, third })
            AssertEffectiveEdges(bytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-logical-borders-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertEffectiveEdges(nativeProjected);
            AssertEffectiveEdges(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData("top")]
    [InlineData("bottom")]
    [InlineData("left")]
    [InlineData("right")]
    public void RowColumnBordersAcrossTwoByTwoStoriesMatchWord(string edge)
    {
        static Table StoryTable(string label) => new(
            new TableProperties(new TableStyle { Val = "RowColumnEdges" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "4000" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0060", FirstRow = true, FirstColumn = true }),
            new TableGrid(new GridColumn { Width = "2000" },
                new GridColumn { Width = "2000" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " A")))),
                new TableCell(new Paragraph(new Run(new Text(label + " B"))))),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " C")))),
                new TableCell(new Paragraph(new Run(new Text(label + " D"))))));
        TableStyleProperties Rule(TableStyleOverrideValues kind, string color)
        {
            BorderType Border() => edge switch
            {
                "top" => new TopBorder { Val = BorderValues.Single, Size = 16, Color = color },
                "bottom" => new BottomBorder { Val = BorderValues.Single, Size = 16, Color = color },
                "left" => new LeftBorder { Val = BorderValues.Single, Size = 16, Color = color },
                _ => new RightBorder { Val = BorderValues.Single, Size = 16, Color = color }
            };
            return new TableStyleProperties(
                new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(Border()))) { Type = kind };
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Row column edges" },
                Rule(TableStyleOverrideValues.FirstRow, "CC0000"),
                Rule(TableStyleOverrideValues.FirstColumn, "0000CC"))
                { Type = StyleValues.Table, StyleId = "RowColumnEdges" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var repeated = DxpDocExport.Export(projected);
        foreach (var bytes in new[] { generated, repeated })
        {
            using var index = new DocTextIndexWalker().Index(new MemoryStream(bytes));
            var style = Assert.Single(index.StyleDefinitions,
                definition => definition.Name == "Row column edges");
            Assert.Contains((ushort)0x0001, style.ConditionalTableBorders!.Keys);
            Assert.Contains((ushort)0x0004, style.ConditionalTableBorders.Keys);
        }
        foreach (var bytes in new[] { projected, DxpDocToDocx.Project(repeated).DocxBytes })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var tables = main.Document.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(part => part.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(part => part.Footer!.Elements<Table>()))
                .ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                Assert.Equal(2, table.Elements<TableRow>().Count());
                Assert.All(table.Elements<TableRow>(), row =>
                    Assert.Equal(2, row.Elements<TableCell>().Count()));
            });
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-2x2-border-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.Combine(Path.GetTempPath(),
            $"docxport-2x2-native-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        byte[]? nativeDoc = null;
        dynamic? opened = null;
        try
        {
            int[] Colors(dynamic document)
            {
                var result = new List<int>();
                foreach (dynamic table in new[] { document.Tables.Item(1),
                    document.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    document.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1) })
                    for (var row = 1; row <= 2; row++)
                        for (var column = 1; column <= 2; column++)
                            result.Add((int)table.Cell(row, column).Borders.Item(
                                edge == "top" ? -1 : edge == "bottom" ? -3 :
                                edge == "left" ? -2 : -4).Color);
                return result.ToArray();
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var expected = Colors(opened);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            nativeDoc = File.ReadAllBytes(nativePath);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
            opened.Close(false);
            opened = null;
            opened = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
        if (edge == "left")
            AssertWordFirstPageRenderClose(source.ToArray(), nativeDoc!, 0.001);
        AssertWordFirstPageRenderClose(source.ToArray(), generated,
            edge == "left" ? 0.001 : 0.04);
        AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        AssertWordFirstPageRenderClose(source.ToArray(), repeated, 0.04);
    }
    [Theory]
    [InlineData(false, false, false)]
    [InlineData(true, false, false)]
    [InlineData(true, false, true)]
    [InlineData(true, true, false)]
    [InlineData(true, true, true)]
    [InlineData(true, false, false, true)]
    [InlineData(true, false, true, true)]
    [InlineData(true, false, false, false, true)]
    [InlineData(true, false, true, false, true)]
    public void FirstRowBorderWinsOverOverlappingSingleCellRule(bool firstColumn, bool bottom, bool reverseRules, bool left = false, bool right = false)
    {
        Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "RowBorderPriority" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = firstColumn ? "0060" : "00A0", FirstRow = true,
                    LastRow = !firstColumn, FirstColumn = firstColumn }),
            new TableGrid(new GridColumn { Width = "4000" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            TableStyleProperties RowStyle(TableStyleOverrideValues kind,
                string color) => new(new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(right
                        ? new RightBorder { Val = BorderValues.Single, Size = 16, Color = color }
                        : left ? new LeftBorder { Val = BorderValues.Single, Size = 16, Color = color }
                        : bottom ? new BottomBorder { Val = BorderValues.Single, Size = 16, Color = color }
                        : new TopBorder { Val = BorderValues.Single, Size = 16, Color = color })))
                { Type = kind };
            var firstRule = RowStyle(TableStyleOverrideValues.FirstRow, "CC0000");
            var otherRule = RowStyle(firstColumn ? TableStyleOverrideValues.FirstColumn :
                TableStyleOverrideValues.LastRow, "0000CC");
            styles.Styles = new Styles(new Style(new StyleName
                { Val = "Row border priority" },
                reverseRules ? otherRule : firstRule,
                reverseRules ? firstRule : otherRule)
                { Type = StyleValues.Table, StyleId = "RowBorderPriority" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var rewritten = DxpDocExport.Export(projected);
        foreach (var bytes in new[] { generated, rewritten })
        {
            using var index = new DocTextIndexWalker().Index(new MemoryStream(bytes));
            var style = Assert.Single(index.StyleDefinitions,
                definition => definition.Name == "Row border priority");
            var first = style.ConditionalTableBorders?[0x0001];
            var other = style.ConditionalTableBorders?[firstColumn ? (ushort)0x0004 : (ushort)0x0002];
            Assert.NotNull(right ? first?.Right : left ? first?.Left : bottom ? first?.Bottom : first?.Top);
            Assert.NotNull(right ? other?.Right : left ? other?.Left : bottom ? other?.Bottom : other?.Top);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-row-border-source-{Guid.NewGuid():N}.docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
            var nativePath = Path.Combine(Path.GetTempPath(),
                $"docxport-row-border-native-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, generated);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                var sourceColor = (int)opened.Tables.Item(1).Cell(1, 1)
                    .Borders.Item(right ? -4 : left ? -2 : bottom ? -3 : -1).Color;
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                var generatedColor = (int)opened.Tables.Item(1).Cell(1, 1)
                    .Borders.Item(right ? -4 : left ? -2 : bottom ? -3 : -1).Color;
                Assert.Equal(sourceColor, generatedColor);
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                Assert.Equal(3, nativeProjection.MainDocumentPart!.Document.Body!
                    .Elements<Table>().Concat(nativeProjection.MainDocumentPart.HeaderParts
                        .SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeProjection.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>()))
                    .Count(x => x.Descendants<TableCell>().Single()
                        .TableCellProperties?.TableCellBorders is { } borders &&
                        (right ? borders.RightBorder?.Color?.Value : left ?
                            borders.LeftBorder?.Color?.Value : bottom ?
                            borders.BottomBorder?.Color?.Value : borders.TopBorder?.Color?.Value) == "CC0000"));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
        using (var stream = new MemoryStream(projected))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            var tables = main.Document.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()));
            Assert.Equal(3, tables.Count());
            Assert.All(tables, table => Assert.Equal("CC0000",
                Assert.Single(table.Descendants<TableCell>()).TableCellProperties?
                    .TableCellBorders is { } borders ?
                        (right ? borders.RightBorder?.Color?.Value : left ?
                            borders.LeftBorder?.Color?.Value : bottom ?
                            borders.BottomBorder?.Color?.Value : borders.TopBorder?.Color?.Value) : null));
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        using (var stream = new MemoryStream(DxpDocToDocx.Project(rewritten).DocxBytes))
        using (var document = WordprocessingDocument.Open(stream, false))
            Assert.Equal(3, document.MainDocumentPart!.Document.Body!
                .Elements<Table>().Concat(document.MainDocumentPart.HeaderParts
                    .SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(document.MainDocumentPart.FooterParts
                    .SelectMany(x => x.Footer!.Elements<Table>()))
                .Count(x => x.Descendants<TableCell>().Single()
                    .TableCellProperties?.TableCellBorders is { } borders &&
                        (right ? borders.RightBorder?.Color?.Value : left ?
                            borders.LeftBorder?.Color?.Value : bottom ?
                            borders.BottomBorder?.Color?.Value : borders.TopBorder?.Color?.Value) == "CC0000"));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), rewritten, 0.04);
        }
    }

    [Theory]
    [InlineData("top", false)]
    [InlineData("bottom", false)]
    [InlineData("left", false)]
    [InlineData("right", false)]
    [InlineData("top", true)]
    [InlineData("bottom", true)]
    [InlineData("left", true)]
    [InlineData("right", true)]
    public void OneColumnFirstLastColumnBordersKeepWordPrecedenceInAllStories(string edge, bool reverseRules)
    {
        static Table StoryTable(string label) => new(
            new TableProperties(new TableStyle { Val = "BothColumnEdges" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "2400" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0180", FirstColumn = true, LastColumn = true }),
            new TableGrid(new GridColumn { Width = "2400" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " 1"))))),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " 2"))))));
        TableStyleProperties Rule(TableStyleOverrideValues kind,
            string color) => new(new TableStyleConditionalFormattingTableCellProperties(
                new TableCellBorders(edge switch
                {
                    "bottom" => new BottomBorder { Val = BorderValues.Single, Size = 16, Color = color },
                    "left" => new LeftBorder { Val = BorderValues.Single, Size = 16, Color = color },
                    "right" => new RightBorder { Val = BorderValues.Single, Size = 16, Color = color },
                    _ => new TopBorder { Val = BorderValues.Single, Size = 16, Color = color }
                })))
            { Type = kind };
        DocParagraphBorder? Edge(DocConditionalTableBorders borders) => edge switch
        {
            "bottom" => borders.Bottom,
            "left" => borders.Left,
            "right" => borders.Right,
            _ => borders.Top
        };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var first = Rule(TableStyleOverrideValues.FirstColumn, "CC0000");
            var last = Rule(TableStyleOverrideValues.LastColumn, "0000CC");
            styles.Styles = new Styles(new Style(new StyleName { Val = "Both column edges" },
                reverseRules ? first : last, reverseRules ? last : first)
            { Type = StyleValues.Table, StyleId = "BothColumnEdges" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var thirdDoc = DxpDocExport.Export(projected);
        foreach (var bytes in new[] { generated, thirdDoc })
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Both column edges");
            Assert.NotNull(Edge(style.ConditionalTableBorders![0x0004]));
            Assert.NotNull(Edge(style.ConditionalTableBorders[0x0008]));
        }
        using (var stream = new MemoryStream(projected))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            var tables = main.Document.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()))
                .ToArray();
            Assert.Equal(3, tables.Length);
            if (edge == "left")
                Assert.All(tables, table =>
                    Assert.Equal(0, table.TableProperties?.TableIndentation?.Width?.Value));
            Assert.All(tables, table =>
            {
                var rows = table.Elements<TableRow>().ToArray();
                if (edge is "top" or "bottom")
                {
                    var boundary = rows[edge == "bottom" ? 1 : 0].Elements<TableCell>().Single().TableCellProperties?.TableCellBorders;
                    var internalEdge = rows[edge == "bottom" ? 0 : 1].Elements<TableCell>().Single().TableCellProperties?.TableCellBorders;
                    Assert.Equal("CC0000", edge == "bottom" ? boundary?.BottomBorder?.Color?.Value : boundary?.TopBorder?.Color?.Value);
                    Assert.Null(edge == "bottom" ? internalEdge?.BottomBorder : internalEdge?.TopBorder);
                }
                else
                    Assert.All(rows, row => Assert.Equal("CC0000", edge == "left" ? row.Elements<TableCell>().Single().TableCellProperties?.TableCellBorders?.LeftBorder?.Color?.Value : row.Elements<TableCell>().Single().TableCellProperties?.TableCellBorders?.RightBorder?.Color?.Value));
            });
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-one-column-borders-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            int[] Colors(dynamic document)
            {
                var result = new List<int>();
                foreach (dynamic table in new[] { document.Tables.Item(1),
                    document.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                    document.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1) })
                    for (var row = 1; row <= 2; row++)
                        result.Add((int)table.Cell(row, 1).Borders.Item(edge == "left" ? -2 : -4).Color);
                return result.ToArray();
            }
            var expectedColors = edge is "left" or "right" ? Colors(opened) : null;
            try { opened.SaveAs2(nativePath, 0); }
            finally { opened.Close(false); }
            if (expectedColors != null)
            {
                foreach (var path in new[] { nativePath, generatedPath })
                {
                    opened = word.Documents.Open(path, ReadOnly: true, AddToRecentFiles: false);
                    try { Assert.Equal(expectedColors, Colors(opened)); }
                    finally { opened.Close(false); }
                }
            }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            if (edge == "left")
            {
                using var projectedStream = new MemoryStream(nativeProjected);
                using var nativePackage = WordprocessingDocument.Open(projectedStream, false);
                var nativeMain = nativePackage.MainDocumentPart!;
                var nativeTables = nativeMain.Document.Body!.Elements<Table>()
                    .Concat(nativeMain.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeMain.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()));
                Assert.All(nativeTables, table =>
                    Assert.Equal(0, table.TableProperties?.TableIndentation?.Width?.Value));
                Assert.Empty(new OpenXmlValidator().Validate(nativePackage));
            }
            var nativeThirdDoc = DxpDocExport.Export(nativeProjected);
            AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
            AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), thirdDoc, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(), nativeThirdDoc, 0.04);
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
            File.Delete(generatedPath);
        }
    }
    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void ColumnHorizontalBorderStaysAtTableEdgeInAllStories(bool lastColumn, bool bottom)
    {
        Table StoryTable(string label) => new(
            new TableProperties(new TableStyle { Val = "ColumnTopBoundary" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "4800" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = lastColumn ? "0100" : "0080",
                    FirstColumn = !lastColumn, LastColumn = lastColumn }),
            new TableGrid(new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " 1")))),
                new TableCell(new Paragraph(new Run(new Text(label + " 2"))))),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " 3")))),
                new TableCell(new Paragraph(new Run(new Text(label + " 4"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Column top boundary" },
                new TableStyleProperties(new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(bottom
                        ? new BottomBorder { Val = BorderValues.Single, Size = 16, Color = "CC0000" }
                        : new TopBorder { Val = BorderValues.Single, Size = 16, Color = "CC0000" })))
                { Type = lastColumn ? TableStyleOverrideValues.LastColumn :
                    TableStyleOverrideValues.FirstColumn })
            { Type = StyleValues.Table, StyleId = "ColumnTopBoundary" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var thirdDoc = DxpDocExport.Export(projected);
        foreach (var bytes in new[] { generated, thirdDoc })
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Column top boundary");
            var border = style.ConditionalTableBorders?[lastColumn ? (ushort)0x0008 : (ushort)0x0004];
            Assert.NotNull(bottom ? border?.Bottom : border?.Top);
        }
        using (var stream = new MemoryStream(projected))
        using (var document = WordprocessingDocument.Open(stream, false))
        {
            var main = document.MainDocumentPart!;
            var tables = main.Document.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()));
            Assert.Equal(3, tables.Count());
            Assert.All(tables, table =>
            {
                var row = table.Elements<TableRow>().ElementAt(bottom ? 0 : 1);
                var borders = row.Elements<TableCell>().ElementAt(lastColumn ? 1 : 0)
                    .TableCellProperties?.TableCellBorders;
                if (bottom) Assert.Null(borders?.BottomBorder);
                else Assert.Null(borders?.TopBorder);
            });
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-column-top-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            try { opened.SaveAs2(nativePath, 0); }
            finally { opened.Close(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            using (var stream = new MemoryStream(nativeProjected))
            using (var document = WordprocessingDocument.Open(stream, false))
                Assert.Empty(new OpenXmlValidator().Validate(document));
            var nativeThirdDoc = DxpDocExport.Export(nativeProjected);
            AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
            AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source.ToArray(), thirdDoc, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(), nativeThirdDoc, 0.04);
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
    }
    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void LastRowBorderWinsOverFirstColumnInBottomLeftCells(bool corner, bool bottom)
    {
        static Paragraph CellParagraph(string text) => new(
            new ParagraphProperties(new SpacingBetweenLines
                { Before = "0", After = "0" }),
            new Run(new Text(text)));
        Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "ColumnRowPriority" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "4800" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = corner ? "01C0" : "00C0",
                    FirstColumn = true, LastRow = true, LastColumn = corner }),
            new TableGrid(new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" }),
            new TableRow(
                new TableCell(CellParagraph(text + " 1")),
                new TableCell(CellParagraph(text + " 2"))),
            new TableRow(
                new TableCell(CellParagraph(text + " 3")),
                new TableCell(CellParagraph(text + " 4"))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            TableStyleProperties Rule(TableStyleOverrideValues kind,
                string color) => new(new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(bottom
                        ? new BottomBorder { Val = BorderValues.Single, Size = 16, Color = color }
                        : new TopBorder { Val = BorderValues.Single, Size = 16, Color = color })))
                { Type = kind };
            var style = new Style(new StyleName { Val = "Column row priority" },
                Rule(TableStyleOverrideValues.LastRow, "0000CC"),
                Rule(TableStyleOverrideValues.FirstColumn, "CC0000"))
                { Type = StyleValues.Table, StyleId = "ColumnRowPriority" };
            if (corner)
            {
                style.Append(Rule(TableStyleOverrideValues.LastColumn, "CC0000"));
                style.Append(Rule(TableStyleOverrideValues.SouthEastCell, "00AA00"));
            }
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertReusableBorders(generated);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        void AssertReusableBorders(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions, x =>
                x.Name == "Column row priority");
            var rules = style.ConditionalTableBorders!;
            Assert.Equal(0x00CC0000u, bottom
                ? rules[0x0002].Bottom?.ColorRgb : rules[0x0002].Top?.ColorRgb);
            Assert.Contains((ushort)0x0004, rules.Keys);
            if (corner) Assert.Contains((ushort)0x0400, rules.Keys);
        }
        byte[]? nativeBytes = null;
        byte[]? nativeProjectedBytes = null;
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-column-border-source-{Guid.NewGuid():N}.docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
            var nativePath = Path.Combine(Path.GetTempPath(),
                $"docxport-column-border-native-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, generated);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                var sourceColor = (int)opened.Tables.Item(1).Cell(2, 1)
                    .Borders.Item(bottom ? -3 : -1).Color;
                if (!bottom) Assert.Equal(0xCC0000, sourceColor & 0xFFFFFF);
                if (corner && !bottom)
                    foreach (dynamic table in new dynamic[]
                    {
                        opened.Tables.Item(1),
                        opened.Sections(1).Headers(1).Range.Tables.Item(1),
                        opened.Sections(1).Footers(1).Range.Tables.Item(1)
                    })
                    {
                        Assert.Equal(0x00AA00, (int)table.Cell(2, 2)
                            .Borders.Item(bottom ? -3 : -1).Color & 0xFFFFFF);
                        Assert.Equal(0x0000CC, (int)table.Cell(1, 2)
                            .Borders.Item(bottom ? -3 : -1).Color & 0xFFFFFF);
                    }
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                var generatedColor = (int)opened.Tables.Item(1).Cell(2, 1)
                    .Borders.Item(bottom ? -3 : -1).Color;
                Assert.Equal(sourceColor, generatedColor);
                if (corner && !bottom)
                {
                    foreach (dynamic table in new dynamic[]
                    {
                        opened.Tables.Item(1),
                        opened.Sections(1).Headers(1).Range.Tables.Item(1),
                        opened.Sections(1).Footers(1).Range.Tables.Item(1)
                    })
                    {
                        Assert.Equal(0x00AA00, (int)table.Cell(2, 2)
                            .Borders.Item(bottom ? -3 : -1).Color & 0xFFFFFF);
                        Assert.Equal(0x0000CC, (int)table.Cell(1, 2)
                            .Borders.Item(bottom ? -3 : -1).Color & 0xFFFFFF);
                    }
                }
                nativeBytes = File.ReadAllBytes(nativePath);
                using var nativeInput = new MemoryStream(nativeBytes);
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                nativeProjectedBytes = new DocToDocxProjector().Project(nativeIndex).DocxBytes;
                using var nativeProjectionStream = new MemoryStream(nativeProjectedBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                Assert.Equal(3, nativeProjection.MainDocumentPart!.Document.Body!
                    .Elements<Table>().Concat(nativeProjection.MainDocumentPart.HeaderParts
                        .SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeProjection.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>()))
                    .Count(x => x.Elements<TableRow>().Last().Elements<TableCell>().First()
                        .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value == "0000CC"));
                if (corner)
                    Assert.Equal(3, nativeProjection.MainDocumentPart.Document.Body!
                        .Elements<Table>().Concat(nativeProjection.MainDocumentPart.HeaderParts
                            .SelectMany(x => x.Header!.Elements<Table>()))
                        .Concat(nativeProjection.MainDocumentPart.FooterParts
                            .SelectMany(x => x.Footer!.Elements<Table>()))
                        .Count(x => x.Elements<TableRow>().Last().Elements<TableCell>().Last()
                            .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value == "00AA00"));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
        if (corner && nativeBytes != null && nativeProjectedBytes != null)
        {
            AssertWordFirstPageRenderClose(source.ToArray(), nativeBytes, 0.04);
            AssertWordPageRenderClose(source.ToArray(), nativeProjectedBytes,
                0.04, 1, ".docx");
        }
        using var stream = new MemoryStream(projected);
        using var result = WordprocessingDocument.Open(stream, false);
        var resultMain = result.MainDocumentPart!;
        var tables = resultMain.Document.Body!.Elements<Table>()
            .Concat(resultMain.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
            .Concat(resultMain.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()))
            .ToArray();
        Assert.Equal(3, tables.Length);
        if (bottom)
            Assert.All(tables, table => Assert.Null(table.Elements<TableRow>()
                .First().Elements<TableCell>().First().TableCellProperties?
                .TableCellBorders?.BottomBorder));
        Assert.All(tables, table => Assert.Equal("0000CC",
            table.Elements<TableRow>().Last().Elements<TableCell>().First()
                .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value));
        if (corner)
            Assert.All(tables, table => Assert.Equal("00AA00",
                table.Elements<TableRow>().Last().Elements<TableCell>().Last()
                    .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value));
        Assert.Empty(new OpenXmlValidator().Validate(result));
        var rewrittenDoc = DxpDocExport.Export(projected);
        AssertReusableBorders(rewrittenDoc);
        var third = DxpDocToDocx.Project(rewrittenDoc).DocxBytes;
        using (var thirdStream = new MemoryStream(third))
        using (var thirdDocument = WordprocessingDocument.Open(thirdStream, false))
            Assert.Equal(3, thirdDocument.MainDocumentPart!.Document.Body!
                .Elements<Table>().Concat(thirdDocument.MainDocumentPart.HeaderParts
                    .SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(thirdDocument.MainDocumentPart.FooterParts
                    .SelectMany(x => x.Footer!.Elements<Table>()))
                .Count(x => x.Elements<TableRow>().Last().Elements<TableCell>().First()
                    .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value == "0000CC"));
        if (corner)
        {
            using var thirdStream = new MemoryStream(third);
            using var thirdDocument = WordprocessingDocument.Open(thirdStream, false);
            Assert.Equal(3, thirdDocument.MainDocumentPart!.Document.Body!
                .Elements<Table>().Concat(thirdDocument.MainDocumentPart.HeaderParts
                    .SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(thirdDocument.MainDocumentPart.FooterParts
                    .SelectMany(x => x.Footer!.Elements<Table>()))
                .Count(x => x.Elements<TableRow>().Last().Elements<TableCell>().Last()
                    .TableCellProperties?.TableCellBorders?.Elements<BorderType>().FirstOrDefault(x => x.LocalName == (bottom ? "bottom" : "top"))?.Color?.Value == "00AA00"));
            Assert.Empty(new OpenXmlValidator().Validate(thirdDocument));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
            AssertWordPageRenderClose(source.ToArray(), third, 0.04, 1, ".docx");
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void LastRowAndFirstColumnSideBordersInAllStories(bool right,
        bool reverseRules)
    {
        static Paragraph CellParagraph(string text) => new(
            new ParagraphProperties(new SpacingBetweenLines
                { Before = "0", After = "0" }),
            new Run(new Text(text)));
        static Table StoryTable(string label) => new(
            new TableProperties(new TableStyle { Val = "SideOverlap" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "4800" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "00C0", LastRow = true, FirstColumn = true }),
            new TableGrid(new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" }),
            new TableRow(new TableCell(CellParagraph(label + " one")),
                new TableCell(CellParagraph(label + " two"))),
            new TableRow(new TableCell(CellParagraph(label + " three")),
                new TableCell(CellParagraph(label + " four"))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            TableStyleProperties Rule(TableStyleOverrideValues region,
                string color) => new(new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(right
                        ? new RightBorder { Val = BorderValues.Single, Size = 16, Color = color }
                        : new LeftBorder { Val = BorderValues.Single, Size = 16, Color = color })))
                    { Type = region };
            var lastRow = Rule(TableStyleOverrideValues.LastRow, "0000CC");
            var firstColumn = Rule(TableStyleOverrideValues.FirstColumn, "CC0000");
            styles.Styles = new Styles(new Style(
                new StyleName { Val = "Side overlap" },
                reverseRules ? firstColumn : lastRow,
                reverseRules ? lastRow : firstColumn)
                { Type = StyleValues.Table, StyleId = "SideOverlap" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var repeated = DxpDocExport.Export(projected);
        foreach (var binary in new[] { generated, repeated })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions, x => x.Name == "Side overlap");
            Assert.Equal(0x00CC0000u, (right ? style.ConditionalTableBorders![0x0002].Right : style.ConditionalTableBorders![0x0002].Left)?.ColorRgb);
            Assert.Equal(0x000000CCu, (right ? style.ConditionalTableBorders[0x0004].Right : style.ConditionalTableBorders[0x0004].Left)?.ColorRgb);
            using var packageStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
            using var package = WordprocessingDocument.Open(packageStream, false);
            Assert.Empty(new OpenXmlValidator().Validate(package));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-side-overlap-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.Combine(Path.GetTempPath(),
            $"docxport-side-overlap-native-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(sourcePath, original);
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            int[] Colors(dynamic document)
            {
                var colors = new List<int>();
                foreach (dynamic table in new dynamic[]
                {
                    document.Tables.Item(1),
                    document.Sections(1).Headers(1).Range.Tables.Item(1),
                    document.Sections(1).Footers(1).Range.Tables.Item(1)
                })
                    for (var row = 1; row <= 2; row++)
                        colors.Add((int)table.Cell(row, 1).Borders.Item(right ? -4 : -2).Color);
                return colors.ToArray();
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var expected = Colors(opened);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
            opened.Close(false);
            opened = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            using (var stream = new MemoryStream(nativeProjected))
            using (var package = WordprocessingDocument.Open(stream, false))
                Assert.Empty(new OpenXmlValidator().Validate(package));
            var nativeRepeated = DxpDocExport.Export(nativeProjected);
            AssertWordFirstPageRenderClose(original, native, 0.06);
            AssertWordPageRenderClose(native, generated, 0.005, 1, ".doc", ".doc");
            AssertWordFirstPageRenderClose(original, generated, 0.06);
            AssertWordPageRenderClose(original, projected, 0.06, 1, ".docx");
            AssertWordFirstPageRenderClose(original, repeated, 0.06);
            AssertWordPageRenderClose(original, nativeProjected, 0.06, 1, ".docx");
            AssertWordFirstPageRenderClose(original, nativeRepeated, 0.06);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DirectNilAndClearCellShadingInConditionalStyleInAllStories()
    {
        static Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "ShadedRow" },
                new TableWidth { Width = "4800", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0020", FirstRow = true }),
            new TableGrid(new GridColumn { Width = "1600" },
                new GridColumn { Width = "1600" },
                new GridColumn { Width = "1600" }),
            new TableRow(
                new TableCell(new TableCellProperties(new Shading
                    { Val = ShadingPatternValues.Nil }),
                    new Paragraph(new Run(new Text(text + " nil")))),
                new TableCell(new Paragraph(new Run(new Text(text + " green")))),
                new TableCell(new TableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear }),
                    new Paragraph(new Run(new Text(text + " clear"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Shaded row" },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading { Val = ShadingPatternValues.Clear,
                            Fill = "00AA00" }))
                { Type = TableStyleOverrideValues.FirstRow })
            { Type = StyleValues.Table, StyleId = "ShadedRow" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var third = DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes;
        foreach (var bytes in new[] { projected, third })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var cells = story.Descendants<TableCell>().ToArray();
                Assert.Equal(3, cells.Length);
                Assert.Equal("00AA00",
                    cells[0].TableCellProperties?.Shading?.Fill?.Value);
                Assert.Equal("00AA00",
                    cells[1].TableCellProperties?.Shading?.Fill?.Value);
                Assert.Equal(ShadingPatternValues.Clear,
                    cells[2].TableCellProperties?.Shading?.Val?.Value);
                Assert.Null(cells[2].TableCellProperties?.Shading?.Fill?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-shading-nil-clear-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    foreach (dynamic table in opened.Tables)
                    {
                        Assert.Equal(table.Cell(1, 1).Shading.BackgroundPatternColor,
                            table.Cell(1, 2).Shading.BackgroundPatternColor);
                        Assert.NotEqual(table.Cell(1, 1).Shading.BackgroundPatternColor,
                            table.Cell(1, 3).Shading.BackgroundPatternColor);
                    }
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            var nativeThird = DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes;
            foreach (var nativeBytes in new[] { nativeProjected, nativeThird })
            {
                using var nativeStream = new MemoryStream(nativeBytes);
                using var nativeDocument = WordprocessingDocument.Open(nativeStream, false);
                var nativeMain = nativeDocument.MainDocumentPart!;
                foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    nativeMain.Document!.Body!, nativeMain.HeaderParts.Single().Header!,
                    nativeMain.FooterParts.Single().Footer!
                })
                {
                    var cells = story.Descendants<TableCell>().ToArray();
                    Assert.Equal(3, cells.Length);
                    Assert.Equal("00AA00", cells[0].TableCellProperties?.Shading?.Fill?.Value);
                    Assert.Equal("00AA00", cells[1].TableCellProperties?.Shading?.Fill?.Value);
                    Assert.Null(cells[2].TableCellProperties?.Shading?.Fill?.Value);
                }
                Assert.Empty(new OpenXmlValidator().Validate(nativeDocument));
            }
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void AdjacentTablesWithDifferentDirectionsStaySeparate(bool firstRightToLeft)
    {
        static Table CreateTable(bool rightToLeft, string text)
        {
            var properties = new TableProperties(new TableLayout
            { Type = TableLayoutValues.Fixed }, new TableBorders(new BottomBorder
            {
                Val = BorderValues.Single, Size = 8,
                Color = rightToLeft ? "CC3300" : "0055AA"
            }));
            if (rightToLeft) properties.PrependChild(new BiDiVisual());
            return new Table(properties,
                new TableGrid(new GridColumn { Width = "2400" }),
                new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                CreateTable(firstRightToLeft, "First table"),
                CreateTable(!firstRightToLeft, "Second table")));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Equal(new[] { firstRightToLeft, !firstRightToLeft },
                index.ParagraphStyles.Where(x => x.Formatting?.TableTerminator == true)
                    .Select(x => x.Formatting?.TableRightToLeft == true));
        using var stream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var tables = projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>().ToArray();
        Assert.Equal(2, tables.Length);
        Assert.Equal(new[] { firstRightToLeft, !firstRightToLeft },
            tables.Select(x => x.TableProperties?.GetFirstChild<BiDiVisual>() != null));
        foreach (var table in tables)
            Assert.Equal(table.TableProperties?.GetFirstChild<BiDiVisual>() != null
                    ? "CC3300" : "0055AA",
                table.Descendants<TableCell>().First().TableCellProperties?
                    .TableCellBorders?.BottomBorder?.Color?.Value);
        Assert.Equal(new[] { "First table", "Second table" },
            tables.Select(x => x.InnerText));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-adjacent-rtl-{Guid.NewGuid():N}.doc");
        var sourcePath = Path.ChangeExtension(generatedPath, ".source.docx");
        var nativePath = Path.ChangeExtension(generatedPath, ".native.doc");
        File.WriteAllBytes(generatedPath, binary);
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        word.DisplayAlerts = 0;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(2, (int)opened.Tables.Count);
            opened.Close(false);
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            using var nativeStream = new MemoryStream(
                DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            var nativeTables = native.MainDocumentPart!.Document!.Body!
                .Elements<Table>().ToArray();
            Assert.Equal(2, nativeTables.Length);
            Assert.Equal(new[] { firstRightToLeft, !firstRightToLeft },
                nativeTables.Select(x => x.TableProperties?
                    .GetFirstChild<BiDiVisual>() != null));
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(generatedPath);
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesVerticalCellMerge()
    {
        static TableCell Cell(string text, MergedCellValues? merge = null) => new(
            merge is MergedCellValues value
                ? new TableCellProperties(new VerticalMerge { Val = value })
                : new TableCellProperties(),
            new Paragraph(new Run(new Text(text))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                new Table(new TableGrid(new GridColumn { Width = "2400" },
                        new GridColumn { Width = "2400" }),
                    new TableRow(Cell("Merged", MergedCellValues.Restart), Cell("Top")),
                    new TableRow(Cell("", MergedCellValues.Continue), Cell("Bottom")))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(2, rows.Length);
            Assert.Equal((byte)3, rows[0].Formatting!.TableCellVerticalMerges![0]);
            Assert.Equal((byte)1, rows[1].Formatting!.TableCellVerticalMerges![0]);
        }
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        using var projectedStream = new MemoryStream(projectedBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var table = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>());
        var rowsAfter = table.Elements<TableRow>().ToArray();
        Assert.Equal(MergedCellValues.Restart, rowsAfter[0].Elements<TableCell>()
            .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
        Assert.Equal(MergedCellValues.Continue, rowsAfter[1].Elements<TableCell>()
            .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
        Assert.Equal(new[] { "Merged", "Top", "", "Bottom" },
            table.Descendants<TableCell>().Select(x => x.InnerText));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                $"docxport-vmerge-{Guid.NewGuid():N}.doc");
            var saved = Path.ChangeExtension(path, ".saved.docx");
            var sourcePath = Path.ChangeExtension(path, ".source.docx");
            var nativePath = Path.ChangeExtension(path, ".native.doc");
            File.WriteAllBytes(path, binary);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(1, (int)opened.Tables.Count);
                opened.SaveAs2(saved, 16);
                opened.Close(false);
                opened = null;
                using var wordStream = File.OpenRead(saved);
                using var wordSaved = WordprocessingDocument.Open(wordStream, false);
                var wordTable = Assert.Single(wordSaved.MainDocumentPart!.Document!.Body!
                    .Elements<Table>());
                var wordRows = wordTable.Elements<TableRow>().ToArray();
                Assert.Equal(MergedCellValues.Restart, wordRows[0].Elements<TableCell>()
                    .First().TableCellProperties?.GetFirstChild<VerticalMerge>()?.Val?.Value);
                var continuation = wordRows[1].Elements<TableCell>().First()
                    .TableCellProperties?.GetFirstChild<VerticalMerge>();
                Assert.NotNull(continuation);
                Assert.True(continuation.Val == null ||
                    continuation.Val.Value == MergedCellValues.Continue);
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                var nativeProjection = DxpDocToDocx.Project(
                    File.ReadAllBytes(nativePath)).DocxBytes;
                using var nativeStream = new MemoryStream(nativeProjection);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var nativeRows = Assert.Single(native.MainDocumentPart!.Document!.Body!
                    .Elements<Table>()).Elements<TableRow>().ToArray();
                Assert.Equal(MergedCellValues.Restart, nativeRows[0]
                    .Elements<TableCell>().First().TableCellProperties?
                    .GetFirstChild<VerticalMerge>()?.Val?.Value);
                Assert.Equal(MergedCellValues.Continue, nativeRows[1]
                    .Elements<TableCell>().First().TableCellProperties?
                    .GetFirstChild<VerticalMerge>()?.Val?.Value);
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                if (File.Exists(saved)) File.Delete(saved);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesSimpleBodyTableGrid()
    {
        static TableCell Cell(string text) => new(new Paragraph(new Run(new Text(text))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Before"))),
                new Table(new TableGrid(new GridColumn { Width = "2400" },
                        new GridColumn { Width = "3600" }),
                    new TableRow(Cell("A1"), Cell("B1")),
                    new TableRow(Cell("A2"), Cell("B2"))),
                new Paragraph(new Run(new Text("After")))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var story = DocStoryTextReader.Read(index, "Main");
            Assert.Equal(4, story.Paragraphs.Count(x => x.End == DocParagraphEnd.CellMark));
            Assert.Equal(2, story.Paragraphs.Count(x => x.End == DocParagraphEnd.RowMark));
            Assert.Equal(new short[] { 0, 2400, 6000 },
                index.ParagraphStyles.First(x => x.Formatting?.TableTerminator == true)
                    .Formatting!.TableCellEdges);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var blocks = projected.MainDocumentPart!.Document!.Body!.ChildElements;
        Assert.Equal(4, blocks.Count);
        Assert.IsType<Paragraph>(blocks[0]);
        var table = Assert.IsType<Table>(blocks[1]);
        Assert.IsType<Paragraph>(blocks[2]);
        Assert.IsType<SectionProperties>(blocks[3]);
        Assert.Equal(new[] { "A1", "B1", "A2", "B2" }, table.Descendants<TableCell>()
            .Select(x => x.InnerText));
        Assert.Equal(new[] { "2400", "3600" }, table.GetFirstChild<TableGrid>()!
            .Elements<GridColumn>().Select(x => x.Width!.Value));
        var errors = new OpenXmlValidator().Validate(projected).ToArray();
        Assert.True(errors.Length == 0, string.Join("; ", errors.Select(x =>
            x.Path?.XPath + ": " + x.Description)));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-table-" + Guid.NewGuid().ToString("N") + ".doc");
            var wordSavedPath = Path.ChangeExtension(path, ".word-saved.doc");
            var sourcePath = Path.ChangeExtension(path, ".source.docx");
            var nativePath = Path.ChangeExtension(path, ".native.doc");
            File.WriteAllBytes(path, bytes);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                Assert.Equal(1, (int)opened.Tables.Count);
                Assert.Contains("A1", (string)opened.Tables.Item(1).Cell(1, 1).Range.Text);
                Assert.Contains("B2", (string)opened.Tables.Item(1).Cell(2, 2).Range.Text);
                opened.SaveAs2(wordSavedPath, 0);
                opened.Close(false);
                opened = null;
                var wordSavedProjection = DxpDocToDocx.Project(File.ReadAllBytes(wordSavedPath));
                using var wordSavedStream = new MemoryStream(wordSavedProjection.DocxBytes);
                using var wordSaved = WordprocessingDocument.Open(wordSavedStream, false);
                var wordSavedTable = Assert.Single(wordSaved.MainDocumentPart!.Document!.Body!
                    .Elements<Table>());
                Assert.Equal(new[] { "A1", "B1", "A2", "B2" },
                    wordSavedTable.Descendants<TableCell>().Select(x => x.InnerText));
                Assert.Empty(new OpenXmlValidator().Validate(wordSaved));
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using (var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var nativeIndex = new DocTextIndexWalker().Index(nativeInput))
                {
                    var nativeRow = nativeIndex.ParagraphStyles.First(x =>
                        x.Formatting?.TableTerminator == true);
                    Assert.NotNull(nativeRow.Formatting?.TableCellBorders);
                }
                using (var input = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    var atoms = index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).ToArray();
                    Console.WriteLine("LEGACY ATOMS " + string.Join(";", atoms.Select(a =>
                        $"{a.CpStart}:{a.Kind}:{string.Join(",", a.Text.Select(c => ((int)c).ToString("X2")))}")));
                    Console.WriteLine("LEGACY FORMATS " + string.Join(";", index.CharacterFormatting
                        .Where(x => x.CpStart < 35).Select(x =>
                            $"{x.CpStart}-{x.CpEnd}:special={x.Formatting.Special}")));
                }                var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var nativeTable = Assert.Single(native.MainDocumentPart!.Document!.Body!
                    .Elements<Table>());
                Assert.Equal(new[] { "A1", "B1", "A2", "B2" },
                    nativeTable.Descendants<TableCell>().Select(x => x.InnerText));
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                if (File.Exists(wordSavedPath)) File.Delete(wordSavedPath);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesTablesInHeaderAndFooterStories()
    {
        static Table TableOf(TableRowAlignmentValues alignment,
            params string[] cells) => new(
            new TableProperties(
                new TableJustification { Val = alignment },
                new TableIndentation { Width = 720, Type = TableWidthUnitValues.Dxa },
                new TableCellMarginDefault(
                    new TableCellLeftMargin { Width = 108,
                        Type = TableWidthValues.Dxa },
                    new TableCellRightMargin { Width = 108,
                        Type = TableWidthValues.Dxa })),
            new TableGrid(cells.Select(_ => new GridColumn { Width = "2400" })),
            new TableRow(cells.Select(value =>
                new TableCell(new Paragraph(new Run(new Text(value)))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TableOf(TableRowAlignmentValues.Center,
                "H1", "H2"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TableOf(TableRowAlignmentValues.Right,
                "F1", "F2"));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(new Text("Body"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(2, index.HeaderStories[7].ReadContent().Paragraphs.Count(x =>
                x.End == DocParagraphEnd.CellMark));
            Assert.Equal(2, index.HeaderStories[9].ReadContent().Paragraphs.Count(x =>
                x.End == DocParagraphEnd.CellMark));
            Assert.True(index.ParagraphStyles.Count(x =>
                x.Formatting.TableTerminator == true &&
                x.Formatting.TableIndentTwips == 720) >= 2);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        Assert.Equal(new[] { "H1", "H2" }, Assert.Single(projected.MainDocumentPart!
            .HeaderParts).Header!.Descendants<TableCell>().Select(x => x.InnerText));
        Assert.Equal(new[] { "F1", "F2" }, Assert.Single(projected.MainDocumentPart!
            .FooterParts).Footer!.Descendants<TableCell>().Select(x => x.InnerText));
        Assert.Equal(720, Assert.Single(projected.MainDocumentPart.HeaderParts)
            .Header!.Descendants<Table>().Single().TableProperties!
            .GetFirstChild<TableIndentation>()!.Width!.Value);
        Assert.Equal(720, Assert.Single(projected.MainDocumentPart.FooterParts)
            .Footer!.Descendants<Table>().Single().TableProperties!
            .GetFirstChild<TableIndentation>()!.Width!.Value);
        Assert.Equal(TableRowAlignmentValues.Center,
            Assert.Single(projected.MainDocumentPart.HeaderParts).Header!
                .Descendants<Table>().Single().TableProperties!
                .GetFirstChild<TableJustification>()!.Val!.Value);
        Assert.Equal(TableRowAlignmentValues.Right,
            Assert.Single(projected.MainDocumentPart.FooterParts).Footer!
                .Descendants<Table>().Single().TableProperties!
                .GetFirstChild<TableJustification>()!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-story-tables-" + Guid.NewGuid().ToString("N") + ".doc");
            var sourcePath = Path.ChangeExtension(path, ".docx");
            var nativePath = Path.Combine(Path.GetDirectoryName(path)!,
                Path.GetFileNameWithoutExtension(path) + "-native.doc");
            File.WriteAllBytes(path, bytes);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using (var nativeStream = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var nativeIndex = new DocTextIndexWalker().Index(nativeStream))
                {
                    Assert.True(nativeIndex.ParagraphStyles.Count(x =>
                        x.Formatting.TableTerminator == true &&
                        x.Formatting.TableIndentTwips == 720) >= 2);
                    Assert.Contains(nativeIndex.ParagraphStyles, x =>
                        x.Formatting.TableTerminator == true &&
                        x.Formatting.TableJustification == 1);
                    Assert.Contains(nativeIndex.ParagraphStyles, x =>
                        x.Formatting.TableTerminator == true &&
                        x.Formatting.TableJustification == 2);
                    var nativeProjection = new DocToDocxProjector().Project(nativeIndex);
                    using var nativeDocxStream = new MemoryStream(nativeProjection.DocxBytes);
                    using var nativeDocx = WordprocessingDocument.Open(nativeDocxStream, false);
                    Assert.Equal(720, Assert.Single(nativeDocx.MainDocumentPart!
                        .HeaderParts).Header!.Descendants<Table>().Single()
                        .TableProperties!.GetFirstChild<TableIndentation>()!.Width!.Value);
                    Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
                }
                opened = word.Documents.Open(path, false, true);
                dynamic section = opened.Sections.Item(1);
                Assert.Equal(1, (int)section.Headers.Item(1).Range.Tables.Count);
                Assert.Equal(1, (int)section.Footers.Item(1).Range.Tables.Count);
                Assert.Equal(36f, (float)section.Headers.Item(1).Range.Tables.Item(1)
                    .Rows.LeftIndent);
                Assert.Equal(36f, (float)section.Footers.Item(1).Range.Tables.Item(1)
                    .Rows.LeftIndent);
                Assert.Equal(1, (int)section.Headers.Item(1).Range.Tables.Item(1)
                    .Rows.Alignment);
                Assert.Equal(2, (int)section.Footers.Item(1).Range.Tables.Item(1)
                    .Rows.Alignment);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void InheritedTablePlacementAndDirectOverrideSurviveAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleTableProperties(
                    new TableJustification { Val = TableRowAlignmentValues.Center },
                    new TableIndentation { Width = 720, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })))
                { Type = StyleValues.Table, StyleId = "PlacementBase" },
                new Style(new BasedOn { Val = "PlacementBase" })
                { Type = StyleValues.Table, StyleId = "PlacementChild" });
            styles.Styles.Save();
            static Table PlacedTable(string text, bool direct = false) => new(
                direct
                    ? new TableProperties(new TableStyle { Val = "PlacementChild" },
                        new TableJustification { Val = TableRowAlignmentValues.Right },
                        new TableIndentation { Width = 1440,
                            Type = TableWidthUnitValues.Dxa },
                        new TableLayout { Type = TableLayoutValues.Fixed })
                    : new TableProperties(new TableStyle { Val = "PlacementChild" },
                        new TableLayout { Type = TableLayoutValues.Fixed }),
                new TableGrid(new GridColumn { Width = "1800" }),
                new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(PlacedTable("Header table", true));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(PlacedTable("Footer table"));
            footer.Footer.Save();
            main.Document = new Document(new Body(PlacedTable("Body table"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var baseStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "PlacementBase");
            var childStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "PlacementChild");
            Assert.Equal(baseStyle.Index, childStyle.BasedOnIndex);
            Assert.Equal((short)720, baseStyle.TableFormatting?.TableIndentTwips);
            Assert.Equal((byte)1, baseStyle.TableFormatting?.TableJustification);
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting.TableTerminator == true).ToArray();
            Assert.Equal(3, rows.Length);
            Assert.Equal(2, rows.Count(x => x.Formatting.TableIndentTwips == 720 &&
                x.Formatting.TableJustification == 1));
            Assert.Single(rows, x => x.Formatting.TableIndentTwips == 1440 &&
                x.Formatting.TableJustification == 2);
        }
        using var projectionStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectionStream, false);
        var part = projected.MainDocumentPart!;
        var tables = new[]
        {
            Assert.Single(part.Document!.Body!.Elements<Table>()),
            Assert.Single(Assert.Single(part.HeaderParts).Header!.Elements<Table>()),
            Assert.Single(Assert.Single(part.FooterParts).Footer!.Elements<Table>())
        };
        Assert.Equal(new[] { 720, 1440, 720 }, tables.Select(x =>
            x.TableProperties!.GetFirstChild<TableIndentation>()!.Width!.Value));
        Assert.Equal(new[] { TableRowAlignmentValues.Center,
            TableRowAlignmentValues.Right, TableRowAlignmentValues.Center },
            tables.Select(x => x.TableProperties!.GetFirstChild<TableJustification>()!
                .Val!.Value));
        var projectedBase = Assert.Single(part.StyleDefinitionsPart!.Styles!
            .Elements<Style>(), x => x.StyleName?.Val?.Value == "PlacementBase");
        Assert.Equal(720, projectedBase.StyleTableProperties?
            .GetFirstChild<TableIndentation>()?.Width?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-placement-{Guid.NewGuid():N}.doc");
        var sourcePath = Path.ChangeExtension(generatedPath, ".docx");
        var nativePath = Path.Combine(Path.GetDirectoryName(generatedPath)!,
            Path.GetFileNameWithoutExtension(generatedPath) + "-native.doc");
        File.WriteAllBytes(generatedPath, binary);
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(1, (int)opened.Tables.Item(1).Rows.Alignment);
            Assert.Equal(36f, (float)opened.Tables.Item(1).Rows.LeftIndent);
            dynamic section = opened.Sections.Item(1);
            Assert.Equal(2, (int)section.Headers.Item(1).Range.Tables.Item(1)
                .Rows.Alignment);
            Assert.Equal(72f, (float)section.Headers.Item(1).Range.Tables.Item(1)
                .Rows.LeftIndent);
            Assert.Equal(1, (int)section.Footers.Item(1).Range.Tables.Item(1)
                .Rows.Alignment);
            opened.Close(false);
            opened = null;
            using var nativeStream = new MemoryStream(File.ReadAllBytes(nativePath));
            using var nativeIndex = new DocTextIndexWalker().Index(nativeStream);
            Assert.Contains(nativeIndex.ParagraphStyles, x =>
                x.Formatting.TableTerminator == true &&
                x.Formatting.TableJustification == 2);
            using var nativeProjectionStream = new MemoryStream(
                new DocToDocxProjector().Project(nativeIndex).DocxBytes);
            using var nativeProjection = WordprocessingDocument.Open(
                nativeProjectionStream, false);
            Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(generatedPath);
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

