    [Fact]
    public void DocRoundTripPreservesTableRowHeightAndHeader()
    {
        static TableRow Row(string text, TableRowProperties properties) => new(
            properties, new TableCell(new Paragraph(new Run(new Text(text)))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableGrid(new GridColumn { Width = "3000" }),
                Row("Heading", new TableRowProperties(new CantSplit(),
                    new TableRowHeight { Val = 500, HeightType = HeightRuleValues.Exact },
                    new TableHeader())),
                Row("Detail", new TableRowProperties(
                    new TableRowHeight { Val = 700,
                        HeightType = HeightRuleValues.AtLeast })))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rowFormats = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).Select(x => x.Formatting!).ToArray();
            Assert.Equal(2, rowFormats.Length);
            Assert.True(rowFormats[0].TableHeader);
            Assert.True(rowFormats[0].TableCantSplit);
            Assert.Equal((short)-500, rowFormats[0].TableRowHeightTwips);
            Assert.Equal((short)700, rowFormats[1].TableRowHeightTwips);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var rows = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Elements<TableRow>().ToArray();
        Assert.NotNull(rows[0].TableRowProperties?.GetFirstChild<TableHeader>());
        Assert.NotNull(rows[0].TableRowProperties?.GetFirstChild<CantSplit>());
        Assert.Equal(HeightRuleValues.Exact,
            rows[0].TableRowProperties?.GetFirstChild<TableRowHeight>()?.HeightType?.Value);
        Assert.Equal((uint)500,
            rows[0].TableRowProperties?.GetFirstChild<TableRowHeight>()?.Val?.Value);
        Assert.Equal(HeightRuleValues.AtLeast,
            rows[1].TableRowProperties?.GetFirstChild<TableRowHeight>()?.HeightType?.Value);
        Assert.Equal((uint)700,
            rows[1].TableRowProperties?.GetFirstChild<TableRowHeight>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-row-format-" + Guid.NewGuid().ToString("N") + ".doc");
            File.WriteAllBytes(path, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                dynamic first = opened.Tables.Item(1).Rows.Item(1);
                dynamic second = opened.Tables.Item(1).Rows.Item(2);
                Assert.Equal(-1, (int)first.HeadingFormat);
                Assert.Equal(2, (int)first.HeightRule);
                Assert.Equal(25f, (float)first.Height);
                Assert.Equal(0, (int)first.AllowBreakAcrossPages);
                Assert.Equal(1, (int)second.HeightRule);
                Assert.Equal(35f, (float)second.Height);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
            }
        }
    }

    [Fact]
    public void ExplicitNoneCellBorderOverridesTableBorder()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableBorders(
                    new TopBorder { Val = BorderValues.Single, Size = 4 })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new TableCellBorders(
                        new TopBorder { Val = BorderValues.None })),
                        new Paragraph(new Run(new Text("No top")))),
                    new TableCell(new Paragraph(new Run(new Text("Top remains"))))))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var row = Assert.Single(index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true));
            Assert.Equal((byte)0, row.Formatting!.TableCellBorders?[0]?.Top?.Type);
            Assert.Equal((byte)1, row.Formatting.TableCellBorders?[1]?.Top?.Type);
        }
        var projection = DxpDocToDocx.Project(binary);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal(BorderValues.Nil, cells[0].TableCellProperties?
            .TableCellBorders?.TopBorder?.Val?.Value);
        Assert.Equal(BorderValues.Single, cells[1].TableCellProperties?
            .TableCellBorders?.TopBorder?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
    }

    [Fact]
    public void DirectNoneAndNilCellBordersOverConditionalStyleInAllStories()
    {
        static Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "RedTopBlueSides" },
                new TableWidth { Width = "4800", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0020", FirstRow = true }),
            new TableGrid(new GridColumn { Width = "1600" },
                new GridColumn { Width = "1600" },
                new GridColumn { Width = "1600" }),
            new TableRow(
                new TableCell(new TableCellProperties(new TableCellBorders(
                    new TopBorder { Val = BorderValues.None },
                    new LeftBorder { Val = BorderValues.None })),
                    new Paragraph(new Run(new Text(text + " none")))),
                new TableCell(new TableCellProperties(new TableCellBorders(
                    new TopBorder { Val = BorderValues.Nil },
                    new LeftBorder { Val = BorderValues.Nil })),
                    new Paragraph(new Run(new Text(text + " nil")))),
                new TableCell(new Paragraph(new Run(new Text(text + " omitted"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Red top blue sides" },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellBorders(new TopBorder
                        { Val = BorderValues.Single, Size = 24, Color = "CC0000" },
                            new LeftBorder
                            { Val = BorderValues.Single, Size = 24, Color = "0000CC" },
                            new RightBorder
                            { Val = BorderValues.Single, Size = 24, Color = "0000CC" })))
                { Type = TableStyleOverrideValues.FirstRow })
            { Type = StyleValues.Table, StyleId = "RedTopBlueSides" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        static void AssertCellEdges(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var result = WordprocessingDocument.Open(stream, false);
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                result.MainDocumentPart!.Document!.Body!,
                result.MainDocumentPart.HeaderParts.Single().Header!,
                result.MainDocumentPart.FooterParts.Single().Footer!
            })
            {
                var cells = story.Descendants<TableCell>().ToArray();
                Assert.Equal(3, cells.Length);
                Assert.Equal(BorderValues.Nil, cells[0].TableCellProperties?
                    .TableCellBorders?.TopBorder?.Val?.Value);
                Assert.Equal(BorderValues.Nil, cells[1].TableCellProperties?
                    .TableCellBorders?.TopBorder?.Val?.Value);
                Assert.Equal("CC0000", cells[2].TableCellProperties?
                    .TableCellBorders?.TopBorder?.Color?.Value);
                Assert.Equal(BorderValues.Nil, cells[0].TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Val?.Value);
                Assert.Equal(BorderValues.Nil, cells[1].TableCellProperties?
                    .TableCellBorders?.LeftBorder?.Val?.Value);
                Assert.Null(cells[2].TableCellProperties?
                    .TableCellBorders?.LeftBorder);
                Assert.Null(cells[0].TableCellProperties?
                    .TableCellBorders?.RightBorder);
                Assert.Null(cells[1].TableCellProperties?
                    .TableCellBorders?.RightBorder);
                Assert.Equal("0000CC", cells[2].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Color?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(result));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertCellEdges(projected);
        AssertCellEdges(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-none-nil-borders-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    Assert.Equal(0, (int)table.Cell(1, 1).Borders.Item(-4).LineStyle);
                    Assert.Equal(0, (int)table.Cell(1, 2).Borders.Item(-4).LineStyle);
                    Assert.Equal(1, (int)table.Cell(1, 3).Borders.Item(-4).LineStyle);
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            var nativeThird = DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes;
            foreach (var bytes in new[] { nativeProjected, nativeThird })
            {
                using var nativeStream = new MemoryStream(bytes);
                using var nativeDocument = WordprocessingDocument.Open(nativeStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(nativeDocument));
            }
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.045, 1,
                    ".docx");
                AssertWordPageRenderClose(source.ToArray(), nativeThird, 0.045, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Fact]
    public void TableStyleVerticalAlignmentAndDirectOverridesInAllStories()
    {
        static void AssertReusableAlignment(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(document.MainDocumentPart!.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), style =>
                    style.StyleName?.Val?.Value == "Aligned rows");
            Assert.Equal(TableVerticalAlignmentValues.Bottom,
                style.StyleTableCellProperties?
                    .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
            Assert.Equal(TableVerticalAlignmentValues.Center,
                Assert.Single(style.Elements<TableStyleProperties>(), condition =>
                    condition.Type?.Value == TableStyleOverrideValues.FirstRow)
                    .TableStyleConditionalFormattingTableCellProperties?
                    .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
            Assert.Equal(TableVerticalAlignmentValues.Top,
                Assert.Single(style.Elements<TableStyleProperties>(), condition =>
                    condition.Type?.Value == TableStyleOverrideValues.LastRow)
                    .TableStyleConditionalFormattingTableCellProperties?
                    .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
        }
        static Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "AlignedRows" },
                new TableWidth { Width = "3600", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0060", FirstRow = true, LastRow = true }),
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new TableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                    new Paragraph(new Run(new Text(text + " direct top")))),
                new TableCell(new Paragraph(new Run(new Text(text + " center"))))),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(text + " base bottom")))),
                new TableCell(new Paragraph(new Run(new Text(text + " base bottom"))))),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(text + " last top")))),
                new TableCell(new TableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Bottom }),
                    new Paragraph(new Run(new Text(text + " direct bottom"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Aligned rows" },
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Bottom }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Center }))
                { Type = TableStyleOverrideValues.FirstRow },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Top }))
                { Type = TableStyleOverrideValues.LastRow })
            { Type = StyleValues.Table, StyleId = "AlignedRows" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        static void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var cells = story.Descendants<TableCell>().ToArray();
                Assert.Equal(6, cells.Length);
                Assert.Equal(new[]
                {
                    TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Bottom,
                    TableVerticalAlignmentValues.Bottom,
                    TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Bottom
                }, cells.Select(cell => cell.TableCellProperties?
                    .TableCellVerticalAlignment?.Val?.Value ??
                    TableVerticalAlignmentValues.Top));
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        var generatedThird = DxpDocToDocx.Project(
            DxpDocExport.Export(projected)).DocxBytes;
        AssertAlignments(projected);
        AssertAlignments(generatedThird);
        AssertReusableAlignment(projected);
        AssertReusableAlignment(generatedThird);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-style-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            var projectedPath = Path.Combine(directory, "projected.docx");
            var wordSavedPath = Path.Combine(directory, "word-saved.docx");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(projectedPath, projected);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                dynamic projectedDocument = word.Documents.Open(projectedPath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { projectedDocument.SaveAs2(wordSavedPath, 16); }
                finally { projectedDocument.Close(false); }
            }
            finally { word.Quit(false); }
            AssertReusableAlignment(File.ReadAllBytes(wordSavedPath));
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            var nativeThird = DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(nativeThird);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.07, 1,
                    ".docx");
                AssertWordPageRenderClose(source.ToArray(), nativeThird, 0.07, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Fact]
    public void ReusableTableStyleVerticalAlignmentRetainsAllTwelveRegions()
    {
        var conditions = new[]
        {
            TableStyleOverrideValues.FirstRow,
            TableStyleOverrideValues.LastRow,
            TableStyleOverrideValues.FirstColumn,
            TableStyleOverrideValues.LastColumn,
            TableStyleOverrideValues.Band1Horizontal,
            TableStyleOverrideValues.Band2Horizontal,
            TableStyleOverrideValues.Band1Vertical,
            TableStyleOverrideValues.Band2Vertical,
            TableStyleOverrideValues.NorthWestCell,
            TableStyleOverrideValues.NorthEastCell,
            TableStyleOverrideValues.SouthWestCell,
            TableStyleOverrideValues.SouthEastCell
        };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var style = new Style(new StyleName { Val = "Twelve alignments" },
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Bottom }))
            { Type = StyleValues.Table, StyleId = "TwelveAlignments" };
            for (var i = 0; i < conditions.Length; i++)
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = i % 2 == 0 ? TableVerticalAlignmentValues.Center :
                            TableVerticalAlignmentValues.Bottom }))
                { Type = conditions[i] });
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableStyle { Val = "TwelveAlignments" }),
                new TableGrid(new GridColumn { Width = "1800" }),
                new TableRow(new TableCell(new Paragraph(new Run(
                    new Text("style")))))), new SectionProperties()));
            main.Document.Save();
        }
        void AssertReusable(byte[] bytes, bool validate = true)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(document.MainDocumentPart!.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), style =>
                    style.StyleName?.Val?.Value == "Twelve alignments");
            Assert.Equal(TableVerticalAlignmentValues.Bottom,
                style.StyleTableCellProperties?
                    .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
            for (var i = 0; i < conditions.Length; i++)
                Assert.Equal(i % 2 == 0 ? TableVerticalAlignmentValues.Center :
                    TableVerticalAlignmentValues.Bottom,
                    Assert.Single(style.Elements<TableStyleProperties>(), rule =>
                        rule.Type?.Value == conditions[i])
                        .TableStyleConditionalFormattingTableCellProperties?
                        .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
            if (validate) Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using (var binaryStream = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(binaryStream))
        {
            var indexedStyle = Assert.Single(index.StyleDefinitions, style =>
                style.Name == "Twelve alignments");
            Assert.Equal((byte)2,
                indexedStyle.TableFormatting?.TableStyleVerticalAlignment);
            Assert.Equal(conditions.Length,
                indexedStyle.ConditionalTableVerticalAlignment?.Count);
        }
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertReusable(projected);
        AssertReusable(DxpDocToDocx.Project(
            DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-twelve-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var projectedPath = Path.Combine(directory, "projected.docx");
            var savedPath = Path.Combine(directory, "saved.docx");
            var generatedPath = Path.Combine(directory, "generated.doc");
            var generatedSavedPath = Path.Combine(directory, "generated-saved.docx");
            File.WriteAllBytes(projectedPath, projected);
            File.WriteAllBytes(generatedPath, generated);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(projectedPath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { opened.SaveAs2(savedPath, 16); }
                finally { opened.Close(false); }
                dynamic generatedOpened = word.Documents.Open(generatedPath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { generatedOpened.SaveAs2(generatedSavedPath, 16); }
                finally { generatedOpened.Close(false); }
            }
            finally { word.Quit(false); }
            AssertReusable(File.ReadAllBytes(savedPath), validate: false);
            AssertReusable(File.ReadAllBytes(generatedSavedPath), validate: false);
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void ColumnStyleVerticalAlignmentAppliesAcrossRowsInAllStories(bool firstColumn)
    {
        Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "ColumnAligned" },
                new TableWidth { Width = "3600", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = firstColumn ? "0080" : "0100",
                    FirstColumn = firstColumn, LastColumn = !firstColumn }),
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(text + " A")))),
                new TableCell(new Paragraph(new Run(new Text(text + " B"))))),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(text + " C")))),
                new TableCell(new TableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Bottom }),
                    new Paragraph(new Run(new Text(text + " D"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Column aligned" },
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Center }))
                { Type = firstColumn ? TableStyleOverrideValues.FirstColumn :
                    TableStyleOverrideValues.LastColumn })
            { Type = StyleValues.Table, StyleId = "ColumnAligned" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        static void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                Assert.Equal(new[]
                {
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Bottom
                }, story.Descendants<TableCell>().Select(cell =>
                    cell.TableCellProperties?.TableCellVerticalAlignment?
                        .Val?.Value ?? TableVerticalAlignmentValues.Top));
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertAlignments(projected);
        AssertAlignments(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-column-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    Assert.Equal(1, (int)table.Cell(1, 1).VerticalAlignment);
                    Assert.Equal(1, (int)table.Cell(1, 2).VerticalAlignment);
                    Assert.Equal(1, (int)table.Cell(2, 1).VerticalAlignment);
                    Assert.Equal(3, (int)table.Cell(2, 2).VerticalAlignment);
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.07, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData("nw", "00A0", true, true)]
    [InlineData("ne", "0120", true, false)]
    [InlineData("sw", "00C0", false, true)]
    [InlineData("se", "0140", false, false)]
    public void CornerStyleVerticalAlignmentAppliesAcrossRowInAllStories(
        string corner, string lookMask, bool north, bool west)
    {
        var condition = corner switch
        {
            "nw" => TableStyleOverrideValues.NorthWestCell,
            "ne" => TableStyleOverrideValues.NorthEastCell,
            "sw" => TableStyleOverrideValues.SouthWestCell,
            _ => TableStyleOverrideValues.SouthEastCell
        };
        Table StoryTable(string text)
        {
            TableCell Cell(string label, bool directBottom = false) => directBottom
                ? new TableCell(new TableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Bottom }),
                    new Paragraph(new Run(new Text(text + " " + label))))
                : new TableCell(new Paragraph(new Run(new Text(text + " " + label))));
            TableRow Row(string prefix, bool target) => new(
                new TableRowProperties(new TableRowHeight
                    { Val = 480, HeightType = HeightRuleValues.Exact }),
                Cell(prefix + " A"), Cell(prefix + " B", target));
            return new Table(
                new TableProperties(new TableStyle { Val = "CornerAligned" },
                    new TableWidth { Width = "3600", Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableLook { Val = lookMask, FirstRow = north, LastRow = !north,
                        FirstColumn = west, LastColumn = !west }),
                new TableGrid(new GridColumn { Width = "1800" },
                    new GridColumn { Width = "1800" }),
                Row("first", north), Row("last", !north));
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Corner aligned" },
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Center }))
                { Type = condition })
            { Type = StyleValues.Table, StyleId = "CornerAligned" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var expected = north
                ? new[] { TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Bottom,
                    TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Top }
                : new[] { TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Bottom };
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
                Assert.Equal(expected, story.Descendants<TableCell>().Select(cell =>
                    cell.TableCellProperties?.TableCellVerticalAlignment?.Val?.Value ??
                    TableVerticalAlignmentValues.Top));
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertAlignments(projected);
        AssertAlignments(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-corner-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    var expectedWord = north ? new[] { 1, 3, 0, 0 } :
                        new[] { 0, 0, 1, 3 };
                    var actualWord = new[]
                    {
                        (int)table.Cell(1, 1).VerticalAlignment,
                        (int)table.Cell(1, 2).VerticalAlignment,
                        (int)table.Cell(2, 1).VerticalAlignment,
                        (int)table.Cell(2, 2).VerticalAlignment
                    };
                    Assert.Equal(expectedWord, actualWord);
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.07, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Trait("Category", "LocalOnly")]
    [Fact]
    public void NilTableStyleShadingDoesNotSuppressInheritedFill()
    {
        static Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "NilFirstRow" },
                new TableLook { FirstRow = true }),
            new TableGrid(new GridColumn { Width = "2000" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleTableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "99DD99" }))
                    { Type = StyleValues.Table, StyleId = "GreenTable" },
                new Style(new BasedOn { Val = "GreenTable" },
                    new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new Shading { Val = ShadingPatternValues.Nil }))
                    { Type = TableStyleOverrideValues.FirstRow })
                    { Type = StyleValues.Table, StyleId = "NilFirstRow" },
                new Style(new StyleTableCellProperties(new Shading
                    { Val = ShadingPatternValues.Nil }))
                    { Type = StyleValues.Table, StyleId = "NilBase" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header cell"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer cell"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body cell"),
                new SectionProperties(new HeaderReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header) },
                    new FooterReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var projectedStyles = projected.MainDocumentPart!.StyleDefinitionsPart!
            .Styles!;
        var green = Assert.Single(projectedStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "GreenTable");
        Assert.Equal("99DD99", green.StyleTableCellProperties?
            .GetFirstChild<Shading>()?.Fill?.Value);
        var derived = Assert.Single(projectedStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "NilFirstRow");
        Assert.Equal(green.StyleId?.Value, derived.BasedOn?.Val?.Value);
        Assert.Null(derived.Elements<TableStyleProperties>().SingleOrDefault()?
            .TableStyleConditionalFormattingTableCellProperties?
            .GetFirstChild<Shading>());
        var nilBase = Assert.Single(projectedStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "NilBase");
        Assert.Null(nilBase.StyleTableCellProperties?.GetFirstChild<Shading>());
        Assert.Equal("Body cell", Assert.Single(projected.MainDocumentPart.Document!
            .Body!.Elements<Table>()).InnerText);
        Assert.Equal("Header cell", Assert.Single(projected.MainDocumentPart
            .HeaderParts).Header!.InnerText);
        Assert.Equal("Footer cell", Assert.Single(projected.MainDocumentPart
            .FooterParts).Footer!.InnerText);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var thirdBinary = DxpDocExport.Export(projectedStream.ToArray());
        using var thirdStream = new MemoryStream(
            DxpDocToDocx.Project(thirdBinary).DocxBytes);
        using var third = WordprocessingDocument.Open(thirdStream, false);
        var thirdStyles = third.MainDocumentPart!.StyleDefinitionsPart!.Styles!;
        Assert.Equal("99DD99", Assert.Single(thirdStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "GreenTable")
            .StyleTableCellProperties?.GetFirstChild<Shading>()?.Fill?.Value);
        Assert.Equal("Body cell", Assert.Single(third.MainDocumentPart.Document!
            .Body!.Elements<Table>()).InnerText);
        Assert.Equal("Header cell", Assert.Single(third.MainDocumentPart.HeaderParts)
            .Header!.InnerText);
        Assert.Equal("Footer cell", Assert.Single(third.MainDocumentPart.FooterParts)
            .Footer!.InnerText);
        Assert.Empty(new OpenXmlValidator().Validate(third));
        AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-nil-table-style-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(
                Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
            using var nativeStream = new MemoryStream(nativeProjection);
            using var nativeDocument = WordprocessingDocument.Open(nativeStream, false);
            Assert.Equal("Body cell", Assert.Single(nativeDocument.MainDocumentPart!
                .Document!.Body!.Elements<Table>()).InnerText);
            Assert.Equal("Header cell", Assert.Single(nativeDocument.MainDocumentPart
                .HeaderParts).Header!.InnerText);
            Assert.Equal("Footer cell", Assert.Single(nativeDocument.MainDocumentPart
                .FooterParts).Footer!.InnerText);
            Assert.All(nativeDocument.MainDocumentPart.Document.Body!
                .Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.All(Assert.Single(nativeDocument.MainDocumentPart.HeaderParts)
                .Header!.Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.All(Assert.Single(nativeDocument.MainDocumentPart.FooterParts)
                .Footer!.Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocument));
            var nativeThird = DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjection)).DocxBytes;
            using var nativeThirdStream = new MemoryStream(nativeThird);
            using var nativeThirdDocument = WordprocessingDocument.Open(
                nativeThirdStream, false);
            Assert.All(nativeThirdDocument.MainDocumentPart!.Document!.Body!
                .Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.All(Assert.Single(nativeThirdDocument.MainDocumentPart.HeaderParts)
                .Header!.Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.All(Assert.Single(nativeThirdDocument.MainDocumentPart.FooterParts)
                .Footer!.Descendants<TableCell>(), cell =>
                Assert.Equal("99DD99", cell.TableCellProperties?.Shading?.Fill?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(nativeThirdDocument));
            AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void BandStyleVerticalAlignmentAppliesAcrossRowsInAllStories(
        bool vertical, bool firstBand)
    {
        var rows = vertical ? 2 : 4;
        var columns = vertical ? 4 : 2;
        var condition = vertical
            ? firstBand ? TableStyleOverrideValues.Band1Vertical :
                TableStyleOverrideValues.Band2Vertical
            : firstBand ? TableStyleOverrideValues.Band1Horizontal :
                TableStyleOverrideValues.Band2Horizontal;
        Table StoryTable(string name)
        {
            var table = new Table(new TableProperties(
                new TableStyle { Val = "BandAligned" },
                new TableWidth { Width = (1800 * columns).ToString(),
                    Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "0000", FirstRow = false, LastRow = false,
                    FirstColumn = false, LastColumn = false,
                    NoHorizontalBand = vertical, NoVerticalBand = !vertical }),
                new TableGrid(Enumerable.Range(0, columns)
                    .Select(_ => new GridColumn { Width = "1800" })));
            for (var row = 0; row < rows; row++)
            {
                var cells = new List<TableCell>();
                for (var column = 0; column < columns; column++)
                {
                    var direct = row == 1 && column == columns - 1;
                    cells.Add(new TableCell(
                        direct ? new TableCellProperties(
                            new TableCellVerticalAlignment
                                { Val = TableVerticalAlignmentValues.Bottom }) :
                            new TableCellProperties(),
                        new Paragraph(new Run(new Text($"{name} {row}{column}")))));
                }
                var tableRow = new TableRow(new TableRowProperties(new TableRowHeight
                    { Val = 480, HeightType = HeightRuleValues.Exact }));
                tableRow.Append(cells);
                table.Append(tableRow);
            }
            return table;
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Band aligned" },
                new StyleTableProperties(vertical
                    ? new TableStyleColumnBandSize { Val = 1 }
                    : new TableStyleRowBandSize { Val = 1 }),
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Center }))
                { Type = condition })
            { Type = StyleValues.Table, StyleId = "BandAligned" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        int Expected(int row, int column) => row == 1 && column == columns - 1
            ? 3 : vertical || (row % 2 == 0) == firstBand ? 1 : 0;
        void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var table = Assert.Single(story.Descendants<Table>());
                var actual = table.Elements<TableRow>().SelectMany(row =>
                    row.Elements<TableCell>().Select(cell =>
                        cell.TableCellProperties?.TableCellVerticalAlignment?
                            .Val?.Value ?? TableVerticalAlignmentValues.Top)).ToArray();
                var expected = Enumerable.Range(0, rows).SelectMany(row =>
                    Enumerable.Range(0, columns).Select(column =>
                        Expected(row, column) == 3 ? TableVerticalAlignmentValues.Bottom :
                        Expected(row, column) == 1 ? TableVerticalAlignmentValues.Center :
                        TableVerticalAlignmentValues.Top)).ToArray();
                Assert.Equal(expected, actual);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertAlignments(projected);
        AssertAlignments(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-band-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    for (var row = 0; row < rows; row++)
                        for (var column = 0; column < columns; column++)
                            Assert.Equal(Expected(row, column),
                                (int)table.Cell(row + 1, column + 1).VerticalAlignment);
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.07, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData("corner-row", false)]
    [InlineData("corner-row", true)]
    [InlineData("row-column", false)]
    [InlineData("row-column", true)]
    [InlineData("column-band", false)]
    [InlineData("column-band", true)]
    [InlineData("vertical-horizontal", false)]
    [InlineData("vertical-horizontal", true)]
    [InlineData("corner-column", false)]
    [InlineData("corner-column", true)]
    [InlineData("column-vertical", false)]
    [InlineData("column-vertical", true)]
    [InlineData("corner-vertical", false)]
    [InlineData("corner-vertical", true)]
    [InlineData("row-vertical", false)]
    [InlineData("row-vertical", true)]
    public void OverlappingStyleVerticalAlignmentMatchesWordInAllStories(
        string overlap, bool reverseStyleOrder)
    {
        var higher = overlap switch
        {
            "corner-row" => TableStyleOverrideValues.NorthWestCell,
            "corner-column" => TableStyleOverrideValues.NorthWestCell,
            "corner-vertical" => TableStyleOverrideValues.NorthWestCell,
            "row-column" => TableStyleOverrideValues.FirstRow,
            "row-vertical" => TableStyleOverrideValues.FirstRow,
            "column-band" => TableStyleOverrideValues.FirstColumn,
            "column-vertical" => TableStyleOverrideValues.FirstColumn,
            _ => TableStyleOverrideValues.Band2Vertical
        };
        var lower = overlap switch
        {
            "corner-row" => TableStyleOverrideValues.FirstRow,
            "corner-column" => TableStyleOverrideValues.FirstColumn,
            "corner-vertical" => TableStyleOverrideValues.Band2Vertical,
            "row-column" => TableStyleOverrideValues.FirstColumn,
            "row-vertical" => TableStyleOverrideValues.Band2Vertical,
            "column-band" => TableStyleOverrideValues.Band2Horizontal,
            "column-vertical" => TableStyleOverrideValues.Band2Vertical,
            _ => TableStyleOverrideValues.Band2Horizontal
        };
        var lookMask = overlap switch
        {
            "corner-row" => "00A0",
            "corner-column" => "00A0",
            "corner-vertical" => "0020",
            "row-column" => "00A0",
            "row-vertical" => "0020",
            "column-band" => "0080",
            "column-vertical" => "0080",
            _ => "0000"
        };
        void AssertReusableConditions(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(document.MainDocumentPart!.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), style =>
                    style.StyleName?.Val?.Value == "Overlap aligned");
            foreach (var (condition, alignment) in new[]
            {
                (higher, TableVerticalAlignmentValues.Center),
                (lower, TableVerticalAlignmentValues.Bottom)
            })
                Assert.Equal(alignment,
                    Assert.Single(style.Elements<TableStyleProperties>(), rule =>
                        rule.Type?.Value == condition)
                        .TableStyleConditionalFormattingTableCellProperties?
                        .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
        }
        Table StoryTable(string name)
        {
            var table = new Table(new TableProperties(
                new TableStyle { Val = "OverlapAligned" },
                new TableWidth { Width = "5400", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = lookMask,
                    FirstRow = overlap is "corner-row" or "row-column" or
                        "corner-column" or "corner-vertical" or "row-vertical",
                    LastRow = false,
                    FirstColumn = overlap is "corner-row" or "row-column" or
                        "column-band" or "corner-column" or
                        "column-vertical" or "corner-vertical", LastColumn = false,
                    NoHorizontalBand = overlap is "corner-row" or "row-column" or
                        "corner-column" or "column-vertical" or
                        "corner-vertical" or "row-vertical",
                    NoVerticalBand = overlap is not ("vertical-horizontal" or
                        "column-vertical" or "corner-vertical" or
                        "row-vertical") }),
                new TableGrid(Enumerable.Range(0, 3)
                    .Select(_ => new GridColumn { Width = "1800" })));
            for (var row = 0; row < 3; row++)
            {
                var tableRow = new TableRow(new TableRowProperties(
                    new TableRowHeight
                    { Val = 480, HeightType = HeightRuleValues.Exact }));
                for (var column = 0; column < 3; column++)
                    tableRow.Append(new TableCell(
                        row == 1 && column == 2
                            ? new TableCellProperties(new TableCellVerticalAlignment
                                { Val = TableVerticalAlignmentValues.Top })
                            : new TableCellProperties(),
                        new Paragraph(new Run(new Text($"{name} {row}{column}")))));
                table.Append(tableRow);
            }
            return table;
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var higherRule = new TableStyleProperties(
                new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Center }))
                { Type = higher };
            var lowerRule = new TableStyleProperties(
                new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Bottom }))
                { Type = lower };
            var style = new Style(new StyleName
                { Val = "Overlap aligned" },
                new StyleTableProperties(
                    new TableStyleRowBandSize { Val = 1 },
                    new TableStyleColumnBandSize { Val = 1 }),
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }))
                { Type = StyleValues.Table, StyleId = "OverlapAligned" };
            style.Append(reverseStyleOrder ? lowerRule : higherRule,
                reverseStyleOrder ? higherRule : lowerRule);
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        int Expected(int row, int column)
        {
            if (row == 1 && column == 2) return 0;
            return overlap switch
            {
                "corner-row" => row == 0 ? 3 : 0,
                "corner-column" => row == 0 ? 1 : 3,
                "corner-vertical" => 3,
                "row-column" => row == 0 ? 1 : 3,
                "row-vertical" => row == 0 ? 1 : 3,
                "column-band" => row == 1 ? 3 : 1,
                "column-vertical" => 3,
                _ => row == 1 ? 3 : 1
            };
        }
        void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var table = Assert.Single(story.Descendants<Table>());
                var actual = table.Descendants<TableCell>().Select(cell =>
                    cell.TableCellProperties?.TableCellVerticalAlignment?
                        .Val?.Value ?? TableVerticalAlignmentValues.Top).ToArray();
                var expected = Enumerable.Range(0, 3).SelectMany(row =>
                    Enumerable.Range(0, 3).Select(column =>
                        Expected(row, column) == 1 ? TableVerticalAlignmentValues.Center :
                        Expected(row, column) == 3 ? TableVerticalAlignmentValues.Bottom :
                        TableVerticalAlignmentValues.Top)).ToArray();
                Assert.True(expected.SequenceEqual(actual),
                    $"{overlap}: expected [{string.Join(',', expected.Select(x => x == TableVerticalAlignmentValues.Center ? 1 : x == TableVerticalAlignmentValues.Bottom ? 3 : 0))}], " +
                    $"projected [{string.Join(',', actual.Select(x => x == TableVerticalAlignmentValues.Center ? 1 : x == TableVerticalAlignmentValues.Bottom ? 3 : 0))}]");
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertAlignments(projected);
        AssertReusableConditions(projected);
        var third = DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes;
        AssertAlignments(third);
        AssertReusableConditions(third);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-overlap-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    var actualWord = Enumerable.Range(0, 3).SelectMany(row =>
                        Enumerable.Range(0, 3).Select(column =>
                            (int)table.Cell(row + 1, column + 1).VerticalAlignment))
                        .ToArray();
                    var expectedWord = Enumerable.Range(0, 3).SelectMany(row =>
                        Enumerable.Range(0, 3).Select(column =>
                            Expected(row, column))).ToArray();
                    Assert.True(expectedWord.SequenceEqual(actualWord),
                        $"{overlap}: expected [{string.Join(',', expectedWord)}], " +
                        $"Word [{string.Join(',', actualWord)}]");
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.075, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData("columns", false)]
    [InlineData("columns", true)]
    [InlineData("corners", false)]
    [InlineData("corners", true)]
    [InlineData("south-corners", false)]
    [InlineData("south-corners", true)]
    [InlineData("vertical-bands", false)]
    [InlineData("vertical-bands", true)]
    [InlineData("one-row", false)]
    [InlineData("one-row", true)]
    public void CompetingSameLevelStyleVerticalAlignmentMatchesWordInAllStories(
        string competition, bool reverseStyleOrder)
    {
        var first = competition switch
        {
            "columns" => TableStyleOverrideValues.FirstColumn,
            "corners" => TableStyleOverrideValues.NorthWestCell,
            "south-corners" => TableStyleOverrideValues.SouthWestCell,
            "one-row" => TableStyleOverrideValues.FirstRow,
            _ => TableStyleOverrideValues.Band1Vertical
        };
        var second = competition switch
        {
            "columns" => TableStyleOverrideValues.LastColumn,
            "corners" => TableStyleOverrideValues.NorthEastCell,
            "south-corners" => TableStyleOverrideValues.SouthEastCell,
            "one-row" => TableStyleOverrideValues.LastRow,
            _ => TableStyleOverrideValues.Band2Vertical
        };
        Table StoryTable(string name)
        {
            var table = new Table(
            new TableProperties(new TableStyle { Val = "CompetingAlignment" },
                new TableWidth { Width = "3600", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = competition == "corners" ? "01A0" :
                    competition == "south-corners" ? "01C0" :
                    competition == "one-row" ? "0060" :
                    competition == "columns" ? "0180" : "0000",
                    FirstRow = competition is "corners" or "one-row",
                    LastRow = competition is "south-corners" or "one-row",
                    FirstColumn = competition is not ("vertical-bands" or "one-row"),
                    LastColumn = competition is not ("vertical-bands" or "one-row"),
                    NoHorizontalBand = true,
                    NoVerticalBand = competition != "vertical-bands" }),
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(name + " 00")))),
                new TableCell(new Paragraph(new Run(new Text(name + " 01"))))),
            new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 480, HeightType = HeightRuleValues.Exact }),
                new TableCell(new Paragraph(new Run(new Text(name + " 10")))),
                new TableCell(new TableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                    new Paragraph(new Run(new Text(name + " 11"))))));
            if (competition == "one-row")
            {
                table.Elements<TableRow>().Last().Remove();
                table.Elements<TableRow>().First().Elements<TableCell>().Last()
                    .PrependChild(new TableCellProperties(
                        new TableCellVerticalAlignment
                        { Val = TableVerticalAlignmentValues.Top }));
            }
            return table;
        }
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var style = new Style(new StyleName { Val = "Competing alignment" },
                new StyleTableProperties(new TableStyleColumnBandSize { Val = 1 }),
                new StyleTableCellProperties(new TableCellVerticalAlignment
                    { Val = TableVerticalAlignmentValues.Top }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                            { Val = TableVerticalAlignmentValues.Center }))
                    { Type = first },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new TableCellVerticalAlignment
                            { Val = TableVerticalAlignmentValues.Bottom }))
                    { Type = second })
            { Type = StyleValues.Table, StyleId = "CompetingAlignment" };
            if (reverseStyleOrder)
            {
                var rules = style.Elements<TableStyleProperties>().ToArray();
                foreach (var rule in rules) rule.Remove();
                style.Append(rules[1], rules[0]);
            }
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        int[] Expected() => competition switch
        {
            "corners" => new[] { 3, 3, 0, 0 },
            "south-corners" => new[] { 0, 0, 3, 0 },
            "one-row" => new[] { 1, 0 },
            _ => new[] { 3, 3, 3, 0 }
        };
        void AssertAlignments(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                document.MainDocumentPart!.Document!.Body!,
                document.MainDocumentPart.HeaderParts.Single().Header!,
                document.MainDocumentPart.FooterParts.Single().Footer!
            })
            {
                var actual = story.Descendants<TableCell>().Select(cell =>
                    cell.TableCellProperties?.TableCellVerticalAlignment?
                        .Val?.Value == TableVerticalAlignmentValues.Center ? 1 :
                    cell.TableCellProperties?.TableCellVerticalAlignment?
                        .Val?.Value == TableVerticalAlignmentValues.Bottom ? 3 : 0)
                    .ToArray();
                Assert.Equal(Expected(), actual);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertAlignments(projected);
        AssertAlignments(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordPageRenderClose(source.ToArray(), projected, 0.04, 1, ".docx");
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-competing-valign-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath,
                    ReadOnly: true, AddToRecentFiles: false);
                try
                {
                    dynamic table = opened.Tables.Item(1);
                    var actualWord = Enumerable.Range(1,
                        competition == "one-row" ? 1 : 2).SelectMany(row =>
                        Enumerable.Range(1, 2).Select(column =>
                            (int)table.Cell(row, column).VerticalAlignment)).ToArray();
                    Assert.True(Expected().SequenceEqual(actualWord),
                        $"{competition}: expected [{string.Join(',', Expected())}], " +
                        $"Word [{string.Join(',', actualWord)}]");
                    opened.SaveAs2(nativePath, 0);
                }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            var native = File.ReadAllBytes(nativePath);
            var nativeProjected = DxpDocToDocx.Project(native).DocxBytes;
            AssertAlignments(nativeProjected);
            AssertAlignments(DxpDocToDocx.Project(
                DxpDocExport.Export(nativeProjected)).DocxBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(), native, 0.04);
                AssertWordPageRenderClose(source.ToArray(), nativeProjected, 0.075, 1,
                    ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void MixedFullAndPercentGapRowsKeepOneSharedGrid(bool reverse)
    {
        var beforeUnit = reverse ? TableWidthUnitValues.Auto : TableWidthUnitValues.Pct;
        var afterUnit = reverse ? TableWidthUnitValues.Pct : TableWidthUnitValues.Auto;
        var expectedBefore = reverse ? new DocTablePreferredWidth(1, 0) :
            new DocTablePreferredWidth(2, 2500);
        var expectedAfter = reverse ? new DocTablePreferredWidth(2, 2500) :
            new DocTablePreferredWidth(1, 0);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(Enumerable.Range(0, 4)
                    .Select(_ => new GridColumn { Width = "1200" })),
                new TableRow(Enumerable.Range(0, 4).Select(i =>
                    new TableCell(new Paragraph(new Run(new Text("Full " + i)))))),
                new TableRow(new TableRowProperties(
                    new GridBefore { Val = 1 }, new GridAfter { Val = 1 },
                    new WidthBeforeTableRow
                    { Type = beforeUnit, Width = reverse ? "0" : "2500" },
                    new WidthAfterTableRow
                    { Type = afterUnit, Width = reverse ? "2500" : "0" }),
                    new TableCell(new Paragraph(new Run(new Text("Partial A")))),
                    new TableCell(new Paragraph(new Run(new Text("Partial B"))))))));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var table = Assert.Single(projected.MainDocumentPart!.Document.Body!
            .Elements<Table>());
        Assert.Equal(4, table.TableGrid!.Elements<GridColumn>().Count());
        var rows = table.Elements<TableRow>().ToArray();
        Assert.Equal(2, rows.Length);
        Assert.Null(rows[0].TableRowProperties?.GetFirstChild<GridBefore>());
        Assert.Equal(1, rows[1].TableRowProperties?
            .GetFirstChild<GridBefore>()?.Val?.Value);
        Assert.Equal(1, rows[1].TableRowProperties?
            .GetFirstChild<GridAfter>()?.Val?.Value);
        Assert.Equal(beforeUnit, rows[1].TableRowProperties?
            .GetFirstChild<WidthBeforeTableRow>()?.Type?.Value);
        Assert.Equal(afterUnit, rows[1].TableRowProperties?
            .GetFirstChild<WidthAfterTableRow>()?.Type?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        var rewrittenRows = rewrittenIndex.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).ToArray();
        Assert.Equal(2, rewrittenRows.Length);
        Assert.Contains(rewrittenRows, x =>
            x.Formatting!.TableWidthBefore == expectedBefore &&
            x.Formatting.TableWidthAfter == expectedAfter);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void PercentAndAutoRowGapWidthsSurviveAllStories(bool reverse)
    {
        var beforeUnit = reverse ? TableWidthUnitValues.Auto : TableWidthUnitValues.Pct;
        var afterUnit = reverse ? TableWidthUnitValues.Pct : TableWidthUnitValues.Auto;
        var beforeValue = reverse ? "0" : "2500";
        var afterValue = reverse ? "2500" : "0";
        var expectedBefore = reverse ? new DocTablePreferredWidth(1, 0) :
            new DocTablePreferredWidth(2, 2500);
        var expectedAfter = reverse ? new DocTablePreferredWidth(2, 2500) :
            new DocTablePreferredWidth(1, 0);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Table GapTable(string text) => new(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(Enumerable.Range(0, 4)
                    .Select(_ => new GridColumn { Width = "1200" })),
                new TableRow(new TableRowProperties(
                    new GridBefore { Val = 1 }, new GridAfter { Val = 1 },
                    new WidthBeforeTableRow
                    { Type = beforeUnit, Width = beforeValue },
                    new WidthAfterTableRow
                    { Type = afterUnit, Width = afterValue }),
                    new TableCell(new Paragraph(new Run(new Text(text + " A")))),
                    new TableCell(new Paragraph(new Run(new Text(text + " B"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(GapTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(GapTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(GapTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(binary);
        using var index = new DocTextIndexWalker().Index(input);
        var rows = index.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).ToArray();
        Assert.Equal(3, rows.Length);
        Assert.All(rows, row =>
        {
            Assert.Equal(expectedBefore, row.Formatting!.TableWidthBefore);
            Assert.Equal(expectedAfter, row.Formatting.TableWidthAfter);
        });
        using var projectedStream = new MemoryStream(
            new DocToDocxProjector().Project(index).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            var properties = Assert.Single(table.Elements<TableRow>()).TableRowProperties!;
            Assert.Equal(1, properties.GetFirstChild<GridBefore>()?.Val?.Value);
            Assert.Equal(1, properties.GetFirstChild<GridAfter>()?.Val?.Value);
            Assert.Equal(beforeUnit,
                properties.GetFirstChild<WidthBeforeTableRow>()?.Type?.Value);
            Assert.Equal(beforeValue,
                properties.GetFirstChild<WidthBeforeTableRow>()?.Width?.Value);
            Assert.Equal(afterUnit,
                properties.GetFirstChild<WidthAfterTableRow>()?.Type?.Value);
            Assert.Equal(afterValue,
                properties.GetFirstChild<WidthAfterTableRow>()?.Width?.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        var rewrittenRows = rewrittenIndex.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).ToArray();
        Assert.Equal(3, rewrittenRows.Length);
        Assert.All(rewrittenRows, row =>
        {
            Assert.Equal(expectedBefore, row.Formatting!.TableWidthBefore);
            Assert.Equal(expectedAfter, row.Formatting.TableWidthAfter);
        });
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-row-gap-units-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                Assert.Equal(3, nativeIndex.ParagraphStyles.Count(x =>
                    x.Formatting?.TableTerminator == true));
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void TallCellsKeepTopCenterBottomAlignmentInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Table TallTable(string label)
            {
                var row = new TableRow(new TableRowProperties(new TableRowHeight
                { Val = 1200, HeightType = HeightRuleValues.Exact }));
                foreach (var (alignment, i) in new[]
                {
                    TableVerticalAlignmentValues.Top,
                    TableVerticalAlignmentValues.Center,
                    TableVerticalAlignmentValues.Bottom
                }.Select((alignment, i) => (alignment, i)))
                    row.Append(new TableCell(
                        new TableCellProperties(new TableCellVerticalAlignment
                        { Val = alignment }),
                        new Paragraph(new ParagraphProperties(new SpacingBetweenLines
                        { Line = "280", LineRule = LineSpacingRuleValues.Exact }),
                            new Run(new Text(label + " " + i)))));
                return new Table(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(Enumerable.Range(0, 3)
                    .Select(_ => new GridColumn { Width = "1800" })), row);
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TallTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TallTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(TallTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(generated);
        using var index = new DocTextIndexWalker().Index(input);
        var rows = index.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).ToArray();
        Assert.Equal(3, rows.Length);
        Assert.All(rows, row =>
        {
            Assert.Equal(new byte?[] { 0, 1, 2 },
                row.Formatting!.TableCellVerticalAlignments);
            Assert.Equal((short)-1200, row.Formatting.TableRowHeightTwips);
        });
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(generated).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            Assert.Equal(HeightRuleValues.Exact, table.Elements<TableRow>().Single()
                .TableRowProperties!.GetFirstChild<TableRowHeight>()!.HeightType!.Value);
            Assert.Equal(new[]
            {
                TableVerticalAlignmentValues.Top,
                TableVerticalAlignmentValues.Center,
                TableVerticalAlignmentValues.Bottom
            }, table.Descendants<TableCell>().Select(x => x.TableCellProperties!
                .GetFirstChild<TableCellVerticalAlignment>()!.Val!.Value));
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.Equal(3, rewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.TableTerminator == true &&
            x.Formatting.TableCellVerticalAlignments?.SequenceEqual(
                new byte?[] { 0, 1, 2 }) == true));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-tall-cells-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                var nativeRows = nativeIndex.ParagraphStyles.Where(x =>
                    x.Formatting?.TableTerminator == true).ToArray();
                Assert.Equal(3, nativeRows.Length);
                Assert.All(nativeRows, row => Assert.Equal(new byte?[] { 0, 1, 2 },
                    row.Formatting!.TableCellVerticalAlignments!
                        .Select(x => (byte?)(x ?? 0))));
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                var nativeTables = nativeProjection.MainDocumentPart!.Document.Body!
                    .Elements<Table>().Concat(nativeProjection.MainDocumentPart
                    .HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeProjection.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>())).ToArray();
                Assert.Equal(3, nativeTables.Length);
                Assert.All(nativeTables, table =>
                {
                    Assert.Equal(HeightRuleValues.Exact, table.Elements<TableRow>()
                        .Single().TableRowProperties!
                        .GetFirstChild<TableRowHeight>()!.HeightType!.Value);
                    Assert.Equal(new[]
                    {
                        TableVerticalAlignmentValues.Top,
                        TableVerticalAlignmentValues.Center,
                        TableVerticalAlignmentValues.Bottom
                    }, table.Descendants<TableCell>().Select(x =>
                        x.TableCellProperties?
                            .GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value ??
                        TableVerticalAlignmentValues.Top));
                });
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void PaletteAndRgbCellShadingStayDistinctInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Table ShadedTable(string label) => new(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new Shading
                    {
                        Val = ShadingPatternValues.Percent50,
                        Fill = "FFFFFF", Color = "FF0000"
                    }), new Paragraph(new ParagraphProperties(new SpacingBetweenLines
                    { Line = "280", LineRule = LineSpacingRuleValues.Exact }),
                    new Run(new Text(label + " palette")))),
                    new TableCell(new TableCellProperties(new Shading
                    {
                        Val = ShadingPatternValues.Clear, Fill = "DDEEFF"
                    }), new Paragraph(new ParagraphProperties(new SpacingBetweenLines
                    { Line = "280", LineRule = LineSpacingRuleValues.Exact }),
                    new Run(new Text(label + " RGB"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(ShadedTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(ShadedTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(ShadedTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(generated);
        using var index = new DocTextIndexWalker().Index(input);
        var rows = index.ParagraphStyles.Where(x =>
            x.Formatting?.TableTerminator == true).ToArray();
        Assert.Equal(3, rows.Length);
        Assert.All(rows, row =>
        {
            Assert.Equal((ushort)8, row.Formatting!.TableCellShadings![0]!.Pattern);
            Assert.Equal(0xFFFFFFu, row.Formatting.TableCellShadings[0]!.FillRgb);
            Assert.Equal(0x0000FFu, row.Formatting.TableCellShadings[0]!.ForegroundRgb);
            Assert.Equal(0xFFEEDDu, row.Formatting.TableCellShadings[1]!.FillRgb);
        });
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(generated).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            var cells = table.Descendants<TableCell>().ToArray();
            Assert.Equal("FFFFFF", cells[0].TableCellProperties!
                .GetFirstChild<Shading>()!.Fill!.Value);
            Assert.Equal("FF0000", cells[0].TableCellProperties!
                .GetFirstChild<Shading>()!.Color!.Value);
            Assert.Equal("DDEEFF", cells[1].TableCellProperties!
                .GetFirstChild<Shading>()!.Fill!.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.Equal(3, rewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.TableTerminator == true &&
            x.Formatting.TableCellShadings?[0]?.Pattern == 8 &&
            x.Formatting.TableCellShadings[1]?.FillRgb == 0xFFEEDDu));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-palette-cell-shading-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
            var nativeDocxPath = Path.ChangeExtension(sourcePath, ".native.docx");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, generated);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(nativePath, ReadOnly: true,
                    AddToRecentFiles: false);
                static int[] WordShadingColors(dynamic document)
                {
                    var tables = new dynamic[]
                    {
                        document.Tables.Item(1),
                        document.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                        document.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                    };
                    var colors = new List<int>();
                    foreach (var table in tables)
                    for (var cell = 1; cell <= 2; cell++)
                    {
                        colors.Add((int)table.Cell(1, cell).Shading.BackgroundPatternColor);
                        colors.Add((int)table.Cell(1, cell).Shading.ForegroundPatternColor);
                        colors.Add((int)table.Cell(1, cell).Shading.Texture);
                    }
                    return colors.ToArray();
                }
                var nativeColors = WordShadingColors(opened);
                static string[] WordGeometry(dynamic document)
                {
                    var tables = new dynamic[]
                    {
                        document.Tables.Item(1),
                        document.Sections.Item(1).Headers.Item(1).Range.Tables.Item(1),
                        document.Sections.Item(1).Footers.Item(1).Range.Tables.Item(1)
                    };
                    return tables.Select(table => string.Join(",",
                        (double)table.Rows.LeftIndent,
                        (double)table.Cell(1, 1).Width,
                        (double)table.Cell(1, 2).Width,
                        (double)table.Cell(1, 1).LeftPadding,
                        (double)table.Cell(1, 1).RightPadding,
                        (double)table.Cell(1, 2).LeftPadding,
                        (double)table.Cell(1, 2).RightPadding,
                        (string)table.Cell(1, 1).Range.Font.Name,
                        (double)table.Cell(1, 1).Range.Font.Size,
                        (double)table.Cell(1, 1).Range.ParagraphFormat.SpaceAfter,
                        (double)table.Cell(1, 1).Range.ParagraphFormat.LineSpacing,
                        (double)table.Range.Information(6))).ToArray();
                }
                var nativeGeometry = WordGeometry(opened);
                opened.SaveAs2(nativeDocxPath, 16);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(nativeColors, WordShadingColors(opened));
                var generatedGeometry = WordGeometry(opened);
                Assert.True(nativeGeometry.SequenceEqual(generatedGeometry),
                    "native: " + string.Join("|", nativeGeometry) +
                    " generated: " + string.Join("|", generatedGeometry));
                opened.Close(false);
                opened = null;
                AssertWordFirstPageRenderClose(source.ToArray(),
                    File.ReadAllBytes(nativePath), 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
                AssertWordFirstPageRenderClose(File.ReadAllBytes(nativeDocxPath),
                    generated, 0.015);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(nativePath);
                File.Delete(generatedPath);
                File.Delete(nativeDocxPath);
            }
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void RotatedTableCellTextSurvivesDocAndProjection(
        bool eastAsian, bool autoFit)
    {
        var firstDirection = eastAsian
            ? TextDirectionValues.LefttoRightTopToBottomRotated
            : TextDirectionValues.TopToBottomRightToLeft;
        var secondDirection = eastAsian
            ? TextDirectionValues.TopToBottomRightToLeftRotated
            : TextDirectionValues.BottomToTopLeftToRight;
        ushort?[] expectedFlows = eastAsian ? [4, 5, null] : [1, 3, null];
        Table MakeTable() => new(
            new TableProperties(
                new TableWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                    TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "7200" },
                new TableLayout { Type = autoFit ? TableLayoutValues.Autofit :
                    TableLayoutValues.Fixed }),
            new TableGrid(new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" }),
            new TableRow(
                new TableCell(new TableCellProperties(
                    new TableCellWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                        TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "2400" },
                    new TextDirection
                    { Val = firstDirection }),
                    new Paragraph(new Run(
                        eastAsian ? new RunProperties(new RunFonts
                            { Ascii = "MS Mincho", HighAnsi = "MS Mincho",
                                EastAsia = "MS Mincho" }) : new RunProperties(),
                        new Text(eastAsian ? "東西" : "Clockwise")))),
                new TableCell(new TableCellProperties(
                    new TableCellWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                        TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "2400" },
                    new TextDirection
                    { Val = secondDirection }),
                    new Paragraph(new Run(
                        eastAsian ? new RunProperties(new RunFonts
                            { Ascii = "MS Mincho", HighAnsi = "MS Mincho",
                                EastAsia = "MS Mincho" }) : new RunProperties(),
                        new Text(eastAsian ? "南北" : "Counterclockwise")))),
                new TableCell(new TableCellProperties(
                    new TableCellWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                        TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "2400" }),
                    new Paragraph(new Run(new Text("Normal"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MakeTable());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MakeTable());
            footer.Footer.Save();
            main.Document = new Document(new Body(MakeTable(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var doc = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(doc);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Equal(3, index.ParagraphStyles.Count(x =>
            x.Formatting?.TableCellTextFlows?.SequenceEqual(expectedFlows) == true));
        var projection = DxpDocToDocx.Project(doc);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table => Assert.Equal(new[]
        {
            firstDirection,
            secondDirection
        }, table.Descendants<TableCell>().Take(2).Select(x =>
            x.TableCellProperties!.GetFirstChild<TextDirection>()!.Val!.Value)));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projection.DocxBytes);
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.Equal(3, rewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.TableCellTextFlows?.SequenceEqual(expectedFlows) == true));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-cell-direction-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            var generatedPath = Path.Combine(Path.GetTempPath(),
                $"docxport-cell-direction-generated-{Guid.NewGuid():N}.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, doc);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                var sourceOrientations = new[]
                {
                    (int)opened.Tables.Item(1).Cell(1, 1).Range.Orientation,
                    (int)opened.Tables.Item(1).Cell(1, 2).Range.Orientation
                };
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(generatedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(sourceOrientations, new[]
                {
                    (int)opened.Tables.Item(1).Cell(1, 1).Range.Orientation,
                    (int)opened.Tables.Item(1).Cell(1, 2).Range.Orientation
                });
                opened.Close(false);
                opened = null;
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                Assert.Equal(3, nativeIndex.ParagraphStyles.Count(x =>
                    x.Formatting?.TableCellTextFlows?.SequenceEqual(expectedFlows) == true));
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                var nativeTables = nativeProjection.MainDocumentPart!.Document.Body!
                    .Elements<Table>().Concat(nativeProjection.MainDocumentPart.HeaderParts
                        .SelectMany(x => x.Header!.Elements<Table>()))
                    .Concat(nativeProjection.MainDocumentPart.FooterParts
                        .SelectMany(x => x.Footer!.Elements<Table>()))
                    .ToArray();
                Assert.Equal(3, nativeTables.Length);
                Assert.All(nativeTables, table => Assert.Equal(new[]
                {
                    firstDirection,
                    secondDirection
                }, table.Descendants<TableCell>().Take(2).Select(x =>
                    x.TableCellProperties!.GetFirstChild<TextDirection>()!.Val!.Value)));
                if (!autoFit)
                {
                    AssertWordFirstPageRenderClose(source.ToArray(), doc, 0.04);
                    AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                        0.04, 1, ".docx");
                    AssertWordFirstPageRenderClose(source.ToArray(), rewritten, 0.04);
                }
                else
                {
                    AssertWordFirstPageRenderClose(source.ToArray(), doc, 0.07);
                    AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                        0.07, 1, ".docx");
                    AssertWordFirstPageRenderClose(source.ToArray(), rewritten, 0.07);
                }
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
                File.Delete(generatedPath);
            }
        }
    }

    [Theory]
    [MemberData(nameof(MappedParagraphShadingPatterns))]
    public void MappedCellShadingPatternsSurviveAllStories(
        ShadingPatternValues pattern, ushort docPattern)
    {
        Table ShadedTable(string text) => new(
            new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed },
                new TableIndentation { Width = 108,
                    Type = TableWidthUnitValues.Dxa },
                new TableCellMarginDefault(
                    new TableCellLeftMargin { Width = 108,
                        Type = TableWidthValues.Dxa },
                    new TableCellRightMargin { Width = 108,
                        Type = TableWidthValues.Dxa })),
            new TableGrid(new GridColumn { Width = "4000" }),
            new TableRow(new TableCell(new TableCellProperties(new Shading
                { Val = pattern, Fill = "FFFFFF", Color = "FF0000" }),
                new Paragraph(new ParagraphProperties(new SpacingBetweenLines
                    { Line = "280", LineRule = LineSpacingRuleValues.Exact }),
                    new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(ShadedTable("Pattern header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(ShadedTable("Pattern footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(ShadedTable("Pattern body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Equal(3, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellShadings?[0]?.Pattern == docPattern &&
                x.Formatting.TableCellShadings[0]!.FillRgb == 0xFFFFFFu &&
                x.Formatting.TableCellShadings[0]!.ForegroundRgb ==
                    0x0000FFu));
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            var cells = projected.MainDocumentPart!.Document.Body!
                .Descendants<TableCell>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Descendants<TableCell>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Descendants<TableCell>())).ToArray();
            Assert.Equal(3, cells.Length);
            Assert.All(cells, cell =>
            {
                var shade = cell.TableCellProperties!.GetFirstChild<Shading>()!;
                Assert.Equal(pattern, shade.Val!.Value);
                Assert.Equal("FFFFFF", shade.Fill!.Value);
                Assert.Equal("FF0000", shade.Color!.Value);
            });
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-native-cell-pattern-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, original);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var input = new MemoryStream(binary);
                using var index = new DocTextIndexWalker().Index(input);
                Assert.Equal(3, index.ParagraphStyles.Count(x =>
                    x.Formatting?.TableTerminator == true &&
                    x.Formatting.TableCellShadings?[0]?.Pattern == docPattern));
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(binary).DocxBytes);
                using var projected = WordprocessingDocument.Open(
                    projectedStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                AssertWordPageRenderClose(original, projectedStream.ToArray(),
                    0.04, 1, ".docx");
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

