    private static void VerifyMappedConditionalTableStyleShadingSurvivesAllStories(
        ShadingPatternValues pattern, ushort docPattern,
        TableStyleOverrideValues region)
    {
        var cornerRegion = region == TableStyleOverrideValues.NorthWestCell ||
            region == TableStyleOverrideValues.NorthEastCell ||
            region == TableStyleOverrideValues.SouthWestCell ||
            region == TableStyleOverrideValues.SouthEastCell;
        var horizontalBandRegion = region == TableStyleOverrideValues.Band1Horizontal ||
            region == TableStyleOverrideValues.Band2Horizontal;
        var verticalBandRegion = region == TableStyleOverrideValues.Band1Vertical ||
            region == TableStyleOverrideValues.Band2Vertical;
        var columnRegion = cornerRegion || horizontalBandRegion ||
            verticalBandRegion ||
            region == TableStyleOverrideValues.FirstColumn ||
            region == TableStyleOverrideValues.LastColumn;
        var firstRowRegion = region == TableStyleOverrideValues.FirstRow ||
            region == TableStyleOverrideValues.NorthWestCell ||
            region == TableStyleOverrideValues.NorthEastCell;
        var lastRowRegion = region == TableStyleOverrideValues.LastRow ||
            region == TableStyleOverrideValues.SouthWestCell ||
            region == TableStyleOverrideValues.SouthEastCell ||
            region == TableStyleOverrideValues.Band2Horizontal;
        var firstColumnRegion = region == TableStyleOverrideValues.FirstColumn ||
            region == TableStyleOverrideValues.NorthWestCell ||
            region == TableStyleOverrideValues.SouthWestCell;
        var lastColumnRegion = region == TableStyleOverrideValues.LastColumn ||
            region == TableStyleOverrideValues.NorthEastCell ||
            region == TableStyleOverrideValues.SouthEastCell ||
            region == TableStyleOverrideValues.Band2Vertical;
        Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "PatternTable" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "4000" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = horizontalBandRegion || verticalBandRegion
                        ? "07E0" : null, FirstRow = firstRowRegion,
                    LastRow = lastRowRegion,
                    FirstColumn = firstColumnRegion,
                    LastColumn = lastColumnRegion,
                    NoHorizontalBand = horizontalBandRegion ? false : null,
                    NoVerticalBand = verticalBandRegion ? false : null }),
            columnRegion
                ? new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" })
                : new TableGrid(new GridColumn { Width = "4000" }),
            new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(text + " first")))),
                columnRegion ? new TableCell(new Paragraph(new Run(
                    new Text(text + " right")))) : null),
            new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(text + " second")))),
                columnRegion ? new TableCell(new Paragraph(new Run(
                    new Text(text + " lower right")))) : null));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(
                new StyleName { Val = "Pattern table" },
                horizontalBandRegion
                    ? new StyleTableProperties(new TableStyleRowBandSize { Val = 1 })
                    : verticalBandRegion
                        ? new StyleTableProperties(new TableStyleColumnBandSize { Val = 1 })
                        : null,
                new StyleTableCellProperties(new Shading
                    { Val = ShadingPatternValues.Percent50,
                        Fill = "E2F0D9", Color = "548235" }),
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading { Val = pattern, Fill = "FFFFFF",
                            Color = "FF0000" }))
                    { Type = region })
                { Type = StyleValues.Table, StyleId = "PatternTable" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Pattern header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Pattern footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Pattern body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        if (horizontalBandRegion || verticalBandRegion)
        {
            using var sourceDoc = WordprocessingDocument.Open(
                new MemoryStream(original), false);
            var sourceStyle = sourceDoc.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>().Single();
            Assert.Equal(1, horizontalBandRegion
                ? sourceStyle.StyleTableProperties?.GetFirstChild<TableStyleRowBandSize>()?
                    .Val?.Value
                : sourceStyle.StyleTableProperties?.GetFirstChild<TableStyleColumnBandSize>()?
                    .Val?.Value);
        }
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Pattern table");
            Assert.Equal((ushort)8, style.TableFormatting?.TableStyleShading?.Pattern);
            if (horizontalBandRegion)
                Assert.Equal((byte)1, style.TableFormatting?.TableHorizontalBandSize);
            if (verticalBandRegion)
                Assert.Equal((byte)1, style.TableFormatting?.TableVerticalBandSize);
            Assert.Contains(style.ConditionalTableShading?.Values ?? [],
                shade => shade.Pattern == docPattern &&
                    shade.FillRgb == 0xFFFFFFu &&
                    shade.ForegroundRgb == 0x0000FFu);
            if (horizontalBandRegion || verticalBandRegion)
                Assert.True(index.ParagraphStyles.Count(x =>
                    x.Formatting?.TableTerminator == true &&
                    x.Formatting.TableCellShadings?.Any(shade =>
                        shade?.Pattern == docPattern &&
                        shade.FillRgb == 0xFFFFFFu) == true) >= 3,
                    string.Join("; ", index.ParagraphStyles.Where(x =>
                        x.Formatting?.TableTerminator == true).Select(x =>
                        $"look={x.Formatting?.TableLookMask:X4} bands={string.Join(",", x.Formatting?.TableCellShadings?.Select(s => s?.Pattern.ToString() ?? "null") ?? [])}")));
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            var projectedStyle = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "Pattern table");
            Assert.Equal(ShadingPatternValues.Percent50,
                projectedStyle.StyleTableCellProperties!.Shading!.Val!.Value);
            if (horizontalBandRegion)
                Assert.Equal(1, projectedStyle.StyleTableProperties?
                    .GetFirstChild<TableStyleRowBandSize>()?.Val?.Value);
            if (verticalBandRegion)
                Assert.Equal(1, projectedStyle.StyleTableProperties?
                    .GetFirstChild<TableStyleColumnBandSize>()?.Val?.Value);
            var conditionalRow = Assert.Single(projectedStyle
                .Elements<TableStyleProperties>(), x =>
                    x.Type?.Value == region);
            var shade = conditionalRow.TableStyleConditionalFormattingTableCellProperties!
                .GetFirstChild<Shading>()!;
            Assert.Equal(pattern, shade.Val!.Value);
            Assert.Equal("FFFFFF", shade.Fill!.Value);
            Assert.Equal("FF0000", shade.Color!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-native-conditional-pattern-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, original);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            if (pattern == ShadingPatternValues.Clear &&
                (horizontalBandRegion || verticalBandRegion))
            {
                var rowNumber = region == TableStyleOverrideValues.Band2Horizontal
                    ? 2 : 1;
                var columnNumber = region == TableStyleOverrideValues.Band2Vertical
                    ? 2 : 1;
                foreach (dynamic storyTable in new dynamic[]
                {
                    opened.Tables.Item(1),
                    opened.Sections(1).Headers(1).Range.Tables.Item(1),
                    opened.Sections(1).Footers(1).Range.Tables.Item(1)
                })
                    Assert.Equal(0xFFFFFF, (int)storyTable.Cell(rowNumber,
                        columnNumber).Shading.BackgroundPatternColor & 0xFFFFFF);
            }
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(binary).DocxBytes);
                using var projected = WordprocessingDocument.Open(
                    projectedStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                var nativeRule = projected.MainDocumentPart!
                    .StyleDefinitionsPart?.Styles?.Elements<Style>()
                    .SelectMany(x => x.Elements<TableStyleProperties>())
                    .Any(x => x.Type?.Value == region &&
                        x.TableStyleConditionalFormattingTableCellProperties?
                            .Shading?.Val?.Value == pattern) == true;
                foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    projected.MainDocumentPart.Document.Body!,
                    projected.MainDocumentPart.HeaderParts.Single(x =>
                        x.Header?.InnerText.Contains("Pattern header") == true).Header!,
                    projected.MainDocumentPart.FooterParts.Single(x =>
                        x.Footer?.InnerText.Contains("Pattern footer") == true).Footer!
                })
                {
                    var table = Assert.Single(story.Descendants<Table>());
                    var conditionalRow = lastRowRegion
                        ? table.Elements<TableRow>().Last()
                        : table.Elements<TableRow>().First();
                    var conditionalCell = lastColumnRegion
                        ? conditionalRow.Elements<TableCell>().Last()
                        : conditionalRow.Elements<TableCell>().First();
                    Assert.True(nativeRule ||
                        conditionalCell.TableCellProperties?.Shading?.Val?.Value == pattern);
                }
                AssertWordPageRenderClose(original, projectedStream.ToArray(),
                    0.04, 1, ".docx");
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

