    private static void VerifyOverlappingTableStyleShadingRetainsVisiblePrecedence(
        bool reverseRules, TableStyleOverrideValues variedRegion,
        ShadingPatternValues variedPattern,
        ushort docPattern, bool mixedBands = false, bool bandSizeTwo = false,
        bool bothLastEdges = false)
    {
        var southeastSweep = variedRegion == TableStyleOverrideValues.SouthEastCell;
        var bandSweep = variedRegion == TableStyleOverrideValues.Band2Horizontal;
        var verticalBandSweep = variedRegion == TableStyleOverrideValues.Band1Vertical;
        var lastRowSweep = variedRegion == TableStyleOverrideValues.LastRow ||
            bothLastEdges || southeastSweep;
        var lastColumnSweep = variedRegion == TableStyleOverrideValues.LastColumn ||
            bothLastEdges || southeastSweep;
        var horizontalBandsEnabled = bandSweep || mixedBands;
        var variedFill = southeastSweep ? 0xD2B694u :
            variedRegion == TableStyleOverrideValues.FirstRow
            ? 0x83B1F4u : variedRegion == TableStyleOverrideValues.FirstColumn
                ? 0xE6C39Du : bandSweep
                    ? 0xCCF2FFu : verticalBandSweep
                        ? 0xE7C6B4u : lastRowSweep ? 0xF8DAC9u : lastColumnSweep ? 0xD6A7B4u : 0x8ED1A9u;
        var variedCell = bandSweep || lastColumnSweep
            ? 2 : variedRegion == TableStyleOverrideValues.FirstRow ||
                verticalBandSweep || lastRowSweep ? 1 : 0;
        var expectedRows = bandSizeTwo ? 12 : bothLastEdges || southeastSweep ? 3 :
            variedRegion == TableStyleOverrideValues.FirstColumn ||
            verticalBandSweep || lastColumnSweep ? 6 : 3;
        static TableStyleProperties Rule(TableStyleOverrideValues kind,
            string fill, ShadingPatternValues pattern) => new(
            new TableStyleConditionalFormattingTableCellProperties(new Shading
                { Val = pattern, Fill = fill, Color = "FF0000" }))
            { Type = kind };
        Table WideStoryTable(string story)
        {
            var table = new Table(
                new TableProperties(new TableStyle { Val = "OverlapShade" },
                    new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "9000" },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableLook { Val = "07E0", FirstRow = true,
                        LastRow = lastRowSweep, FirstColumn = true,
                        LastColumn = lastColumnSweep, NoHorizontalBand = false,
                        NoVerticalBand = false }),
                new TableGrid(Enumerable.Range(0, 5).Select(_ =>
                    new GridColumn { Width = "1800" })));
            for (var row = 0; row < 5; row++)
            {
                var cells = new TableRow();
                for (var column = 0; column < 5; column++)
                {
                    var cell = new TableCell();
                    if (row == 0 && column == 4)
                        cell.Append(new TableCellProperties(new Shading
                        { Val = ShadingPatternValues.Clear, Fill = "CC99FF" }));
                    cell.Append(new Paragraph(new Run(new Text(
                        $"{story} {row}{column}"))));
                    cells.Append(cell);
                }
                table.Append(cells);
            }
            return table;
        }
        Table StoryTable(string story) => bandSizeTwo ? WideStoryTable(story) : new(
            new TableProperties(new TableStyle { Val = "OverlapShade" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "6000" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "07E0", FirstRow = true,
                    LastRow = lastRowSweep, FirstColumn = true,
                    LastColumn = lastColumnSweep, NoHorizontalBand = false,
                    NoVerticalBand = false }),
            new TableGrid(new GridColumn { Width = "2000" },
                new GridColumn { Width = "2000" },
                new GridColumn { Width = "2000" }),
            new TableRow(new TableCell(new Paragraph(new Run(
                    new Text(story + " northwest")))),
                new TableCell(new Paragraph(new Run(new Text("top")))),
                new TableCell(new TableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "CC99FF" }),
                    new Paragraph(new Run(new Text("direct"))))),
            new TableRow(new TableCell(new Paragraph(new Run(
                    new Text("column")))),
                new TableCell(new Paragraph(new Run(new Text("band")))),
                new TableCell(new Paragraph(new Run(new Text("band right"))))),
            new TableRow(new TableCell(new Paragraph(new Run(
                    new Text("column bottom")))),
                new TableCell(new Paragraph(new Run(new Text("bottom")))),
                new TableCell(new Paragraph(new Run(new Text("bottom right"))))));
        var rules = new List<TableStyleProperties>
        {
            Rule(TableStyleOverrideValues.Band1Horizontal,
                horizontalBandsEnabled ? "FCE4D6" : "FFF2CC",
                ShadingPatternValues.Clear),
            Rule(TableStyleOverrideValues.Band1Vertical, "B4C6E7",
                verticalBandSweep ? variedPattern : ShadingPatternValues.Clear),
            Rule(TableStyleOverrideValues.FirstColumn, "9DC3E6",
                variedRegion == TableStyleOverrideValues.FirstColumn
                    ? variedPattern : ShadingPatternValues.Clear),
            Rule(TableStyleOverrideValues.FirstRow, "F4B183",
                variedRegion == TableStyleOverrideValues.FirstRow
                    ? variedPattern : ShadingPatternValues.Clear),
            Rule(TableStyleOverrideValues.NorthWestCell, "A9D18E",
                variedRegion == TableStyleOverrideValues.NorthWestCell
                    ? variedPattern : ShadingPatternValues.Clear)
        };
        if (lastRowSweep)
            rules.Add(Rule(TableStyleOverrideValues.LastRow, "C9DAF8",
                southeastSweep ? ShadingPatternValues.Clear : variedPattern));
        if (lastColumnSweep)
            rules.Add(Rule(TableStyleOverrideValues.LastColumn, "B4A7D6",
                bothLastEdges || southeastSweep ? ShadingPatternValues.Clear : variedPattern));
        if (southeastSweep)
            rules.Add(Rule(TableStyleOverrideValues.SouthEastCell, "94B6D2",
                variedPattern));
        if (horizontalBandsEnabled)
            rules.Insert(1, Rule(TableStyleOverrideValues.Band2Horizontal,
                "FFF2CC", bandSweep ? variedPattern : ShadingPatternValues.Clear));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var style = new Style(new StyleName { Val = "Overlap shade" },
                horizontalBandsEnabled ? new StyleTableProperties(
                    new TableStyleRowBandSize { Val = bandSizeTwo ? 2 : 1 },
                    new TableStyleColumnBandSize { Val = bandSizeTwo ? 2 : 1 }) :
                    verticalBandSweep ? new StyleTableProperties(
                        new TableStyleColumnBandSize { Val = 1 }) : null,
                new StyleTableCellProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "E7E6E6" }))
                { Type = StyleValues.Table, StyleId = "OverlapShade" };
            foreach (var rule in reverseRules ? rules.AsEnumerable().Reverse() : rules)
                style.Append(rule);
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Overlap shade");
            Assert.Equal((horizontalBandsEnabled ? 6 : 5) +
                (lastRowSweep ? 1 : 0) + (lastColumnSweep ? 1 : 0) +
                (southeastSweep ? 1 : 0),
                style.ConditionalTableShading?.Count);
            Assert.Contains(style.ConditionalTableShading?.Values ?? [], shade =>
                shade.Pattern == docPattern && shade.FillRgb == variedFill &&
                shade.ForegroundRgb == 0x0000FFu);
            Assert.Equal(expectedRows, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellShadings?[variedCell] is { } shade &&
                shade.Pattern == docPattern && shade.FillRgb == variedFill));
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-overlap-shade-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var projectedPath = Path.ChangeExtension(sourcePath, ".projected.docx");
        File.WriteAllBytes(sourcePath, original);
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            int[][] ReadColors(dynamic document)
            {
                var tables = new[]
                {
                    document.Tables.Item(1),
                    document.Sections(1).Headers(1).Range.Tables.Item(1),
                    document.Sections(1).Footers(1).Range.Tables.Item(1)
                };
                return tables.Select(table =>
                    Enumerable.Range(1, bandSizeTwo ? 5 : 3).SelectMany(row =>
                        Enumerable.Range(1, bandSizeTwo ? 5 : 3).Select(column =>
                            (int)table.Cell(row, column).Shading
                                .BackgroundPatternColor)).ToArray()).ToArray();
            }
            string ReadLayout(dynamic document)
            {
                var tables = new[]
                {
                    document.Tables.Item(1),
                    document.Sections(1).Headers(1).Range.Tables.Item(1),
                    document.Sections(1).Footers(1).Range.Tables.Item(1)
                };
                return string.Join(" | ", tables.Select(table =>
                    $"indent={table.Rows.Item(1).LeftIndent}," +
                    $"widths={string.Join("/", Enumerable.Range(1,
                        bandSizeTwo ? 5 : 3).Select(column =>
                        table.Cell(1, column).Width))}," +
                    $"padding={table.LeftPadding}/{table.RightPadding}"));
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var sourceColors = ReadColors(opened);
            var sourceLayout = ReadLayout(opened);
            opened.SaveAs2(nativePath, 0);
            var nativeLayout = ReadLayout(opened);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            var generatedColors = ReadColors(opened);
            for (var story = 0; story < 3; story++)
                Assert.Equal(sourceColors[story], generatedColors[story]);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            var nativeError = AssertWordFirstPageRenderClose(original, native, 0.06);
            using var nativeInput = new MemoryStream(native);
            using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
            var nativeRow = nativeIndex.ParagraphStyles.First(x =>
                x.Formatting?.TableTerminator == true).Formatting!;
            var nativeStyle = nativeIndex.StyleDefinitions.FirstOrDefault(x =>
                x.Index == nativeRow.TableStyleIndex);
            var nativeFormatting = $"row margins={nativeRow.TableDefaultCellMargins}," +
                $" indent={nativeRow.TableIndentTwips}," +
                $" origin={nativeRow.TableRowOriginTwips}," +
                $" style={nativeStyle?.Name}," +
                $" style margins={nativeStyle?.TableFormatting?.TableDefaultCellMargins}";
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(binary).DocxBytes);
                using var projected = WordprocessingDocument.Open(
                    projectedStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                File.WriteAllBytes(projectedPath, projectedStream.ToArray());
                opened = word.Documents.Open(projectedPath, ReadOnly: true,
                    AddToRecentFiles: false);
                var projectedColors = ReadColors(opened);
                for (var story = 0; story < 3; story++)
                    Assert.Equal(sourceColors[story], projectedColors[story]);
                var projectedLayout = ReadLayout(opened);
                Assert.True(projectedLayout == nativeLayout,
                    $"Source: {sourceLayout}; native: {nativeLayout}; projected: {projectedLayout}; {nativeFormatting}");
                opened.Close(false);
                opened = null;
                var projectedError = AssertWordPageRenderClose(original,
                    projectedStream.ToArray(), 0.06, 1, ".docx");
                Assert.InRange(Math.Abs(projectedError - nativeError), 0, 0.005);
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            File.Delete(projectedPath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void SingleColumnFirstAndLastStyleShadingMatchesWord(
        bool reverseRules)
    {
        Table StoryTable(string text) => new(
            new TableProperties(new TableStyle { Val = "BothColumnsShade" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "3000" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = "07E0", FirstColumn = true,
                    LastColumn = true }),
            new TableGrid(new GridColumn { Width = "3000" }),
            new TableRow(new TableCell(new Paragraph(new Run(
                new Text(text + " first"))))),
            new TableRow(new TableCell(new Paragraph(new Run(
                new Text(text + " second"))))));
        static TableStyleProperties ColumnRule(TableStyleOverrideValues kind,
            string fill) => new(
            new TableStyleConditionalFormattingTableCellProperties(new Shading
                { Val = ShadingPatternValues.Clear, Fill = fill }))
            { Type = kind };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var style = new Style(new StyleName { Val = "Both columns shade" })
                { Type = StyleValues.Table, StyleId = "BothColumnsShade" };
            var rules = new[]
            {
                ColumnRule(TableStyleOverrideValues.FirstColumn, "9DC3E6"),
                ColumnRule(TableStyleOverrideValues.LastColumn, "F4B183")
            };
            foreach (var rule in reverseRules ? rules.Reverse() : rules)
                style.Append(rule);
            styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Equal(2, Assert.Single(index.StyleDefinitions,
                x => x.Name == "Both columns shade")
                .ConditionalTableShading?.Count);
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-one-column-shade-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, original);
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            int[] Colors(dynamic document) => new[]
            {
                (int)document.Tables.Item(1).Cell(1, 1).Shading.BackgroundPatternColor,
                (int)document.Sections(1).Headers(1).Range.Tables.Item(1)
                    .Cell(1, 1).Shading.BackgroundPatternColor,
                (int)document.Sections(1).Footers(1).Range.Tables.Item(1)
                    .Cell(1, 1).Shading.BackgroundPatternColor
            };
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var expected = Colors(opened);
            Assert.True(expected[0] == 0xE6C39D,
                $"Word's one-column style color is 0x{expected[0]:X6}.");
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(binary).DocxBytes);
                using var projected = WordprocessingDocument.Open(
                    projectedStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                AssertWordPageRenderClose(original, projectedStream.ToArray(),
                    0.04, 1, ".docx");
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

