                    .Cell(2, 1).Shading.BackgroundPatternColor
            };
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var expected = Colors(opened);
            Assert.Equal(new[] { 0xE6C39D, 0x8ED1A9,
                0xE6C39D, 0x8ED1A9, 0xE6C39D, 0x8ED1A9 }, expected);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, Colors(opened));
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(binary).DocxBytes);
                using var projected = WordprocessingDocument.Open(
                    projectedStream, false);
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                AssertWordPageRenderClose(original, projectedStream.ToArray(),
                    0.04, 1, ".docx");
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData("tb", 0)]
    [InlineData("rl", 1)]
    [InlineData("lr", 3)]
    [InlineData("tbV", 4)]
    [InlineData("rlV", 5)]
    public void EquivalentTableCellDirectionsSurviveAllStories(
        string value, ushort expectedFlow)
    {
        var direction = new TextDirectionValues(value);
        var canonical = expectedFlow switch
        {
            0 => TextDirectionValues.LefToRightTopToBottom,
            1 => TextDirectionValues.TopToBottomRightToLeft,
            3 => TextDirectionValues.BottomToTopLeftToRight,
            4 => TextDirectionValues.LefttoRightTopToBottomRotated,
            _ => TextDirectionValues.TopToBottomRightToLeftRotated
        };
        Table MakeTable(string text) => new(
            new TableProperties(new TableWidth
                { Type = TableWidthUnitValues.Dxa, Width = "3000" },
                new TableLayout { Type = TableLayoutValues.Fixed }),
            new TableGrid(new GridColumn { Width = "3000" }),
            new TableRow(new TableCell(new TableCellProperties(
                new TableCellWidth { Type = TableWidthUnitValues.Dxa,
                    Width = "3000" },
                new TextDirection { Val = direction }),
                new Paragraph(new Run(new Text(text))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MakeTable("Direction header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MakeTable("Direction footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(MakeTable("Direction body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.True(index.ParagraphStyles.Count(x =>
                x.Formatting?.TableCellTextFlows?.Contains(expectedFlow) == true)
                >= 3);
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            var cells = projected.MainDocumentPart!.Document.Body!
                .Descendants<TableCell>()
                .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Descendants<TableCell>()))
                .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Descendants<TableCell>())).ToArray();
            Assert.Equal(3, cells.Length);
            Assert.All(cells, cell => Assert.Equal(canonical,
                cell.TableCellProperties!.GetFirstChild<TextDirection>()!
                    .Val!.Value));
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-cell-flow-alias-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, original);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            using var nativeInput = new MemoryStream(native);
            using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
            if (expectedFlow == 0)
                Assert.DoesNotContain(nativeIndex.ParagraphStyles, x =>
                    x.Formatting?.TableCellTextFlows?.Any(flow =>
                        flow is not null and not 0) == true);
            else
                Assert.True(nativeIndex.ParagraphStyles.Count(x =>
                    x.Formatting?.TableCellTextFlows?.Contains(expectedFlow) == true)
                    >= 3);
            using var nativeProjectionStream = new MemoryStream(
                DxpDocToDocx.Project(native).DocxBytes);
            using var nativeProjection = WordprocessingDocument.Open(
                nativeProjectionStream, false);
            Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
            AssertWordPageRenderClose(original,
                nativeProjectionStream.ToArray(), 0.04, 1, ".docx");
            var nativeRewritten = DxpDocExport.Export(
                nativeProjectionStream.ToArray());
            using var rewrittenInput = new MemoryStream(nativeRewritten);
            using var rewrittenIndex = new DocTextIndexWalker().Index(
                rewrittenInput);
            if (expectedFlow == 0)
                Assert.DoesNotContain(rewrittenIndex.ParagraphStyles, x =>
                    x.Formatting?.TableCellTextFlows?.Any(flow =>
                        flow is not null and not 0) == true);
            else
                Assert.True(rewrittenIndex.ParagraphStyles.Count(x =>
                    x.Formatting?.TableCellTextFlows?.Contains(expectedFlow) == true)
                    >= 3);
            AssertWordFirstPageRenderClose(original, nativeRewritten, 0.04);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void EmptyCellHideMarkSurvivesBothDocRoutesInAllStories(bool autoFit)
    {
        Table MakeTable() => new(
            new TableProperties(
                new TableWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                    TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "4800" },
                new TableLayout { Type = autoFit ? TableLayoutValues.Autofit :
                    TableLayoutValues.Fixed }),
            new TableGrid(new GridColumn { Width = "2400" },
                new GridColumn { Width = "2400" }),
            new TableRow(
                new TableCell(new TableCellProperties(new HideMark
                    { Val = OnOffOnlyValues.On }), new Paragraph()),
                new TableCell(new TableCellProperties(new HideMark
                    { Val = OnOffOnlyValues.On }), new Paragraph())),
            new TableRow(
                new TableCell(new Paragraph()),
                new TableCell(new Paragraph())));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MakeTable());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MakeTable());
            footer.Footer.Save();
            main.Document = new Document(new Body(MakeTable(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using var input = new MemoryStream(generated);
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Equal(3, index.ParagraphStyles.Count(x =>
            x.Formatting?.TableCellHideMarks?.SequenceEqual(
                new bool?[] { true, true }) == true));
        var projection = DxpDocToDocx.Project(generated);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var tables = projected.MainDocumentPart!.Document.Body!.Elements<Table>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Table>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Table>())).ToArray();
        Assert.Equal(3, tables.Length);
        Assert.All(tables, table =>
        {
            Assert.All(table.Elements<TableRow>().First().Elements<TableCell>(),
                cell => Assert.Equal(OnOffOnlyValues.On,
                    cell.TableCellProperties!.GetFirstChild<HideMark>()!.Val!.Value));
            Assert.All(table.Elements<TableRow>().Last().Elements<TableCell>(),
                cell => Assert.Null(cell.TableCellProperties?.GetFirstChild<HideMark>()));
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projection.DocxBytes);
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.Equal(3, rewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.TableCellHideMarks?.SequenceEqual(
                new bool?[] { true, true }) == true));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-hide-mark-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                Assert.Equal(3, nativeIndex.ParagraphStyles.Count(x =>
                    x.Formatting?.TableCellHideMarks?.SequenceEqual(
                        new bool?[] { true, true }) == true));
                AssertWordFirstPageRenderClose(source.ToArray(), generated,
                    autoFit ? 0.07 : 0.04);
                AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                    autoFit ? 0.07 : 0.04, 1, ".docx");
                AssertWordFirstPageRenderClose(source.ToArray(), rewritten,
                    autoFit ? 0.07 : 0.04);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesTableCellShading()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(
                        new TableCellBorders(new TopBorder
                            { Val = BorderValues.Single, Size = 12, Color = "CC3300" }),
                        new Shading
                    {
                        Val = ShadingPatternValues.Clear, Fill = "FCE8B2"
                    }, new TableCellVerticalAlignment
                            { Val = TableVerticalAlignmentValues.Center }),
                        new Paragraph(new Run(new Text("Amber")))),
                    new TableCell(new TableCellProperties(
                        new TableCellBorders(new LeftBorder
                            { Val = BorderValues.Dotted, Size = 8, Color = "0055AA" }),
                        new Shading
                    {
                        Val = ShadingPatternValues.Percent50,
                        Fill = "DDEEFF", Color = "335577"
                    }, new TableCellVerticalAlignment
                            { Val = TableVerticalAlignmentValues.Bottom }),
                        new Paragraph(new Run(new Text("Pattern"))))))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var row = Assert.Single(index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true));
            Assert.Equal((ushort)0, row.Formatting!.TableCellShadings![0]!.Pattern);
            Assert.Equal((ushort)8, row.Formatting.TableCellShadings[1]!.Pattern);
            Assert.Equal((byte)1, row.Formatting.TableCellVerticalAlignments![0]);
            Assert.Equal((byte)2, row.Formatting.TableCellVerticalAlignments[1]);
            Assert.Equal(new DocParagraphBorder(1, 12, 0, 0x0033CC),
                row.Formatting.TableCellBorders![0]!.Top);
            Assert.Equal(new DocParagraphBorder(6, 8, 0, 0xAA5500),
                row.Formatting.TableCellBorders[1]!.Left);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal("FCE8B2", cells[0].TableCellProperties?.GetFirstChild<Shading>()?.Fill?.Value);
        Assert.Equal("DDEEFF", cells[1].TableCellProperties?.GetFirstChild<Shading>()?.Fill?.Value);
        Assert.Equal("335577", cells[1].TableCellProperties?.GetFirstChild<Shading>()?.Color?.Value);
        Assert.Equal(TableVerticalAlignmentValues.Center,
            cells[0].TableCellProperties?.GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
        Assert.Equal(TableVerticalAlignmentValues.Bottom,
            cells[1].TableCellProperties?.GetFirstChild<TableCellVerticalAlignment>()?.Val?.Value);
        Assert.Equal("CC3300", cells[0].TableCellProperties?.GetFirstChild<TableCellBorders>()?
            .TopBorder?.Color?.Value);
        Assert.Equal("0055AA", cells[1].TableCellProperties?.GetFirstChild<TableCellBorders>()?
            .LeftBorder?.Color?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-cell-shading-" + Guid.NewGuid().ToString("N") + ".doc");
            File.WriteAllBytes(path, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                // Word returns its COLORREF as BGR in the low 24 bits.
                Assert.Equal(0xB2E8FC, (int)opened.Tables.Item(1)
                    .Cell(1, 1).Shading.BackgroundPatternColor & 0xFFFFFF);
                Assert.Equal(1, (int)opened.Tables.Item(1).Cell(1, 1).VerticalAlignment);
                Assert.Equal(3, (int)opened.Tables.Item(1).Cell(1, 2).VerticalAlignment);
                Assert.Equal(1, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Borders.Item(-1).LineStyle);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
            }
        }
    }

    [Fact]
    public void ExplicitTableRowOriginKeepsIndependentHalfGap()
    {
        var formatting = DocParagraphFormatting.Empty with
        {
            TableRowOriginTwips = 148,
            TableDefaultCellMargins = new DocCellMargins(Left: 200, Right: 400)
        };
        var sprms = formatting.Encode();
        var origin = sprms.AsSpan().IndexOf(new byte[] { 0x01, 0x96 });
        var halfGap = sprms.AsSpan().IndexOf(new byte[] { 0x02, 0x96 });
        Assert.True(origin >= 0);
        Assert.True(halfGap >= 0);
        Assert.Equal(148, BinaryPrimitives.ReadInt16LittleEndian(
            sprms.AsSpan(origin + 2)));
        Assert.Equal(300, BinaryPrimitives.ReadInt16LittleEndian(
            sprms.AsSpan(halfGap + 2)));
    }

