    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public void TableStyleBackgroundShadingSurvivesBothDocHopsInAllStories(
        bool directOverride, bool autoFit)
    {
        Table StoryTable(string label) => new(
            new TableProperties(new TableStyle { Val = "BackgroundTable" },
                new TableWidth { Type = autoFit ? TableWidthUnitValues.Auto :
                    TableWidthUnitValues.Dxa, Width = autoFit ? "0" : "3600" },
                new TableLayout { Type = autoFit ? TableLayoutValues.Autofit :
                    TableLayoutValues.Fixed },
                new TableCellSpacing { Width = "120", Type = TableWidthUnitValues.Dxa },
                directOverride ? new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "00B0F0" } : null),
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(new TableCell(new Paragraph(new Run(new Text(label + " A")))),
                new TableCell(new Paragraph(new Run(new Text(label + " B"))))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(
                new StyleName { Val = "Background table" },
                new StyleTableProperties(new Shading
                    { Val = ShadingPatternValues.Clear, Fill = "FFD700" }))
                { Type = StyleValues.Table, StyleId = "BackgroundTable" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        var binary = DxpDocExport.Export(original);
        if (autoFit)
        {
            static IEnumerable<DocStructureNode> Descendants(DocStructureNode node) =>
                node.Children.SelectMany(child =>
                    new[] { child }.Concat(Descendants(child)));
            using var structure = new DocStructureWalker().Accept(
                new MemoryStream(binary), new DocStructurePrintVisitor(TextWriter.Null));
            var modernRows = Descendants(structure.Root).Where(node =>
                node.Kind == "PrcData" && node.Name == "TableProperties").ToArray();
            Assert.Equal(3, modernRows.Length);
            Assert.All(modernRows, row =>
            {
                var codes = Descendants(row).Where(node => node.Kind == "Sprm")
                    .Select(node => node.Attributes["code"]).ToArray();
                Assert.Contains("0xD633", codes);
                Assert.Equal(directOverride, codes.Contains("0xD660"));
            });
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(original, binary, 0.04);
        for (var hop = 0; hop < 2; hop++)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                var style = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "Background table");
                Assert.Equal(0x00D7FFu,
                    style.TableFormatting?.TableBackgroundShading?.FillRgb);
                Assert.Equal((ushort)0,
                    style.TableFormatting?.TableBackgroundShading?.Pattern);
                var rows = index.ParagraphStyles.Where(x =>
                    x.Formatting?.TableTerminator == true).ToArray();
                Assert.Equal(3, rows.Length);
                Assert.All(rows, row =>
                {
                    Assert.Equal(directOverride ? 0x00F0B000u : (uint?)null,
                        row.Formatting?.TableBackgroundShading?.FillRgb);
                    if (autoFit)
                        Assert.Equal(new[] { new DocTablePreferredWidth(1, 0),
                            new DocTablePreferredWidth(1, 0) },
                            row.Formatting?.TableCellPreferredWidths);
                });
            }
            var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
            using (var projected = WordprocessingDocument.Open(
                new MemoryStream(projectedBytes), false))
            {
                Assert.Empty(new OpenXmlValidator().Validate(projected));
                var style = Assert.Single(projected.MainDocumentPart!
                    .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                    x => x.StyleName?.Val?.Value == "Background table");
                Assert.Equal("FFD700", style.StyleTableProperties?
                    .GetFirstChild<Shading>()?.Fill?.Value);
                Assert.Single(projected.MainDocumentPart.HeaderParts);
                Assert.Single(projected.MainDocumentPart.FooterParts);
                var tables = projected.MainDocumentPart.Document.Body!
                    .Descendants<Table>().Concat(projected.MainDocumentPart.HeaderParts
                        .SelectMany(part => part.Header!.Descendants<Table>()))
                    .Concat(projected.MainDocumentPart.FooterParts
                        .SelectMany(part => part.Footer!.Descendants<Table>())).ToArray();
                Assert.Equal(3, tables.Length);
                Assert.All(tables, table => Assert.Equal(
                    directOverride ? "00B0F0" : null,
                    table.TableProperties?.GetFirstChild<Shading>()?.Fill?.Value));
            }
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordPageRenderClose(original, projectedBytes, 0.04, 1, ".docx");
            binary = DxpDocExport.Export(projectedBytes);
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
    }

    [Theory]
    [InlineData("WordTableBackgroundAutoStyleAllStories", false)]
    [InlineData("WordTableBackgroundAutoDirectAllStories", true)]
    public void WordNativeSpacedAutoFitTableBackgroundSurvivesBothDocRoutes(
        string name, bool directOverride)
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "DocNativeOracle", name + ".docx"));
        var source = File.ReadAllBytes(path);
        var native = File.ReadAllBytes(Path.ChangeExtension(path, ".doc"));
        using (var input = new MemoryStream(native))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Background table");
            Assert.Equal(0x00D7FFu,
                style.TableFormatting?.TableBackgroundShading?.FillRgb);
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(3, rows.Length);
            Assert.All(rows, row =>
            {
                Assert.Equal(directOverride ? 0x00F0B000u : 0x00D7FFu,
                    row.Formatting?.TableBackgroundShading?.FillRgb);
                Assert.Equal(new[] { new DocTablePreferredWidth(1, 0),
                    new DocTablePreferredWidth(1, 0) },
                    row.Formatting?.TableCellPreferredWidths);
                Assert.Equal((short)240, row.Formatting?.TableIndentTwips);
            });
        }
        var projectedBytes = DxpDocToDocx.Project(native).DocxBytes;
        using (var projected = WordprocessingDocument.Open(
            new MemoryStream(projectedBytes), false))
        {
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            var mode = projected.MainDocumentPart!.DocumentSettingsPart?.Settings?
                .Descendants<CompatibilitySetting>().SingleOrDefault(x =>
                    x.Name?.Value == CompatSettingNameValues.CompatibilityMode);
            Assert.Equal("11", mode?.Val?.Value);
            var tables = projected.MainDocumentPart.Document.Body!
                .Descendants<Table>().Concat(projected.MainDocumentPart.HeaderParts
                    .SelectMany(part => part.Header!.Descendants<Table>()))
                .Concat(projected.MainDocumentPart.FooterParts
                    .SelectMany(part => part.Footer!.Descendants<Table>())).ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table =>
            {
                Assert.Equal(directOverride ? "00B0F0" : "FFD700",
                    table.TableProperties?.GetFirstChild<Shading>()?.Fill?.Value);
                Assert.Equal(TableLayoutValues.Autofit,
                    table.TableProperties?.GetFirstChild<TableLayout>()?.Type?.Value);
                Assert.All(table.Descendants<TableCell>(), cell =>
                    Assert.Equal(TableWidthUnitValues.Auto,
                        cell.TableCellProperties?.GetFirstChild<TableCellWidth>()?.Type?.Value));
            });
        }
        var third = DxpDocExport.Export(projectedBytes);
        using (var structure = new DocStructureWalker().Accept(
            new MemoryStream(third), new DocStructurePrintVisitor(TextWriter.Null)))
        {
            static IEnumerable<DocStructureNode> Descendants(DocStructureNode node) =>
                node.Children.SelectMany(child =>
                    new[] { child }.Concat(Descendants(child)));
            var modernRows = Descendants(structure.Root).Where(node =>
                node.Kind == "PrcData" && node.Name == "TableProperties").ToArray();
            Assert.Equal(3, modernRows.Length);
            Assert.All(modernRows, row => Assert.Contains(Descendants(row), node =>
                node.Kind == "Sprm" && node.Attributes["code"] == "0xF661"));
        }
        using (var input = new MemoryStream(third))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(3, rows.Length);
            Assert.All(rows, row => Assert.Equal((short)240,
                row.Formatting?.TableIndentTwips));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source, native, 0.04);
            AssertWordPageRenderClose(source, projectedBytes, 0.04, 1, ".docx");
            AssertWordFirstPageRenderClose(source, third, 0.04);
        }
    }

    [Theory]
    [InlineData("base")]
    [InlineData("rows")]
    [InlineData("inheritedRows")]
    [InlineData("inheritedOverrideRows")]
    [InlineData("overlapRows")]
    [InlineData("overlapColumns")]
    [InlineData("overlapRowColumn")]
    [InlineData("overlapRowCorner")]
    [InlineData("overlapRowCornerOff")]
    [InlineData("overlapLastCorner")]
    [InlineData("overlapLastCornerOff")]
    [InlineData("firstColumn")]
    [InlineData("lastColumn")]
    [InlineData("northWest")]
    [InlineData("northEast")]
    [InlineData("southWest")]
    [InlineData("southEast")]
    [InlineData("firstBandHorizontal")]
    [InlineData("secondBandHorizontal")]
    [InlineData("firstBandVertical")]
    [InlineData("secondBandVertical")]
    public void TableStyleNoWrapWithDirectOffSurvivesAllStories(string mode)
    {
        var conditional = mode != "base";
        var singleRow = mode is "base" or "overlapRows";
        var inherited = mode is "inheritedRows" or "inheritedOverrideRows";
        Table StoryTable(string label) => new(
            new TableProperties(new TableStyle
                { Val = inherited ? "NoWrapDerived" : "NoWrapStyle" },
                new TableWidth { Type = TableWidthUnitValues.Dxa, Width = "2400" },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = mode switch
                    { "rows" or "inheritedRows" or "inheritedOverrideRows" or
                        "overlapRows" => "0060", "firstColumn" => "0080",
                        "lastColumn" => "0100", "overlapColumns" => "0180",
                        "overlapRowColumn" => "0120", "overlapRowCorner" or
                        "overlapRowCornerOff" or
                        "northWest" => "00A0",
                        "northEast" => "0120", "southWest" => "00C0",
                        "southEast" or "overlapLastCorner" or "overlapLastCornerOff" =>
                        "0140", _ => "0000" } }),
            new TableGrid(new GridColumn { Width = "1200" },
                new GridColumn { Width = "1200" }),
            new TableRow(
                new TableCell(new Paragraph(new Run(new Text(label + " keep together")))),
                new TableCell(new TableCellProperties(new NoWrap
                    { Val = OnOffOnlyValues.Off }),
                    new Paragraph(new Run(new Text(label + " may wrap"))))),
            !singleRow ? new TableRow(
                new TableCell(new Paragraph(new Run(new Text(label + " middle wraps")))),
                new TableCell(new TableCellProperties(new NoWrap
                    { Val = OnOffOnlyValues.Off }),
                    new Paragraph(new Run(new Text(label + " middle may wrap"))))) : null,
            !singleRow ? new TableRow(
                new TableCell(new Paragraph(new Run(new Text(label + " last together")))),
                new TableCell(new TableCellProperties(new NoWrap
                    { Val = OnOffOnlyValues.Off }),
                    new Paragraph(new Run(new Text(label + " last may wrap"))))) : null);
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var band = mode.Contains("Band", StringComparison.Ordinal);
            var style = new Style(new StyleName { Val = "No wrap style" },
                band ? new StyleTableProperties(
                    new TableStyleRowBandSize { Val = 1 },
                    new TableStyleColumnBandSize { Val = 1 }) : null,
                new StyleTableCellProperties(new NoWrap
                    { Val = conditional ? OnOffOnlyValues.Off : OnOffOnlyValues.On }))
                { Type = StyleValues.Table, StyleId = "NoWrapStyle" };
            if (mode == "overlapRows")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.FirstRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.LastRow });
            }
            else if (mode == "overlapRowColumn")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.FirstRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.LastColumn });
            }
            else if (mode == "overlapRowCorner")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.FirstRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.NorthWestCell });
            }
            else if (mode == "overlapRowCornerOff")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.FirstRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.NorthWestCell });
            }
            else if (mode == "overlapLastCorner")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.LastRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.SouthEastCell });
            }
            else if (mode == "overlapLastCornerOff")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.LastRow });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.SouthEastCell });
            }
            else if (mode == "overlapColumns")
            {
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap())) { Type = TableStyleOverrideValues.FirstColumn });
                style.Append(new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new NoWrap { Val = OnOffOnlyValues.Off }))
                    { Type = TableStyleOverrideValues.LastColumn });
            }
            else if (conditional)
                foreach (var region in mode switch
                {
                    "rows" or "inheritedRows" or "inheritedOverrideRows" =>
                        new[] { TableStyleOverrideValues.FirstRow,
                        TableStyleOverrideValues.LastRow },
                    "firstColumn" => new[] { TableStyleOverrideValues.FirstColumn },
                    "lastColumn" => new[] { TableStyleOverrideValues.LastColumn },
                    "northWest" => new[] { TableStyleOverrideValues.NorthWestCell },
                    "northEast" => new[] { TableStyleOverrideValues.NorthEastCell },
                    "southWest" => new[] { TableStyleOverrideValues.SouthWestCell },
                    "southEast" => new[] { TableStyleOverrideValues.SouthEastCell },
                    "firstBandHorizontal" => new[] { TableStyleOverrideValues.Band1Horizontal },
                    "secondBandHorizontal" => new[] { TableStyleOverrideValues.Band2Horizontal },
                    "firstBandVertical" => new[] { TableStyleOverrideValues.Band1Vertical },
                    _ => new[] { TableStyleOverrideValues.Band2Vertical }
                })
                    style.Append(new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new NoWrap())) { Type = region });
            if (inherited)
            {
                var derived = new Style(new StyleName { Val = "No wrap derived" },
                    new BasedOn { Val = "NoWrapStyle" })
                    { Type = StyleValues.Table, StyleId = "NoWrapDerived" };
                if (mode == "inheritedOverrideRows")
                    derived.Append(new TableStyleProperties(
                        new TableStyleConditionalFormattingTableCellProperties(
                            new NoWrap { Val = OnOffOnlyValues.Off }))
                        { Type = TableStyleOverrideValues.FirstRow });
                styles.Styles = new Styles(style, derived);
            }
            else styles.Styles = new Styles(style);
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StoryTable("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StoryTable("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StoryTable("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var original = source.ToArray();
        using (var stream = new MemoryStream(original))
        using (var package = WordprocessingDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator().Validate(package));
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var stream = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(stream);
            var baseStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "No wrap style");
            Assert.Equal(!conditional, baseStyle.TableFormatting?.TableStyleNoWrap);
            Assert.Equal(mode is "rows" or "inheritedRows" or
                "inheritedOverrideRows" or "overlapRows" or
                "overlapColumns" or "overlapRowColumn" or "overlapRowCorner" or
                "overlapLastCorner" or "overlapLastCornerOff" or
                "overlapRowCornerOff" ? 2 :
                conditional ? 1 : 0,
                baseStyle.ConditionalTableNoWrap?.Count ?? 0);
            if (inherited)
            {
                var derivedStyle = Assert.Single(index.StyleDefinitions,
                    x => x.Name == "No wrap derived");
                Assert.Equal(baseStyle.Index, derivedStyle.BasedOnIndex);
                Assert.Equal(mode == "inheritedOverrideRows" ? 1 : 0,
                    derivedStyle.ConditionalTableNoWrap?.Count ?? 0);
                if (mode == "inheritedOverrideRows")
                    Assert.False(derivedStyle.ConditionalTableNoWrap![0x0001]);
            }
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).ToArray();
            Assert.Equal(singleRow ? 3 : 9, rows.Length);
            for (var i = 0; i < rows.Length; i++)
                Assert.Equal(new bool?[] { mode switch
                    {
                        "rows" or "inheritedRows" => i % 3 != 1,
                        "inheritedOverrideRows" => i % 3 == 2,
                        "overlapRows" => true,
                        "overlapColumns" => false,
                        "overlapRowColumn" => i % 3 == 0,
                        "overlapRowCorner" => i % 3 == 0,
                        "overlapRowCornerOff" => false,
                        "overlapLastCorner" => i % 3 == 2,
                        "overlapLastCornerOff" => false,
                        "northWest" or "northEast" => i % 3 == 0,
                        "southWest" or "southEast" => i % 3 == 2,
                        "firstBandHorizontal" => i % 3 != 1,
                        "secondBandHorizontal" => i % 3 == 1,
                        _ => true
                    }, false },
                    rows[i].Formatting!.TableCellNoWraps);
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream, false);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            var projectedBaseStyle = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "No wrap style");
            Assert.Equal(conditional ? OnOffOnlyValues.Off : OnOffOnlyValues.On,
                projectedBaseStyle.StyleTableCellProperties?
                    .GetFirstChild<NoWrap>()?.Val?.Value);
            Assert.Equal(baseStyle.ConditionalTableNoWrap?.Count ?? 0,
                projectedBaseStyle.Elements<TableStyleProperties>().Count(x =>
                    x.TableStyleConditionalFormattingTableCellProperties?
                        .GetFirstChild<NoWrap>() != null));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(original, binary, 0.06);
                AssertWordPageRenderClose(original, projectedStream.ToArray(),
                    0.06, 1, ".docx");
            }
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-nowrap-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        var generatedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-nowrap-generated-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(sourcePath, original);
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
            "Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            bool[] WordWraps(dynamic document)
            {
                var values = new List<bool>();
                foreach (dynamic table in new dynamic[]
                {
                    document.Tables.Item(1),
                    document.Sections(1).Headers(1).Range.Tables.Item(1),
                    document.Sections(1).Footers(1).Range.Tables.Item(1)
                })
                    for (var row = 1; row <= (singleRow ? 1 : 3); row++)
                        for (var column = 1; column <= 2; column++)
                            values.Add((bool)table.Cell(row, column).WordWrap);
                return values.ToArray();
            }
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            var expected = WordWraps(opened);
            var expectedRow = mode switch
            {
                "rows" or "inheritedRows" =>
                    new[] { false, true, true, true, false, true },
                "inheritedOverrideRows" =>
                    new[] { true, true, true, true, false, true },
                "northWest" or "northEast" =>
                    new[] { false, true, true, true, true, true },
                "southWest" or "southEast" =>
                    new[] { true, true, true, true, false, true },
                "firstBandHorizontal" =>
                    new[] { false, true, true, true, false, true },
                "secondBandHorizontal" =>
                    new[] { true, true, false, true, true, true },
                "base" or "overlapRows" => new[] { false, true },
                "overlapColumns" => new[] { true, true, true, true, true, true },
                "overlapRowColumn" =>
                    new[] { false, true, true, true, true, true },
                "overlapRowCorner" =>
                    new[] { false, true, true, true, true, true },
                "overlapRowCornerOff" =>
                    new[] { true, true, true, true, true, true },
                "overlapLastCorner" =>
                    new[] { true, true, true, true, false, true },
                "overlapLastCornerOff" =>
                    new[] { true, true, true, true, true, true },
                _ => new[] { false, true, false, true, false, true }
            };
            Assert.Equal(Enumerable.Repeat(expectedRow, 3).SelectMany(x => x), expected);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, WordWraps(opened));
            opened.Close(false);
            opened = word.Documents.Open(nativePath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(expected, WordWraps(opened));
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            foreach (var binary in new[] { native,
                         DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes) })
            {
                using var stream = new MemoryStream(binary);
                using var index = new DocTextIndexWalker().Index(stream);
                if (mode is "base" or "rows")
                {
                    var nativeStyle = Assert.Single(index.StyleDefinitions,
                        x => x.Name == "No wrap style");
                    if (mode == "base")
                        Assert.True(nativeStyle.TableFormatting?.TableStyleNoWrap);
                    else
                        Assert.NotEqual(true,
                            nativeStyle.TableFormatting?.TableStyleNoWrap);
                    // Word flattens conditional noWrap into row flags on DOC save.
                    Assert.Equal(0,
                        nativeStyle.ConditionalTableNoWrap?.Count ?? 0);
                }
                var projected = new DocToDocxProjector().Project(index).DocxBytes;
                using var package = WordprocessingDocument.Open(
                    new MemoryStream(projected), false);
                Assert.Empty(new OpenXmlValidator().Validate(package));
                AssertWordPageRenderClose(original, projected, 0.06, 1, ".docx");
            }
            AssertWordFirstPageRenderClose(original, native, 0.06);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesTableCellNoWrap()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Autofit },
                    new TableIndentation { Width = 108, Type = TableWidthUnitValues.Dxa },
                    new TableCellMarginDefault(
                        new TableCellLeftMargin { Width = 108,
                            Type = TableWidthValues.Dxa },
                        new TableCellRightMargin { Width = 108,
                            Type = TableWidthValues.Dxa })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(
                    new TableCell(new TableCellProperties(new NoWrap()),
                        new Paragraph(new Run(new Text("Keep together")))),
                    new TableCell(new TableCellProperties(new NoWrap
                        { Val = OnOffOnlyValues.Off }),
                        new Paragraph(new Run(new Text("May wrap"))))))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        AssertGeneratedDocCellFlags(bytes, 0x2000, 0);
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var row = Assert.Single(index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true));
            Assert.Equal(new bool?[] { true, false }, row.Formatting!.TableCellNoWraps);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal(OnOffOnlyValues.On,
            cells[0].TableCellProperties?.GetFirstChild<NoWrap>()?.Val?.Value);
        Assert.Equal(OnOffOnlyValues.Off,
            cells[1].TableCellProperties?.GetFirstChild<NoWrap>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-cell-nowrap-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                var nativeRow = Assert.Single(nativeIndex.ParagraphStyles.Where(x =>
                    x.Formatting?.TableTerminator == true));
                Assert.Equal(new bool?[] { true, null },
                    nativeRow.Formatting!.TableCellNoWraps);
                using var nativeProjectionStream = new MemoryStream(
                    new DocToDocxProjector().Project(nativeIndex).DocxBytes);
                using var nativeProjection = WordprocessingDocument.Open(
                    nativeProjectionStream, false);
                var nativeCells = Assert.Single(nativeProjection.MainDocumentPart!
                    .Document.Body!.Elements<Table>()).Descendants<TableCell>()
                    .ToArray();
                Assert.Equal(2, nativeCells.Length);
                Assert.Equal(OnOffOnlyValues.On, nativeCells[0]
                    .TableCellProperties?.GetFirstChild<NoWrap>()?.Val?.Value);
                Assert.Null(nativeCells[1].TableCellProperties?
                    .GetFirstChild<NoWrap>());
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjection));
                AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.03);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesTableCellFitText()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed }),
                new TableGrid(new GridColumn { Width = "1800" },
                    new GridColumn { Width = "1800" }),
                new TableRow(
                    new TableCell(new TableCellProperties(
                        new TableCellWidth { Type = TableWidthUnitValues.Dxa, Width = "1800" },
                        new TableCellFitText()),
                        new Paragraph(new Run(new Text("Condensed cell content")))),
                    new TableCell(new TableCellProperties(
                        new TableCellWidth { Type = TableWidthUnitValues.Dxa, Width = "1800" },
                        new TableCellFitText { Val = OnOffOnlyValues.Off }),
                        new Paragraph(new Run(new Text("Ordinary cell content"))))))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        AssertGeneratedDocCellFlags(bytes, 0x1000, 0);
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var row = Assert.Single(index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true));
            Assert.Equal(new bool?[] { true, false }, row.Formatting!.TableCellFitTexts);
        }
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal(OnOffOnlyValues.On,
            cells[0].TableCellProperties?.GetFirstChild<TableCellFitText>()?.Val?.Value);
        Assert.Equal(OnOffOnlyValues.Off,
            cells[1].TableCellProperties?.GetFirstChild<TableCellFitText>()?.Val?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-cell-fittext-" + Guid.NewGuid().ToString("N") + ".docx");
            var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
            var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            File.WriteAllBytes(generatedPath, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                foreach (var path in new[] { nativePath, generatedPath })
                {
                    opened = word.Documents.Open(path, false, true);
                    Assert.True((bool)opened.Tables.Item(1).Cell(1, 1).FitText);
                    Assert.False((bool)opened.Tables.Item(1).Cell(1, 2).FitText);
                    opened.Close(false);
                    opened = null;
                }
                using var nativeInput = new MemoryStream(File.ReadAllBytes(nativePath));
                using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
                var nativeRow = Assert.Single(nativeIndex.ParagraphStyles.Where(x =>
                    x.Formatting?.TableTerminator == true));
                Assert.True(nativeRow.Formatting!.TableCellFitTexts?[0]);
                using var nativeProjectedStream = new MemoryStream(
                    DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
                using var nativeProjected = WordprocessingDocument.Open(
                    nativeProjectedStream, false);
                var nativeProjectedCell = Assert.Single(nativeProjected.MainDocumentPart!
                    .Document!.Body!.Elements<Table>()).Descendants<TableCell>().First();
                Assert.Equal(OnOffOnlyValues.On, nativeProjectedCell.TableCellProperties?
                    .GetFirstChild<TableCellFitText>()?.Val?.Value);
                Assert.Empty(new OpenXmlValidator().Validate(nativeProjected));
                AssertWordFirstPageRenderClose(source.ToArray(),
                    File.ReadAllBytes(nativePath), 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                File.Delete(generatedPath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void TableCellFitTextSurvivesBodyHeaderAndFooter()
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordTablesAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        source.Position = 0;
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var tables = main.Document!.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()))
                .ToArray();
            Assert.Equal(3, tables.Length);
            foreach (var table in tables)
            {
                var cell = table.Descendants<TableCell>().First();
                cell.TableCellProperties!.AppendChild(new TableCellFitText());
            }
        }
        var sourceBytes = source.ToArray();
        var generatedBytes = DxpDocExport.Export(sourceBytes);
        static void AssertFitTextRows(byte[] binary)
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Equal(3, index.ParagraphStyles.Count(x =>
                x.Formatting?.TableTerminator == true &&
                x.Formatting.TableCellFitTexts?.FirstOrDefault() == true));
        }
        static void AssertFitTextProjection(byte[] binary)
        {
            using var stream = new MemoryStream(DxpDocToDocx.Project(binary).DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var tables = main.Document!.Body!.Elements<Table>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Table>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Table>()))
                .ToArray();
            Assert.Equal(3, tables.Length);
            Assert.All(tables, table => Assert.NotNull(table.Descendants<TableCell>()
                .First().TableCellProperties?.GetFirstChild<TableCellFitText>()));
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        AssertFitTextRows(generatedBytes);
        AssertFitTextProjection(generatedBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            "docxport-all-story-fittext-" + Guid.NewGuid().ToString("N") + ".docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        var nativeDocxPath = Path.ChangeExtension(sourcePath, ".native.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        File.WriteAllBytes(sourcePath, sourceBytes);
        File.WriteAllBytes(generatedPath, generatedBytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        dynamic? opened = null;
        try
        {
            word.Visible = false;
            word.DisplayAlerts = 0;
            opened = word.Documents.Open(sourcePath, false, true);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            foreach (var path in new[] { nativePath, generatedPath })
            {
                opened = word.Documents.Open(path, false, true);
                Assert.True((bool)opened.Tables.Item(1).Cell(1, 1).FitText);
                Assert.True((bool)opened.Sections.Item(1).Headers.Item(1)
                    .Range.Tables.Item(1).Cell(1, 1).FitText);
                Assert.True((bool)opened.Sections.Item(1).Footers.Item(1)
                    .Range.Tables.Item(1).Cell(1, 1).FitText);
                if (path == nativePath) opened.SaveAs2(nativeDocxPath, 16);
                opened.Close(false);
                opened = null;
            }
            var nativeBytes = File.ReadAllBytes(nativePath);
            AssertFitTextRows(nativeBytes);
            AssertFitTextProjection(nativeBytes);
            AssertWordFirstPageRenderClose(sourceBytes, nativeBytes, 0.055);
            AssertWordFirstPageRenderClose(sourceBytes, generatedBytes, 0.055);
            AssertWordFirstPageRenderClose(File.ReadAllBytes(nativeDocxPath),
                generatedBytes, 0.03);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
            if (File.Exists(nativeDocxPath)) File.Delete(nativeDocxPath);
            File.Delete(generatedPath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesTableLevelOuterAndInsideBorders()
    {
        static TableCell Cell(string text, TableCellProperties? properties = null) =>
            new(properties ?? new TableCellProperties(),
                new Paragraph(new Run(new Text(text))));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableBorders(
                    new TopBorder { Val = BorderValues.Single, Size = 12, Color = "CC3300" },
                    new LeftBorder { Val = BorderValues.Single, Size = 8, Color = "112233" },
                    new BottomBorder { Val = BorderValues.Single, Size = 8, Color = "112233" },
                    new RightBorder { Val = BorderValues.Single, Size = 8, Color = "112233" },
                    new InsideHorizontalBorder { Val = BorderValues.Dotted,
                        Size = 8, Color = "22AA44" },
                    new InsideVerticalBorder { Val = BorderValues.Dashed,
                        Size = 8, Color = "0055AA" })),
                new TableGrid(new GridColumn { Width = "2000" },
                    new GridColumn { Width = "2000" }),
                new TableRow(Cell("A1", new TableCellProperties(new TableCellBorders(
                        new BottomBorder { Val = BorderValues.Double,
                            Size = 8, Color = "EEBB00" }))), Cell("B1")),
                new TableRow(Cell("A2"), Cell("B2")))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var rows = index.ParagraphStyles.Where(x =>
                x.Formatting?.TableTerminator == true).Select(x => x.Formatting!).ToArray();
            Assert.Equal(2, rows.Length);
            Assert.Equal((byte)1, rows[0].TableCellBorders![0]!.Top!.Type);
            Assert.Equal((byte)3, rows[0].TableCellBorders[0]!.Bottom!.Type);
            Assert.Equal((byte)7, rows[0].TableCellBorders[0]!.Right!.Type);
            Assert.Equal((byte)6, rows[1].TableCellBorders![1]!.Top!.Type);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Elements<Table>()).Descendants<TableCell>().ToArray();
        Assert.Equal("CC3300", cells[0].TableCellProperties?.TableCellBorders?.TopBorder?.Color?.Value);
        Assert.Equal(BorderValues.Double,
            cells[0].TableCellProperties?.TableCellBorders?.BottomBorder?.Val?.Value);
        Assert.Equal("0055AA", cells[0].TableCellProperties?.TableCellBorders?.RightBorder?.Color?.Value);
        Assert.Equal("22AA44", cells[3].TableCellProperties?.TableCellBorders?.TopBorder?.Color?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-table-borders-" + Guid.NewGuid().ToString("N") + ".doc");
            var sourcePath = Path.ChangeExtension(path, ".source.docx");
            var nativePath = Path.ChangeExtension(path, ".native.doc");
            File.WriteAllBytes(path, bytes);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                Assert.Equal(1, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Borders.Item(-1).LineStyle);
                Assert.Equal(7, (int)opened.Tables.Item(1).Cell(1, 1)
                    .Borders.Item(-3).LineStyle);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using (var input = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    var atoms = index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).ToArray();
                    Console.WriteLine("LEGACY ATOMS " + string.Join(";", atoms.Select(a =>
                        $"{a.CpStart}:{a.Kind}:{string.Join(",", a.Text.Select(c => ((int)c).ToString("X2")))}")));
                    Console.WriteLine("LEGACY FORMATS " + string.Join(";", index.CharacterFormatting
                        .Where(x => x.CpStart < 35).Select(x =>
                            $"{x.CpStart}-{x.CpEnd}:special={x.Formatting.Special}")));
                }                var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var nativeCells = Assert.Single(native.MainDocumentPart!.Document!.Body!
                    .Elements<Table>()).Descendants<TableCell>().ToArray();
                Assert.Equal("CC3300", nativeCells[0].TableCellProperties?
                    .TableCellBorders?.TopBorder?.Color?.Value);
                Assert.Equal("0055AA", nativeCells[0].TableCellProperties?
                    .TableCellBorders?.RightBorder?.Color?.Value);
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void EdgeColumnStyleOnSkippedGridColumnMatchesWordInAllStories(bool first)
    {
        static TableCell Cell(string text) => new(new Paragraph(new Run(new Text(text))));
        Table TableWithGap() => new(
            new TableProperties(new TableStyle { Val = "GapEdgeColumn" },
                new TableWidth { Width = "3600", Type = TableWidthUnitValues.Dxa },
                new TableLayout { Type = TableLayoutValues.Fixed },
                new TableLook { Val = first ? "0080" : "0100",
                    FirstColumn = first, LastColumn = !first }),
            new TableGrid(new GridColumn { Width = "1800" },
                new GridColumn { Width = "1800" }),
            new TableRow(Cell("A1"), Cell("B1")),
            new TableRow(new TableRowProperties(first
                ? new GridBefore { Val = 1 }
                : new GridAfter { Val = 1 }), Cell("B2")),
            new TableRow(Cell("A3"), Cell("B3")));

        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName
                { Val = "Gap edge column" },
                new TableStyleProperties(
                    new TableStyleConditionalFormattingTableCellProperties(
                        new Shading { Val = ShadingPatternValues.Clear,
                            Fill = first ? "FF0000" : "0000FF" }))
                { Type = first ? TableStyleOverrideValues.FirstColumn :
                    TableStyleOverrideValues.LastColumn })
            { Type = StyleValues.Table, StyleId = "GapEdgeColumn" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TableWithGap());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TableWithGap());
            footer.Footer.Save();
            main.Document = new Document(new Body(TableWithGap(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        void AssertProjected(byte[] bytes, bool requireGap = true)
        {
            var projectedBytes = DxpDocToDocx.Project(bytes).DocxBytes;
            using var stream = new MemoryStream(projectedBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            var tables = main.Document!.Body!.Elements<Table>()
                .Concat(Assert.Single(main.HeaderParts).Header!.Elements<Table>())
                .Concat(Assert.Single(main.FooterParts).Footer!.Elements<Table>())
                .ToArray();
            Assert.Equal(3, tables.Length);
            foreach (var table in tables)
            {
                var rowProperties = table.Elements<TableRow>().ElementAt(1)
                    .TableRowProperties;
                if (requireGap)
                    Assert.True((first
                        ? rowProperties?.GetFirstChild<GridBefore>()?.Val?.Value
                        : rowProperties?.GetFirstChild<GridAfter>()?.Val?.Value) == 1,
                        rowProperties?.OuterXml);
                var cells = table.Descendants<TableCell>().ToArray();
                Assert.Equal(first
                    ? new[] { "FF0000", null, "FF0000", "FF0000", null }
                    : new[] { null, "0000FF", "0000FF", null, "0000FF" },
                    cells.Select(cell => cell.TableCellProperties?.Shading?.Fill?.Value));
            }
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjected(generated);
        AssertProjected(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-first-column-gap-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(sourcePath, false, false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                var native = File.ReadAllBytes(nativePath);
                AssertProjected(native, first);
                AssertProjected(DxpDocExport.Export(
                    DxpDocToDocx.Project(native).DocxBytes), first);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void TableStyleRowAndColumnBordersSurviveBothDocRoutes()
    {
        static TableCell Cell(string text, string? directColor = null) =>
            new(directColor == null
                    ? new TableCellProperties(new TableCellWidth
                    { Width = "1800", Type = TableWidthUnitValues.Dxa })
                    : new TableCellProperties(new TableCellWidth
                    { Width = "1800", Type = TableWidthUnitValues.Dxa },
                        new TableCellBorders(new TopBorder
                        { Val = BorderValues.Single, Size = 8, Color = directColor })),
                new Paragraph(new Run(new Text(text))));
        static TableStyleProperties Conditional(TableStyleOverrideValues kind,
            string color, string side, string fill) => new(
                new TableStyleConditionalFormattingTableCellProperties(
                    new TableCellBorders(side switch
                    {
                        "left" => new LeftBorder
                        { Val = BorderValues.Single, Size = 8, Color = color },
                        "right" => new RightBorder
                        { Val = BorderValues.Single, Size = 8, Color = color },
                        "bottom" => new BottomBorder
                        { Val = BorderValues.Single, Size = 8, Color = color },
                        _ => new TopBorder
                        { Val = BorderValues.Single, Size = 8, Color = color }
                    }),
                    new Shading { Val = ShadingPatternValues.Clear, Fill = fill }))
            { Type = kind };
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName
                { Val = "Column Borders" },
                Conditional(TableStyleOverrideValues.FirstColumn, "00AA00", "left", "CCEECC"),
                Conditional(TableStyleOverrideValues.LastColumn, "0000AA", "right", "CCCCEE"),
                Conditional(TableStyleOverrideValues.FirstRow, "AA0000", "top", "DDEEFF"),
                Conditional(TableStyleOverrideValues.LastRow, "CC8800", "bottom", "FFEEDD"),
                Conditional(TableStyleOverrideValues.NorthWestCell, "114477", "top", "AADDDD"),
                Conditional(TableStyleOverrideValues.NorthEastCell, "772244", "top", "DDAACC"),
                Conditional(TableStyleOverrideValues.SouthWestCell, "227744", "bottom", "AAEEAA"),
                Conditional(TableStyleOverrideValues.SouthEastCell, "884411", "bottom", "EEAA99"))
            { Type = StyleValues.Table, StyleId = "ColumnBorders" });
            styles.Styles.Save();
            main.Document = new Document(new Body(new Table(
                new TableProperties(new TableStyle { Val = "ColumnBorders" },
                    new TableWidth { Width = "5400", Type = TableWidthUnitValues.Dxa },
                    new TableLayout { Type = TableLayoutValues.Fixed },
                    new TableLook { Val = "01E0", FirstRow = true, LastRow = true,
                        FirstColumn = true, LastColumn = true },
                    new TableCellMarginDefault(new LeftMargin
                    { Width = "108", Type = TableWidthUnitValues.Dxa },
                        new RightMargin
                        { Width = "108", Type = TableWidthUnitValues.Dxa })),
                new TableGrid(new GridColumn { Width = "1800" },
                    new GridColumn { Width = "1800" },
                    new GridColumn { Width = "1800" }),
                new TableRow(Cell("A1"), Cell("B1"), Cell("C1")),
                new TableRow(Cell("A2"), Cell("B2"), Cell("C2", "AA00AA")),
                new TableRow(Cell("A3"), Cell("B3"), Cell("C3")))));
            main.Document.Save();
        }
        var expectedTop = new[]
        {
            "114477", "AA0000", "772244",
            null, null, "AA00AA",
            null, null, null
        };
        var expectedFills = new[]
        {
            "AADDDD", "DDEEFF", "DDAACC",
            "CCEECC", null, "CCCCEE",
            "AAEEAA", "FFEEDD", "EEAA99"
        };
        var generated = DxpDocExport.Export(source.ToArray());
        AssertBorders(generated);
        AssertBorders(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        var pairedNative = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordConditionalColumnBorders.doc"));
        var native = File.ReadAllBytes(pairedNative);
        AssertBorders(native);
        AssertBorders(DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes));
        void AssertBorders(byte[] docBytes)
        {
            var projectedBytes = DxpDocToDocx.Project(docBytes).DocxBytes;
            using var stream = new MemoryStream(projectedBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var cells = Assert.Single(projected.MainDocumentPart!.Document!.Body!
                .Elements<Table>()).Descendants<TableCell>().ToArray();
            Assert.Equal(expectedTop, cells.Select(x => x.TableCellProperties?
                .TableCellBorders?.TopBorder?.Color?.Value));
            Assert.Equal(expectedFills, cells.Select(x =>
                x.TableCellProperties?.Shading?.Fill?.Value));
            if (new[] { 0, 3, 6 }.Any(index => cells[index].TableCellProperties?
                    .TableCellBorders?.LeftBorder == null))
                Assert.Contains(projected.MainDocumentPart.StyleDefinitionsPart!.Styles!
                    .Descendants<LeftBorder>(), border => border.Color?.Value == "00AA00");
            foreach (var index in new[] { 0, 3, 6 })
                Assert.True(cells[index].TableCellProperties?.TableCellBorders?
                    .LeftBorder?.Color?.Value is null or "00AA00");
            Assert.Equal("0000AA", cells[2].TableCellProperties?
                .TableCellBorders?.RightBorder?.Color?.Value);
            Assert.Equal("0000AA", cells[5].TableCellProperties?
                .TableCellBorders?.RightBorder?.Color?.Value);
            Assert.Equal("0000AA", cells[8].TableCellProperties?
                .TableCellBorders?.RightBorder?.Color?.Value);
            Assert.Equal(new[] { "227744", "CC8800", "884411" },
                cells[6..9].Select(cell => cell.TableCellProperties?
                    .TableCellBorders?.BottomBorder?.Color?.Value));
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
    }

    [Fact]
    public void DocRoundTripPreservesDistinctHyphenControlsAndNonbreakingSpace()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            static Run HyphenRun(string prefix) => new(
                new Text(prefix), new NoBreakHyphen(), new Text("B"),
                new SoftHyphen(), new Text("C\u00A0D"));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(HyphenRun("H")));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(HyphenRun("F")));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(
                new Text("A"), new NoBreakHyphen(), new Text("B"),
                new SoftHyphen(), new Text("C\u00A0D"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            Assert.Equal("A\u001EB\u001FC\u00A0D\r",
                string.Concat(index.GetPartSpans("Main").Select(x => x.Text)));
            Assert.Contains(index.HeaderStories, x =>
                string.Concat(x.ReadContent().Paragraphs.SelectMany(p => p.Atoms)
                    .Select(a => a.Text)).Contains("H\u001EB\u001FC\u00A0D"));
            Assert.Contains(index.HeaderStories, x =>
                string.Concat(x.ReadContent().Paragraphs.SelectMany(p => p.Atoms)
                    .Select(a => a.Text)).Contains("F\u001EB\u001FC\u00A0D"));
        }

        var projection = DxpDocToDocx.Project(docBytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var paragraph = Assert.Single(projected.MainDocumentPart!.Document!.Body!.Elements<Paragraph>());
        Assert.Single(paragraph.Descendants<NoBreakHyphen>());
        Assert.Single(paragraph.Descendants<SoftHyphen>());
        Assert.Contains("C\u00A0D", paragraph.InnerText);
        foreach (var story in projected.MainDocumentPart.HeaderParts
            .Select(x => (DocumentFormat.OpenXml.OpenXmlElement)x.Header!)
            .Concat(projected.MainDocumentPart.FooterParts.Select(x =>
                (DocumentFormat.OpenXml.OpenXmlElement)x.Footer!)))
        {
            Assert.Single(story.Descendants<NoBreakHyphen>());
            Assert.Single(story.Descendants<SoftHyphen>());
            Assert.Contains("C\u00A0D", story.InnerText);
        }
        Assert.Empty(projection.Coverage.OmittedCharacters);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projection.DocxBytes);
        using var rewrittenStream = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenStream);
        Assert.Equal("A\u001EB\u001FC\u00A0D\r",
            string.Concat(rewrittenIndex.GetPartSpans("Main").Select(x => x.Text)));
        Assert.Contains(rewrittenIndex.HeaderStories, x =>
            string.Concat(x.ReadContent().Paragraphs.SelectMany(p => p.Atoms)
                .Select(a => a.Text)).Contains("H\u001EB\u001FC\u00A0D"));
        Assert.Contains(rewrittenIndex.HeaderStories, x =>
            string.Concat(x.ReadContent().Paragraphs.SelectMany(p => p.Atoms)
                .Select(a => a.Text)).Contains("F\u001EB\u001FC\u00A0D"));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), docBytes, 0.04);
            var directory = Path.Combine(Path.GetTempPath(),
                $"docxport-hyphen-space-{Guid.NewGuid():N}");
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                var nativeProjection = DxpDocToDocx.Project(
                    File.ReadAllBytes(nativePath)).DocxBytes;
                using var nativeStream = new MemoryStream(nativeProjection);
                using var nativePackage = WordprocessingDocument.Open(nativeStream, false);
                var nativeMain = nativePackage.MainDocumentPart!;
                Assert.Contains("C\u00A0D", nativeMain.Document!.Body!.InnerText);
                Assert.Single(nativeMain.Document.Body.Descendants<NoBreakHyphen>());
                Assert.Single(nativeMain.Document.Body.Descendants<SoftHyphen>());
                Assert.All(nativeMain.HeaderParts, part =>
                {
                    Assert.Contains("C\u00A0D", part.Header!.InnerText);
                    Assert.Single(part.Header.Descendants<NoBreakHyphen>());
                    Assert.Single(part.Header.Descendants<SoftHyphen>());
                });
                Assert.All(nativeMain.FooterParts, part =>
                {
                    Assert.Contains("C\u00A0D", part.Footer!.InnerText);
                    Assert.Single(part.Footer.Descendants<NoBreakHyphen>());
                    Assert.Single(part.Footer.Descendants<SoftHyphen>());
                });
                Assert.Empty(new OpenXmlValidator().Validate(nativePackage));
                AssertWordPageRenderClose(source.ToArray(), nativeProjection,
                    0.04, 1, ".docx");
            }
            finally
            {
                if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                    Directory.Delete(directory, true);
            }
        }
    }

    [Fact]
    public void StyledTextControlsRetainRunFormattingInAllStories()
    {
        static Paragraph StyledControls(string prefix) => new(new Run(
            new RunProperties(new Bold(), new Color { Val = "008844" }),
            new Text(prefix), new TabChar(), new Break(),
            new NoBreakHyphen(), new SoftHyphen(), new Text("end")));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(StyledControls("header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(StyledControls("footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(StyledControls("body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        static void AssertStories(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var stories = new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            };
            foreach (var story in stories)
                foreach (var control in story.Descendants<Run>().Where(run =>
                    run.Elements<TabChar>().Any() || run.Elements<Break>().Any() ||
                    run.Elements<NoBreakHyphen>().Any() ||
                    run.Elements<SoftHyphen>().Any()))
                {
                    Assert.True(control.RunProperties?.Bold?.Val?.Value ?? true);
                    Assert.Equal("008844", control.RunProperties?.Color?.Val?.Value);
                }
            Assert.All(stories, story =>
            {
                Assert.Single(story.Descendants<TabChar>());
                Assert.Single(story.Descendants<Break>());
                Assert.Single(story.Descendants<NoBreakHyphen>());
                Assert.Single(story.Descendants<SoftHyphen>());
            });
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var doc = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(doc).DocxBytes;
        AssertStories(projected);
        AssertStories(DxpDocToDocx.Project(DxpDocExport.Export(projected)).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), doc, 0.04);
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-styled-controls-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                AssertStories(DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            }
            finally
            {
                if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                    Directory.Delete(directory, true);
            }
        }
    }

    [Fact]
    public void RevisedTextControlsRetainRevisionAndFormattingInAllStories()
    {
        var changedAt = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc);
        static Paragraph RevisedControls() => new(
            new InsertedRun(new Run(new RunProperties(new Bold()), new TabChar()))
            { Id = "1", Author = "Editor A",
                Date = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc) },
            new DeletedRun(new Run(new RunProperties(new Italic()),
                new NoBreakHyphen()))
            { Id = "2", Author = "Editor B",
                Date = new DateTime(2025, 12, 21, 2, 40, 0, DateTimeKind.Utc) });
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(RevisedControls());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(RevisedControls());
            footer.Footer.Save();
            main.Document = new Document(new Body(RevisedControls(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var doc = DxpDocExport.Export(source.ToArray());
        var projected = DxpDocToDocx.Project(doc).DocxBytes;
        foreach (var bytes in new[] { projected,
            DxpDocToDocx.Project(DxpDocExport.Export(
                projected)).DocxBytes })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
            {
                main.Document!.Body!, main.HeaderParts.Single().Header!,
                main.FooterParts.Single().Footer!
            })
            {
                var inserted = Assert.Single(story.Descendants<InsertedRun>());
                Assert.Equal("Editor A", inserted.Author?.Value);
                Assert.Equal(changedAt, inserted.Date?.Value);
                Assert.Single(inserted.Descendants<TabChar>());
                Assert.NotNull(Assert.Single(inserted.Descendants<Run>()).RunProperties?.Bold);
                var deleted = Assert.Single(story.Descendants<DeletedRun>());
                Assert.Equal("Editor B", deleted.Author?.Value);
                Assert.Equal(changedAt, deleted.Date?.Value);
                Assert.Single(deleted.Descendants<NoBreakHyphen>());
                Assert.NotNull(Assert.Single(deleted.Descendants<Run>()).RunProperties?.Italic);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-revised-controls-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                using var nativeStream = new MemoryStream(
                    DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var nativeMain = native.MainDocumentPart!;
                foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    nativeMain.Document!.Body!,
                    nativeMain.HeaderParts.Single().Header!,
                    nativeMain.FooterParts.Single().Footer!
                })
                {
                    Assert.Single(Assert.Single(story.Descendants<InsertedRun>())
                        .Descendants<TabChar>());
                    Assert.Single(Assert.Single(story.Descendants<DeletedRun>())
                        .Descendants<NoBreakHyphen>());
                }
            }
            finally
            {
                if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                    Directory.Delete(directory, true);
            }
        }
    }

    [Fact]
    public void ValuelessUnderlineFollowsWordAppearanceInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            static Paragraph TextWithUnderlineElement(string text) => new(
                new Run(new RunProperties(new Underline()), new Text(text)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TextWithUnderlineElement("Header text"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TextWithUnderlineElement("Footer text"));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                TextWithUnderlineElement("Body text"), new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.DoesNotContain(index.CharacterFormatting, x =>
                x.Formatting.UnderlineCode is > 0);
        var projected = DxpDocToDocx.Project(binary);
        using (var input = new MemoryStream(projected.DocxBytes))
        using (var document = WordprocessingDocument.Open(input, false))
        {
            Assert.DoesNotContain(document.MainDocumentPart!.Document!
                .Descendants<Underline>(), x => x.Val?.Value == UnderlineValues.Single);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var rewritten = DxpDocExport.Export(projected.DocxBytes);
        using (var input = new MemoryStream(rewritten))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.DoesNotContain(index.CharacterFormatting, x =>
                x.Formatting.UnderlineCode is > 0);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
    }

    [Fact]
    public void DocRoundTripPreservesExternalHyperlinkFieldsInStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var bodyLink = main.AddHyperlinkRelationship(
                new Uri("https://example.com/body?q=1"), true);
            var header = main.AddNewPart<HeaderPart>();
            var headerLink = header.AddHyperlinkRelationship(
                new Uri("https://example.com/header"), true);
            header.Header = new Header(new Paragraph(
                new BookmarkStart { Id = "2", Name = "HeaderTarget" },
                new Hyperlink(new Run(new Text("Header link"))) { Id = headerLink.Id },
                new BookmarkEnd { Id = "2" }));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            var footerLink = footer.AddHyperlinkRelationship(
                new Uri("https://example.com/footer"), true);
            footer.Footer = new Footer(new Paragraph(
                new BookmarkStart { Id = "3", Name = "FooterTarget" },
                new Hyperlink(new Run(new Text("Footer link"))) { Id = footerLink.Id },
                new BookmarkEnd { Id = "3" }));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Hyperlink(
                new Run(new Text("Body link"))) { Id = bodyLink.Id }),
                new SectionProperties(new HeaderReference
                { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header) },
                    new FooterReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Contains("HYPERLINK \"https://example.com/body?q=1\"",
                DocStoryTextReader.Read(index, "Main").Paragraphs[0].Atoms
                    .Where(x => x.Kind == DocStoryAtomKind.Text)
                    .Aggregate("", (text, atom) => text + atom.Text));
            Assert.Contains(index.Structure.Locations, x => x.Name == "MainFields" && x.IsPresent);
            Assert.Contains(index.Structure.Locations, x => x.Name == "HeaderFields" && x.IsPresent);
            Assert.Equal(3, index.GetFieldMarks("Main").Count);
            var headerMarks = index.GetFieldMarks("Headers");
            Assert.Equal(6, headerMarks.Count);
            foreach (var slot in new[] { 7, 9 })
            {
                var storyRange = index.HeaderStories[slot].ReadContent();
                Assert.Equal(3, headerMarks.Count(cp => cp >= storyRange.CpStart &&
                    cp < storyRange.CpEnd));
            }
            Assert.Equal(new[] { "HeaderTarget", "FooterTarget" },
                index.Bookmarks.Select(x => x.Name).ToArray());
            Assert.Empty(index.ReadStory("Main").Bookmarks);
            var headerBookmark = Assert.Single(index.HeaderStories[7]
                .ReadIndexedContent().Bookmarks);
            var footerBookmark = Assert.Single(index.HeaderStories[9]
                .ReadIndexedContent().Bookmarks);
            Assert.Equal((0, "HeaderTarget"),
                (headerBookmark.Id, headerBookmark.Name));
            Assert.Equal((1, "FooterTarget"),
                (footerBookmark.Id, footerBookmark.Name));
            foreach (var (slot, bookmark) in new[]
            {
                (7, headerBookmark), (9, footerBookmark)
            })
            {
                var story = index.HeaderStories[slot].ReadContent();
                Assert.Equal(story.CpStart + (uint)bookmark.Start,
                    bookmark.SourceCpStart);
                Assert.Equal(story.CpStart + (uint)bookmark.End,
                    bookmark.SourceCpEnd);
                Assert.Equal(index.GetTextOffset(bookmark.SourceCpStart!.Value),
                    bookmark.SourceTextOffsetStart);
                Assert.NotNull(bookmark.SourceTextOffsetEnd);
            }
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        Assert.Contains("HYPERLINK \"https://example.com/body?q=1\"",
            projected.MainDocumentPart!.Document!.Body!.Descendants<FieldCode>().Single().Text);
        Assert.Contains("HYPERLINK \"https://example.com/header\"",
            projected.MainDocumentPart.HeaderParts.Single().Header!
                .Descendants<FieldCode>().Single().Text);
        Assert.Contains("HYPERLINK \"https://example.com/footer\"",
            projected.MainDocumentPart.FooterParts.Single().Footer!
                .Descendants<FieldCode>().Single().Text);
        Assert.Equal("HeaderTarget", Assert.Single(projected.MainDocumentPart
            .HeaderParts.Single().Header!.Descendants<BookmarkStart>()).Name!.Value);
        Assert.Equal("FooterTarget", Assert.Single(projected.MainDocumentPart
            .FooterParts.Single().Footer!.Descendants<BookmarkStart>()).Name!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-links-" + Guid.NewGuid().ToString("N") + ".doc");
            var sourcePath = Path.ChangeExtension(path, ".source.docx");
            var nativePath = Path.ChangeExtension(path, ".native.doc");
            File.WriteAllBytes(path, bytes);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                Assert.Equal("https://example.com/body?q=1",
                    (string)opened.Hyperlinks.Item(1).Address);
                Assert.Equal("https://example.com/header",
                    (string)opened.Sections.Item(1).Headers.Item(1)
                        .Range.Hyperlinks.Item(1).Address);
                Assert.Equal("https://example.com/footer",
                    (string)opened.Sections.Item(1).Footers.Item(1)
                        .Range.Hyperlinks.Item(1).Address);
                Assert.True((bool)opened.Bookmarks.Exists("HeaderTarget"));
                Assert.True((bool)opened.Bookmarks.Exists("FooterTarget"));
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using (var input = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    var atoms = index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).ToArray();
                    Console.WriteLine("LEGACY ATOMS " + string.Join(";", atoms.Select(a =>
                        $"{a.CpStart}:{a.Kind}:{string.Join(",", a.Text.Select(c => ((int)c).ToString("X2")))}")));
                    Console.WriteLine("LEGACY FORMATS " + string.Join(";", index.CharacterFormatting
                        .Where(x => x.CpStart < 35).Select(x =>
                            $"{x.CpStart}-{x.CpEnd}:special={x.Formatting.Special}")));
                }                var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                Assert.Contains("HYPERLINK \"https://example.com/body?q=1\"",
                    native.MainDocumentPart!.Document!.Body!
                        .Descendants<FieldCode>().Single().Text);
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void BookmarksAroundTabsKeepExactBoundariesInAllStories()
    {
        static Paragraph MarkedTab(string prefix, string id) => new(
            new Run(new Text(prefix)),
            new BookmarkStart { Id = id, Name = "TabMark" + id },
            new Run(new TabChar()),
            new BookmarkEnd { Id = id },
            new Run(new Text("tail")));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(MarkedTab("header", "2"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(MarkedTab("footer", "3"));
            footer.Footer.Save();
            main.Document = new Document(new Body(MarkedTab("body", "1"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var doc = DxpDocExport.Export(source.ToArray());
        using (var indexStream = new MemoryStream(doc))
        using (var index = new DocTextIndexWalker().Index(indexStream))
        {
            Assert.Equal(3, index.Bookmarks.Count);
            Assert.All(index.Bookmarks, bookmark =>
                Assert.Equal(bookmark.CpStart + 1, bookmark.CpEnd));
        }
        foreach (var bytes in new[] { DxpDocToDocx.Project(doc).DocxBytes,
            DxpDocToDocx.Project(DxpDocExport.Export(
                DxpDocToDocx.Project(doc).DocxBytes)).DocxBytes })
        {
            using var stream = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            foreach (var paragraph in new[]
            {
                main.Document!.Body!.Elements<Paragraph>().Single(),
                main.HeaderParts.Single().Header!.Elements<Paragraph>().Single(),
                main.FooterParts.Single().Footer!.Elements<Paragraph>().Single()
            })
            {
                var children = paragraph.ChildElements.ToList();
                var start = Assert.Single(paragraph.Elements<BookmarkStart>());
                var end = Assert.Single(paragraph.Elements<BookmarkEnd>());
                var startAt = children.IndexOf(start);
                Assert.Equal(startAt + 2, children.IndexOf(end));
                Assert.Single(((Run)children[startAt + 1]).Elements<TabChar>());
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var directory = Path.Combine(Path.GetTempPath(),
                "docxport-tab-bookmark-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(directory);
            try
            {
                var sourcePath = Path.Combine(directory, "source.docx");
                var nativePath = Path.Combine(directory, "native.doc");
                File.WriteAllBytes(sourcePath, source.ToArray());
                dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                    "Word.Application")!)!;
                word.Visible = false;
                try
                {
                    dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                        AddToRecentFiles: false);
                    try { opened.SaveAs2(nativePath, 0); }
                    finally { opened.Close(false); }
                }
                finally { word.Quit(false); }
                using var nativeStream = File.OpenRead(nativePath);
                using var nativeIndex = new DocTextIndexWalker().Index(nativeStream);
                Assert.Equal(3, nativeIndex.Bookmarks.Count);
                Assert.All(nativeIndex.Bookmarks, bookmark =>
                    Assert.Equal(bookmark.CpStart + 1, bookmark.CpEnd));
                using var projectedStream = new MemoryStream(
                    DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
                using var projected = WordprocessingDocument.Open(projectedStream, false);
                Assert.Equal(3, projected.MainDocumentPart!.Document!.Body!
                    .Descendants<BookmarkStart>().Count() +
                    projected.MainDocumentPart.HeaderParts.Sum(x =>
                        x.Header!.Descendants<BookmarkStart>().Count()) +
                    projected.MainDocumentPart.FooterParts.Sum(x =>
                        x.Footer!.Descendants<BookmarkStart>().Count()));
                Assert.Empty(new OpenXmlValidator().Validate(projected));
            }
            finally
            {
                if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                    Directory.Delete(directory, true);
            }
        }
    }

