    [Fact]
    public void DocRoundTripPreservesAllExplicitHeaderFooterStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var settings = main.AddNewPart<DocumentSettingsPart>();
            settings.Settings = new Settings(new EvenAndOddHeaders());
            settings.Settings.Save();

            HeaderReference AddHeader(string text, HeaderFooterValues type)
            {
                var part = main.AddNewPart<HeaderPart>();
                part.Header = new Header(new Paragraph(new Run(new Text(text))));
                part.Header.Save();
                return new HeaderReference { Type = type, Id = main.GetIdOfPart(part) };
            }
            FooterReference AddFooter(string text, HeaderFooterValues type)
            {
                var part = main.AddNewPart<FooterPart>();
                part.Footer = new Footer(new Paragraph(new Run(new Text(text))));
                part.Footer.Save();
                return new FooterReference { Type = type, Id = main.GetIdOfPart(part) };
            }

            var section = new SectionProperties(
                AddHeader("Even header", HeaderFooterValues.Even),
                AddHeader("Odd header", HeaderFooterValues.Default),
                AddFooter("Even footer", HeaderFooterValues.Even),
                AddFooter("Odd footer", HeaderFooterValues.Default),
                AddHeader("First header", HeaderFooterValues.First),
                AddFooter("First footer", HeaderFooterValues.First),
                new TitlePage());
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Body"))), section));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            Assert.Equal("Body\r", string.Concat(index.GetPartSpans("Main").Select(x => x.Text)));
            Assert.Equal(12, index.HeaderStories.Count);
            var expected = new[] { "Even header", "Odd header", "Even footer",
                "Odd footer", "First header", "First footer" };
            for (var i = 0; i < expected.Length; i++)
                Assert.Equal(expected[i], string.Concat(index.HeaderStories[6 + i]
                    .ReadContent().Paragraphs.SelectMany(x => x.Atoms).Select(x => x.Text)));
        }

        var projected = DxpDocToDocx.Project(docBytes);
        using var stream = new MemoryStream(projected.DocxBytes);
        using var document2 = WordprocessingDocument.Open(stream, false);
        var main2 = document2.MainDocumentPart!;
        var section2 = Assert.Single(main2.Document!.Body!.Elements<SectionProperties>());
        Assert.Equal(3, section2.Elements<HeaderReference>().Count());
        Assert.Equal(3, section2.Elements<FooterReference>().Count());
        Assert.Empty(new OpenXmlValidator().Validate(document2));
    }

    [Fact]
    public void ProjectionRejectsHeaderSlotCountThatOmitsASection()
    {
        var path = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc",
            "WordThreeSectionEmptyInheritedHeader.docx"));
        var generated = DxpDocExport.Export(File.ReadAllBytes(path));
        using var edited = new MemoryStream();
        edited.Write(generated);
        using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
        using (var word = compound.OpenStream("WordDocument"))
        using (var table = compound.OpenStream("1Table"))
        {
            const int pair = 154 + 11 * 8;
            var location = new byte[8];
            word.Position = pair;
            word.ReadExactly(location);
            var offset = BinaryPrimitives.ReadUInt32LittleEndian(location);
            var length = BinaryPrimitives.ReadUInt32LittleEndian(location.AsSpan(4));
            Assert.True(length >= 24);
            // Keep the PLC terminal CP while dropping one section's six slots.
            table.Position = offset + length - 4;
            var terminalCp = new byte[4];
            table.ReadExactly(terminalCp);
            table.Position = offset + length - 28;
            table.Write(terminalCp);
            word.Position = pair + 4;
            var shortenedLength = new byte[4];
            BinaryPrimitives.WriteUInt32LittleEndian(shortenedLength, length - 24);
            word.Write(shortenedLength);
            compound.Flush();
        }
        using var input = new MemoryStream(edited.ToArray());
        using var index = new DocTextIndexWalker().Index(input);
        Assert.Equal(3, index.Sections.Count);
        Assert.Equal(18, index.HeaderStories.Count);
        Assert.Throws<InvalidDataException>(() =>
            new DocToDocxProjector().Project(index));
    }
    [Fact]
    public void DocRoundTripKeepsHeadersBoundToTheirSections()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            HeaderReference AddHeader(string text)
            {
                var header = main.AddNewPart<HeaderPart>();
                header.Header = new Header(new Paragraph(new Run(new Text(text))));
                header.Header.Save();
                return new HeaderReference
                {
                    Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header)
                };
            }
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    AddHeader("Section one"))), new Run(new Text("First"))),
                new Paragraph(new Run(new Text("Second"))),
                new SectionProperties(AddHeader("Section two"))));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            Assert.Equal("First\fSecond\r",
                string.Concat(index.GetPartSpans("Main").Select(x => x.Text)));
            Assert.Equal(2, index.Sections.Count);
            Assert.Equal(18, index.HeaderStories.Count);
            Assert.Equal("Section one", Assert.Single(index.HeaderStories[7]
                .ReadContent().Paragraphs[0].Atoms).Text);
            Assert.Equal("Section two", Assert.Single(index.HeaderStories[13]
                .ReadContent().Paragraphs[0].Atoms).Text);
        }

        var projection = DxpDocToDocx.Project(docBytes);
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var body = projected.MainDocumentPart!.Document!.Body!;
        var firstSection = Assert.Single(body.Elements<Paragraph>().First()
            .ParagraphProperties!.Elements<SectionProperties>());
        var lastSection = Assert.Single(body.Elements<SectionProperties>());
        Assert.NotEqual(Assert.Single(firstSection.Elements<HeaderReference>()).Id!.Value,
            Assert.Single(lastSection.Elements<HeaderReference>()).Id!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

