    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(4)]
    [InlineData(8)]
    [InlineData(16)]
    [InlineData(32)]
    [InlineData(64)]
    [InlineData(128)]
    [InlineData(192)]
    [InlineData(255)]
    [InlineData(256)]
    public void TwoPlainSectionsOpenInWord(int mode)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var firstSection = new SectionProperties();
            if ((mode & 16) != 0) firstSection.AppendChild(
                new SectionType { Val = SectionMarkValues.Continuous });
            if ((mode & 1) != 0) firstSection.AppendChild(new PageSize
                { Width = 15840, Height = 12240,
                    Orient = PageOrientationValues.Landscape });
            if ((mode & 2) != 0) firstSection.AppendChild(new PageMargin
                { Left = 1800, Right = 1600, Top = 1200,
                    Bottom = 1400, Header = 600, Footer = 700, Gutter = 200 });
            if ((mode & 256) != 0) firstSection.AppendChild(new PageMargin
                { Left = 1440, Right = 1440, Top = -1100,
                    Bottom = -1200, Header = 720, Footer = 720 });
            if ((mode & 4) != 0) firstSection.AppendChild(new Columns
                { ColumnCount = 2, Space = "720" });
            if ((mode & 8) != 0) firstSection.AppendChild(new TitlePage());
            var finalSection = new SectionProperties();
            if ((mode & 32) != 0) finalSection.AppendChild(
                new SectionType { Val = SectionMarkValues.OddPage });
            if ((mode & 64) != 0)
                finalSection.AppendChild(new PageSize { Width = 12240,
                    Height = 15840, Orient = PageOrientationValues.Portrait });
            if ((mode & 128) != 0)
                finalSection.AppendChild(new PageMargin { Left = 900, Right = 1000,
                    Top = 1100, Bottom = 1200, Header = 400, Footer = 500,
                    Gutter = 0 });
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(firstSection),
                    new Run(new Text("First"))),
                new Paragraph(new Run(new Text("Second"))),
                finalSection));
            main.Document.Save();
        }
        var binary = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Equal(2, index.Sections.Count);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), binary, 0.03);
    }

