    [Fact]
    public void UnevenSectionColumnsRoundTrip()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Left column"))),
                new SectionProperties(
                    new PageSize { Width = 12240, Height = 15840 },
                    new PageMargin { Left = 1440, Right = 1440, Top = 1440,
                        Bottom = 1440, Header = 720, Footer = 720 },
                    new Columns(new Column { Width = "5400", Space = "720" },
                        new Column { Width = "3240" })
                    { ColumnCount = 2, EqualWidth = false, Separator = true })));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var stream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(stream))
            Assert.Single(index.Sections);
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(docBytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var columns = projected.MainDocumentPart!.Document!.Body!
            .GetFirstChild<SectionProperties>()!.GetFirstChild<Columns>()!;
        Assert.False(columns.EqualWidth!.Value);
        Assert.True(columns.Separator!.Value);
        Assert.Equal((short)2, columns.ColumnCount!.Value);
        var children = columns.Elements<Column>().ToArray();
        Assert.Equal(2, children.Length);
        Assert.Equal("5400", children[0].Width!.Value);
        Assert.Equal("720", children[0].Space!.Value);
        Assert.Equal("3240", children[1].Width!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), docBytes, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-uneven-columns-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, docBytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? original = null, generated = null;
        try
        {
            original = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            generated = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            dynamic sourceColumns = original.Sections.Item(1).PageSetup.TextColumns;
            dynamic generatedColumns = generated.Sections.Item(1).PageSetup.TextColumns;
            Assert.Equal(2, (int)generatedColumns.Count);
            Assert.Equal((int)sourceColumns.LineBetween,
                (int)generatedColumns.LineBetween);
            for (var column = 1; column <= 2; column++)
                Assert.Equal((double)sourceColumns.Item(column).Width,
                    (double)generatedColumns.Item(column).Width, 1);
            Assert.Equal((double)sourceColumns.Item(1).SpaceAfter,
                (double)generatedColumns.Item(1).SpaceAfter, 1);
            original.SaveAs2(nativePath, 0);
            original.Close(false);
            original = null;
            using var nativeStream = new MemoryStream(
                DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            var nativeColumns = native.MainDocumentPart!.Document!.Body!
                .GetFirstChild<SectionProperties>()!.GetFirstChild<Columns>()!;
            Assert.False(nativeColumns.EqualWidth!.Value);
            Assert.True(nativeColumns.Separator!.Value);
            var nativeChildren = nativeColumns.Elements<Column>().ToArray();
            Assert.Equal(2, nativeChildren.Length);
            Assert.Equal("5400", nativeChildren[0].Width!.Value);
            Assert.Equal("720", nativeChildren[0].Space!.Value);
            Assert.Equal("3240", nativeChildren[1].Width!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (original != null) original.Close(false);
            if (generated != null) generated.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void SectionPageGeometryAndDistinctStoriesSurviveBothDocRoutes()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var settings = main.AddNewPart<DocumentSettingsPart>();
            settings.Settings = new Settings(new EvenAndOddHeaders());
            settings.Settings.Save();
            HeaderPart Header(string value)
            {
                var part = main.AddNewPart<HeaderPart>();
                part.Header = new Header(new Paragraph(new Run(new Text(value))));
                part.Header.Save();
                return part;
            }
            FooterPart Footer(string value)
            {
                var part = main.AddNewPart<FooterPart>();
                part.Footer = new Footer(new Paragraph(new Run(new Text(value)
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve })));
                part.Footer.Save();
                return part;
            }
            SectionProperties Section(bool landscape, HeaderPart header,
                FooterPart footer) => new(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new SectionType { Val = SectionMarkValues.NextPage },
                    new PageSize { Width = landscape ? 15840U : 12240U,
                        Height = landscape ? 12240U : 15840U,
                        Orient = landscape ? PageOrientationValues.Landscape :
                            PageOrientationValues.Portrait },
                    new PageMargin { Left = landscape ? 1800U : 900U,
                        Right = landscape ? 1200U : 1000U,
                        Top = 1200, Bottom = 1200,
                        Header = landscape ? 500U : 300U,
                        Footer = landscape ? 600U : 400U });
            var first = Section(true, Header("Landscape header"),
                Footer("Landscape footer"));
            first.InsertBefore(new HeaderReference
            {
                Type = HeaderFooterValues.First,
                Id = main.GetIdOfPart(Header("Landscape first header"))
            }, first.GetFirstChild<FooterReference>());
            first.InsertBefore(new FooterReference
            {
                Type = HeaderFooterValues.First,
                Id = main.GetIdOfPart(Footer("Landscape first footer"))
            }, first.GetFirstChild<SectionType>());
            first.AppendChild(new TitlePage());
            var second = Section(false, Header("Portrait header"),
                Footer("Portrait footer"));
            var evenFooter = Footer("Portrait even footer ");
            evenFooter.Footer!.GetFirstChild<Paragraph>()!.AppendChild(
                new SimpleField(new Run(new Text("VII")))
                    { Instruction = " PAGE " });
            evenFooter.Footer.Save();
            second.InsertBefore(new HeaderReference
            {
                Type = HeaderFooterValues.Even,
                Id = main.GetIdOfPart(Header("Portrait even header"))
            }, second.GetFirstChild<FooterReference>());
            second.InsertBefore(new FooterReference
            {
                Type = HeaderFooterValues.Even,
                Id = main.GetIdOfPart(evenFooter)
            }, second.GetFirstChild<SectionType>());
            second.AppendChild(new PageNumberType { Start = 7,
                Format = NumberFormatValues.UpperRoman });
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(first),
                    new Run(new Text("Landscape body"))),
                new Paragraph(new Run(new Text("Portrait body"))),
                new Paragraph(new Run(new Break { Type = BreakValues.Page }),
                    new Run(new Text("Portrait later body"))), second));
            main.Document.Save();
        }

        static void AssertProjected(byte[] binary)
        {
            var docx = DxpDocToDocx.Project(binary).DocxBytes;
            using var stream = new MemoryStream(docx);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            var body = main.Document!.Body!;
            Assert.Equal(new[] { "Landscape body", "Portrait body",
                "Portrait later body" },
                body.Elements<Paragraph>().Select(x => x.InnerText));
            var sections = body.Descendants<SectionProperties>().ToArray();
            Assert.Equal(2, sections.Length);
            Assert.Equal(new[] { PageOrientationValues.Landscape,
                PageOrientationValues.Portrait }, sections.Select(x =>
                x.GetFirstChild<PageSize>()?.Orient?.Value ??
                PageOrientationValues.Portrait));
            Assert.Equal(new uint[] { 1800, 900 }, sections.Select(x =>
                x.GetFirstChild<PageMargin>()!.Left!.Value));
            Assert.Equal(new uint[] { 500, 300 }, sections.Select(x =>
                x.GetFirstChild<PageMargin>()!.Header!.Value));
            Assert.Equal(new uint[] { 600, 400 }, sections.Select(x =>
                x.GetFirstChild<PageMargin>()!.Footer!.Value));
            Assert.Equal(7, sections[1].GetFirstChild<PageNumberType>()?.Start?.Value);
            Assert.Equal(NumberFormatValues.UpperRoman,
                sections[1].GetFirstChild<PageNumberType>()?.Format?.Value);
            Assert.Equal(new[] { "Landscape header", "Portrait header" },
                sections.Select(x => ((HeaderPart)main.GetPartById(
                    Assert.Single(x.Elements<HeaderReference>(), reference =>
                        reference.Type?.Value == HeaderFooterValues.Default).Id!))
                    .Header!.InnerText));
            Assert.Equal(new[] { "Landscape footer", "Portrait footer" },
                sections.Select(x => ((FooterPart)main.GetPartById(
                    Assert.Single(x.Elements<FooterReference>(), reference =>
                        reference.Type?.Value == HeaderFooterValues.Default).Id!))
                    .Footer!.InnerText));
            Assert.NotNull(sections[0].GetFirstChild<TitlePage>());
            Assert.Equal("Landscape first header", ((HeaderPart)main.GetPartById(
                Assert.Single(sections[0].Elements<HeaderReference>(), x =>
                    x.Type?.Value == HeaderFooterValues.First).Id!)).Header!.InnerText);
            Assert.Equal("Landscape first footer", ((FooterPart)main.GetPartById(
                Assert.Single(sections[0].Elements<FooterReference>(), x =>
                    x.Type?.Value == HeaderFooterValues.First).Id!)).Footer!.InnerText);
            Assert.NotNull(main.DocumentSettingsPart?.Settings?.GetFirstChild<EvenAndOddHeaders>());
            Assert.Equal("Portrait even header", ((HeaderPart)main.GetPartById(
                Assert.Single(sections[1].Elements<HeaderReference>(), x =>
                    x.Type?.Value == HeaderFooterValues.Even).Id!)).Header!.InnerText);
            var evenFooterOut = ((FooterPart)main.GetPartById(
                Assert.Single(sections[1].Elements<FooterReference>(), x =>
                    x.Type?.Value == HeaderFooterValues.Even).Id!)).Footer!;
            Assert.Equal("Portrait even footer VII", string.Concat(
                evenFooterOut.Descendants<Text>().Select(x => x.Text)));
            Assert.Contains(evenFooterOut.Descendants<SimpleField>()
                .Select(x => x.Instruction?.Value)
                .Concat(evenFooterOut.Descendants<FieldCode>().Select(x => x.Text)),
                instruction => instruction?.Contains("PAGE", StringComparison.Ordinal) == true);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }

        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjected(generated);
        AssertProjected(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 1);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 2);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 3);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            "docxport-section-stories-" + Guid.NewGuid().ToString("N") + ".docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        dynamic? opened = null;
        try
        {
            word.Visible = false;
            word.DisplayAlerts = 0;
            opened = word.Documents.Open(sourcePath, false, false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            AssertProjected(native);
            AssertProjected(DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesSectionPageSetupWithoutHeaders()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(
                    new Justification { Val = JustificationValues.Center },
                    new SectionProperties(
                        new SectionType { Val = SectionMarkValues.Continuous },
                        new PageSize { Width = 15840, Height = 12240,
                            Orient = PageOrientationValues.Landscape },
                        new PageMargin { Left = 1800, Right = 1600, Top = 1200,
                            Bottom = 1400, Header = 600, Footer = 700, Gutter = 200 },
                        new PageBorders(
                            new TopBorder { Val = BorderValues.Single, Size = 16,
                                Space = 12, Color = "AA3366" },
                            new LeftBorder { Val = BorderValues.Dashed, Size = 8,
                                Space = 12, Color = "3366AA" },
                            new BottomBorder { Val = BorderValues.Single, Size = 16,
                                Space = 12, Color = "AA3366" },
                            new RightBorder { Val = BorderValues.Dashed, Size = 8,
                                Space = 12, Color = "3366AA" })
                        { Display = PageBorderDisplayValues.FirstPage,
                            OffsetFrom = PageBorderOffsetValues.Page,
                            ZOrder = PageBorderZOrderValues.Back },
                        new Columns { ColumnCount = 2, Space = "720" },
                        new VerticalTextAlignmentOnPage
                            { Val = VerticalJustificationValues.Center },
                        new TitlePage(),
                        new BiDi(),
                        new GutterOnRight())),
                    new Run(new Text("First"))),
                new Paragraph(new Run(new Text("Second"))),
                new SectionProperties(
                    new SectionType { Val = SectionMarkValues.OddPage },
                    new PageSize { Width = 12240, Height = 15840,
                        Orient = PageOrientationValues.Portrait },
                    new PageMargin { Left = 900, Right = 1000, Top = -1100,
                        Bottom = -1200, Header = 400, Footer = 500, Gutter = 0 },
                    new PageNumberType { Start = 7,
                        Format = NumberFormatValues.LowerRoman },
                    new VerticalTextAlignmentOnPage
                        { Val = VerticalJustificationValues.Bottom })));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var stream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(stream))
        {
            Assert.Equal(2, index.Sections.Count);
            Assert.All(index.Sections, section => Assert.Contains(section.Children,
                child => child.Kind == "Sepx"));
            var paragraphs = index.ReadStory("Main").ParagraphRanges;
            var sectionMark = Assert.Single(paragraphs,
                x => x.EndKind == DocParagraphEnd.SectionMark);
            Assert.Equal(index.Sections[0].Attributes["cpEnd"],
                sectionMark.SourceCpEnd?.ToString(
                    System.Globalization.CultureInfo.InvariantCulture));
            Assert.Equal(index.GetTextOffset(sectionMark.SourceCpStart!.Value),
                sectionMark.SourceTextOffsetStart);
        }
        var projection = DxpDocToDocx.Project(docBytes);
        Assert.False(projection.Coverage.ApproximateCharacters.ContainsKey(0x000C));
        using var projectedStream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var body = projected.MainDocumentPart!.Document!.Body!;
        var first = body.Elements<Paragraph>().First();
        Assert.Equal(JustificationValues.Center,
            first.ParagraphProperties!.GetFirstChild<Justification>()!.Val!.Value);
        var firstSection = first.ParagraphProperties.GetFirstChild<SectionProperties>()!;
        var lastSection = body.GetFirstChild<SectionProperties>()!;
        Assert.Equal((uint)15840, firstSection.GetFirstChild<PageSize>()!.Width!.Value);
        Assert.Equal(PageOrientationValues.Landscape,
            firstSection.GetFirstChild<PageSize>()!.Orient!.Value);
        Assert.Equal((uint)600, firstSection.GetFirstChild<PageMargin>()!.Header!.Value);
        Assert.Equal((uint)200, firstSection.GetFirstChild<PageMargin>()!.Gutter!.Value);
        var pageBorders = firstSection.GetFirstChild<PageBorders>()!;
        Assert.Equal(BorderValues.Single, pageBorders.GetFirstChild<TopBorder>()!.Val!.Value);
        Assert.Equal("AA3366", pageBorders.GetFirstChild<TopBorder>()!.Color!.Value);
        Assert.Equal(BorderValues.Dashed, pageBorders.GetFirstChild<LeftBorder>()!.Val!.Value);
        Assert.Equal("3366AA", pageBorders.GetFirstChild<LeftBorder>()!.Color!.Value);
        Assert.Equal(4, pageBorders.ChildElements.Count);
        Assert.Equal(PageBorderOffsetValues.Page, pageBorders.OffsetFrom!.Value);
        Assert.Equal(PageBorderDisplayValues.FirstPage, pageBorders.Display!.Value);
        Assert.Equal(PageBorderZOrderValues.Back, pageBorders.ZOrder!.Value);
        Assert.Equal(SectionMarkValues.Continuous,
            firstSection.GetFirstChild<SectionType>()!.Val!.Value);
        Assert.Equal((short)2, firstSection.GetFirstChild<Columns>()!.ColumnCount!.Value);
        Assert.Equal("720", firstSection.GetFirstChild<Columns>()!.Space!.Value);
        Assert.Equal(VerticalJustificationValues.Center,
            firstSection.GetFirstChild<VerticalTextAlignmentOnPage>()!.Val!.Value);
        Assert.NotNull(firstSection.GetFirstChild<TitlePage>());
        Assert.NotNull(firstSection.GetFirstChild<BiDi>());
        Assert.NotNull(firstSection.GetFirstChild<GutterOnRight>());
        Assert.Equal((uint)12240, lastSection.GetFirstChild<PageSize>()!.Width!.Value);
        Assert.Equal(SectionMarkValues.OddPage,
            lastSection.GetFirstChild<SectionType>()!.Val!.Value);
        Assert.Equal((uint)500, lastSection.GetFirstChild<PageMargin>()!.Footer!.Value);
        Assert.Equal(-1100, lastSection.GetFirstChild<PageMargin>()!.Top!.Value);
        Assert.Equal(-1200, lastSection.GetFirstChild<PageMargin>()!.Bottom!.Value);
        Assert.Equal(7, lastSection.GetFirstChild<PageNumberType>()!.Start!.Value);
        Assert.Equal(NumberFormatValues.LowerRoman,
            lastSection.GetFirstChild<PageNumberType>()!.Format!.Value);
        Assert.Equal(VerticalJustificationValues.Bottom,
            lastSection.GetFirstChild<VerticalTextAlignmentOnPage>()!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), docBytes, 0.03);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-section-geometry-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, docBytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? original = null, generated = null;
        try
        {
            original = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            generated = word.Documents.Open(generatedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(2, (int)original.Sections.Count);
            Assert.Equal(2, (int)generated.Sections.Count);
            for (var section = 1; section <= 2; section++)
            {
                dynamic sourceSetup = original.Sections[section].PageSetup;
                dynamic generatedSetup = generated.Sections[section].PageSetup;
                Assert.Equal((int)sourceSetup.Orientation,
                    (int)generatedSetup.Orientation);
                Assert.Equal((double)sourceSetup.PageWidth,
                    (double)generatedSetup.PageWidth, 1);
                Assert.Equal((double)sourceSetup.PageHeight,
                    (double)generatedSetup.PageHeight, 1);
                Assert.Equal((double)sourceSetup.LeftMargin,
                    (double)generatedSetup.LeftMargin, 1);
                Assert.Equal((double)sourceSetup.RightMargin,
                    (double)generatedSetup.RightMargin, 1);
                Assert.Equal((double)sourceSetup.TopMargin,
                    (double)generatedSetup.TopMargin, 1);
                Assert.Equal((double)sourceSetup.BottomMargin,
                    (double)generatedSetup.BottomMargin, 1);
                Assert.Equal((double)sourceSetup.HeaderDistance,
                    (double)generatedSetup.HeaderDistance, 1);
                Assert.Equal((double)sourceSetup.FooterDistance,
                    (double)generatedSetup.FooterDistance, 1);
                Assert.Equal((double)sourceSetup.Gutter,
                    (double)generatedSetup.Gutter, 1);
                Assert.Equal((int)sourceSetup.TextColumns.Count,
                    (int)generatedSetup.TextColumns.Count);
                Assert.Equal((double)sourceSetup.TextColumns.Spacing,
                    (double)generatedSetup.TextColumns.Spacing, 1);
                Assert.Equal((int)sourceSetup.DifferentFirstPageHeaderFooter,
                    (int)generatedSetup.DifferentFirstPageHeaderFooter);
                Assert.Equal((int)sourceSetup.SectionStart,
                    (int)generatedSetup.SectionStart);
                Assert.Equal((int)sourceSetup.VerticalAlignment,
                    (int)generatedSetup.VerticalAlignment);
            }
            Assert.Equal((int)original.Sections[2].Footers.Item(1).PageNumbers.StartingNumber,
                (int)generated.Sections[2].Footers.Item(1).PageNumbers.StartingNumber);
            Assert.Equal(7, (int)generated.Sections[2].Footers.Item(1).PageNumbers.StartingNumber);
            Assert.Equal((int)original.Sections[2].Footers.Item(1).PageNumbers.NumberStyle,
                (int)generated.Sections[2].Footers.Item(1).PageNumbers.NumberStyle);
            original.SaveAs2(nativePath, 0);
            original.Close(false);
            original = null;
            using var nativeStream = new MemoryStream(
                DxpDocToDocx.Project(File.ReadAllBytes(nativePath)).DocxBytes);
            using var native = WordprocessingDocument.Open(nativeStream, false);
            var nativeBody = native.MainDocumentPart!.Document!.Body!;
            Assert.Equal(PageOrientationValues.Landscape,
                nativeBody.Elements<Paragraph>().First().ParagraphProperties?
                    .GetFirstChild<SectionProperties>()?.GetFirstChild<PageSize>()?
                    .Orient?.Value);
            Assert.Equal(PageOrientationValues.Portrait,
                nativeBody.GetFirstChild<SectionProperties>()?
                    .GetFirstChild<PageSize>()?.Orient?.Value ??
                    PageOrientationValues.Portrait);
            Assert.Equal(7, nativeBody.GetFirstChild<SectionProperties>()?
                .GetFirstChild<PageNumberType>()?.Start?.Value);
            Assert.Equal(NumberFormatValues.LowerRoman,
                nativeBody.GetFirstChild<SectionProperties>()?
                    .GetFirstChild<PageNumberType>()?.Format?.Value);
            Assert.Equal(-1100, nativeBody.GetFirstChild<SectionProperties>()?
                .GetFirstChild<PageMargin>()?.Top?.Value);
            Assert.Equal(-1200, nativeBody.GetFirstChild<SectionProperties>()?
                .GetFirstChild<PageMargin>()?.Bottom?.Value);
            Assert.Equal(VerticalJustificationValues.Center,
                nativeBody.Elements<Paragraph>().First().ParagraphProperties?
                    .GetFirstChild<SectionProperties>()?
                    .GetFirstChild<VerticalTextAlignmentOnPage>()?.Val?.Value);
            var nativePageBorders = nativeBody.Elements<Paragraph>().First()
                .ParagraphProperties?.GetFirstChild<SectionProperties>()?
                .GetFirstChild<PageBorders>();
            Assert.Equal("AA3366", nativePageBorders?.GetFirstChild<TopBorder>()?.Color?.Value);
            Assert.Equal("3366AA", nativePageBorders?.GetFirstChild<LeftBorder>()?.Color?.Value);
            Assert.Equal(BorderValues.Single,
                nativePageBorders?.GetFirstChild<TopBorder>()?.Val?.Value);
            Assert.Equal(BorderValues.Dashed,
                nativePageBorders?.GetFirstChild<LeftBorder>()?.Val?.Value);
            Assert.Equal((uint)16,
                nativePageBorders?.GetFirstChild<TopBorder>()?.Size?.Value);
            Assert.Equal((uint)12,
                nativePageBorders?.GetFirstChild<TopBorder>()?.Space?.Value);
            Assert.Equal(PageBorderOffsetValues.Page, nativePageBorders?.OffsetFrom?.Value);
            Assert.Equal(PageBorderDisplayValues.FirstPage, nativePageBorders?.Display?.Value);
            Assert.Equal(PageBorderZOrderValues.Back, nativePageBorders?.ZOrder?.Value);
            Assert.NotNull(nativeBody.Elements<Paragraph>().First()
                .ParagraphProperties?.GetFirstChild<SectionProperties>()?
                .GetFirstChild<BiDi>());
            Assert.NotNull(nativeBody.Elements<Paragraph>().First()
                .ParagraphProperties?.GetFirstChild<SectionProperties>()?
                .GetFirstChild<GutterOnRight>());
            Assert.Equal(VerticalJustificationValues.Bottom,
                nativeBody.GetFirstChild<SectionProperties>()?
                    .GetFirstChild<VerticalTextAlignmentOnPage>()?.Val?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(native));
        }
        finally
        {
            if (original != null) original.Close(false);
            if (generated != null) generated.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void SupplementaryUnicodeTextSurvivesAllStoriesAndBothDocRoutes()
    {
        const string bodyText = "Body \U0001F600 symbol";
        const string headerText = "Header \U0001D11E symbol";
        const string footerText = "Footer \U0001F600 \U0001D11E";
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new Run(new Text("Header ") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new Italic()), new Text("\U0001D11E")),
                new Run(new Text(" symbol") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve })));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(
                new Run(new Text("Footer ") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new Underline { Val = UnderlineValues.Single }),
                    new Text("\U0001F600 \U0001D11E"))));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(
                    new Run(new Text("Body ") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                    new Run(new RunProperties(new Bold()), new Text("\U0001F600")),
                    new Run(new Text(" symbol") { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve })),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        void AssertIndex(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.Contains(bodyText, string.Concat(index.GetPartSpans("Main")
                .Select(span => span.Text)));
            var indexedMain = index.ReadStory("Main");
            Assert.Contains(indexedMain.CharacterFormatting, range =>
                range.CpStart <= 5 && range.CpEnd >= 7 &&
                range.Formatting.Bold == true);
            Assert.All(indexedMain.CharacterFormatting, range =>
                Assert.True(range.CpStart < indexedMain.Text.CpEnd &&
                    range.CpEnd > indexedMain.Text.CpStart));
            Assert.True(index.HeaderStories.Count > 9,
                $"Header count {index.HeaderStories.Count}; parts: {string.Join(",", index.Parts.Select(x => x.Name))}");
            Assert.Equal(headerText, index.HeaderStories[7].ReadContent()
                .Paragraphs[0].Atoms[0].Text);
            var indexedHeader = index.HeaderStories[7].ReadIndexedContent();
            Assert.Contains(indexedHeader.CharacterFormatting, range =>
                range.CpStart <= indexedHeader.Text.CpStart + 7 &&
                range.CpEnd >= indexedHeader.Text.CpStart + 9 &&
                range.Formatting.Italic == true);
            Assert.All(indexedHeader.ParagraphStyles, range =>
                Assert.True(range.CpStart < indexedHeader.Text.CpEnd &&
                    range.CpEnd > indexedHeader.Text.CpStart));
            Assert.Equal(footerText, index.HeaderStories[9].ReadContent()
                .Paragraphs[0].Atoms[0].Text);
            void AssertSupplementaryAt(string partName, uint cp)
            {
                var span = Assert.Single(index.GetPartSpans(partName).Where(x =>
                    x.CpStart <= cp && x.CpEnd >= cp + 2));
                Assert.Equal("utf16", span.Piece.Encoding);
                var start = span.Piece.GetTextOffset(cp);
                Assert.Equal(start + 4, span.Piece.GetTextOffset(cp + 2));
                Assert.Equal(cp, span.Piece.GetCharacterPosition(start));
            }
            AssertSupplementaryAt("Main", 5);
            AssertSupplementaryAt("Headers", index.HeaderStories[7].CpStart + 7);
            AssertSupplementaryAt("Headers", index.HeaderStories[9].CpStart + 7);
            AssertSupplementaryAt("Headers", index.HeaderStories[9].CpStart + 10);
            Assert.Contains(index.CharacterFormatting, range =>
                range.CpStart <= 5 && range.CpEnd >= 7 &&
                range.Formatting.Bold == true);
            Assert.Contains(index.CharacterFormatting, range =>
                range.CpStart <= index.HeaderStories[7].CpStart + 7 &&
                range.CpEnd >= index.HeaderStories[7].CpStart + 9 &&
                range.Formatting.Italic == true);
            Assert.Contains(index.CharacterFormatting, range =>
                range.CpStart <= index.HeaderStories[9].CpStart + 7 &&
                range.CpEnd >= index.HeaderStories[9].CpStart + 9 &&
                range.Formatting.UnderlineCode == 1);
        }
        void AssertDocx(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(input, false);
            var main = document.MainDocumentPart!;
            Assert.Equal(bodyText, main.Document.Body!.Descendants<Text>()
                .Select(x => x.Text).Aggregate(string.Concat));
            Assert.Equal(headerText, Assert.Single(main.HeaderParts).Header!
                .Descendants<Text>().Select(x => x.Text).Aggregate(string.Concat));
            Assert.Equal(footerText, Assert.Single(main.FooterParts).Footer!
                .Descendants<Text>().Select(x => x.Text).Aggregate(string.Concat));
            Assert.NotNull(main.Document.Body.Descendants<Run>().Single(x => x.InnerText.Contains("\U0001F600"))
                .RunProperties?.GetFirstChild<Bold>());
            Assert.NotNull(Assert.Single(main.HeaderParts).Header!
                .Descendants<Run>().Single(x => x.InnerText.Contains("\U0001D11E")).RunProperties?.GetFirstChild<Italic>());
            Assert.Equal(UnderlineValues.Single, Assert.Single(main.FooterParts).Footer!
                .Descendants<Run>().Single(x => x.InnerText.Contains("\U0001F600")).RunProperties?
                .GetFirstChild<Underline>()?.Val?.Value);
            Assert.Null(main.Document.Body.Descendants<Run>().First()
                .RunProperties?.GetFirstChild<Bold>());
            Assert.Null(main.Document.Body.Descendants<Run>().Last()
                .RunProperties?.GetFirstChild<Bold>());
            Assert.Null(Assert.Single(main.HeaderParts).Header!
                .Descendants<Run>().First().RunProperties?.GetFirstChild<Italic>());
            Assert.Null(Assert.Single(main.FooterParts).Footer!
                .Descendants<Run>().First().RunProperties?.GetFirstChild<Underline>());
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertIndex(generated);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertDocx(projected);
        var repeated = DxpDocExport.Export(projected);
        AssertIndex(repeated);
        AssertDocx(DxpDocToDocx.Project(repeated).DocxBytes);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var sourcePath = Path.Combine(Path.GetTempPath(),
                "docxport-supplementary-unicode-" + Guid.NewGuid().ToString("N") + ".docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                var native = File.ReadAllBytes(nativePath);
                AssertIndex(native);
                AssertDocx(DxpDocToDocx.Project(native).DocxBytes);
                AssertIndex(DxpDocExport.Export(DxpDocToDocx.Project(native).DocxBytes));
                AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(), projected, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(),
                    DxpDocToDocx.Project(native).DocxBytes, 0.04);
                AssertWordFirstPageRenderClose(source.ToArray(), repeated, 0.04);
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }
    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void DocRoundTripKeepsInheritedHeaderSlotEmpty(
        bool changedSectionLayout, bool directResets)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Story note base" },
                    new StyleRunProperties(new Bold(),
                        new Color { Val = "225588" }))
                { Type = StyleValues.Paragraph, StyleId = "StoryNoteBase" },
                new Style(new StyleName { Val = "Story note derived" },
                    new BasedOn { Val = "StoryNoteBase" },
                    new StyleRunProperties(new Italic()))
                { Type = StyleValues.Paragraph, StyleId = "StoryNoteDerived" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new ParagraphProperties(new ParagraphStyleId { Val = "StoryNoteDerived" }),
                new Run(directResets ? new RunProperties(new Bold { Val = false })
                    : new RunProperties(), new Text("Inherited"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(
                new ParagraphProperties(new ParagraphStyleId { Val = "StoryNoteDerived" }),
                new Run(directResets ? new RunProperties(new Italic { Val = false })
                    : new RunProperties(), new Text("Inherited footer"))));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    new HeaderReference
                    {
                        Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header)
                    }, new FooterReference
                    {
                        Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer)
                    })), new Run(new Text("First"))),
                new Paragraph(new Run(new Text("Second"))),
                changedSectionLayout
                    ? new SectionProperties(
                        new PageSize { Width = 15840, Height = 12240,
                            Orient = PageOrientationValues.Landscape },
                        new PageMargin { Top = 900, Bottom = 900,
                            Left = 1200, Right = 1200, Header = 360, Footer = 360 })
                    : new SectionProperties()));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            Assert.False(index.HeaderStories[7].IsEmpty);
            Assert.False(index.HeaderStories[9].IsEmpty);
            Assert.True(index.HeaderStories[13].IsEmpty);
            Assert.True(index.HeaderStories[15].IsEmpty);
            var baseStyle = Assert.Single(index.StyleDefinitions,
                style => style.Name == "Story note base");
            var derivedStyle = Assert.Single(index.StyleDefinitions,
                style => style.Name == "Story note derived");
            Assert.Equal(baseStyle.Index, derivedStyle.BasedOnIndex);
        }
        var projection = DxpDocToDocx.Project(docBytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var body = projected.MainDocumentPart!.Document!.Body!;
        Assert.Single(body.Elements<Paragraph>().First().ParagraphProperties!
            .Elements<SectionProperties>().Single().Elements<HeaderReference>());
        Assert.Single(body.Elements<Paragraph>().First().ParagraphProperties!
            .Elements<SectionProperties>().Single().Elements<FooterReference>());
        Assert.Empty(body.Elements<SectionProperties>().Single().Elements<HeaderReference>());
        Assert.Empty(body.Elements<SectionProperties>().Single().Elements<FooterReference>());
        void AssertStyledStories(WordprocessingDocument document)
        {
            var main = document.MainDocumentPart!;
            var definitions = main.StyleDefinitionsPart!.Styles!;
            var baseStyle = Assert.Single(definitions.Elements<Style>(),
                style => style.StyleName?.Val?.Value == "Story note base");
            var derived = Assert.Single(definitions.Elements<Style>(),
                style => style.StyleName?.Val?.Value == "Story note derived");
            Assert.Equal(baseStyle.StyleId?.Value, derived.BasedOn?.Val?.Value);
            Assert.NotNull(baseStyle.StyleRunProperties?.Bold);
            Assert.Equal("225588", baseStyle.StyleRunProperties?.Color?.Val?.Value);
            Assert.NotNull(derived.StyleRunProperties?.Italic);
            Assert.Equal(derived.StyleId?.Value, Assert.Single(main.HeaderParts)
                .Header!.Elements<Paragraph>().Single().ParagraphProperties?
                .ParagraphStyleId?.Val?.Value);
            Assert.Equal(derived.StyleId?.Value, Assert.Single(main.FooterParts)
                .Footer!.Elements<Paragraph>().Single().ParagraphProperties?
                .ParagraphStyleId?.Val?.Value);
            var secondSection = main.Document.Body!.GetFirstChild<SectionProperties>()!;
            if (changedSectionLayout)
            {
                Assert.Equal(PageOrientationValues.Landscape,
                    secondSection.GetFirstChild<PageSize>()?.Orient?.Value);
                Assert.Equal((uint)15840,
                    secondSection.GetFirstChild<PageSize>()?.Width?.Value);
                Assert.Equal((uint)1200,
                    secondSection.GetFirstChild<PageMargin>()?.Left?.Value);
                Assert.Equal((uint)360,
                    secondSection.GetFirstChild<PageMargin>()?.Header?.Value);
            }
            if (directResets)
            {
                Assert.False(Assert.Single(main.HeaderParts).Header!
                    .Descendants<Run>().Single().RunProperties?.Bold?.Val?.Value);
                Assert.False(Assert.Single(main.FooterParts).Footer!
                    .Descendants<Run>().Single().RunProperties?.Italic?.Val?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        AssertStyledStories(projected);
        var repeatedDoc = DxpDocExport.Export(projection.DocxBytes);
        using (var repeatStream = new MemoryStream(repeatedDoc))
        using (var repeatIndex = new DocTextIndexWalker().Index(repeatStream))
        {
            Assert.True(repeatIndex.HeaderStories[13].IsEmpty);
            Assert.True(repeatIndex.HeaderStories[15].IsEmpty);
            var inherited = Assert.Single(repeatIndex.StyleDefinitions,
                style => style.Name == "Story note derived");
            Assert.Equal("Story note base", repeatIndex.StyleDefinitions
                .Single(style => style.Index == inherited.BasedOnIndex).Name);
        }
        var repeatedProjection = DxpDocToDocx.Project(repeatedDoc).DocxBytes;
        using (var repeatedStream = new MemoryStream(repeatedProjection))
        using (var repeated = WordprocessingDocument.Open(repeatedStream, false))
            AssertStyledStories(repeated);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            foreach (var page in new[] { 1, 2 })
            {
                AssertWordPageRenderClose(source.ToArray(), docBytes, 0.04, page);
                AssertWordPageRenderClose(source.ToArray(), projection.DocxBytes,
                    0.04, page, ".docx");
                AssertWordPageRenderClose(source.ToArray(), repeatedDoc, 0.04, page);
            }
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-inherited-header-footer-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, docBytes);
        var sourcePath = Path.ChangeExtension(path, ".docx");
        var nativePath = Path.ChangeExtension(path, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        byte[]? nativeDoc = null;
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(2, (int)opened.Sections.Count);
            Assert.Contains("Inherited", (string)opened.Sections.Item(2)
                .Headers.Item(1).Range.Text);
            Assert.Contains("Inherited footer", (string)opened.Sections.Item(2)
                .Footers.Item(1).Range.Text);
            Assert.True((bool)opened.Sections.Item(2).Headers.Item(1).LinkToPrevious);
            Assert.True((bool)opened.Sections.Item(2).Footers.Item(1).LinkToPrevious);
            Assert.Equal(directResets ? 0 : -1,
                (int)opened.Sections.Item(2).Headers.Item(1).Range.Characters.Item(1).Font.Bold);
            Assert.NotEqual(0, (int)opened.Sections.Item(2).Headers.Item(1).Range.Characters.Item(1).Font.Italic);
            Assert.NotEqual(0, (int)opened.Sections.Item(2).Footers.Item(1).Range.Characters.Item(1).Font.Bold);
            Assert.Equal(directResets ? 0 : -1,
                (int)opened.Sections.Item(2).Footers.Item(1).Range.Characters.Item(1).Font.Italic);
            if (changedSectionLayout)
            {
                Assert.Equal(1, (int)opened.Sections.Item(2).PageSetup.Orientation);
                Assert.Equal(60d,
                    Convert.ToDouble(opened.Sections.Item(2).PageSetup.LeftMargin), 1);
                Assert.Equal(18d,
                    Convert.ToDouble(opened.Sections.Item(2).PageSetup.HeaderDistance), 1);
            }
            opened.Close(false);
            opened = word.Documents.Open(sourcePath, ReadOnly: false,
                AddToRecentFiles: false);
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            nativeDoc = File.ReadAllBytes(nativePath);
            using (var nativeStream = new MemoryStream(nativeDoc))
            using (var nativeIndex = new DocTextIndexWalker().Index(nativeStream))
            {
                Assert.True(nativeIndex.HeaderStories[13].IsEmpty);
                Assert.True(nativeIndex.HeaderStories[15].IsEmpty);
                var inherited = Assert.Single(nativeIndex.StyleDefinitions,
                    style => style.Name == "Story note derived");
                Assert.Equal("Story note base", nativeIndex.StyleDefinitions
                    .Single(style => style.Index == inherited.BasedOnIndex).Name);
            }
            var nativeProjection = DxpDocToDocx.Project(nativeDoc).DocxBytes;
            using (var nativeStream = new MemoryStream(nativeProjection))
            using (var nativeProjected = WordprocessingDocument.Open(nativeStream, false))
                AssertStyledStories(nativeProjected);
            var nativeRepeat = DxpDocExport.Export(nativeProjection);
            using (var repeatStream = new MemoryStream(nativeRepeat))
            using (var repeatIndex = new DocTextIndexWalker().Index(repeatStream))
            {
                Assert.True(repeatIndex.HeaderStories[13].IsEmpty);
                Assert.True(repeatIndex.HeaderStories[15].IsEmpty);
            }
            using (var repeatStream = new MemoryStream(DxpDocToDocx.Project(nativeRepeat).DocxBytes))
            using (var repeatProjected = WordprocessingDocument.Open(repeatStream, false))
                AssertStyledStories(repeatProjected);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
            File.Delete(sourcePath);
            if (File.Exists(nativePath)) File.Delete(nativePath);
        }
        if (nativeDoc != null &&
            Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            var nativeProjection = DxpDocToDocx.Project(nativeDoc).DocxBytes;
            var nativeRepeat = DxpDocExport.Export(nativeProjection);
            foreach (var page in new[] { 1, 2 })
            {
                AssertWordPageRenderClose(source.ToArray(), nativeDoc, 0.04, page);
                AssertWordPageRenderClose(source.ToArray(), nativeProjection,
                    0.04, page, ".docx");
                AssertWordPageRenderClose(source.ToArray(), nativeRepeat, 0.04, page);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void DocRoundTripInheritsFirstEvenAndDefaultHeaderFooterStories(
        bool overrideEvenFooter)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var settings = main.AddNewPart<DocumentSettingsPart>();
            settings.Settings = new Settings(new EvenAndOddHeaders());
            settings.Settings.Save();
            HeaderReference Header(string text, HeaderFooterValues type)
            {
                var part = main.AddNewPart<HeaderPart>();
                part.Header = new Header(new Paragraph(new Run(new Text(text))));
                part.Header.Save();
                return new HeaderReference { Type = type, Id = main.GetIdOfPart(part) };
            }
            FooterReference Footer(string text, HeaderFooterValues type)
            {
                var part = main.AddNewPart<FooterPart>();
                part.Footer = new Footer(new Paragraph(new Run(new Text(text))));
                part.Footer.Save();
                return new FooterReference { Type = type, Id = main.GetIdOfPart(part) };
            }
            var first = new SectionProperties(
                Header("Even header", HeaderFooterValues.Even),
                Header("Default header", HeaderFooterValues.Default),
                Footer("Even footer", HeaderFooterValues.Even),
                Footer("Default footer", HeaderFooterValues.Default),
                Header("First header", HeaderFooterValues.First),
                Footer("First footer", HeaderFooterValues.First),
                new TitlePage());
            var second = new SectionProperties();
            if (overrideEvenFooter)
                second.AppendChild(Footer("New even footer", HeaderFooterValues.Even));
            second.AppendChild(new TitlePage());
            var body = new Body(new Paragraph(new ParagraphProperties(first),
                new Run(new Text("First section"))));
            if (overrideEvenFooter)
            {
                body.AppendChild(new Paragraph(new ParagraphProperties(second),
                    new Run(new Text("Second section"))));
                body.AppendChild(new Paragraph(new Run(new Text("Third section"))));
                body.AppendChild(new SectionProperties(new TitlePage()));
            }
            else
            {
                body.AppendChild(new Paragraph(new Run(new Text("Second section"))));
                body.AppendChild(second);
            }
            main.Document = new Document(body);
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(overrideEvenFooter ? 24 : 18, index.HeaderStories.Count);
            Assert.All(index.HeaderStories.Skip(6).Take(6), story => Assert.False(story.IsEmpty));
            for (var slot = 12; slot < 18; slot++)
                Assert.Equal(overrideEvenFooter && slot == 14,
                    !index.HeaderStories[slot].IsEmpty);
            if (overrideEvenFooter)
                Assert.All(index.HeaderStories.Skip(18).Take(6), story =>
                    Assert.True(story.IsEmpty));
        }
        using var projection = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projection, false);
        var sections = projected.MainDocumentPart!.Document!.Body!;
        var firstOut = sections.Elements<Paragraph>().First().ParagraphProperties!
            .GetFirstChild<SectionProperties>()!;
        var secondOut = overrideEvenFooter
            ? sections.Elements<Paragraph>().Skip(1).First().ParagraphProperties!
                .GetFirstChild<SectionProperties>()!
            : sections.GetFirstChild<SectionProperties>()!;
        Assert.Equal(3, firstOut.Elements<HeaderReference>().Count());
        Assert.Equal(3, firstOut.Elements<FooterReference>().Count());
        Assert.Empty(secondOut.Elements<HeaderReference>());
        Assert.Equal(overrideEvenFooter ? 1 : 0,
            secondOut.Elements<FooterReference>().Count());
        Assert.NotNull(secondOut.GetFirstChild<TitlePage>());
        if (overrideEvenFooter)
        {
            var thirdOut = sections.GetFirstChild<SectionProperties>()!;
            Assert.Empty(thirdOut.Elements<HeaderReference>());
            Assert.Empty(thirdOut.Elements<FooterReference>());
            Assert.NotNull(thirdOut.GetFirstChild<TitlePage>());
        }
        Assert.NotNull(projected.MainDocumentPart.DocumentSettingsPart!.Settings!
            .GetFirstChild<EvenAndOddHeaders>());
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
            AssertWordPageRenderClose(source.ToArray(), bytes, 0.04, 2);
            if (overrideEvenFooter)
                AssertWordPageRenderClose(source.ToArray(), bytes, 0.04, 3);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-inherited-six-stories-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true, AddToRecentFiles: false);
            Assert.Equal(overrideEvenFooter ? 3 : 2, (int)opened.Sections.Count);
            foreach (var (kind, expectedHeader, expectedFooter) in new[]
            {
                (1, "Default header", "Default footer"),
                (2, "First header", "First footer"),
                (3, "Even header", "Even footer")
            })
            {
                dynamic header = opened.Sections.Item(2).Headers.Item(kind);
                dynamic footer = opened.Sections.Item(2).Footers.Item(kind);
                Assert.True((bool)header.LinkToPrevious);
                Assert.Equal(!(overrideEvenFooter && kind == 3),
                    (bool)footer.LinkToPrevious);
                Assert.Contains(expectedHeader, (string)header.Range.Text);
                Assert.Contains(overrideEvenFooter && kind == 3
                    ? "New even footer" : expectedFooter, (string)footer.Range.Text);
            }
            if (overrideEvenFooter)
            {
                foreach (var (kind, expectedHeader, expectedFooter) in new[]
                {
                    (1, "Default header", "Default footer"),
                    (2, "First header", "First footer"),
                    (3, "Even header", "New even footer")
                })
                {
                    dynamic header = opened.Sections.Item(3).Headers.Item(kind);
                    dynamic footer = opened.Sections.Item(3).Footers.Item(kind);
                    Assert.True((bool)header.LinkToPrevious);
                    Assert.True((bool)footer.LinkToPrevious);
                    Assert.Contains(expectedHeader, (string)header.Range.Text);
                    Assert.Contains(expectedFooter, (string)footer.Range.Text);
                }
            }
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void DocRoundTripPreservesExplicitBlankHeaderAcrossSections()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var visible = main.AddNewPart<HeaderPart>();
            visible.Header = new Header(new Paragraph(new Run(new Text("Visible header"))));
            visible.Header.Save();
            var blank = main.AddNewPart<HeaderPart>();
            blank.Header = new Header(new Paragraph());
            blank.Header.Save();
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(visible) })),
                    new Run(new Text("First section"))),
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(blank) })),
                    new Run(new Text("Second section"))),
                new Paragraph(new Run(new Text("Third section"))),
                new SectionProperties()));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(24, index.HeaderStories.Count);
            Assert.False(index.HeaderStories[7].IsEmpty);
            Assert.False(index.HeaderStories[13].IsEmpty);
            Assert.True(index.HeaderStories[19].IsEmpty);
            var sections = index.StorySections;
            Assert.Equal(3, sections.Count);
            Assert.Equal(new[] { true, true, false }, sections.Select(x =>
                x.Slots[1].IsPresent));
            Assert.All(sections, section =>
            {
                Assert.Equal(6, section.Slots.Count);
                Assert.Equal(index.GetTextOffset((uint)section.StartCp),
                    section.SourceTextOffsetStart);
                Assert.Equal(index.GetTextOffset((uint)section.EndCp - 1) + 2,
                    section.SourceTextOffsetEnd);
                Assert.NotNull(section.SourceSepxOffset);
            });
            Assert.Equal(sections[0].EndCp, sections[1].StartCp);
            Assert.Equal(sections[1].EndCp, sections[2].StartCp);
            Assert.Equal(index.HeaderStories[7].CpStart,
                sections[0].Slots[1].SourceCpStart);
            Assert.Equal(index.HeaderStories[13].CpEnd - 1,
                sections[1].Slots[1].SourceCpEnd);
        }
        using var projection = new MemoryStream(DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projection, false);
        var paragraphs = projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>().ToArray();
        var first = paragraphs[0].ParagraphProperties!.GetFirstChild<SectionProperties>()!;
        var second = paragraphs[1].ParagraphProperties!.GetFirstChild<SectionProperties>()!;
        var third = projected.MainDocumentPart.Document.Body!
            .GetFirstChild<SectionProperties>()!;
        Assert.Single(first.Elements<HeaderReference>());
        var secondReference = Assert.Single(second.Elements<HeaderReference>());
        Assert.Empty(third.Elements<HeaderReference>());
        var secondPart = (HeaderPart)projected.MainDocumentPart.GetPartById(
            secondReference.Id!.Value!);
        Assert.Empty(secondPart.Header!.Descendants<Text>());
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            for (var page = 1; page <= 3; page++)
                AssertWordPageRenderClose(source.ToArray(), bytes, 0.04, page);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-explicit-blank-header-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true, AddToRecentFiles: false);
            Assert.Equal(3, (int)opened.Sections.Count);
            Assert.Contains("Visible header",
                (string)opened.Sections.Item(1).Headers.Item(1).Range.Text);
            Assert.False((bool)opened.Sections.Item(2).Headers.Item(1).LinkToPrevious);
            Assert.DoesNotContain("Visible header",
                (string)opened.Sections.Item(2).Headers.Item(1).Range.Text);
            Assert.True((bool)opened.Sections.Item(3).Headers.Item(1).LinkToPrevious);
            Assert.DoesNotContain("Visible header",
                (string)opened.Sections.Item(3).Headers.Item(1).Range.Text);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void StyleTabDeletionOperandPreservesItsTolerance()
    {
        var sprms = new byte[]
        {
            0x15, 0xC6, 0x09, 0x01, 0x84, 0x03, 0xB4, 0x00,
            0x01, 0x08, 0x07, 0x00
        };
        var formatting = DocParagraphFormatting.Parse(sprms);
        Assert.Equal(new short[] { 900 }, formatting.ClearedTabPositions);
        Assert.Equal(new[] { new DocTabClearRange(900, 180) },
            formatting.TabClearRanges);
        Assert.Equal(new[] { new DocTabStop(1800, 0, 0) },
            formatting.TabStops);
        var parent = DocParagraphFormatting.Empty with
        {
            TabStops = new[] { new DocTabStop(720, 0, 0),
                new DocTabStop(1440, 0, 0) }
        };
        var (cleared, added) = DocStyleDefinitionsReader.ComposeTabs(parent, formatting);
        Assert.Equal(new short[] { 720, 900 }, cleared);
        Assert.Equal(new short[] { 1440, 1800 },
            added.Select(x => x.PositionTwips));
    }

    [Fact]
    public void ExtendedStyleTabOperandDoesNotConsumeFollowingSprm()
    {
        var sprms = new List<byte> { 0x15, 0xC6, 0xFF, 16 };
        for (short i = 0; i < 16; i++)
        {
            var position = (short)(i * 100);
            sprms.Add((byte)position);
            sprms.Add((byte)(position >> 8));
        }
        for (var i = 0; i < 16; i++)
        {
            sprms.Add(25);
            sprms.Add(0);
        }
        sprms.Add(64);
        for (short i = 0; i < 64; i++)
        {
            var position = (short)(i * 100);
            sprms.Add((byte)position);
            sprms.Add((byte)(position >> 8));
        }
        sprms.AddRange(new byte[64]);
        sprms.AddRange(new byte[] { 0x61, 0x24, 0x02 });
        var formatting = DocParagraphFormatting.Parse(sprms.ToArray());
        Assert.Equal(16, formatting.TabClearRanges!.Count);
        Assert.Equal(64, formatting.TabStops!.Count);
        Assert.Equal((byte)2, formatting.Justification);
    }

    [Fact]
    public void LegacyTableCellShadingDecodesWithModernCellPrecedence()
    {
        var legacy = new byte[] { 0x09, 0xD6, 4, 0x06, 0x21, 0, 0 };
        var legacyCells = DocParagraphFormatting.Parse(legacy).TableCellShadings!;
        Assert.Equal(2, legacyCells.Count);
        Assert.Equal((ushort)8, legacyCells[0]?.Pattern);
        Assert.Equal(0xFFFFFFu, legacyCells[0]?.FillRgb);
        Assert.Equal(0x0000FFu, legacyCells[0]?.ForegroundRgb);
        Assert.Null(legacyCells[1]);
        var modernCells = new DocCellShading?[]
        {
            new(0x123456u, 0x654321u, 5),
            new(0xDDEEFFu, 0x112233u, 8)
        };
        var encoded = (DocParagraphFormatting.Empty with
        { TableCellShadings = modernCells }).Encode();
        var legacyAt = encoded.AsSpan().IndexOf(new byte[]
            { 0x09, 0xD6, 4, 0x00, 0x00 });
        var modernAt = encoded.AsSpan().IndexOf(new byte[] { 0x70, 0xD6, 20 });
        Assert.True(legacyAt < 0 && modernAt >= 0); // custom colors have no palette fallback
        var mixed = (DocParagraphFormatting.Empty with
        {
            TableCellShadings = new DocCellShading?[]
            {
                new(0xFFFFFFu, 0x0000FFu, 8),
                modernCells[1]
            }
        }).Encode();
        legacyAt = mixed.AsSpan().IndexOf(new byte[] { 0x09, 0xD6, 4, 0x06, 0x21 });
        modernAt = mixed.AsSpan().IndexOf(new byte[] { 0x70, 0xD6, 20 });
        Assert.True(legacyAt >= 0 && modernAt > legacyAt);
        var decoded = DocParagraphFormatting.Parse(mixed).TableCellShadings!;
        Assert.Equal(2, decoded.Count);
        Assert.Equal(0xFFFFFFu, decoded[0]?.FillRgb);
        Assert.Equal(0xDDEEFFu, decoded[1]?.FillRgb);
        var reversed = DocParagraphFormatting.Parse(
            mixed.AsSpan(modernAt).ToArray().Concat(mixed.AsSpan(legacyAt,
                modernAt - legacyAt).ToArray()).ToArray()).TableCellShadings!;
        Assert.Equal(0xFFFFFFu, reversed[0]?.FillRgb);
        Assert.Equal(0xDDEEFFu, reversed[1]?.FillRgb);
    }

    [Fact]
    public void NilRowGapWidthLeavesPreviousValueUnchanged()
    {
        var formatting = DocParagraphFormatting.Parse(new byte[]
        {
            0x17, 0xF6, 3, 0x20, 0x03, // before: 800 twips
            0x17, 0xF6, 0, 0xFF, 0xFF, // nil: width bytes are undefined
            0x18, 0xF6, 0, 0xFF, 0xFF  // after: unspecified
        });
        Assert.Equal(new DocTablePreferredWidth(3, 800), formatting.TableWidthBefore);
        Assert.Null(formatting.TableWidthAfter);
    }

    [Fact]
    public void NilTableAndCellPreferredWidthsLeavePreviousValuesUnchanged()
    {
        var formatting = DocParagraphFormatting.Parse(new byte[]
        {
            0x14, 0xF6, 3, 0xA0, 0x0F, // table: 4000 twips
            0x14, 0xF6, 0, 0xFF, 0xFF, // nil table width
            0x35, 0xD6, 5, 0, 1, 3, 0xD0, 0x07, // cell 0: 2000 twips
            0x35, 0xD6, 5, 0, 1, 0, 0xFF, 0xFF  // nil cell width
        });
        Assert.Equal(new DocTablePreferredWidth(3, 4000),
            formatting.TablePreferredWidth);
        Assert.Equal(new DocTablePreferredWidth(3, 2000),
            formatting.TableCellPreferredWidths![0]);
    }

    [Fact]
    public void LegacyParagraphShadingDecodesAndModernShadingTakesPrecedence()
    {
        var legacy = new byte[] { 0x2D, 0x44, 0x06, 0x21 };
        var modern = new byte[]
        {
            0x4D, 0xC6, 10,
            0x00, 0x00, 0xFF, 0x00,
            0x00, 0xFF, 0x00, 0x00,
            0x05, 0x00
        };
        var decoded = DocParagraphFormatting.Parse(legacy);
        Assert.Equal((ushort)8, decoded.ShadingPattern);
        Assert.Equal(0xFFFFFFu, decoded.FillRgb);
        Assert.Equal(0x0000FFu, decoded.ShadingForegroundRgb);
        foreach (var bytes in new[]
        {
            modern.Concat(legacy).ToArray(), legacy.Concat(modern).ToArray()
        })
        {
            var formatting = DocParagraphFormatting.Parse(bytes);
            Assert.Equal((ushort)5, formatting.ShadingPattern);
            Assert.Equal(0x00FF00u, formatting.FillRgb);
            Assert.Equal(0xFF0000u, formatting.ShadingForegroundRgb);
        }
        var nil = DocParagraphFormatting.Parse(
            new byte[] { 0x2D, 0x44, 0xFF, 0xFF });
        Assert.Equal((ushort)0, nil.ShadingPattern);
        Assert.Null(nil.FillRgb);
        var modernNil = DocParagraphFormatting.Parse(new byte[]
        {
            0x4D, 0xC6, 10,
            0xFF, 0xFF, 0xFF, 0xFF,
            0x00, 0x00, 0x00, 0xFF,
            0x00, 0x00
        });
        Assert.Equal(ushort.MaxValue, modernNil.ShadingPattern);
        Assert.Null(modernNil.FillRgb);
        Assert.Null(modernNil.ShadingForegroundRgb);
        var encoded = (DocParagraphFormatting.Empty with
        {
            FillRgb = 0xFFFFFFu,
            ShadingForegroundRgb = 0x0000FFu,
            ShadingPattern = 8
        }).Encode();
        var legacyAt = encoded.AsSpan().IndexOf(legacy);
        var modernAt = encoded.AsSpan().IndexOf(new byte[] { 0x4D, 0xC6, 10 });
        Assert.True(legacyAt >= 0 && modernAt > legacyAt);
    }

    public static IEnumerable<object[]> MappedParagraphShadingPatterns()
    {
        var standard = new[]
        {
            ShadingPatternValues.Clear, ShadingPatternValues.Solid,
            ShadingPatternValues.Percent5, ShadingPatternValues.Percent10,
            ShadingPatternValues.Percent20, ShadingPatternValues.Percent25,
            ShadingPatternValues.Percent30, ShadingPatternValues.Percent40,
            ShadingPatternValues.Percent50, ShadingPatternValues.Percent60,
            ShadingPatternValues.Percent70, ShadingPatternValues.Percent75,
            ShadingPatternValues.Percent80, ShadingPatternValues.Percent90,
            ShadingPatternValues.HorizontalStripe,
            ShadingPatternValues.VerticalStripe,
            ShadingPatternValues.ReverseDiagonalStripe,
            ShadingPatternValues.DiagonalStripe,
            ShadingPatternValues.HorizontalCross,
            ShadingPatternValues.DiagonalCross,
            ShadingPatternValues.ThinHorizontalStripe,
            ShadingPatternValues.ThinVerticalStripe,
            ShadingPatternValues.ThinReverseDiagonalStripe,
            ShadingPatternValues.ThinDiagonalStripe,
            ShadingPatternValues.ThinHorizontalCross,
            ShadingPatternValues.ThinDiagonalCross
        };
        for (ushort i = 0; i < standard.Length; i++)
            yield return new object[] { standard[i], i };
        yield return new object[] { ShadingPatternValues.Percent12, (ushort)0x25 };
        yield return new object[] { ShadingPatternValues.Percent15, (ushort)0x26 };
        yield return new object[] { ShadingPatternValues.Percent35, (ushort)0x2B };
        yield return new object[] { ShadingPatternValues.Percent37, (ushort)0x2C };
        yield return new object[] { ShadingPatternValues.Percent45, (ushort)0x2E };
        yield return new object[] { ShadingPatternValues.Percent55, (ushort)0x31 };
        yield return new object[] { ShadingPatternValues.Percent62, (ushort)0x33 };
        yield return new object[] { ShadingPatternValues.Percent65, (ushort)0x34 };
        yield return new object[] { ShadingPatternValues.Percent85, (ushort)0x39 };
        yield return new object[] { ShadingPatternValues.Percent87, (ushort)0x3A };
        yield return new object[] { ShadingPatternValues.Percent95, (ushort)0x3C };
    }

    [Theory]
    [MemberData(nameof(MappedParagraphShadingPatterns))]
    public void AdditionalParagraphShadingPatternsSurviveAllStories(
        ShadingPatternValues pattern, ushort docPattern)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Paragraph Shaded(string text) => new(
                new ParagraphProperties(new Shading
                {
                    Val = pattern, Fill = "FFF2CC", Color = "4472C4"
                }), new Run(new Text(text)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Shaded("Pattern header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Shaded("Pattern footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Shaded("Pattern body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            Assert.True(index.ParagraphStyles.Count(x =>
                x.Formatting?.ShadingPattern == docPattern &&
                x.Formatting.FillRgb == 0xCCF2FFu &&
                x.Formatting.ShadingForegroundRgb == 0xC47244u) >= 3);
            using var projectionStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projection = WordprocessingDocument.Open(projectionStream,
                false);
            var paragraphs = projection.MainDocumentPart!.Document.Body!
                .Elements<Paragraph>()
                .Concat(projection.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Elements<Paragraph>()))
                .Concat(projection.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Elements<Paragraph>()))
                .Where(x => x.InnerText.StartsWith("Pattern ")).ToArray();
            Assert.Equal(3, paragraphs.Length);
            Assert.All(paragraphs, paragraph =>
            {
                var shading = paragraph.ParagraphProperties!
                    .GetFirstChild<Shading>()!;
                Assert.Equal(pattern, shading.Val!.Value);
                Assert.Equal("FFF2CC", shading.Fill!.Value);
                Assert.Equal("4472C4", shading.Color!.Value);
            });
            Assert.Empty(new OpenXmlValidator().Validate(projection));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
    }

    [Theory]
    [MemberData(nameof(MappedParagraphShadingPatterns))]
    public void PatternedParagraphStyleAndDirectOverrideSurviveAllStories(
        ShadingPatternValues pattern, ushort docPattern)
    {
        var directory = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures", "Doc"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(Path.Combine(directory,
            "WordThreeLevelStyleOverrides.docx")));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleId == "GrandchildDisplay");
            style.StyleParagraphProperties ??= new StyleParagraphProperties();
            style.StyleParagraphProperties.Shading = new Shading
                { Val = pattern, Fill = "FFF2CC", Color = "4472C4" };
            var body = main.Document.Body!.Descendants<Paragraph>().First(
                x => x.ParagraphProperties?.ParagraphStyleId?.Val?.Value ==
                    "GrandchildDisplay");
            body.ParagraphProperties!.Shading = new Shading
                { Val = ShadingPatternValues.Percent50,
                    Fill = "DDEEFF", Color = "335577" };
            main.StyleDefinitionsPart.Styles.Save();
            main.Document.Save();
        }

        var original = source.ToArray();
        var generated = DxpDocExport.Export(original);
        foreach (var binary in new[] { generated,
                     DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes) })
        {
            using var input = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(input);
            var style = Assert.Single(index.StyleDefinitions,
                x => x.Name == "GrandchildDisplay");
            Assert.Equal(docPattern, style.ParagraphFormatting.ShadingPattern);
            Assert.Equal(0xCCF2FFu, style.ParagraphFormatting.FillRgb);
            Assert.Contains(index.ParagraphStyles, x =>
                x.Formatting?.ShadingPattern == 8 &&
                x.Formatting.FillRgb == 0xFFEEDDu);
            using var projectedStream = new MemoryStream(
                DxpDocToDocx.Project(binary).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream,
                false);
            var projectedStyle = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "GrandchildDisplay");
            var styleShade = projectedStyle.StyleParagraphProperties!
                .GetFirstChild<Shading>()!;
            Assert.Equal(pattern, styleShade.Val!.Value);
            Assert.Equal("FFF2CC", styleShade.Fill!.Value);
            Assert.Equal("4472C4", styleShade.Color!.Value);
            var overrideParagraph = Assert.Single(projected.MainDocumentPart
                .Document.Body!.Descendants<Paragraph>(), x =>
                    x.ParagraphProperties?.Shading != null);
            Assert.Equal(ShadingPatternValues.Percent50,
                overrideParagraph.ParagraphProperties!.Shading!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                AssertWordFirstPageRenderClose(original, binary, 0.04);
        }
    }

