            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>())).Where(x =>
                x.InnerText.StartsWith("Palette ")).ToArray();
        Assert.Equal(3, paragraphs.Length);
        Assert.All(paragraphs, paragraph =>
        {
            var shading = paragraph.ParagraphProperties!.GetFirstChild<Shading>()!;
            Assert.Equal(ShadingPatternValues.Percent50, shading.Val!.Value);
            Assert.Equal("FFFFFF", shading.Fill!.Value);
            Assert.Equal("FF0000", shading.Color!.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.True(rewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.ShadingPattern == 8 &&
            x.Formatting.FillRgb == 0xFFFFFFu &&
            x.Formatting.ShadingForegroundRgb == 0x0000FFu) >= 3);
        using var edited = new MemoryStream();
        edited.Write(generated);
        edited.Position = 0;
        using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
        using (var wordDocument = compound.OpenStream("WordDocument"))
        {
            var replacements = 0;
            foreach (var page in index.FormattingPages.Where(x => !x.IsCharacterFormatting))
            foreach (var run in page.Runs)
            {
                var papx = run.Children.FirstOrDefault(x => x.Kind == "PapxInFkp");
                if (papx?.Offset is not long offset || papx.Length is not long length)
                    continue;
                var bytes = index.Structure.ReadRange("WordDocument", offset,
                    checked((int)length));
                var modern = bytes.AsSpan().IndexOf(new byte[] { 0x4D, 0xC6, 10 });
                if (modern < 0) continue;
                var compatibility = bytes.AsSpan().IndexOf(
                    new byte[] { 0x2D, 0x44, 0x06, 0x21 });
                Assert.True(compatibility >= 0 && compatibility < modern);
                // Keep the PAPX byte count while retaining the legacy shade.
                var legacy = new byte[]
                {
                    0x2D, 0x44, 0x06, 0x21,
                    0x05, 0x24, 0, 0x06, 0x24, 0, 0x07, 0x24, 0
                };
                wordDocument.Position = offset + modern;
                wordDocument.Write(legacy);
                replacements++;
            }
            Assert.True(replacements >= 3);
            compound.Flush();
        }
        var legacyDoc = edited.ToArray();
        using var legacyInput = new MemoryStream(legacyDoc);
        using var legacyIndex = new DocTextIndexWalker().Index(legacyInput);
        Assert.True(legacyIndex.ParagraphStyles.Count(x =>
            x.Formatting?.ShadingPattern == 8 &&
            x.Formatting.FillRgb == 0xFFFFFFu &&
            x.Formatting.ShadingForegroundRgb == 0x0000FFu) >= 3);
        using var legacyProjectionStream = new MemoryStream(
            DxpDocToDocx.Project(legacyDoc).DocxBytes);
        using var legacyProjection = WordprocessingDocument.Open(
            legacyProjectionStream, false);
        var legacyParagraphs = legacyProjection.MainDocumentPart!.Document.Body!
            .Elements<Paragraph>()
            .Concat(legacyProjection.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()))
            .Concat(legacyProjection.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>())).Where(x =>
                x.InnerText.StartsWith("Palette ")).ToArray();
        Assert.Equal(3, legacyParagraphs.Length);
        Assert.All(legacyParagraphs, paragraph =>
        {
            var shading = paragraph.ParagraphProperties!.GetFirstChild<Shading>()!;
            Assert.Equal(ShadingPatternValues.Percent50, shading.Val!.Value);
            Assert.Equal("FFFFFF", shading.Fill!.Value);
            Assert.Equal("FF0000", shading.Color!.Value);
        });
        Assert.Empty(new OpenXmlValidator().Validate(legacyProjection));
        var legacyRewritten = DxpDocExport.Export(legacyProjectionStream.ToArray());
        using var legacyRewrittenInput = new MemoryStream(legacyRewritten);
        using var legacyRewrittenIndex = new DocTextIndexWalker().Index(
            legacyRewrittenInput);
        Assert.True(legacyRewrittenIndex.ParagraphStyles.Count(x =>
            x.Formatting?.ShadingPattern == 8 &&
            x.Formatting.FillRgb == 0xFFFFFFu &&
            x.Formatting.ShadingForegroundRgb == 0x0000FFu) >= 3);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);
            AssertWordFirstPageRenderClose(source.ToArray(), legacyDoc, 0.04);
        }
    }

    [Fact]
    public void LegacyCharacterShadingDecodesAndModernShadingTakesPrecedence()
    {
        var legacy = new byte[] { 0x66, 0x48, 0x06, 0x21 };
        var modern = new byte[]
        {
            0x71, 0xCA, 10,
            0x00, 0x00, 0xFF, 0x00,
            0x00, 0xFF, 0x00, 0x00,
            0x05, 0x00
        };
        var decodedLegacy = DocCharacterFormattingReader.ParseSprms(legacy).Shading;
        Assert.Equal((ushort)8, decodedLegacy?.Pattern);
        Assert.Equal(0xFFFFFFu, decodedLegacy?.FillRgb);
        Assert.Equal(0x0000FFu, decodedLegacy?.ForegroundRgb);
        var modernFirst = DocCharacterFormattingReader.ParseSprms(
            modern.Concat(legacy).ToArray()).Shading;
        var legacyFirst = DocCharacterFormattingReader.ParseSprms(
            legacy.Concat(modern).ToArray()).Shading;
        foreach (var shading in new[] { modernFirst, legacyFirst })
        {
            Assert.Equal((ushort)5, shading?.Pattern);
            Assert.Equal(0x00FF00u, shading?.FillRgb);
            Assert.Equal(0xFF0000u, shading?.ForegroundRgb);
        }
        var nil = DocCharacterFormattingReader.ParseSprms(
            new byte[] { 0x66, 0x48, 0xFF, 0xFF }).Shading;
        Assert.Equal((ushort)0, nil?.Pattern);
        Assert.Null(nil?.FillRgb);
        var modernNil = DocCharacterFormattingReader.ParseSprms(new byte[]
        {
            0x71, 0xCA, 10,
            0xFF, 0xFF, 0xFF, 0xFF,
            0x00, 0x00, 0x00, 0xFF,
            0x00, 0x00
        }).Shading;
        Assert.Equal(ushort.MaxValue, modernNil?.Pattern);
        Assert.Null(modernNil?.FillRgb);
        Assert.Null(modernNil?.ForegroundRgb);
    }

    [Fact]
    public void LegacyCharacterShadingProjectsInBodyHeaderAndFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Paragraph Shaded(string text) => new(new Run(
                new RunProperties(new Shading
                {
                    Val = ShadingPatternValues.Percent50,
                    Fill = "FFFFFF", Color = "FF0000"
                }), new Text(text)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Shaded("Legacy header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Shaded("Legacy footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Shaded("Legacy body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using var edited = new MemoryStream();
        edited.Write(generated);
        edited.Position = 0;
        using (var input = new MemoryStream(generated))
        using (var index = new DocTextIndexWalker().Index(input))
        using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
        using (var wordDocument = compound.OpenStream("WordDocument"))
        {
            var replaced = 0;
            foreach (var page in index.FormattingPages.Where(x => x.IsCharacterFormatting))
            foreach (var run in page.Runs)
            {
                var chpx = run.Children.FirstOrDefault(x => x.Kind == "Chpx");
                if (chpx?.Offset is not long offset || chpx.Length is not long length)
                    continue;
                var bytes = index.Structure.ReadRange("WordDocument", offset,
                    checked((int)length));
                var modern = bytes.AsSpan().IndexOf(new byte[] { 0x71, 0xCA, 10 });
                if (modern < 0) continue;
                var compatibility = bytes.AsSpan().IndexOf(
                    new byte[] { 0x66, 0x48, 0x06, 0x21 });
                Assert.True(compatibility >= 0 && compatibility < modern,
                    "Palette shading must precede the modern color operand.");
                // Preserve CHPX length: one Shd80 and three explicit-off toggles.
                var legacy = new byte[]
                {
                    0x66, 0x48, 0x06, 0x21,
                    0x35, 0x08, 0, 0x36, 0x08, 0, 0x3C, 0x08, 0
                };
                Assert.True(modern + legacy.Length <= bytes.Length);
                wordDocument.Position = offset + modern;
                wordDocument.Write(legacy);
                replaced++;
            }
            Assert.Equal(3, replaced);
            compound.Flush();
        }
        var legacyDoc = edited.ToArray();
        using var legacyInput = new MemoryStream(legacyDoc);
        using var legacyIndex = new DocTextIndexWalker().Index(legacyInput);
        Assert.Equal(3, legacyIndex.CharacterFormatting.Count(x =>
            x.Formatting.Shading?.Pattern == 8 &&
            x.Formatting.Shading.FillRgb == 0xFFFFFFu &&
            x.Formatting.Shading.ForegroundRgb == 0x0000FFu));
        using var projectedStream = new MemoryStream(DxpDocToDocx.Project(legacyDoc).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var shadedRuns = projected.MainDocumentPart!.Document.Body!.Descendants<Run>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Descendants<Run>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Descendants<Run>())).Where(x =>
                x.RunProperties?.GetFirstChild<Shading>()?.Val?.Value ==
                    ShadingPatternValues.Percent50).ToArray();
        Assert.Equal(3, shadedRuns.Length);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var rewritten = DxpDocExport.Export(projectedStream.ToArray());
        using var rewrittenInput = new MemoryStream(rewritten);
        using var rewrittenIndex = new DocTextIndexWalker().Index(rewrittenInput);
        Assert.Equal(3, rewrittenIndex.CharacterFormatting.Count(x =>
            x.Formatting.Shading?.Pattern == 8 &&
            x.Formatting.Shading.FillRgb == 0xFFFFFFu &&
            x.Formatting.Shading.ForegroundRgb == 0x0000FFu));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), legacyDoc, 0.04);
    }

    [Fact]
    public void RelativeComplexScriptRunTogglesUseCharacterStyleOverParagraphStyle()
    {
        var paragraphStyle = DocCharacterFormatting.Empty with
        {
            ComplexScriptBold = true,
            ComplexScriptItalic = false,
            RightToLeftText = true,
            ForceComplexScript = false
        };
        var characterStyle = DocCharacterFormatting.Empty with
        {
            ComplexScriptBold = false,
            ComplexScriptItalic = true,
            RightToLeftText = false,
            ForceComplexScript = true
        };
        var run = DocCharacterFormattingReader.ParseSprms(new byte[]
        {
            0x5C, 0x08, 0x81, 0x5D, 0x08, 0x81,
            0x5A, 0x08, 0x81, 0x82, 0x08, 0x81
        });
        var result = run.ResolveStyleToggles(
            DocCharacterFormattingReader.OverlayToggleBase(
                paragraphStyle, characterStyle));
        Assert.True(result.ComplexScriptBold);
        Assert.False(result.ComplexScriptItalic);
        Assert.True(result.RightToLeftText);
        Assert.False(result.ForceComplexScript);
    }

    [Fact]
    public void PieceLevelBoldOverridesChpxInBodyHeaderAndFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Paragraph Text(string value) => new(new Run(
                new RunProperties(new Bold { Val = false }), new Text(value)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Text("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Text("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Text("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            using (var original = new MemoryStream(bytes))
            using (var index = new DocTextIndexWalker().Index(original))
            {
                var piece = Assert.Single(index.Pieces);
                using var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen);
                using var table = compound.OpenStream(piece.Node.StreamName!);
                table.Position = piece.Node.Offset!.Value + 6;
                table.WriteByte(0xAA); // Prm0 isprm 0x55: sprmCFBold
                table.WriteByte(0x01);
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(0x55, int.Parse(index.Pieces[0].Node.Children
                .Single(x => x.Kind == "Prm").Children.Single()
                .Attributes["modifierIndex"], CultureInfo.InvariantCulture));
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.Bold == true) >= 3);
        }
        var projectedBytes = DxpDocToDocx.Project(bytes).DocxBytes;
        using var projectedStream = new MemoryStream(projectedBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var runs = projected.MainDocumentPart!.Document!.Descendants<Run>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Descendants<Run>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Descendants<Run>())).ToArray();
        Assert.Equal(3, runs.Count(x => x.RunProperties?.Bold?.Val?.Value == true));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-piece-bold-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(-1, (int)opened.Paragraphs.Item(1).Range.Bold);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Headers.Item(1).Range.Bold);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Footers.Item(1).Range.Bold);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void PiecePropertyBlockAppliesCharacterSprmsAfterChpx()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            Paragraph Text(string value) => new(new Run(
                new RunProperties(new Bold { Val = false },
                    new Italic { Val = false }), new Text(value)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Text("Header piece"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Text("Footer piece"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Text("Body piece"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            using (var original = new MemoryStream(bytes))
            using (var index = new DocTextIndexWalker().Index(original))
            {
                var piece = Assert.Single(index.Pieces);
                var clx = Assert.Single(index.Structure.Locations,
                    x => x.Name == "TextPieceTable" && x.IsPresent);
                var originalClx = index.Structure.ReadRange(clx.StreamName,
                    clx.Offset, checked((int)clx.Length));
                var sprms = new List<byte> { 0x15, 0xC6, 0xFF, 16 };
                for (short i = 0; i < 16; i++)
                {
                    var position = (short)(i * 100);
                    sprms.Add((byte)position);
                    sprms.Add((byte)(position >> 8));
                }
                for (var i = 0; i < 16; i++)
                {
                    sprms.Add(25);
                    sprms.Add(0);
                }
                sprms.Add(64);
                for (short i = 0; i < 64; i++)
                {
                    var position = (short)(i * 100);
                    sprms.Add((byte)position);
                    sprms.Add((byte)(position >> 8));
                }
                sprms.AddRange(new byte[64]);
                sprms.AddRange(new byte[]
                {
                    0x14, 0xA4, 0xF0, 0x00, // paragraph after-spacing
                    0x35, 0x08, 1, 0x36, 0x08, 1
                });
                var prc = new byte[3 + sprms.Count];
                prc[0] = 1;
                BinaryPrimitives.WriteUInt16LittleEndian(prc.AsSpan(1),
                    checked((ushort)sprms.Count));
                sprms.CopyTo(prc, 3);
                using var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen);
                using var table = compound.OpenStream(clx.StreamName);
                using var word = compound.OpenStream("WordDocument");
                var newClxOffset = checked((uint)table.Length);
                table.Position = table.Length;
                table.Write(prc, 0, prc.Length);
                table.Write(originalClx, 0, originalClx.Length);
                table.Position = newClxOffset + prc.Length +
                    piece.Node.Offset!.Value - clx.Offset + 6;
                table.WriteByte(1); // Prm1, property-block index zero
                table.WriteByte(0);
                var pair = new byte[8];
                BinaryPrimitives.WriteUInt32LittleEndian(pair, newClxOffset);
                BinaryPrimitives.WriteUInt32LittleEndian(pair.AsSpan(4),
                    checked((uint)(prc.Length + originalClx.Length)));
                word.Position = clx.FibFieldOffset;
                word.Write(pair, 0, pair.Length);
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal("Prm1", index.Pieces[0].Node.Children
                .Single(x => x.Kind == "Prm").Children.Single().Kind);
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.Bold == true && x.Formatting.Italic == true) >= 3);
            Assert.True(index.ParagraphStyles.Count(x =>
                x.Formatting?.AfterTwips == 240 &&
                x.Formatting.TabStops?.Count == 64) >= 3);
        }
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var paragraphs = projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>())).ToArray();
        Assert.Equal(3, paragraphs.Length);
        foreach (var paragraph in paragraphs)
        {
            var run = Assert.Single(paragraph.Elements<Run>());
            Assert.True(run.RunProperties!.Bold!.Val!.Value);
            Assert.True(run.RunProperties.Italic!.Val!.Value);
            Assert.Equal("240", paragraph.ParagraphProperties!
                .SpacingBetweenLines!.After!.Value);
            Assert.Equal(64, paragraph.ParagraphProperties.Tabs!
                .Elements<TabStop>().Count(x => x.Val?.Value != TabStopValues.Clear));
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-piece-block-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic app = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        app.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = app.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(-1, (int)opened.Paragraphs.Item(1).Range.Bold);
            Assert.Equal(-1, (int)opened.Paragraphs.Item(1).Range.Italic);
            Assert.Equal(12f, (float)opened.Paragraphs.Item(1)
                .Range.ParagraphFormat.SpaceAfter);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Headers.Item(1).Range.Bold);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Footers.Item(1).Range.Italic);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            app.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void PieceLevelAlignmentOverridesPapx()
    {
