                using var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen);
                using var table = compound.OpenStream(piece.Node.StreamName!);
                table.Position = piece.Node.Offset!.Value + 6;
                table.WriteByte(0xC4); // Prm0 isprm 0x62: sprmCIco
                table.WriteByte(6); // red in the DOC Ico palette
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == 0 && x.Formatting.ColorRef ==
                    (modernColor ? 0xFF0000u : 0x0000FFu));
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var run = Assert.Single(projected.MainDocumentPart!.Document!.Body!
            .Descendants<Run>());
        Assert.Equal(modernColor ? "0000FF" : "FF0000",
            run.RunProperties!.Color!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-piece-color-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic app = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        app.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = app.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(modernColor ? 16711680 : 255,
                (int)opened.Paragraphs.Item(1).Range.Font.Color);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            app.Quit();
            File.Delete(path);
        }
    }

    [Fact]
    public void PiecePlainResetRestoresParagraphStyleInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Plain base" },
                    new StyleRunProperties(new Bold()))
                { Type = StyleValues.Paragraph, StyleId = "PlainBase" },
                new Style(new StyleName { Val = "Plain accent" },
                    new StyleRunProperties(new Italic(),
                        new Color { Val = "00AA00" }))
                { Type = StyleValues.Character, StyleId = "PlainAccent" });
            styles.Styles.Save();
            Paragraph Text(string value) => new(
                new ParagraphProperties(new ParagraphStyleId { Val = "PlainBase" }),
                new Run(new RunProperties(new RunStyle { Val = "PlainAccent" },
                    new Bold { Val = false },
                    new Italic(), new Highlight { Val = HighlightColorValues.Yellow }),
                    new Text(value)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Text("Header plain"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Text("Footer plain"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Text("Body plain"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            using (var original = new MemoryStream(bytes))
            using (var index = new DocTextIndexWalker().Index(original))
            {
                var piece = Assert.Single(index.Pieces);
                using var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen);
                using var table = compound.OpenStream(piece.Node.StreamName!);
                table.Position = piece.Node.Offset!.Value + 6;
                table.WriteByte(0xA6); // Prm0 isprm 0x53: sprmCPlain
                table.WriteByte(0);
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.Bold == null && x.Formatting.Italic == null &&
                x.Formatting.CharacterStyleIndex == null &&
                x.Formatting.ColorRef == null &&
                x.Formatting.HighlightCode == 7) >= 3);
            Assert.True(Assert.Single(index.StyleDefinitions,
                x => x.Name == "Plain base").CharacterFormatting.Bold);
        }
        using var projectedStream = new MemoryStream(
            DxpDocToDocx.Project(bytes).DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var paragraphs = projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>())).ToArray();
        Assert.Equal(3, paragraphs.Length);
        foreach (var paragraph in paragraphs)
        {
            Assert.NotNull(paragraph.ParagraphProperties?.ParagraphStyleId);
            var properties = Assert.Single(paragraph.Elements<Run>()).RunProperties!;
            Assert.Null(properties.Bold);
            Assert.Null(properties.Italic);
            Assert.Null(properties.RunStyle);
            Assert.Null(properties.Color);
            Assert.Equal(HighlightColorValues.Yellow, properties.Highlight!.Val!.Value);
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var path = Path.Combine(Path.GetTempPath(),
            $"docxport-piece-plain-{Guid.NewGuid():N}.doc");
        File.WriteAllBytes(path, bytes);
        dynamic app = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        app.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = app.Documents.Open(path, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(-1, (int)opened.Paragraphs.Item(1).Range.Bold);
            Assert.Equal(0, (int)opened.Paragraphs.Item(1).Range.Italic);
            Assert.Equal(-1, (int)opened.Sections.Item(1).Headers.Item(1).Range.Bold);
            Assert.Equal(0, (int)opened.Sections.Item(1).Footers.Item(1).Range.Italic);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            app.Quit();
            File.Delete(path);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void StyledKeepAndPageBreakControlsReachAllStories(bool directReset)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new RunPropertiesDefault(new RunPropertiesBaseStyle(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new FontSize { Val = "24" })),
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { After = "0", Line = "280",
                        LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new StyleName { Val = "Flow heading" },
                    new StyleParagraphProperties(new KeepNext(), new KeepLines(),
                        new PageBreakBefore(),
                        new SpacingBetweenLines { After = "120", Line = "280",
                            LineRule = LineSpacingRuleValues.Exact }))
                { Type = StyleValues.Paragraph, StyleId = "FlowHeading" },
                new Style(new StyleName { Val = "Flow story" },
                    new StyleParagraphProperties(new KeepNext(), new KeepLines()))
                { Type = StyleValues.Paragraph, StyleId = "FlowStory" });
            styles.Styles.Save();
            Paragraph Styled(string text, bool heading = false) => new(
                heading
                    ? directReset
                        ? new ParagraphProperties(
                            new ParagraphStyleId { Val = "FlowHeading" },
                            new KeepNext { Val = false },
                            new KeepLines { Val = false },
                            new PageBreakBefore { Val = false })
                        : new ParagraphProperties(
                            new ParagraphStyleId { Val = "FlowHeading" })
                    : new ParagraphProperties(
                        new ParagraphStyleId { Val = "FlowStory" }),
                new Run(new Text(text)));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Flow header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Flow footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                new Paragraph(new Run(new Text("Opening paragraph"))),
                Styled("Page two heading", true),
                new Paragraph(new Run(new Text("Page two body"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
            Assert.Empty(new OpenXmlValidator().Validate(original));
        void AssertProjection(byte[] bytes)
        {
            var result = DxpDocToDocx.Project(bytes);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "Flow heading");
            Assert.True(style.StyleParagraphProperties!.KeepNext!.Val!.Value);
            Assert.True(style.StyleParagraphProperties.KeepLines!.Val!.Value);
            Assert.True(style.StyleParagraphProperties.PageBreakBefore!.Val!.Value);
            var body = projected.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().ToArray();
            Assert.Equal(3, body.Length);
            Assert.Equal("Page two heading", body[1].InnerText);
            if (directReset)
            {
                Assert.False(body[1].ParagraphProperties!.KeepNext!.Val!.Value);
                Assert.False(body[1].ParagraphProperties.KeepLines!.Val!.Value);
                Assert.False(body[1].ParagraphProperties.PageBreakBefore!.Val!.Value);
            }
            else
                Assert.Null(body[1].ParagraphProperties!.PageBreakBefore);
            Assert.Contains(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()), x => x.InnerText == "Flow header");
            Assert.Contains(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>()), x => x.InnerText == "Flow footer");
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        if (!directReset)
            AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 2);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-styled-flow-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.Equal(directReset ? 1 : 2,
                    Convert.ToInt32(opened.ComputeStatistics(2)));
                var storyParagraphs = new dynamic[]
                {
                    opened.Paragraphs.Item(2),
                    opened.Sections.Item(1).Headers.Item(1).Range.Paragraphs.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Paragraphs.Item(1)
                };
                for (var storyIndex = 0; storyIndex < storyParagraphs.Length;
                    storyIndex++)
                {
                    dynamic format = storyParagraphs[storyIndex].Range.ParagraphFormat;
                    var expected = storyIndex != 0 || !directReset;
                    Assert.Equal(expected, Convert.ToBoolean(format.KeepWithNext));
                    Assert.Equal(expected, Convert.ToBoolean(format.KeepTogether));
                }
                Assert.Equal(!directReset, Convert.ToBoolean(opened.Paragraphs.Item(2)
                    .Range.ParagraphFormat.PageBreakBefore));
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertProjection(File.ReadAllBytes(nativePath));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void StyledKeepWithNextControlsPageBoundary(bool directReset)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new RunPropertiesDefault(new RunPropertiesBaseStyle(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new FontSize { Val = "24" })),
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { Before = "0", After = "0",
                        Line = "280", LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new StyleName { Val = "Kept heading" },
                    new StyleParagraphProperties(new KeepNext()))
                { Type = StyleValues.Paragraph, StyleId = "KeptHeading" });
            styles.Styles.Save();
            var introRun = new Run();
            for (var i = 1; i <= 8; i++)
            {
                if (i > 1) introRun.AppendChild(new Break());
                introRun.AppendChild(new Text($"Opening line {i}"));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new Run(new Text("Page header"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new Run(new Text("Page footer"))));
            footer.Footer.Save();
            var headingProperties = new ParagraphProperties(
                new ParagraphStyleId { Val = "KeptHeading" });
            if (directReset)
                headingProperties.AppendChild(new KeepNext { Val = false });
            main.Document = new Document(new Body(
                new Paragraph(introRun),
                new Paragraph(headingProperties, new Run(new Text("Keep heading"))),
                new Paragraph(new Run(new Text("Following paragraph"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new PageSize { Width = 12240, Height = 3600 },
                    new PageMargin { Left = 720, Right = 720, Top = 360,
                        Bottom = 360, Header = 180, Footer = 180 })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
            Assert.Empty(new OpenXmlValidator().Validate(original));
        void AssertProjection(byte[] bytes)
        {
            var result = DxpDocToDocx.Project(bytes);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "Kept heading");
            Assert.True(style.StyleParagraphProperties!.KeepNext!.Val!.Value);
            var paragraphs = projected.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().ToArray();
            Assert.Equal(3, paragraphs.Length);
            Assert.Equal("Keep heading", paragraphs[1].InnerText);
            Assert.Equal("Following paragraph", paragraphs[2].InnerText);
            if (directReset)
                Assert.False(paragraphs[1].ParagraphProperties!.KeepNext!.Val!.Value);
            Assert.Contains(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()), x => x.InnerText == "Page header");
            Assert.Contains(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>()), x => x.InnerText == "Page footer");
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 2);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-keep-boundary-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.Repaginate();
                Assert.Equal(2, Convert.ToInt32(opened.ComputeStatistics(2)));
                var heading = opened.Paragraphs.Item(2);
                var following = opened.Paragraphs.Item(3);
                Assert.Equal(directReset ? 1 : 2,
                    Convert.ToInt32(heading.Range.Information(3)));
                Assert.Equal(2, Convert.ToInt32(following.Range.Information(3)));
                Assert.Equal(!directReset, Convert.ToBoolean(
                    heading.Range.ParagraphFormat.KeepWithNext));
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertProjection(File.ReadAllBytes(nativePath));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void StyledKeepLinesControlsParagraphSplit(bool directReset)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new RunPropertiesDefault(new RunPropertiesBaseStyle(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new FontSize { Val = "24" })),
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { Before = "0", After = "0",
                        Line = "280", LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new StyleName { Val = "Kept lines" },
                    new StyleParagraphProperties(new KeepLines()))
                { Type = StyleValues.Paragraph, StyleId = "KeptLines" });
            styles.Styles.Save();
            Run Lines(string prefix, int count)
            {
                var run = new Run();
                for (var i = 1; i <= count; i++)
                {
                    if (i > 1) run.AppendChild(new Break());
                    run.AppendChild(new Text($"{prefix} {i}"));
                }
                return run;
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new ParagraphProperties(
                new ParagraphStyleId { Val = "KeptLines" }),
                new Run(new Text("Lines header"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new ParagraphProperties(
                new ParagraphStyleId { Val = "KeptLines" }),
                new Run(new Text("Lines footer"))));
            footer.Footer.Save();
            var targetProperties = new ParagraphProperties(
                new ParagraphStyleId { Val = "KeptLines" });
            if (directReset)
                targetProperties.AppendChild(new KeepLines { Val = false });
            main.Document = new Document(new Body(
                new Paragraph(Lines("Opening", 6)),
                new Paragraph(targetProperties, Lines("Target", 5)),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new PageSize { Width = 12240, Height = 3600 },
                    new PageMargin { Left = 720, Right = 720, Top = 360,
                        Bottom = 360, Header = 180, Footer = 180 })));
            main.Document.Save();
        }
        using (var original = WordprocessingDocument.Open(source, false))
            Assert.Empty(new OpenXmlValidator().Validate(original));
        void AssertProjection(byte[] bytes, bool expectExplicitKern = true)
        {
            var result = DxpDocToDocx.Project(bytes);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var style = Assert.Single(projected.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "Kept lines");
            var projectedKerning = projected.MainDocumentPart.StyleDefinitionsPart
                .Styles.GetFirstChild<DocDefaults>()?
                .GetFirstChild<RunPropertiesDefault>()?
                .RunPropertiesBaseStyle?.GetFirstChild<Kern>()?.Val?.Value;
            if (expectExplicitKern) Assert.Equal((uint)0, projectedKerning);
            else Assert.True(projectedKerning == null || projectedKerning == 0);
            Assert.True(style.StyleParagraphProperties!.KeepLines!.Val!.Value);
            var body = projected.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().ToArray();
            Assert.Equal(2, body.Length);
            Assert.Equal(4, body[1].Descendants<Break>().Count());
            if (directReset)
                Assert.False(body[1].ParagraphProperties!.KeepLines!.Val!.Value);
            Assert.Contains(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Elements<Paragraph>()), x => x.InnerText == "Lines header" &&
                x.ParagraphProperties?.ParagraphStyleId?.Val?.Value ==
                    style.StyleId?.Value);
            Assert.Contains(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Elements<Paragraph>()), x => x.InnerText == "Lines footer" &&
                x.ParagraphProperties?.ParagraphStyleId?.Val?.Value ==
                    style.StyleId?.Value);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 2);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-keep-lines-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                opened.Repaginate();
                Assert.Equal(2, Convert.ToInt32(opened.ComputeStatistics(2)));
                dynamic target = opened.Paragraphs.Item(2).Range;
                Assert.Equal(directReset ? 1 : 2,
                    Convert.ToInt32(target.Characters.Item(1).Information(3)));
                Assert.Equal(2, Convert.ToInt32(target.Characters.Item(
                    target.Characters.Count - 1).Information(3)));
                Assert.Equal(!directReset, Convert.ToBoolean(
                    target.ParagraphFormat.KeepTogether));
                Assert.Equal(0, Convert.ToDouble(
                    target.Characters.Item(1).Font.Kerning));
                Assert.Equal(0, Convert.ToDouble(opened.Sections.Item(1)
                    .Headers.Item(1).Range.Characters.Item(1).Font.Kerning));
                Assert.Equal(0, Convert.ToDouble(opened.Sections.Item(1)
                    .Footers.Item(1).Range.Characters.Item(1).Font.Kerning));
                Assert.True(Convert.ToBoolean(opened.Sections.Item(1).Headers.Item(1)
                    .Range.Paragraphs.Item(1).Range.ParagraphFormat.KeepTogether));
                Assert.True(Convert.ToBoolean(opened.Sections.Item(1).Footers.Item(1)
                    .Range.Paragraphs.Item(1).Range.ParagraphFormat.KeepTogether));
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertProjection(File.ReadAllBytes(nativePath), false);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void InheritedStyleTabsComposeClearsAndAdditionsInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "TabBase" },
                    new StyleParagraphProperties(new Tabs(
                        new TabStop { Position = 720, Val = TabStopValues.Left },
                        new TabStop { Position = 1440, Val = TabStopValues.Right,
                            Leader = TabStopLeaderCharValues.Dot },
                        new TabStop { Position = 2160, Val = TabStopValues.Bar })))
                { Type = StyleValues.Paragraph, StyleId = "TabBase" },
                new Style(new StyleName { Val = "TabChild" },
                    new BasedOn { Val = "TabBase" },
                    new StyleParagraphProperties(new Tabs(
                        new TabStop { Position = 720, Val = TabStopValues.Clear },
                        new TabStop { Position = 1080, Val = TabStopValues.Center,
                            Leader = TabStopLeaderCharValues.Hyphen },
                        new TabStop { Position = 1440, Val = TabStopValues.Decimal })))
                { Type = StyleValues.Paragraph, StyleId = "TabChild" },
                new Style(new StyleName { Val = "TabGrandchild" },
                    new BasedOn { Val = "TabChild" },
                    new StyleParagraphProperties(new Tabs(
                        new TabStop { Position = 1440, Val = TabStopValues.Clear },
                        new TabStop { Position = 1800, Val = TabStopValues.Right })))
                { Type = StyleValues.Paragraph, StyleId = "TabGrandchild" });
            styles.Styles.Save();
            Paragraph TabParagraph(string text, bool directTabs = false) => new(
                directTabs
                    ? new ParagraphProperties(new ParagraphStyleId
                        { Val = "TabGrandchild" }, new Tabs(
                            new TabStop { Position = 1080,
                                Val = TabStopValues.Clear },
                            new TabStop { Position = 1800,
                                Val = TabStopValues.Center,
                                Leader = TabStopLeaderCharValues.Hyphen },
                            new TabStop { Position = 2520,
                                Val = TabStopValues.Right,
                                Leader = TabStopLeaderCharValues.Dot }))
                    : new ParagraphProperties(new ParagraphStyleId
                        { Val = "TabGrandchild" }),
                new Run(new Text(text), new TabChar(), new Text("value")));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(TabParagraph("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(TabParagraph("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(TabParagraph("Body", true),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var grandchild = Assert.Single(index.StyleDefinitions,
                x => x.Name == "TabGrandchild");
            Assert.Equal(new short[] { 720, 1440 },
                grandchild.ParagraphFormatting!.ClearedTabPositions);
            Assert.Equal(new short[] { 1080, 1800, 2160 },
                grandchild.ParagraphFormatting.TabStops!
                    .Select(x => x.PositionTwips));
        }
        var result = DxpDocToDocx.Project(bytes);
        Assert.Empty(result.Coverage.OmittedCharacters);
        using var output = new MemoryStream(result.DocxBytes);
        using var projected = WordprocessingDocument.Open(output, false);
        var styleOut = Assert.Single(projected.MainDocumentPart!
            .StyleDefinitionsPart!.Styles!.Elements<Style>(),
            x => x.StyleName?.Val?.Value == "TabGrandchild");
        var tabsOut = styleOut.StyleParagraphProperties!.Tabs!
            .Elements<TabStop>().ToArray();
        Assert.Equal(1, tabsOut.Count(x => x.Val?.Value == TabStopValues.Clear));
        Assert.Equal(1, tabsOut.Count(x => x.Val?.Value != TabStopValues.Clear));
        Assert.Contains(tabsOut, x => x.Position?.Value == 1440 &&
            x.Val?.Value == TabStopValues.Clear);
        Assert.Contains(tabsOut, x => x.Position?.Value == 1800 &&
            x.Val?.Value == TabStopValues.Right);
        var bodyDirectTabs = projected.MainDocumentPart.Document.Body!
            .Elements<Paragraph>().First().ParagraphProperties!.Tabs!
            .Elements<TabStop>().ToArray();
        Assert.Contains(bodyDirectTabs, x => x.Position?.Value == 1080 &&
            x.Val?.Value == TabStopValues.Clear);
        Assert.Contains(bodyDirectTabs, x => x.Position?.Value == 1800 &&
            x.Val?.Value == TabStopValues.Center &&
            x.Leader?.Value == TabStopLeaderCharValues.Hyphen);
        Assert.Contains(bodyDirectTabs, x => x.Position?.Value == 2520 &&
            x.Val?.Value == TabStopValues.Right &&
            x.Leader?.Value == TabStopLeaderCharValues.Dot);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        var third = DxpDocToDocx.Project(DxpDocExport.Export(result.DocxBytes));
        Assert.Empty(third.Coverage.OmittedCharacters);
        using (var thirdStream = new MemoryStream(third.DocxBytes))
        using (var thirdDocx = WordprocessingDocument.Open(thirdStream, false))
        {
            var thirdStyle = Assert.Single(thirdDocx.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "TabGrandchild");
            Assert.Equal(new short[] { 1800 },
                thirdStyle.StyleParagraphProperties!.Tabs!.Elements<TabStop>()
                    .Where(x => x.Val?.Value != TabStopValues.Clear)
                    .Select(x => checked((short)x.Position!.Value)));
            Assert.Contains(thirdDocx.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().First().ParagraphProperties!.Tabs!
                .Elements<TabStop>(), x => x.Position?.Value == 1800 &&
                x.Val?.Value == TabStopValues.Center &&
                x.Leader?.Value == TabStopLeaderCharValues.Hyphen);
            Assert.Contains(thirdDocx.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().First().ParagraphProperties!.Tabs!
                .Elements<TabStop>(), x => x.Position?.Value == 2520 &&
                x.Val?.Value == TabStopValues.Right &&
                x.Leader?.Value == TabStopLeaderCharValues.Dot);
            Assert.All(new[]
            {
                thirdDocx.MainDocumentPart.Document.Body!.Elements<Paragraph>().First(),
                thirdDocx.MainDocumentPart.HeaderParts.Single().Header!
                    .Elements<Paragraph>().First(),
                thirdDocx.MainDocumentPart.FooterParts.Single().Footer!
                    .Elements<Paragraph>().First()
            }, paragraph => Assert.Single(paragraph.Descendants<TabChar>()));
            Assert.Empty(new OpenXmlValidator().Validate(thirdDocx));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1" &&
            Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1") return;
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-tabs-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var storyParagraphs = new dynamic[]
                {
                    opened.Paragraphs.Item(1),
                    opened.Sections.Item(1).Headers.Item(1).Range.Paragraphs.Item(1),
                    opened.Sections.Item(1).Footers.Item(1).Range.Paragraphs.Item(1)
                };
                for (var storyIndex = 0; storyIndex < storyParagraphs.Length;
                    storyIndex++)
                {
                    dynamic paragraph = storyParagraphs[storyIndex];
                    dynamic tabs = paragraph.Range.ParagraphFormat.TabStops;
                    var positions = Enumerable.Range(1, (int)tabs.Count)
                        .Select(i => (float)tabs.Item(i).Position).ToArray();
                    Assert.Equal(storyIndex == 0
                        ? new[] { 90f, 108f, 126f }
                        : new[] { 54f, 90f, 108f }, positions.Take(3));
                    Assert.DoesNotContain(36f, positions);
                    Assert.DoesNotContain(72f, positions);
                    if (storyIndex == 0)
                    {
                        Assert.DoesNotContain(54f, positions);
                        Assert.Equal(1, Convert.ToInt32(tabs.Item(1).Alignment));
                        Assert.Equal(2, Convert.ToInt32(tabs.Item(1).Leader));
                        Assert.Equal(2, Convert.ToInt32(tabs.Item(3).Alignment));
                        Assert.Equal(1, Convert.ToInt32(tabs.Item(3).Leader));
                    }
                }
                if (path == sourcePath)
                    opened.SaveAs2(FileName: nativePath, FileFormat: 0);
                opened.Close(false);
                opened = null;
            }
            var nativeBytes = File.ReadAllBytes(nativePath);
            using var nativeInput = new MemoryStream(nativeBytes);
            using var nativeIndex = new DocTextIndexWalker().Index(nativeInput);
            var nativeStyle = Assert.Single(nativeIndex.StyleDefinitions,
                x => x.Name == "TabGrandchild");
            var nativePositions = nativeStyle.ParagraphFormatting!.TabStops!
                .Select(x => x.PositionTwips).ToArray();
            Assert.True(new short[] { 1080, 1800, 2160 }
                .SequenceEqual(nativePositions),
                string.Join("; ", nativeIndex.StyleDefinitions
                    .Where(x => x.Name.StartsWith("Tab", StringComparison.Ordinal))
                    .Select(x => x.Name + ": clear=" + string.Join(",",
                        x.ParagraphFormatting?.ClearedTabPositions ?? []) +
                        " add=" + string.Join(",",
                            x.ParagraphFormatting?.TabStops?.Select(t => t.PositionTwips)
                            ?? []))));
            using var nativeProjection = new MemoryStream(
                DxpDocToDocx.Project(nativeBytes).DocxBytes);
            using var nativeDocx = WordprocessingDocument.Open(nativeProjection, false);
            var projectedNativeStyle = Assert.Single(nativeDocx.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "TabGrandchild");
            Assert.Equal("TabChild", Assert.Single(nativeDocx.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                    x.StyleId?.Value == projectedNativeStyle.BasedOn?.Val?.Value)
                .StyleName?.Val?.Value);
            Assert.Equal(new short[] { 1800 },
                projectedNativeStyle.StyleParagraphProperties!.Tabs!
                    .Elements<TabStop>()
                    .Where(x => x.Val?.Value != TabStopValues.Clear)
                    .Select(x => checked((short)x.Position!.Value)));
            Assert.Contains(nativeDocx.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().First().ParagraphProperties!.Tabs!
                .Elements<TabStop>(), x => x.Position?.Value == 1800 &&
                x.Val?.Value == TabStopValues.Center &&
                x.Leader?.Value == TabStopLeaderCharValues.Hyphen);
            Assert.Contains(nativeDocx.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().First().ParagraphProperties!.Tabs!
                .Elements<TabStop>(), x => x.Position?.Value == 2520 &&
                x.Val?.Value == TabStopValues.Right &&
                x.Leader?.Value == TabStopLeaderCharValues.Dot);
            Assert.Empty(new OpenXmlValidator().Validate(nativeDocx));
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void RightToLeftComplexScriptRunsRenderInBodyHeaderAndFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(new RunPropertiesDefault(
                new RunPropertiesBaseStyle(new RunFonts
                { Ascii = "Arial", HighAnsi = "Arial", ComplexScript = "Arial" },
                    new FontSize { Val = "24" },
                    new FontSizeComplexScript { Val = "24" }))),
                new Style(new StyleName { Val = "Base script paragraph" },
                    new StyleRunProperties(new RightToLeftText()))
                { Type = StyleValues.Paragraph, StyleId = "BaseScriptParagraph" },
                new Style(new StyleName { Val = "Script paragraph" },
                    new BasedOn { Val = "BaseScriptParagraph" },
                    new StyleRunProperties(new BoldComplexScript()))
                { Type = StyleValues.Paragraph, StyleId = "ScriptParagraph" },
                new Style(new StyleName { Val = "Script paragraph reset" },
                    new BasedOn { Val = "ScriptParagraph" },
                    new StyleRunProperties(new RightToLeftText { Val = false }))
                { Type = StyleValues.Paragraph, StyleId = "ScriptParagraphReset" },
                new Style(new StyleName { Val = "Script direction" },
                    new StyleRunProperties(new RightToLeftText()))
                { Type = StyleValues.Character, StyleId = "ScriptDirection" },
                new Style(new StyleName { Val = "Script emphasis" },
                    new BasedOn { Val = "ScriptDirection" },
                    new StyleRunProperties(new ItalicComplexScript()))
                { Type = StyleValues.Character, StyleId = "ScriptEmphasis" },
                new Style(new StyleName { Val = "Script direction reset" },
                    new BasedOn { Val = "ScriptDirection" },
                    new StyleRunProperties(new RightToLeftText { Val = false }))
                { Type = StyleValues.Character, StyleId = "ScriptDirectionReset" });
            styles.Styles.Save();
            Assert.NotNull(styles.Styles.Elements<Style>().First(x =>
                x.StyleId?.Value == "ScriptEmphasis")
                .StyleRunProperties?.ItalicComplexScript);
            Paragraph ScriptParagraph(string text) => new(
                new ParagraphProperties(new ParagraphStyleId
                    { Val = "ScriptParagraph" }), new Run(new RunProperties(
                new RunStyle { Val = "ScriptEmphasis" },
                new RunFonts
                { Ascii = "Arial", HighAnsi = "Arial", ComplexScript = "Arial" },
                new FontSize { Val = "24" },
                new FontSizeComplexScript { Val = "24" },
                new ItalicComplexScript { Val = false },
                new RightToLeftText(), new ComplexScript()),
                new Text(text) { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new RunStyle { Val = "ScriptEmphasis" }),
                    new Text(" styled")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new RunStyle { Val = "ScriptEmphasis" },
                    new RightToLeftText { Val = false }),
                    new Text(" reset")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new Text(" paragraph")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new RunStyle { Val = "ScriptDirectionReset" }),
                    new Text(" charreset")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }));
            Paragraph ResetParagraph(string text) => new(
                new ParagraphProperties(new ParagraphStyleId
                    { Val = "ScriptParagraphReset" }),
                new Run(new Text(text)));
            Table StyledTable() => new(
                new TableProperties(new TableLayout { Type = TableLayoutValues.Fixed }),
                new TableGrid(new GridColumn { Width = "2400" }),
                new TableRow(new TableCell(new Paragraph(
                    new ParagraphProperties(new ParagraphStyleId
                        { Val = "ScriptParagraph" }),
                    new Run(new Text(" cell"))))));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(ScriptParagraph("Header مرحبا 123"),
                ResetParagraph("Header reset paragraph"), StyledTable());
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(ScriptParagraph("Footer שלום 456"),
                ResetParagraph("Footer reset paragraph"), StyledTable());
            footer.Footer.Save();
            main.Document = new Document(new Body(
                ScriptParagraph("Body مرحبا שלום 789"),
                ResetParagraph("Body reset paragraph"),
                StyledTable(),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) },
                    new PageSize { Width = 12240, Height = 15840 },
                    new PageMargin { Left = 1440, Right = 1440,
                        Top = 1440, Bottom = 1440, Header = 720, Footer = 720 })));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        var toggleOffsets = new List<long>();
        using (var original = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(original))
            foreach (var page in index.FormattingPages.Where(x => x.IsCharacterFormatting))
            foreach (var run in page.Runs.Where(x => x.Kind == "ChpxRange"))
            {
                var chpx = run.Children.FirstOrDefault(x => x.Kind == "Chpx");
                if (chpx?.Offset is not long offset || chpx.Length is not long length)
                    continue;
                var data = index.Structure.ReadRange("WordDocument", offset,
                    checked((int)length));
                for (var i = 0; i < data.Length - 2; i++)
                    if (data[i] == 0x5D && data[i + 1] == 0x08 && data[i + 2] == 0)
                        toggleOffsets.Add(offset + i + 2);
            }
        Assert.True(toggleOffsets.Count >= 3);
        using (var edited = new MemoryStream())
        {
            edited.Write(bytes, 0, bytes.Length);
            edited.Position = 0;
            using (var compound = RootStorage.Open(edited, StorageModeFlags.LeaveOpen))
            using (var word = compound.OpenStream("WordDocument"))
            {
                foreach (var offset in toggleOffsets)
                {
                    word.Position = offset;
                    word.WriteByte(0x81);
                }
                compound.Flush();
            }
            bytes = edited.ToArray();
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.True(index.HeaderStories[7].CpEnd > index.HeaderStories[7].CpStart);
            Assert.True(index.HeaderStories[9].CpEnd > index.HeaderStories[9].CpStart);
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.RightToLeftText == true &&
                x.Formatting.ForceComplexScript == true) >= 3);
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.ComplexScriptItalic == false) >= 3);
            var paragraphStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Script paragraph");
            var resetParagraphStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Script paragraph reset");
            var baseParagraphStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Base script paragraph");
            var characterStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Script emphasis");
            var directionStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Script direction");
            var resetDirectionStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Script direction reset");
            Assert.True(paragraphStyle.CharacterFormatting.ComplexScriptBold);
            Assert.True(baseParagraphStyle.CharacterFormatting.RightToLeftText);
            Assert.Equal(baseParagraphStyle.Index, paragraphStyle.BasedOnIndex);
            Assert.Equal(paragraphStyle.Index, resetParagraphStyle.BasedOnIndex);
            Assert.False(resetParagraphStyle.CharacterFormatting.RightToLeftText);
            Assert.True(characterStyle.CharacterFormatting.ComplexScriptItalic);
            Assert.True(directionStyle.CharacterFormatting.RightToLeftText);
            Assert.Equal(directionStyle.Index, characterStyle.BasedOnIndex);
            Assert.Equal(directionStyle.Index, resetDirectionStyle.BasedOnIndex);
            Assert.False(resetDirectionStyle.CharacterFormatting.RightToLeftText);
            Assert.True(index.CharacterFormatting.Count(x =>
                x.Formatting.CharacterStyleIndex == characterStyle.Index) >= 3);
        }
        var result = DxpDocToDocx.Project(bytes);
        Assert.Empty(result.Coverage.OmittedCharacters);
        using var projectedStream = new MemoryStream(result.DocxBytes);
        using var projected = WordprocessingDocument.Open(projectedStream, false);
        var projectedStyles = projected.MainDocumentPart!.StyleDefinitionsPart!.Styles!;
        Assert.Contains(projectedStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "Script paragraph" &&
            x.StyleRunProperties?.BoldComplexScript?.Val?.Value != false &&
            x.StyleRunProperties?.ChildElements.Any(y => y.LocalName == "rtl") == false);
        Assert.Contains(projectedStyles.Elements<Style>(), x =>
            x.StyleName?.Val?.Value == "Script emphasis" &&
            x.StyleRunProperties?.ItalicComplexScript?.Val?.Value != false &&
            x.StyleRunProperties?.ChildElements.Any(y => y.LocalName == "rtl") == false);
        var projectedRuns = projected.MainDocumentPart.Document.Descendants<Run>()
            .Concat(projected.MainDocumentPart.HeaderParts.SelectMany(x =>
                x.Header!.Descendants<Run>()))
            .Concat(projected.MainDocumentPart.FooterParts.SelectMany(x =>
                x.Footer!.Descendants<Run>())).ToArray();
        Assert.Equal(12, projectedRuns.Count(x => x.RunProperties?.RunStyle != null));
        Assert.Equal(3, projectedRuns.Count(x =>
            x.RunProperties?.ItalicComplexScript?.Val?.Value == false));
        Assert.Equal(3, projectedRuns.Count(x => x.InnerText == " styled" &&
            x.RunProperties?.RightToLeftText?.Val?.Value == true));
        Assert.Equal(3, projectedRuns.Count(x => x.InnerText == " reset" &&
            x.RunProperties?.RightToLeftText?.Val?.Value == false));
        Assert.Equal(3, projectedRuns.Count(x => x.InnerText == " paragraph" &&
            x.RunProperties?.RightToLeftText?.Val?.Value == true));
        Assert.Equal(3, projectedRuns.Count(x => x.InnerText == " cell" &&
            x.RunProperties?.RightToLeftText?.Val?.Value == true));
        Assert.Equal(3, projectedRuns.Count(x => x.InnerText == " charreset" &&
            x.RunProperties?.RightToLeftText?.Val?.Value == false));
        Assert.Equal(3, projectedRuns.Count(x =>
            x.InnerText.EndsWith(" reset paragraph", StringComparison.Ordinal) &&
            x.RunProperties?.RightToLeftText?.Val?.Value == false));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        using (var thirdStream = new MemoryStream(DxpDocToDocx.Project(
            DxpDocExport.Export(result.DocxBytes)).DocxBytes))
        using (var third = WordprocessingDocument.Open(thirdStream, false))
        {
            var thirdRuns = third.MainDocumentPart!.Document!.Descendants<Run>()
                .Concat(third.MainDocumentPart.HeaderParts.SelectMany(x =>
                    x.Header!.Descendants<Run>()))
                .Concat(third.MainDocumentPart.FooterParts.SelectMany(x =>
                    x.Footer!.Descendants<Run>()));
            Assert.Equal(3, thirdRuns.Count(x => x.InnerText == " styled" &&
                x.RunProperties?.RightToLeftText?.Val?.Value == true));
            Assert.Equal(3, thirdRuns.Count(x => x.InnerText == " reset" &&
                x.RunProperties?.RightToLeftText?.Val?.Value == false));
            Assert.Equal(3, thirdRuns.Count(x => x.InnerText == " paragraph" &&
                x.RunProperties?.RightToLeftText?.Val?.Value == true));
            Assert.Equal(3, thirdRuns.Count(x => x.InnerText == " cell" &&
                x.RunProperties?.RightToLeftText?.Val?.Value == true));
            Assert.Equal(3, thirdRuns.Count(x => x.InnerText == " charreset" &&
                x.RunProperties?.RightToLeftText?.Val?.Value == false));
            Assert.Equal(3, thirdRuns.Count(x =>
                x.InnerText.EndsWith(" reset paragraph", StringComparison.Ordinal) &&
                x.RunProperties?.RightToLeftText?.Val?.Value == false));
            Assert.Empty(new OpenXmlValidator().Validate(third));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordFirstPageRenderClose(source.ToArray(), bytes, 0.04);
    }

    [Fact]
    public void WordNativeDirectRunDirectionInAllStories()
    {
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1")
            return;
        static Paragraph Story(string label) => new(
            new ParagraphProperties(new BiDi()),
            new Run(new RunProperties(new RightToLeftText(), new ComplexScript()),
                new Text(label + " שלום ")),
            new Run(new RunProperties(new RightToLeftText { Val = false }),
                new Text("LTR 123")));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Story("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Story("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Story("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        using (var sourceStream = new MemoryStream(source.ToArray()))
        using (var sourceDocx = WordprocessingDocument.Open(sourceStream, false))
            Assert.Empty(new OpenXmlValidator().Validate(sourceDocx));
        var directory = Path.Combine(Path.GetTempPath(),
            "docxport-native-run-direction-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        try
        {
            var sourcePath = Path.Combine(directory, "source.docx");
            var nativePath = Path.Combine(directory, "native.doc");
            var savedPath = Path.Combine(directory, "saved.docx");
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            word.DisplayAlerts = 0;
            try
            {
                dynamic opened = word.Documents.Open(sourcePath, ReadOnly: true,
                    AddToRecentFiles: false);
                try { opened.SaveAs2(nativePath, 0); }
                finally { opened.Close(false); }
                opened = word.Documents.Open(nativePath, ReadOnly: true,
                    AddToRecentFiles: false);
                try { opened.SaveAs2(savedPath, 16); }
                finally { opened.Close(false); }
            }
            finally { word.Quit(false); }
            using var wordSaved = WordprocessingDocument.Open(savedPath, false);
            using var projectedStream = new MemoryStream(DxpDocToDocx.Project(
                File.ReadAllBytes(nativePath)).DocxBytes);
            using var projected = WordprocessingDocument.Open(projectedStream, false);
            static string[] Facts(WordprocessingDocument doc)
            {
                var main = doc.MainDocumentPart!;
                return new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    main.Document!.Body!, main.HeaderParts.Single().Header!,
                    main.FooterParts.Single().Footer!
                }.SelectMany(story => story.Descendants<Run>().Select(run =>
                    run.InnerText))
                    .ToArray();
            }
            static void AssertStoryDirections(WordprocessingDocument doc)
            {
                var main = doc.MainDocumentPart!;
                foreach (var story in new DocumentFormat.OpenXml.OpenXmlElement[]
                {
                    main.Document!.Body!, main.HeaderParts.Single().Header!,
                    main.FooterParts.Single().Footer!
                })
                {
                    var paragraph = Assert.Single(story.Elements<Paragraph>());
                    Assert.True(paragraph.ParagraphProperties?.BiDi?.Val?.Value);
                    Assert.True(paragraph.Elements<Run>().First()
                        .RunProperties?.RightToLeftText?.Val?.Value);
                }
            }
            Assert.Equal(Facts(wordSaved), Facts(projected));
            AssertStoryDirections(projected);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
            var thirdBytes = DxpDocToDocx.Project(DxpDocExport.Export(
                projectedStream.ToArray())).DocxBytes;
            using (var thirdStream = new MemoryStream(thirdBytes))
            using (var third = WordprocessingDocument.Open(thirdStream, false))
            {
                Assert.Equal(Facts(wordSaved), Facts(third));
                AssertStoryDirections(third);
                Assert.Empty(new OpenXmlValidator().Validate(third));
            }
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            {
                AssertWordFirstPageRenderClose(source.ToArray(),
                    File.ReadAllBytes(nativePath), 0.04);
                AssertWordPageRenderClose(source.ToArray(), projectedStream.ToArray(),
                    0.04, 1, ".docx");
                AssertWordPageRenderClose(source.ToArray(), thirdBytes,
                    0.04, 1, ".docx");
            }
        }
        finally { Directory.Delete(directory, true); }
    }

    [Fact]
    public void DocRoundTripReusesHeaderPartWithBookmarkAcrossSections()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new BookmarkStart { Id = "7", Name = "SharedHeaderMark" },
                new Run(new Text("Shared")), new BookmarkEnd { Id = "7" }));
            header.Header.Save();
            var relationship = main.GetIdOfPart(header);
            HeaderReference Reference() => new()
                { Type = HeaderFooterValues.Default, Id = relationship };
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(new SectionProperties(Reference())),
                    new Run(new Text("First"))),
                new Paragraph(new Run(new Text("Second"))),
                new SectionProperties(Reference())));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal("SharedHeaderMark", Assert.Single(index.Bookmarks).Name);
            Assert.False(index.HeaderStories[7].IsEmpty);
            Assert.True(index.HeaderStories[13].IsEmpty);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var first = projected.MainDocumentPart!.Document!.Body!
            .Elements<Paragraph>().First().ParagraphProperties!
            .GetFirstChild<SectionProperties>()!;
        Assert.Single(first.Elements<HeaderReference>());
        Assert.Empty(projected.MainDocumentPart.Document.Body
            .Elements<SectionProperties>().Single().Elements<HeaderReference>());
        Assert.Equal("SharedHeaderMark", Assert.Single(projected.MainDocumentPart
            .HeaderParts.Single().Header!.Descendants<BookmarkStart>()).Name!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void DocRoundTripReusesEarlierHeaderAfterDifferentHeader()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var first = main.AddNewPart<HeaderPart>();
            first.Header = new Header(new Paragraph(
                new BookmarkStart { Id = "8", Name = "OriginalHeader" },
                new Run(new Text("A")), new BookmarkEnd { Id = "8" }));
            first.Header.Save();
            var second = main.AddNewPart<HeaderPart>();
            second.Header = new Header(new Paragraph(new Run(new Text("B"))));
            second.Header.Save();
            HeaderReference Reference(HeaderPart part) => new()
                { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(part) };
            main.Document = new Document(new Body(
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    Reference(first))), new Run(new Text("One"))),
                new Paragraph(new ParagraphProperties(new SectionProperties(
                    Reference(second))), new Run(new Text("Two"))),
                new Paragraph(new Run(new Text("Three"))),
                new SectionProperties(Reference(first))));
            main.Document.Save();
        }
        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal("OriginalHeader", Assert.Single(index.Bookmarks).Name);
            Assert.False(index.HeaderStories[7].IsEmpty);
            Assert.False(index.HeaderStories[13].IsEmpty);
            Assert.False(index.HeaderStories[19].IsEmpty);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var headers = projected.MainDocumentPart!.HeaderParts
            .Select(x => x.Header!.InnerText).ToArray();
        Assert.Equal(3, headers.Length);
        Assert.Equal(2, headers.Count(x => x == "A"));
        Assert.Contains("B", headers);
        Assert.Single(projected.MainDocumentPart.HeaderParts
            .SelectMany(x => x.Header!.Descendants<BookmarkStart>()));
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-reused-header-" + Guid.NewGuid().ToString("N") + ".doc");
            File.WriteAllBytes(path, bytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                Assert.Equal(3, (int)opened.Sections.Count);
                Assert.Contains("A", (string)opened.Sections.Item(1).Headers.Item(1).Range.Text);
                Assert.Contains("B", (string)opened.Sections.Item(2).Headers.Item(1).Range.Text);
                Assert.Contains("A", (string)opened.Sections.Item(3).Headers.Item(1).Range.Text);
                Assert.True((bool)opened.Bookmarks.Exists("OriginalHeader"));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
            }
        }
    }

    [Fact]
    public void DocRoundTripPreservesDirectCharacterFormattingInBodyAndHeader()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new Run(
                new RunProperties(new Bold()), new Text("Header"))));
            header.Header.Save();
            main.Document = new Document(new Body(new Paragraph(
                new Run(new Text("Plain")),
                new Run(new RunProperties(new Bold()), new Text("Bold")),
                new Run(new RunProperties(new Italic(), new FontSize { Val = "28" }),
                    new Text("Italic"))),
                new SectionProperties(new HeaderReference
                {
                    Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header)
                })));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == 5 && x.CpEnd == 9 && x.Formatting.Bold == true);
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == 9 && x.CpEnd == 15 && x.Formatting.Italic == true &&
                x.Formatting.SizeHalfPoints == 28);
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == index.HeaderStories[7].CpStart && x.Formatting.Bold == true);
        }

        var projection = DxpDocToDocx.Project(docBytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var runs = projected.MainDocumentPart!.Document!.Body!.Elements<Paragraph>()
            .Single().Elements<Run>().ToArray();
        Assert.Equal(new[] { "Plain", "Bold", "Italic" }, runs.Select(x => x.InnerText));
        Assert.NotNull(runs[1].RunProperties?.Bold);
        Assert.NotNull(runs[2].RunProperties?.Italic);
        Assert.Equal("28", runs[2].RunProperties?.FontSize?.Val?.Value);
        Assert.NotNull(Assert.Single(projected.MainDocumentPart.HeaderParts).Header!
            .Descendants<Run>().Single().RunProperties?.Bold);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void DocWriterSplitsCharacterFormattingAcrossFkpPages()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            main.Document = new Document(new Body(new Paragraph(
                Enumerable.Range(0, 45).Select(i => new Run(
                    new RunProperties(new Bold { Val = i % 2 == 0 },
                        new Italic(), new Caps(), new SmallCaps(),
                        new Strike(), new Vanish { Val = false },
                        new FontSize { Val = "24" },
                        new Underline { Val = UnderlineValues.Single }),
                    new Text(((char)('A' + i % 26)).ToString()))))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var characterPages = index.FormattingPages.Where(x => x.IsCharacterFormatting)
                .ToArray();
            Assert.True(characterPages.Length >= 3);
            Assert.True(characterPages[0].Runs.Count < 20);
            Assert.Equal(45, index.CharacterFormatting.Count);
            Assert.All(index.CharacterFormatting, x =>
            {
                Assert.True(x.Formatting.Italic);
                Assert.True(x.Formatting.Caps);
                Assert.True(x.Formatting.SmallCaps);
                Assert.True(x.Formatting.Strike);
                Assert.False(x.Formatting.Hidden);
                Assert.Equal((byte)1, x.Formatting.UnderlineCode);
            });
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var runs = projected.MainDocumentPart!.Document!.Body!.Elements<Paragraph>()
            .Single().Elements<Run>().ToArray();
        Assert.Equal(45, runs.Length);
        for (var i = 0; i < runs.Length; i++)
        {
            Assert.Equal(i % 2 == 0, runs[i].RunProperties!.Bold!.Val!.Value);
            Assert.True(runs[i].RunProperties!.Caps!.Val!.Value);
            Assert.Equal(UnderlineValues.Single, runs[i].RunProperties.Underline!.Val!.Value);
        }
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Trait("Category", "LocalOnly")]
    [Fact]
    public void LinkedParagraphAndCharacterStylesSurviveBothDocRoutesInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Linked paragraph" },
                    new LinkedStyle { Val = "LinkedChar" },
                    new StyleRunProperties(new Bold(), new FontSize { Val = "24" }))
                { Type = StyleValues.Paragraph, StyleId = "LinkedPara", CustomStyle = true },
                new Style(new StyleName { Val = "Linked character" },
                    new LinkedStyle { Val = "LinkedPara" },
                    new StyleRunProperties(new Bold(), new FontSize { Val = "24" }))
                { Type = StyleValues.Character, StyleId = "LinkedChar", CustomStyle = true });
            styles.Styles.Save();
            static Paragraph Styled(string text) => new(
                new ParagraphProperties(new ParagraphStyleId { Val = "LinkedPara" }),
                new Run(new Text(text + " ")
                    { Space = DocumentFormat.OpenXml.SpaceProcessingModeValues.Preserve }),
                new Run(new RunProperties(new RunStyle { Val = "LinkedChar" }),
                    new Text("linked")));
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Styled("Body"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var generated = DxpDocExport.Export(source.ToArray());
        void AssertDoc(byte[] bytes)
        {
            using var input = new MemoryStream(bytes);
            using var index = new DocTextIndexWalker().Index(input);
            var paragraph = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Linked paragraph");
            var character = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Linked character");
            Assert.Equal(character.Index, paragraph.LinkedStyleIndex);
            Assert.Equal(paragraph.Index, character.LinkedStyleIndex);
            Assert.Contains(index.Styles, x => x.Children.Any(y => y.Kind == "STD" &&
                y.Attributes["baseSize"] == "18"));
        }
        void AssertProjection(byte[] bytes)
        {
            using var stream = new MemoryStream(bytes);
            using var docx = WordprocessingDocument.Open(stream, false);
            var main = docx.MainDocumentPart!;
            var styles = main.StyleDefinitionsPart!.Styles!.Elements<Style>().ToArray();
            var paragraph = Assert.Single(styles, x => x.StyleName?.Val?.Value ==
                "Linked paragraph");
            var character = Assert.Single(styles, x => x.StyleName?.Val?.Value ==
                "Linked character");
            Assert.Equal(character.StyleId!.Value, paragraph.LinkedStyle!.Val!.Value);
            Assert.Equal(paragraph.StyleId!.Value, character.LinkedStyle!.Val!.Value);
            foreach (var story in new[] { main.Document!.Body!.Elements<Paragraph>().Single(),
                main.HeaderParts.Single().Header!.Elements<Paragraph>().Single(),
                main.FooterParts.Single().Footer!.Elements<Paragraph>().Single() })
            {
                Assert.Equal(paragraph.StyleId.Value,
                    story.ParagraphProperties!.ParagraphStyleId!.Val!.Value);
                Assert.Equal(character.StyleId.Value,
                    story.Elements<Run>().Last().RunProperties!.RunStyle!.Val!.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(docx));
        }
        AssertDoc(generated);
        var projected = DxpDocToDocx.Project(generated).DocxBytes;
        AssertProjection(projected);
        AssertDoc(DxpDocExport.Export(projected));
        AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.04);

        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-linked-styles-{Guid.NewGuid():N}.docx");
        var nativePath = Path.ChangeExtension(sourcePath, ".doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(sourcePath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(0, Convert.ToInt32(opened.Paragraphs.Item(1)
                .Range.Characters.Item(6).Font.Bold));
            opened.SaveAs2(nativePath, 0);
            opened.Close(false);
            opened = null;
            var native = File.ReadAllBytes(nativePath);
            AssertDoc(native);
            var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;
            AssertProjection(nativeProjection);
            AssertDoc(DxpDocExport.Export(nativeProjection));
            AssertWordPageRenderClose(source.ToArray(), nativeProjection, 0.04, 1,
                ".docx");
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(nativePath);
        }
    }

    [Trait("Category", "LocalOnly")]
    [Fact]
    public void DocRoundTripPreservesNamedParagraphStylesAndBasedOnLink()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var stylesPart = main.AddNewPart<StyleDefinitionsPart>();
            stylesPart.Styles = new Styles(
                new Style(new StyleName { Val = "Normal" },
                    new StyleRunProperties(new FontSize { Val = "24" }))
                { Type = StyleValues.Paragraph, StyleId = "Normal" },
                new Style(new StyleName { Val = "Emphasis" },
                    new BasedOn { Val = "Normal" },
                    new StyleRunProperties(new Bold()))
                { Type = StyleValues.Paragraph, StyleId = "Emphasis" });
            stylesPart.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new ParagraphProperties(new ParagraphStyleId { Val = "Normal" }),
                new Run(new Text("Header"))));
            header.Header.Save();
            main.Document = new Document(new Body(new Paragraph(
                new ParagraphProperties(new ParagraphStyleId { Val = "Emphasis" }),
                new Run(new Text("Styled body"))),
                new SectionProperties(new HeaderReference
                {
                    Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header)
                })));
            main.Document.Save();
        }

        var docBytes = DxpDocExport.Export(source.ToArray());
        using (var docStream = new MemoryStream(docBytes))
        using (var index = new DocTextIndexWalker().Index(docStream))
        {
            var normal = Assert.Single(index.StyleDefinitions, x => x.Name == "Normal");
            var emphasis = Assert.Single(index.StyleDefinitions, x => x.Name == "Emphasis");
            Assert.Equal(normal.Index, emphasis.BasedOnIndex);
            Assert.True(emphasis.CharacterFormatting.Bold);
            Assert.Equal((ushort)24, normal.CharacterFormatting.SizeHalfPoints);
            Assert.Contains(index.ParagraphStyles, x => x.CpStart == 0 &&
                x.StyleIndex == emphasis.Index);
            Assert.Contains(index.ParagraphStyles, x =>
                x.CpStart == index.HeaderStories[7].CpStart && x.StyleIndex == normal.Index);
            foreach (var (story, expectedStyle) in new[]
            {
                (index.ReadStory("Main"), emphasis.Index),
                (index.HeaderStories[7].ReadIndexedContent(), normal.Index)
            })
            {
                var styleRun = Assert.Single(story.StoryParagraphStyles,
                    x => x.StyleIndex == expectedStyle);
                Assert.Equal(0, styleRun.Start);
                Assert.Equal(story.Text.CpStart, styleRun.SourceCpStart);
                Assert.Equal(story.Text.CpStart + (uint)styleRun.End,
                    styleRun.SourceCpEnd);
                Assert.Equal(index.GetTextOffset(styleRun.SourceCpStart!.Value),
                    styleRun.SourceTextOffsetStart);
                Assert.NotNull(styleRun.SourceTextOffsetEnd);
            }
        }

        var projection = DxpDocToDocx.Project(docBytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var styles = projected.MainDocumentPart!.StyleDefinitionsPart!.Styles!
            .Elements<Style>().ToArray();
        var normalOut = Assert.Single(styles, x => x.StyleName?.Val?.Value == "Normal");
        var emphasisOut = Assert.Single(styles, x => x.StyleName?.Val?.Value == "Emphasis");
        Assert.Equal(normalOut.StyleId!.Value, emphasisOut.BasedOn!.Val!.Value);
        Assert.Null(emphasisOut.StyleRunProperties?.GetFirstChild<FontSize>());
        Assert.Equal(emphasisOut.StyleId!.Value, projected.MainDocumentPart.Document!
            .Body!.Elements<Paragraph>().Single().ParagraphProperties!
            .ParagraphStyleId!.Val!.Value);
        Assert.Equal(normalOut.StyleId!.Value, projected.MainDocumentPart.HeaderParts.Single()
            .Header!.Elements<Paragraph>().Single().ParagraphProperties!
            .ParagraphStyleId!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));

        using (var thirdStream = new MemoryStream(DxpDocToDocx.Project(
            DxpDocExport.Export(projection.DocxBytes)).DocxBytes))
        using (var third = WordprocessingDocument.Open(thirdStream, false))
        {
            var child = Assert.Single(third.MainDocumentPart!.StyleDefinitionsPart!
                .Styles!.Elements<Style>(), x => x.StyleName?.Val?.Value == "Emphasis");
            Assert.NotNull(child.BasedOn);
            Assert.Null(child.StyleRunProperties?.GetFirstChild<FontSize>());
            Assert.Empty(new OpenXmlValidator().Validate(third));
        }

        using var editedStream = new MemoryStream();
        editedStream.Write(projection.DocxBytes);
        editedStream.Position = 0;
        using (var editable = WordprocessingDocument.Open(editedStream, true))
        {
            var normal = Assert.Single(editable.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(),
                x => x.StyleName?.Val?.Value == "Normal");
            normal.StyleRunProperties!.FontSize!.Val = "32";
            editable.MainDocumentPart.StyleDefinitionsPart.Styles.Save();
        }
        var editedPath = Path.Combine(Path.GetTempPath(),
            $"docxport-style-inheritance-{Guid.NewGuid():N}.docx");
        File.WriteAllBytes(editedPath, editedStream.ToArray());
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            opened = word.Documents.Open(editedPath, ReadOnly: true,
                AddToRecentFiles: false);
            Assert.Equal(16d, Convert.ToDouble(opened.Paragraphs.Item(1)
                .Range.Font.Size), 1);
            Assert.Equal(16d, Convert.ToDouble(opened.Sections.Item(1)
                .Headers.Item(1).Range.Paragraphs.Item(1).Range.Font.Size), 1);
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(editedPath);
        }
    }

    [Fact]
    public void DirectAutomaticTextColorResetsLayeredStylesInAllStories()
    {
        static Paragraph ColoredParagraph(string text) => new(
            new ParagraphProperties(new ParagraphStyleId { Val = "ColorParagraph" }),
            new Run(new RunProperties(new RunStyle { Val = "ColorCharacter" },
                new Color { Val = "auto" }), new Text(text)));
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
