                new Style(new StyleName { Val = "Normal" })
                    { Type = StyleValues.Paragraph, StyleId = "Normal" },
                new Style(new StyleName { Val = "Color Paragraph" },
                    new BasedOn { Val = "Normal" },
                    new StyleRunProperties(new Color { Val = "CC2222" }))
                    { Type = StyleValues.Paragraph, StyleId = "ColorParagraph",
                        CustomStyle = true },
                new Style(new StyleName { Val = "Color Character" },
                    new StyleRunProperties(new Color { Val = "2244CC" }))
                    { Type = StyleValues.Character, StyleId = "ColorCharacter",
                        CustomStyle = true });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(ColoredParagraph("Header automatic color"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(ColoredParagraph("Footer automatic color"));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                ColoredParagraph("Body automatic color"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        var sourceBytes = source.ToArray();
        var binary = DxpDocExport.Export(sourceBytes);
        using (var input = new MemoryStream(binary))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var paragraphStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Color Paragraph");
            var characterStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Color Character");
            Assert.Equal(0x002222CCu, paragraphStyle.CharacterFormatting.ColorRef);
            Assert.Equal(0x00CC4422u, characterStyle.CharacterFormatting.ColorRef);
            foreach (var story in new[] { index.ReadStory("Main"),
                index.HeaderStories[7].ReadIndexedContent(),
                index.HeaderStories[9].ReadIndexedContent() })
            {
                Assert.Contains(story.StoryParagraphStyles,
                    x => x.StyleIndex == paragraphStyle.Index);
                Assert.Contains(story.Runs, x => x.Formatting.CharacterStyleIndex ==
                    characterStyle.Index && x.Formatting.ColorRef == 0xFF000000u);
            }
        }
        var projectedBytes = DxpDocToDocx.Project(binary).DocxBytes;
        foreach (var bytes in new[] { projectedBytes,
            DxpDocToDocx.Project(DxpDocExport.Export(projectedBytes)).DocxBytes })
        {
            using var input = new MemoryStream(bytes);
            using var document = WordprocessingDocument.Open(input, false);
            var main = document.MainDocumentPart!;
            foreach (var paragraph in new[]
            {
                Assert.Single(main.Document!.Body!.Elements<Paragraph>()),
                Assert.Single(Assert.Single(main.HeaderParts).Header!.Elements<Paragraph>()),
                Assert.Single(Assert.Single(main.FooterParts).Footer!.Elements<Paragraph>())
            })
            {
                Assert.NotNull(paragraph.ParagraphProperties?.ParagraphStyleId);
                var run = Assert.Single(paragraph.Elements<Run>());
                Assert.NotNull(run.RunProperties?.RunStyle);
                Assert.Equal("auto", run.RunProperties?.Color?.Val?.Value);
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(sourceBytes, binary, 0.04);
            AssertWordPageRenderClose(sourceBytes, projectedBytes, 0.04, 1, ".docx");
            var sourcePath = Path.Combine(Path.GetTempPath(),
                $"docxport-auto-color-source-{Guid.NewGuid():N}.docx");
            var nativePath = Path.ChangeExtension(sourcePath, ".doc");
            File.WriteAllBytes(sourcePath, sourceBytes);
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID(
                "Word.Application")!)!;
            word.Visible = false;
            dynamic? opened = null;
            try
            {
                opened = word.Documents.Open(sourcePath, ReadOnly: false,
                    AddToRecentFiles: false);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                var native = File.ReadAllBytes(nativePath);
                using (var input = new MemoryStream(native))
                using (var index = new DocTextIndexWalker().Index(input))
                    foreach (var story in new[] { index.ReadStory("Main"),
                        index.HeaderStories[7].ReadIndexedContent(),
                        index.HeaderStories[9].ReadIndexedContent() })
                        Assert.Contains(story.Runs,
                            x => x.Formatting.ColorRef == 0xFF000000u);
                var nativeProjection = DxpDocToDocx.Project(native).DocxBytes;

                using var stream = new MemoryStream(nativeProjection);
                using var document = WordprocessingDocument.Open(stream, false);
                var nativeMain = document.MainDocumentPart!;
                foreach (var paragraph in new[]
                {
                    Assert.Single(nativeMain.Document!.Body!.Elements<Paragraph>()),
                    Assert.Single(Assert.Single(nativeMain.HeaderParts).Header!
                        .Elements<Paragraph>()),
                    Assert.Single(Assert.Single(nativeMain.FooterParts).Footer!
                        .Elements<Paragraph>())
                })
                {
                    Assert.NotNull(paragraph.ParagraphProperties?.ParagraphStyleId);
                    var run = Assert.Single(paragraph.Elements<Run>());
                    Assert.NotNull(run.RunProperties?.RunStyle);
                    Assert.Equal("auto", run.RunProperties?.Color?.Val?.Value);
                }
                Assert.Empty(new OpenXmlValidator().Validate(document));
                AssertWordPageRenderClose(sourceBytes, nativeProjection, 0.04, 1,
                    ".docx");
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit(false);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
    }

    [Fact]
    public void DocWriterKeepsParagraphStylesAcrossPapxPages()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Heading" })
            { Type = StyleValues.Paragraph, StyleId = "Heading" });
            styles.Styles.Save();
            main.Document = new Document(new Body(Enumerable.Range(0, 35)
                .Select(i => new Paragraph(
                    new ParagraphProperties(new ParagraphStyleId { Val = "Heading" },
                        new SpacingBetweenLines { After = (40 + i).ToString() }),
                    new Run(new Text($"Line {i}"))))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.True(index.FormattingPages.Count(x => !x.IsCharacterFormatting) > 1);
            Assert.Equal(35, index.ParagraphStyles.Count(x => x.StyleIndex == 15));
            Assert.Equal(35, index.ParagraphStyles.Count(x => x.Formatting?.AfterTwips != null));
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var paragraphs = projected.MainDocumentPart!.Document!.Body!.Elements<Paragraph>()
            .ToArray();
        Assert.Equal(35, paragraphs.Length);
        Assert.All(paragraphs, x => Assert.Equal("DocStyle15",
            x.ParagraphProperties?.ParagraphStyleId?.Val?.Value));
        for (var i = 0; i < paragraphs.Length; i++)
            Assert.Equal((40 + i).ToString(),
                paragraphs[i].ParagraphProperties?.SpacingBetweenLines?.After?.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void DocRoundTripPreservesParagraphFormattingInBodyHeaderAndFooter()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Centered" },
                new StyleParagraphProperties(new KeepNext(),
                    new ParagraphBorders(new RightBorder { Val = BorderValues.Dotted,
                        Size = 6, Space = 2, Color = "123456" }),
                    new Tabs(new TabStop { Position = 720, Val = TabStopValues.Left },
                        new TabStop { Position = 1440, Val = TabStopValues.Right,
                            Leader = TabStopLeaderCharValues.Dot }),
                    new Indentation { Left = "720", FirstLine = "360" },
                    new Justification { Val = JustificationValues.Center },
                    new SpacingBetweenLines { Before = "120", After = "80",
                        Line = "360", LineRule = LineSpacingRuleValues.Auto },
                    new Shading { Val = ShadingPatternValues.Percent50,
                        Color = "123456", Fill = "E1F2A3" }))
            { Type = StyleValues.Paragraph, StyleId = "Centered" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(
                new ParagraphProperties(new KeepLines { Val = false },
                    new PageBreakBefore(),
                    new ParagraphBorders(new LeftBorder { Val = BorderValues.Dashed,
                        Size = 8, Space = 3, Color = "AABBCC" }),
                    new Tabs(new TabStop { Position = 1800, Val = TabStopValues.Decimal }),
                    new Indentation { Right = "480", Hanging = "240" },
                    new Justification { Val = JustificationValues.Right },
                    new SpacingBetweenLines { After = "60", Line = "420",
                        LineRule = LineSpacingRuleValues.AtLeast },
                    new Shading { Val = ShadingPatternValues.HorizontalStripe,
                        Color = "102030", Fill = "FFCC00" }),
                new Run(new Text("Header"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(
                new ParagraphProperties(new KeepNext(),
                    new ParagraphBorders(new BetweenBorder { Val = BorderValues.Single,
                        Size = 4, Space = 1, Color = "667788" }),
                    new Tabs(new TabStop { Position = 2160, Val = TabStopValues.Bar }),
                    new SpacingBetweenLines { Before = "100", Line = "480",
                        LineRule = LineSpacingRuleValues.Auto },
                    new Shading { Val = ShadingPatternValues.Clear, Fill = "667788" }),
                new Run(new Text("Footer"))));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(
                new ParagraphProperties(new ParagraphStyleId { Val = "Centered" },
                    new KeepLines(), new KeepNext { Val = false },
                    new ParagraphBorders(new TopBorder { Val = BorderValues.Single,
                        Size = 8, Space = 2, Color = "112233", Shadow = true },
                        new BottomBorder { Val = BorderValues.Double,
                            Size = 6, Space = 2, Color = "445566" }),
                    new Tabs(new TabStop { Position = 720, Val = TabStopValues.Clear },
                        new TabStop { Position = 1080, Val = TabStopValues.Center,
                            Leader = TabStopLeaderCharValues.Hyphen }),
                    new Indentation { Left = "1080", Hanging = "360" },
                    new Justification { Val = JustificationValues.Both },
                    new SpacingBetweenLines { Before = "240", Line = "300",
                        LineRule = LineSpacingRuleValues.Exact },
                    new Shading { Val = ShadingPatternValues.Clear, Fill = "A1B2C3" }),
                new Run(new Text("Body"))),
                new SectionProperties(new HeaderReference
                { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header) },
                    new FooterReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            var style = Assert.Single(index.StyleDefinitions, x => x.Name == "Centered");
            Assert.Equal((byte)1, style.ParagraphFormatting!.Justification);
            Assert.Equal((ushort)120, style.ParagraphFormatting.BeforeTwips);
            Assert.Equal((ushort)80, style.ParagraphFormatting.AfterTwips);
            Assert.Equal((short)720, style.ParagraphFormatting.LeftTwips);
            Assert.Equal((short)360, style.ParagraphFormatting.FirstLineTwips);
            Assert.True(style.ParagraphFormatting.KeepWithNext);
            Assert.Equal((short)360, style.ParagraphFormatting.LineValue);
            Assert.True(style.ParagraphFormatting.LineIsMultiple);
            Assert.Equal(2, style.ParagraphFormatting.TabStops!.Count);
            Assert.Equal(new DocTabStop(1440, 2, 1), style.ParagraphFormatting.TabStops[1]);
            Assert.Equal(0xA3F2E1u, style.ParagraphFormatting.FillRgb);
            Assert.Equal(0x563412u, style.ParagraphFormatting.ShadingForegroundRgb);
            Assert.Equal((ushort)8, style.ParagraphFormatting.ShadingPattern);
            Assert.Equal(new DocParagraphBorder(6, 6, 2, 0x563412u),
                style.ParagraphFormatting.RightBorder);
            Assert.Contains(index.ParagraphStyles, x => x.CpStart == 0 &&
                x.Formatting?.Justification == 3 && x.Formatting.BeforeTwips == 240 &&
                x.Formatting.LeftTwips == 1080 && x.Formatting.FirstLineTwips == -360 &&
                x.Formatting.KeepLines == true && x.Formatting.KeepWithNext == false &&
                x.Formatting.LineValue == -300 && x.Formatting.LineIsMultiple == false &&
                x.Formatting.ClearedTabPositions!.Contains((short)720) &&
                x.Formatting.TabStops!.Contains(new DocTabStop(1080, 1, 2)) &&
                x.Formatting.FillRgb == 0xC3B2A1u);
            Assert.Contains(index.ParagraphStyles, x => x.CpStart == 0 &&
                x.Formatting?.TopBorder == new DocParagraphBorder(1, 8, 2, 0x332211u, true) &&
                x.Formatting.BottomBorder == new DocParagraphBorder(3, 6, 2, 0x665544u));
            Assert.Contains(index.ParagraphStyles, x =>
                x.CpStart == index.HeaderStories[7].CpStart &&
                x.Formatting?.Justification == 2 && x.Formatting.AfterTwips == 60 &&
                x.Formatting.RightTwips == 480 && x.Formatting.FirstLineTwips == -240 &&
                x.Formatting.KeepLines == false && x.Formatting.PageBreakBefore == true &&
                x.Formatting.LineValue == 420 && x.Formatting.LineIsMultiple == false &&
                x.Formatting.TabStops!.Contains(new DocTabStop(1800, 3, 0)) &&
                x.Formatting.FillRgb == 0x00CCFFu &&
                x.Formatting.ShadingForegroundRgb == 0x302010u &&
                x.Formatting.ShadingPattern == 0x0E);
            Assert.Contains(index.ParagraphStyles, x =>
                x.CpStart == index.HeaderStories[9].CpStart &&
                x.Formatting?.KeepWithNext == true && x.Formatting.BeforeTwips == 100 &&
                x.Formatting.LineValue == 480 && x.Formatting.LineIsMultiple == true &&
                x.Formatting.TabStops!.Contains(new DocTabStop(2160, 4, 0)) &&
                x.Formatting.FillRgb == 0x887766u);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var styleOut = Assert.Single(projected.MainDocumentPart!.StyleDefinitionsPart!.Styles!
            .Elements<Style>(), x => x.StyleName?.Val?.Value == "Centered");
        Assert.Equal(JustificationValues.Center,
            styleOut.StyleParagraphProperties!.Justification!.Val!.Value);
        Assert.Equal("120", styleOut.StyleParagraphProperties.SpacingBetweenLines!.Before!.Value);
        Assert.Equal("720", styleOut.StyleParagraphProperties.Indentation!.Left!.Value);
        Assert.Equal("360", styleOut.StyleParagraphProperties.Indentation.FirstLine!.Value);
        Assert.True(styleOut.StyleParagraphProperties.KeepNext!.Val!.Value);
        Assert.Equal("360", styleOut.StyleParagraphProperties.SpacingBetweenLines.Line!.Value);
        Assert.Equal(LineSpacingRuleValues.Auto,
            styleOut.StyleParagraphProperties.SpacingBetweenLines.LineRule!.Value);
        var styleTabs = styleOut.StyleParagraphProperties.Tabs!.Elements<TabStop>().ToArray();
        Assert.Equal(2, styleTabs.Length);
        Assert.Equal(TabStopValues.Right, styleTabs[1].Val!.Value);
        Assert.Equal(TabStopLeaderCharValues.Dot, styleTabs[1].Leader!.Value);
        Assert.Equal("E1F2A3", styleOut.StyleParagraphProperties.Shading!.Fill!.Value);
        Assert.Equal("123456", styleOut.StyleParagraphProperties.Shading.Color!.Value);
        Assert.Equal(ShadingPatternValues.Percent50,
            styleOut.StyleParagraphProperties.Shading.Val!.Value);
        Assert.Equal(BorderValues.Dotted,
            styleOut.StyleParagraphProperties.ParagraphBorders!.RightBorder!.Val!.Value);
        var body = projected.MainDocumentPart.Document!.Body!.Elements<Paragraph>().Single();
        Assert.Equal(JustificationValues.Both, body.ParagraphProperties!.Justification!.Val!.Value);
        Assert.Equal("240", body.ParagraphProperties.SpacingBetweenLines!.Before!.Value);
        Assert.Equal("1080", body.ParagraphProperties.Indentation!.Left!.Value);
        Assert.Equal("360", body.ParagraphProperties.Indentation.Hanging!.Value);
        Assert.True(body.ParagraphProperties.KeepLines!.Val!.Value);
        Assert.False(body.ParagraphProperties.KeepNext!.Val!.Value);
        Assert.Equal("300", body.ParagraphProperties.SpacingBetweenLines.Line!.Value);
        Assert.Equal(LineSpacingRuleValues.Exact,
            body.ParagraphProperties.SpacingBetweenLines.LineRule!.Value);
        var bodyTabs = body.ParagraphProperties.Tabs!.Elements<TabStop>().ToArray();
        Assert.Equal(TabStopValues.Clear, bodyTabs[0].Val!.Value);
        Assert.Equal(TabStopValues.Center, bodyTabs[1].Val!.Value);
        Assert.Equal(TabStopLeaderCharValues.Hyphen, bodyTabs[1].Leader!.Value);
        Assert.Equal("A1B2C3", body.ParagraphProperties.Shading!.Fill!.Value);
        Assert.Equal("112233", body.ParagraphProperties.ParagraphBorders!.TopBorder!.Color!.Value);
        Assert.True(body.ParagraphProperties.ParagraphBorders.TopBorder.Shadow!.Value);
        Assert.Equal(BorderValues.Double,
            body.ParagraphProperties.ParagraphBorders.BottomBorder!.Val!.Value);
        var headerOut = projected.MainDocumentPart.HeaderParts.Single().Header!
            .Elements<Paragraph>().Single();
        Assert.Equal(JustificationValues.Right,
            headerOut.ParagraphProperties!.Justification!.Val!.Value);
        Assert.Equal("60", headerOut.ParagraphProperties.SpacingBetweenLines!.After!.Value);
        Assert.Equal("480", headerOut.ParagraphProperties.Indentation!.Right!.Value);
        Assert.Equal("240", headerOut.ParagraphProperties.Indentation.Hanging!.Value);
        Assert.False(headerOut.ParagraphProperties.KeepLines!.Val!.Value);
        Assert.True(headerOut.ParagraphProperties.PageBreakBefore!.Val!.Value);
        Assert.Equal("420", headerOut.ParagraphProperties.SpacingBetweenLines.Line!.Value);
        Assert.Equal(LineSpacingRuleValues.AtLeast,
            headerOut.ParagraphProperties.SpacingBetweenLines.LineRule!.Value);
        Assert.Equal(TabStopValues.Decimal, headerOut.ParagraphProperties.Tabs!
            .Elements<TabStop>().Single().Val!.Value);
        Assert.Equal("FFCC00", headerOut.ParagraphProperties.Shading!.Fill!.Value);
        Assert.Equal("102030", headerOut.ParagraphProperties.Shading.Color!.Value);
        Assert.Equal(ShadingPatternValues.HorizontalStripe,
            headerOut.ParagraphProperties.Shading.Val!.Value);
        Assert.Equal(BorderValues.Dashed,
            headerOut.ParagraphProperties.ParagraphBorders!.LeftBorder!.Val!.Value);
        var footerOut = projected.MainDocumentPart.FooterParts.Single().Footer!
            .Elements<Paragraph>().Single();
        Assert.True(footerOut.ParagraphProperties!.KeepNext!.Val!.Value);
        Assert.Equal("100", footerOut.ParagraphProperties.SpacingBetweenLines!.Before!.Value);
        Assert.Equal("480", footerOut.ParagraphProperties.SpacingBetweenLines.Line!.Value);
        Assert.Equal(LineSpacingRuleValues.Auto,
            footerOut.ParagraphProperties.SpacingBetweenLines.LineRule!.Value);
        Assert.Equal(TabStopValues.Bar, footerOut.ParagraphProperties.Tabs!
            .Elements<TabStop>().Single().Val!.Value);
        Assert.Equal("667788", footerOut.ParagraphProperties.Shading!.Fill!.Value);
        Assert.Equal(BorderValues.Single,
            footerOut.ParagraphProperties.ParagraphBorders!.BetweenBorder!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;

        AssertWordPageRenderClose(source.ToArray(), bytes, 0.06, 1);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-paragraph-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, bytes);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                var bodyParagraph = opened.Paragraphs.Item(1);
                Assert.Equal(15d, (double)bodyParagraph.Range.ParagraphFormat.LineSpacing,
                    1);
                Assert.Equal(12d, (double)bodyParagraph.Range.ParagraphFormat.SpaceBefore,
                    1);
                Assert.Equal(54d, (double)bodyParagraph.Range.ParagraphFormat.LeftIndent,
                    1);
                var headerParagraph = opened.Sections.Item(1).Headers.Item(1)
                    .Range.Paragraphs.Item(1);
                Assert.Equal(21d, (double)headerParagraph.Range.ParagraphFormat.LineSpacing,
                    1);
                var footerParagraph = opened.Sections.Item(1).Footers.Item(1)
                    .Range.Paragraphs.Item(1);
                Assert.Equal(5d, (double)footerParagraph.Range.ParagraphFormat.SpaceBefore,
                    1);
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            using (var nativeStream = new MemoryStream(nativeProjection.DocxBytes))
            using (var nativeDocument = WordprocessingDocument.Open(nativeStream, false))
                Assert.Empty(new OpenXmlValidator().Validate(nativeDocument));
            AssertWordPageRenderClose(source.ToArray(), nativeProjection.DocxBytes,
                0.06, 1, ".docx");
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Theory]
    [InlineData(false, false, 24)]
    [InlineData(true, false, 24)]
    [InlineData(true, true, 24)]
    [InlineData(true, true, 16)]
    public void LineAndCharacterUnitParagraphLayoutSurvivesBothDocRoutesInAllStories(
        bool explicitNormal, bool explicitDefaults, int normalHalfPoints)
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            var styleRoot = new Styles();
            if (explicitDefaults)
                styleRoot.AppendChild(new DocDefaults(
                    new RunPropertiesDefault(new RunPropertiesBaseStyle(
                        new FontSize { Val = "20" }))));
            if (explicitNormal)
                styleRoot.AppendChild(new Style(new StyleName { Val = "Normal" },
                    new StyleRunProperties(new FontSize
                    { Val = normalHalfPoints.ToString() }))
                { Type = StyleValues.Paragraph, StyleId = "Normal" });
            styleRoot.AppendChild(new Style(new StyleName { Val = "Line unit gaps" },
                new StyleParagraphProperties(
                    new SpacingBetweenLines
                    { BeforeLines = 150, AfterLines = 75 },
                    new Indentation
                    { StartCharacters = 200, EndCharacters = 100,
                        FirstLineChars = 100 }))
            { Type = StyleValues.Paragraph, StyleId = "LineUnitGaps" });
            styles.Styles = styleRoot;
            styles.Styles.Save();
            static Paragraph Styled(string text, bool reset = false)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = "LineUnitGaps" });
                if (reset)
                    properties.AppendChild(new SpacingBetweenLines
                    { BeforeLines = 0, AfterLines = 0 });
                if (reset)
                    properties.AppendChild(new Indentation
                    { LeftChars = 0, RightChars = 0, HangingChars = 100 });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Line header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Line footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Styled("Line body"),
                Styled("Reset body", true), Styled("Final body"),
                new Paragraph(new ParagraphProperties(new BiDi(),
                    new Indentation { StartCharacters = 200,
                        EndCharacters = 100 }),
                    new Run(new Text("RTL logical"))),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        void AssertProjection(byte[] binary)
        {
            var result = DxpDocToDocx.Project(binary);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            if (explicitDefaults)
            {
                Assert.Equal("20", main.StyleDefinitionsPart!.Styles!
                    .GetFirstChild<DocDefaults>()!.RunPropertiesDefault!
                    .RunPropertiesBaseStyle!.GetFirstChild<FontSize>()!.Val!.Value);
                Assert.DoesNotContain(main.StyleDefinitionsPart.Styles.Elements<Style>(),
                    x => x.StyleName?.Val?.Value ==
                        "DocxportNet Preserved Run Defaults");
            }
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Line unit gaps");
            Assert.Equal(150, style.StyleParagraphProperties!.SpacingBetweenLines!
                .BeforeLines!.Value);
            Assert.Equal(75, style.StyleParagraphProperties.SpacingBetweenLines
                .AfterLines!.Value);
            Assert.Equal(200, style.StyleParagraphProperties.Indentation!
                .LeftChars!.Value);
            Assert.Equal(100, style.StyleParagraphProperties.Indentation
                .RightChars!.Value);
            Assert.Equal(100, style.StyleParagraphProperties.Indentation
                .FirstLineChars!.Value);
            var reset = main.Document.Body!.Elements<Paragraph>().ElementAt(1)
                .ParagraphProperties!.SpacingBetweenLines!;
            Assert.Equal(0, reset.BeforeLines!.Value);
            Assert.Equal(0, reset.AfterLines!.Value);
            var resetIndent = main.Document.Body.Elements<Paragraph>().ElementAt(1)
                .ParagraphProperties!.Indentation!;
            Assert.Equal(0, resetIndent.LeftChars!.Value);
            Assert.Equal(0, resetIndent.RightChars!.Value);
            Assert.Equal(100, resetIndent.HangingChars!.Value);
            var rtlIndent = main.Document.Body.Elements<Paragraph>().ElementAt(3)
                .ParagraphProperties!.Indentation!;
            Assert.True(main.Document.Body.Elements<Paragraph>().ElementAt(3)
                .ParagraphProperties!.BiDi!.Val!.Value);
            Assert.Equal(200, rtlIndent.LeftChars!.Value);
            Assert.Equal(100, rtlIndent.RightChars!.Value);
            Assert.Equal("Line header", main.HeaderParts.Single().Header!.InnerText);
            Assert.Equal("Line footer", main.FooterParts.Single().Footer!.InnerText);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        if (explicitNormal)
        {
            using var binaryStream = new MemoryStream(binary);
            using var index = new DocTextIndexWalker().Index(binaryStream);
            var normal = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Normal" && x.Index == 0);
            Assert.Equal(0, normal.Index);
            var lineStyle = Assert.Single(index.StyleDefinitions,
                x => x.Name == "Line unit gaps");
            Assert.Equal(explicitDefaults ? (int?)null : normal.Index,
                lineStyle.BasedOnIndex);
            if (explicitDefaults)
            {
                var carrier = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "DocxportNet Preserved Run Defaults");
                var entry = Assert.Single(index.Styles, x =>
                    x.Attributes["styleIndex"] == carrier.Index.ToString());
                var flagsNode = entry.Children.Single(x => x.Kind == "STD")
                    .Children.Single(x => x.Kind == "Stdf")
                    .Children.Single(x => x.Kind == "StdfBase")
                    .Children.Single(x => x.Kind == "GRFSTD");
                var flags = System.Buffers.Binary.BinaryPrimitives
                    .ReadUInt16LittleEndian(index.Structure.ReadRange(
                        flagsNode.StreamName!, flagsNode.Offset!.Value, 2));
                Assert.Equal(0x0102, flags & 0x0102);
            }
        }
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        if (explicitDefaults)
            AssertWordPageRenderClose(source.ToArray(),
                DxpDocToDocx.Project(binary).DocxBytes, 0.04, 1, ".docx");
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-line-unit-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        var rtlPositions = new Dictionary<string, double>();
        var rtlIndents = new Dictionary<string, string>();
        var rtlFontNames = new Dictionary<string, string>();
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                if (explicitDefaults && path == generatedPath)
                {
                    var styleProbe = Path.ChangeExtension(generatedPath, ".style-probe.docx");
                    opened.SaveAs2(styleProbe, 16);
                    opened.Close(false);
                    opened = null;
                    using (var styleProbeDocument = WordprocessingDocument.Open(
                        styleProbe, false))
                    {
                        var markerStyle = Assert.Single(styleProbeDocument.MainDocumentPart!
                            .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                            x.StyleName?.Val?.Value == "DocxportNet Preserved Run Defaults");
                        Assert.Contains("<w:hidden", markerStyle.OuterXml);
                        Assert.Contains("<w:semiHidden", markerStyle.OuterXml);
                    }
                    File.Delete(styleProbe);
                    opened = word.Documents.Open(path, ReadOnly: true,
                        AddToRecentFiles: false);
                }
                Assert.True(Convert.ToDouble(opened.Paragraphs.Item(1)
                    .Range.ParagraphFormat.SpaceBefore) > 0);
                Assert.True(Convert.ToDouble(opened.Paragraphs.Item(1)
                    .Range.ParagraphFormat.LeftIndent) >
                    Convert.ToDouble(opened.Paragraphs.Item(2)
                    .Range.ParagraphFormat.LeftIndent));
                if (explicitDefaults)
                    Assert.Equal(10d, Convert.ToDouble(opened.Paragraphs.Item(1)
                        .Range.Font.Size), 1);
                dynamic rtlStart = opened.Paragraphs.Item(4).Range.Duplicate;
                rtlStart.Collapse(1);
                rtlPositions[path] = Convert.ToDouble(rtlStart.Information(5));
                dynamic rtlFormat = opened.Paragraphs.Item(4)
                    .Range.ParagraphFormat;
                dynamic rtlFont = opened.Paragraphs.Item(4).Range.Font;
                Assert.Equal(explicitDefaults ? 10d : 15d,
                    Convert.ToDouble(rtlFont.SizeBi), 1);
                rtlFontNames[path] = Convert.ToString(rtlFont.NameBi)!;
                rtlIndents[path] = $"L={rtlFormat.LeftIndent}, R={rtlFormat.RightIndent}, F={rtlFormat.FirstLineIndent}";
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertProjection(File.ReadAllBytes(nativePath));
            if (explicitDefaults)
            {
                using var nativeIndex = new DocTextIndexWalker().Index(nativePath);
                var nativeNormal = Assert.Single(nativeIndex.StyleDefinitions,
                    x => x.Index == 0);
                Assert.Equal((ushort)normalHalfPoints,
                    nativeNormal.CharacterFormatting.SizeHalfPoints);
                var nativeLineStyle = Assert.Single(nativeIndex.StyleDefinitions,
                    x => x.Name == "Line unit gaps");
                Assert.Null(nativeLineStyle.BasedOnIndex);
                Assert.Null(nativeLineStyle.CharacterFormatting.SizeHalfPoints);
                Assert.DoesNotContain(nativeIndex.CharacterFormatting,
                    x => x.Formatting.SizeHalfPoints == 20);
            }
            Assert.Equal(rtlFontNames[nativePath], rtlFontNames[generatedPath]);
            static bool? Balanced(string path)
            {
                using var input = File.OpenRead(path);
                using var index = new DocTextIndexWalker().Index(input);
                return index.BalanceSingleByteDoubleByteWidth;
            }
            Assert.True(Math.Abs(rtlPositions[sourcePath] -
                rtlPositions[generatedPath]) <= 2,
                $"RTL x: source={rtlPositions[sourcePath]} ({rtlIndents[sourcePath]}), generated={rtlPositions[generatedPath]} ({rtlIndents[generatedPath]}, balance={Balanced(generatedPath)}), native={rtlPositions[nativePath]} ({rtlIndents[nativePath]}, balance={Balanced(nativePath)})");
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            AssertWordPageRenderClose(source.ToArray(), nativeProjection.DocxBytes,
                0.04, 1, ".docx");
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(Path.ChangeExtension(generatedPath, ".style-probe.docx"));
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void AutomaticParagraphSpacingSurvivesBothDocRoutesInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(new StyleName { Val = "Automatic gaps" },
                new StyleParagraphProperties(new SpacingBetweenLines
                {
                    Before = "240", After = "240", BeforeAutoSpacing = true,
                    AfterAutoSpacing = true
                })) { Type = StyleValues.Paragraph, StyleId = "AutomaticGaps" });
            styles.Styles.Save();
            static Paragraph Styled(string text, bool reset = false)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = "AutomaticGaps" });
                if (reset)
                    properties.AppendChild(new SpacingBetweenLines
                    {
                        Before = "120", After = "120", BeforeAutoSpacing = false,
                        AfterAutoSpacing = false
                    });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Automatic header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Automatic footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(Styled("Automatic body"),
                Styled("Explicit body", true),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        void AssertProjection(byte[] binary)
        {
            var result = DxpDocToDocx.Project(binary);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Automatic gaps");
            Assert.True(style.StyleParagraphProperties!.SpacingBetweenLines!
                .BeforeAutoSpacing!.Value);
            Assert.True(style.StyleParagraphProperties.SpacingBetweenLines
                .AfterAutoSpacing!.Value);
            var reset = main.Document.Body!.Elements<Paragraph>().ElementAt(1)
                .ParagraphProperties!.SpacingBetweenLines!;
            Assert.False(reset.BeforeAutoSpacing!.Value);
            Assert.False(reset.AfterAutoSpacing!.Value);
            Assert.Equal("120", reset.Before!.Value);
            Assert.Equal("120", reset.After!.Value);
            Assert.Equal("Automatic header", main.HeaderParts.Single().Header!.InnerText);
            Assert.Equal("Automatic footer", main.FooterParts.Single().Footer!.InnerText);
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-auto-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.True(Convert.ToBoolean(opened.Paragraphs.Item(1)
                    .SpaceBeforeAuto));
                Assert.True(Convert.ToBoolean(opened.Paragraphs.Item(1)
                    .SpaceAfterAuto));
                Assert.False(Convert.ToBoolean(opened.Paragraphs.Item(2)
                    .SpaceBeforeAuto));
                Assert.False(Convert.ToBoolean(opened.Paragraphs.Item(2)
                    .SpaceAfterAuto));
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            AssertProjection(File.ReadAllBytes(nativePath));
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            AssertWordPageRenderClose(source.ToArray(), nativeProjection.DocxBytes,
                0.04, 1, ".docx");
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void SuppressAutoHyphensStyleAndResetSurviveBothDocRoutes()
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var settingsPart = main.DocumentSettingsPart ??
                main.AddNewPart<DocumentSettingsPart>();
            settingsPart.Settings ??= new Settings();
            settingsPart.Settings.AddChild(new AutoHyphenation(), true);
            settingsPart.Settings.AddChild(new DoNotHyphenateCaps(), true);
            settingsPart.Settings.AddChild(new HyphenationZone { Val = "360" }, true);
            settingsPart.Settings.AddChild(new ConsecutiveHyphenLimit { Val = 2 }, true);
            settingsPart.Settings.Save();
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleId?.Value == "MirroredBody");
            style.StyleParagraphProperties!.InsertBefore(
                new SuppressAutoHyphens(),
                style.StyleParagraphProperties.GetFirstChild<Indentation>());
            style.StyleParagraphProperties.AddChild(new TextAlignment
                { Val = VerticalTextAlignmentValues.Top }, true);
            main.StyleDefinitionsPart.Styles.Save();
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            body[1].ParagraphProperties!.InsertBefore(
                new SuppressAutoHyphens { Val = false },
                body[1].ParagraphProperties!.GetFirstChild<MirrorIndents>());
            body[1].ParagraphProperties.AddChild(new TextAlignment
                { Val = VerticalTextAlignmentValues.Baseline }, true);
            foreach (var paragraph in body.Concat(main.HeaderParts.SelectMany(x =>
                         x.Header!.Elements<Paragraph>())).Concat(
                         main.FooterParts.SelectMany(x => x.Footer!.Elements<Paragraph>())))
            {
                var small = paragraph.Elements<Run>().First();
                small.RunProperties ??= new RunProperties();
                small.RunProperties.RunFonts = new RunFonts { Ascii = "Arial",
                    HighAnsi = "Arial" };
                small.RunProperties.FontSize = new FontSize { Val = "24" };
                paragraph.AppendChild(new Run(
                    new RunProperties(new RunFonts { Ascii = "Arial",
                        HighAnsi = "Arial" }, new FontSize { Val = "48" }),
                    new Text(" Tall")));
            }
            main.Document.Save();
            foreach (var header in main.HeaderParts) header.Header!.Save();
            foreach (var footer in main.FooterParts) footer.Footer!.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                Assert.True(index.AutoHyphenation);
                Assert.False(index.HyphenateCaps);
                Assert.Equal((short)360, index.HyphenationZoneTwips);
                Assert.Equal((short)2, index.ConsecutiveHyphenLimit);
                var style = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "Mirrored body");
                Assert.True(style.ParagraphFormatting?.SuppressAutoHyphens);
                Assert.Equal((short)0, style.ParagraphFormatting?.TextAlignmentCode);
                Assert.Contains(index.ParagraphStyles, x =>
                    x.Formatting?.SuppressAutoHyphens == false);
                Assert.Contains(index.ParagraphStyles, x =>
                    x.Formatting?.TextAlignmentCode == 2);
            }
            var projection = DxpDocToDocx.Project(binary);
            Assert.Empty(projection.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(projection.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            Assert.True(main.DocumentSettingsPart!.Settings!
                .GetFirstChild<AutoHyphenation>()!.Val?.Value ?? true);
            Assert.True(main.DocumentSettingsPart.Settings
                .GetFirstChild<DoNotHyphenateCaps>()!.Val?.Value ?? true);
            Assert.Equal("360", main.DocumentSettingsPart.Settings
                .GetFirstChild<HyphenationZone>()!.Val!.Value);
            Assert.Equal((ushort)2, main.DocumentSettingsPart.Settings
                .GetFirstChild<ConsecutiveHyphenLimit>()!.Val!.Value);
            var styleNode = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Mirrored body");
            Assert.True(styleNode.StyleParagraphProperties!
                .SuppressAutoHyphens!.Val!.Value);
            Assert.Equal(VerticalTextAlignmentValues.Top,
                styleNode.StyleParagraphProperties.TextAlignment!.Val!.Value);
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.False(body[1].ParagraphProperties!
                .SuppressAutoHyphens!.Val!.Value);
            Assert.Equal(VerticalTextAlignmentValues.Baseline,
                body[1].ParagraphProperties.TextAlignment!.Val!.Value);
            var errors = new OpenXmlValidator().Validate(document).ToArray();
            Assert.True(errors.Length == 0, string.Join("\n", errors.Select(x =>
                $"{x.Description} at {x.Path?.XPath}: {x.Node?.OuterXml}")));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.065, 1);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.065, 2);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var temporary = Path.Combine(Path.GetTempPath(),
            $"docxport-suppress-hyphens-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporary);
        var paths = new[]
        {
            Path.Combine(temporary, "source.docx"),
            Path.Combine(temporary, "generated.doc"),
            Path.Combine(temporary, "native.doc")
        };
        File.WriteAllBytes(paths[0], source.ToArray());
        File.WriteAllBytes(paths[1], generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in paths)
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    Assert.True((bool)document.AutoHyphenation);
                    Assert.False((bool)document.HyphenateCaps);
                    Assert.Equal(18d, Convert.ToDouble(document.HyphenationZone), 1);
                    Assert.Equal(2, Convert.ToInt32(document.ConsecutiveHyphensLimit));
                    Assert.Equal(0, (int)document.Styles.Item("Mirrored body")
                        .ParagraphFormat.Hyphenation);
                    Assert.Equal(0, (int)document.Styles.Item("Mirrored body")
                        .ParagraphFormat.BaseLineAlignment);
                    Assert.Equal(0, (int)document.Paragraphs.Item(1)
                        .Range.ParagraphFormat.BaseLineAlignment);
                    Assert.NotEqual(0, (int)document.Paragraphs.Item(2)
                        .Range.ParagraphFormat.Hyphenation);
                    Assert.Equal(2, (int)document.Paragraphs.Item(2)
                        .Range.ParagraphFormat.BaseLineAlignment);
                    Assert.Equal("Arial", Convert.ToString(document.Paragraphs
                        .Item(1).Range.Words.Item(1).Font.Name));
                    Assert.Equal(12d, Convert.ToDouble(document.Paragraphs
                        .Item(1).Range.Words.Item(1).Font.Size), 1);
                    Assert.Equal(0, (int)document.Sections.Item(1)
                        .Headers.Item(1).Range.Paragraphs.Item(1)
                        .Range.ParagraphFormat.Hyphenation);
                    Assert.Equal(0, (int)document.Sections.Item(1)
                        .Footers.Item(1).Range.Paragraphs.Item(1)
                        .Range.ParagraphFormat.Hyphenation);
                    if (path == paths[0]) document.SaveAs2(paths[2], 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(paths[2]));
        }
        finally
        {
            word.Quit(false);
            foreach (var path in paths) File.Delete(path);
            Directory.Delete(temporary);
        }
    }

    [Fact]
    public void KerningStyleAndDirectOverrideSurviveAllStoriesAndWord()
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleId?.Value == "MirroredBody");
            var styleRuns = style.StyleRunProperties ??
                style.AppendChild(new StyleRunProperties());
            styleRuns.AddChild(new Kern { Val = 4 }, true);
            main.StyleDefinitionsPart.Styles.Save();
            var reset = main.Document.Body!.Elements<Paragraph>()
                .Skip(1).First().GetFirstChild<Run>()!;
            var resetRuns = reset.RunProperties ?? reset.PrependChild(new RunProperties());
            resetRuns.AddChild(new Kern { Val = 0 }, true);
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] bytes)
        {
            using (var index = new DocTextIndexWalker().Index(new MemoryStream(bytes)))
            {
                var indexedStyle = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "Mirrored body");
                Assert.Equal((ushort)4,
                    indexedStyle.CharacterFormatting?.KerningThresholdHalfPoints);
                Assert.Contains(index.CharacterFormatting, x =>
                    x.Formatting?.KerningThresholdHalfPoints == 0);
            }
            var projected = DxpDocToDocx.Project(bytes);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var document = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var main = document.MainDocumentPart!;
            var projectedStyle = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Mirrored body");
            Assert.Equal((ushort)4, projectedStyle.StyleRunProperties!.Kern!.Val!.Value);
            Assert.Equal((ushort)0, main.Document.Body!.Elements<Paragraph>()
                .Skip(1).First().GetFirstChild<Run>()!.RunProperties!.Kern!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 1);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 2);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-kerning-stories-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        var nativePath = Path.Combine(directory, "native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    Assert.Equal(2, Convert.ToDouble(document.Paragraphs.Item(1)
                        .Range.Characters.Item(1).Font.Kerning));
                    Assert.Equal(0, Convert.ToDouble(document.Paragraphs.Item(2)
                        .Range.Characters.Item(1).Font.Kerning));
                    Assert.Equal(2, Convert.ToDouble(document.Sections.Item(1)
                        .Headers.Item(1).Range.Characters.Item(1).Font.Kerning));
                    Assert.Equal(2, Convert.ToDouble(document.Sections.Item(1)
                        .Footers.Item(1).Range.Characters.Item(1).Font.Kerning));
                    if (path == sourcePath) document.SaveAs2(nativePath, 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(nativePath));
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            Directory.Delete(directory);
        }
    }

    [Fact]
    public void SectionLineNumbersWithoutDistanceOmitOptionalAttribute()
    {
        var properties = new SectionProperties();
        new DocSectionFormatting(LineNumberCountBy: 5).ApplyTo(properties);
        var numbering = Assert.Single(properties.Elements<LineNumberType>());
        Assert.Equal((short)5, numbering.CountBy!.Value);
        Assert.Null(numbering.Distance);
        Assert.DoesNotContain("w:distance", numbering.OuterXml);
    }

    [Theory]
    [InlineData(1, 0, 360, 0)]
    [InlineData(2, 3, 240, 1)]
    [InlineData(3, 5, 180, 2)]
    public void SectionLineNumbersSurviveBothDocRoutesAndWordRendering(
        int countBy, int start, int distance, int restart)
    {
        var restartValue = restart switch
        {
            1 => LineNumberRestartValues.NewSection,
            2 => LineNumberRestartValues.Continuous,
            _ => LineNumberRestartValues.NewPage
        };
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            main.Document.Body!
                .GetFirstChild<SectionProperties>()!.AddChild(new LineNumberType
                {
                    CountBy = checked((short)countBy), Start = checked((short)start),
                    Distance = distance.ToString(CultureInfo.InvariantCulture),
                    Restart = restartValue
                }, true);
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleId?.Value == "MirroredBody");
            style.StyleParagraphProperties!.AddChild(new SuppressLineNumbers(), true);
            main.StyleDefinitionsPart.Styles.Save();
            main.Document.Body.Elements<Paragraph>().Skip(1).First()
                .ParagraphProperties!.AddChild(new SuppressLineNumbers
                    { Val = false }, true);
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] bytes)
        {
            using (var index = new DocTextIndexWalker().Index(new MemoryStream(bytes)))
            {
                var section = DocSectionFormatting.Read(index,
                    Assert.Single(index.Sections));
                Assert.Equal((ushort)countBy, section.LineNumberCountBy);
                Assert.Equal((ushort)start, section.LineNumberStart ?? 0);
                Assert.Equal((ushort)distance, section.LineNumberDistance);
                Assert.Equal((byte)restart, section.LineNumberRestart ?? 0);
                var indexedStyle = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "Mirrored body");
                Assert.True(indexedStyle.ParagraphFormatting?.SuppressLineNumbers);
                Assert.Contains(index.ParagraphStyles, x =>
                    x.Formatting?.SuppressLineNumbers == false);
            }
            var projected = DxpDocToDocx.Project(bytes);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var document = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var numbering = document.MainDocumentPart!.Document.Body!
                .GetFirstChild<SectionProperties>()!
                .GetFirstChild<LineNumberType>()!;
            Assert.Equal((short)countBy, numbering.CountBy!.Value);
            Assert.Equal((short)start, numbering.Start?.Value ?? 0);
            Assert.Equal(distance.ToString(CultureInfo.InvariantCulture),
                numbering.Distance!.Value);
            Assert.Equal(restartValue,
                numbering.Restart?.Value ?? LineNumberRestartValues.NewPage);
            var style = Assert.Single(document.MainDocumentPart
                .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                x.StyleName?.Val?.Value == "Mirrored body");
            Assert.True(style.StyleParagraphProperties!
                .SuppressLineNumbers!.Val?.Value ?? true);
            Assert.False(document.MainDocumentPart.Document.Body!
                .Elements<Paragraph>().Skip(1).First().ParagraphProperties!
                .SuppressLineNumbers!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 1);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 2);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-section-lines-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        var nativePath = Path.Combine(directory, "native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    dynamic numbering = document.Sections.Item(1)
                        .PageSetup.LineNumbering;
                    Assert.NotEqual(0, (int)numbering.Active);
                    Assert.Equal(countBy, (int)numbering.CountBy);
                    Assert.Equal(start + 1, (int)numbering.StartingNumber);
                    Assert.Equal(distance / 20d,
                        Convert.ToDouble(numbering.DistanceFromText), 1);
                    Assert.Equal(restart switch { 0 => 2, 1 => 1, _ => 0 },
                        (int)numbering.RestartMode);
                    Assert.NotEqual(0, (int)document.Styles.Item("Mirrored body")
                        .ParagraphFormat.NoLineNumber);
                    Assert.Equal(0, (int)document.Paragraphs.Item(2)
                        .Range.ParagraphFormat.NoLineNumber);
                    Assert.Equal(1, Convert.ToDouble(document.Paragraphs.Item(1)
                        .Range.Characters.Item(1).Font.Kerning));
                    Assert.Equal(1, Convert.ToDouble(document.Sections.Item(1)
                        .Headers.Item(1).Range.Characters.Item(1).Font.Kerning));
                    Assert.Equal(1, Convert.ToDouble(document.Sections.Item(1)
                        .Footers.Item(1).Range.Characters.Item(1).Font.Kerning));
                    if (path == sourcePath) document.SaveAs2(nativePath, 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(nativePath));
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            Directory.Delete(directory);
        }
    }

    [Fact]
    public void SectionLineNumberingTransitionsAcrossThreeStorySections()
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordThreeSectionStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var sections = document.MainDocumentPart!.Document.Body!
                .Descendants<SectionProperties>().ToArray();
            Assert.Equal(3, sections.Length);
            sections[0].AddChild(new LineNumberType
            {
                CountBy = 1, Start = 0, Distance = "360",
                Restart = LineNumberRestartValues.Continuous
            }, true);
            sections[1].AddChild(new LineNumberType
            {
                CountBy = 2, Start = 3, Distance = "240",
                Restart = LineNumberRestartValues.NewSection
            }, true);
            sections[1].AddChild(new VerticalTextAlignmentOnPage
                { Val = VerticalJustificationValues.Center }, true);
            sections[2].AddChild(new VerticalTextAlignmentOnPage
                { Val = VerticalJustificationValues.Bottom }, true);
            document.MainDocumentPart.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] bytes)
        {
            using (var index = new DocTextIndexWalker().Index(new MemoryStream(bytes)))
            {
                Assert.Equal(3, index.Sections.Count);
                var first = DocSectionFormatting.Read(index, index.Sections[0]);
                var second = DocSectionFormatting.Read(index, index.Sections[1]);
                var third = DocSectionFormatting.Read(index, index.Sections[2]);
                Assert.Equal((ushort)1, first.LineNumberCountBy);
                Assert.Equal((byte)2, first.LineNumberRestart);
                Assert.Equal((ushort)360, first.LineNumberDistance);
                Assert.Equal((ushort)2, second.LineNumberCountBy);
                Assert.Equal((ushort)3, second.LineNumberStart);
                Assert.Equal((ushort)240, second.LineNumberDistance);
                Assert.Equal((byte)1, second.LineNumberRestart);
                Assert.Equal((ushort)0, third.LineNumberCountBy ?? 0);
                Assert.Equal((byte)1, second.VerticalAlignment);
                Assert.Equal((byte)3, third.VerticalAlignment);
            }
            var projected = DxpDocToDocx.Project(bytes);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var document = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var sections = document.MainDocumentPart!.Document.Body!
                .Descendants<SectionProperties>().ToArray();
            Assert.Equal(3, sections.Length);
            Assert.Equal((short)1, sections[0].GetFirstChild<LineNumberType>()!.CountBy!.Value);
            Assert.Equal(LineNumberRestartValues.Continuous,
                sections[0].GetFirstChild<LineNumberType>()!.Restart!.Value);
            Assert.Equal((short)2, sections[1].GetFirstChild<LineNumberType>()!.CountBy!.Value);
            Assert.Equal((short)3, sections[1].GetFirstChild<LineNumberType>()!.Start!.Value);
            Assert.Null(sections[2].GetFirstChild<LineNumberType>());
            Assert.Equal(VerticalJustificationValues.Center,
                sections[1].GetFirstChild<VerticalTextAlignmentOnPage>()!.Val!.Value);
            Assert.Equal(VerticalJustificationValues.Bottom,
                sections[2].GetFirstChild<VerticalTextAlignmentOnPage>()!.Val!.Value);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            for (var page = 1; page <= 3; page++)
                AssertWordPageRenderClose(source.ToArray(), generated, 0.04, page);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-three-section-lines-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        var nativePath = Path.Combine(directory, "native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    Assert.Equal(3, (int)document.Sections.Count);
                    var first = document.Sections.Item(1).PageSetup.LineNumbering;
                    var second = document.Sections.Item(2).PageSetup.LineNumbering;
                    var third = document.Sections.Item(3).PageSetup.LineNumbering;
                    Assert.NotEqual(0, (int)first.Active);
                    Assert.Equal(1, (int)first.CountBy);
                    Assert.Equal(0, (int)first.RestartMode);
                    Assert.NotEqual(0, (int)second.Active);
                    Assert.Equal(2, (int)second.CountBy);
                    Assert.Equal(4, (int)second.StartingNumber);
                    Assert.Equal(1, (int)second.RestartMode);
                    Assert.Equal(0, (int)third.Active);
                    Assert.Equal(1, (int)document.Sections.Item(2)
                        .PageSetup.VerticalAlignment);
                    Assert.Equal(3, (int)document.Sections.Item(3)
                        .PageSetup.VerticalAlignment);
                    if (path == sourcePath) document.SaveAs2(nativePath, 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(nativePath));
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            Directory.Delete(directory);
        }
    }

    [Theory]
    [InlineData(false, 1, false)]
    [InlineData(true, 0, false)]
    [InlineData(false, 1, true)]
    public void SectionLineNumberingSurvivesLongBodyFlowWithExemptParagraphs(
        bool explicitZeroKerning, int expectedKerning, bool styledExemptParagraphs)
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var body = document.MainDocumentPart!.Document.Body!;
            body.GetFirstChild<SectionProperties>()!.AddChild(new LineNumberType
            {
                CountBy = 5, Start = 0, Distance = "360",
                Restart = LineNumberRestartValues.NewPage
            }, true);
            for (var i = 0; i < 90; i++)
            {
                var properties = new ParagraphProperties(new SpacingBetweenLines
                {
                    Before = "0", After = "0", Line = "300",
                    LineRule = LineSpacingRuleValues.Exact
                });
                var runProperties = new RunProperties(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new FontSize { Val = "22" });
                if (explicitZeroKerning)
                    runProperties.AddChild(new Kern { Val = 0 }, true);
                var paragraph = new Paragraph(properties, new Run(
                    runProperties,
                    new Text($"Line numbering flow paragraph {i + 1:D2}. " +
                        "This sentence continues the body across page boundaries.")));
                if (i % 9 == 0)
                {
                    if (styledExemptParagraphs)
                        properties.AddChild(new ParagraphStyleId
                            { Val = "MirroredBody" }, true);
                    properties.AddChild(new SuppressLineNumbers(), true);
                }
                body.InsertBefore(paragraph, body.GetFirstChild<SectionProperties>());
            }
            document.MainDocumentPart.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] bytes)
        {
            using (var index = new DocTextIndexWalker().Index(new MemoryStream(bytes)))
            {
                var section = DocSectionFormatting.Read(index, Assert.Single(index.Sections));
                Assert.Equal((ushort)5, section.LineNumberCountBy);
                Assert.Equal((ushort)360, section.LineNumberDistance);
                Assert.Equal((byte)0, section.LineNumberRestart ?? 0);
                Assert.True(index.ParagraphStyles.Count(x =>
                    x.Formatting?.SuppressLineNumbers == true) >= 10);
            }
            var projected = DxpDocToDocx.Project(bytes);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var document = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var body = document.MainDocumentPart!.Document.Body!;
            var numbering = body.GetFirstChild<SectionProperties>()!
                .GetFirstChild<LineNumberType>()!;
            Assert.Equal((short)5, numbering.CountBy!.Value);
            Assert.Equal("360", numbering.Distance!.Value);
            Assert.Equal(10, body.Elements<Paragraph>().Count(x =>
                x.ParagraphProperties?.SuppressLineNumbers != null));
            if (styledExemptParagraphs)
            {
                var styledId = body.Elements<Paragraph>().Skip(3).First()
                    .ParagraphProperties?.ParagraphStyleId?.Val?.Value;
                Assert.False(string.IsNullOrEmpty(styledId));
                Assert.Equal(10, body.Elements<Paragraph>().Skip(3).Count(x =>
                    x.ParagraphProperties?.ParagraphStyleId?.Val?.Value == styledId));
            }
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            for (var page = 1; page <= 4; page++)
                AssertWordPageRenderClose(source.ToArray(), generated, 0.05, page);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-long-section-lines-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        var nativePath = Path.Combine(directory, "native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            int? pageCount = null;
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    var numbering = document.Sections.Item(1).PageSetup.LineNumbering;
                    Assert.NotEqual(0, (int)numbering.Active);
                    Assert.Equal(5, (int)numbering.CountBy);
                    Assert.Equal(2, (int)numbering.RestartMode);
                    Assert.Equal(expectedKerning,
                        Convert.ToDouble(document.Paragraphs.Item(4)
                        .Range.Font.Kerning));
                    if (styledExemptParagraphs)
                        Assert.Equal("Mirrored body", (string)document.Paragraphs
                            .Item(4).Style.NameLocal);
                    var pages = (int)document.ComputeStatistics(2);
                    Assert.True(pages >= 4);
                    if (pageCount.HasValue) Assert.Equal(pageCount.Value, pages);
                    else pageCount = pages;
                    if (path == sourcePath) document.SaveAs2(nativePath, 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(nativePath));
            if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
                for (var page = 1; page <= 4; page++)
                    AssertWordPageRenderClose(source.ToArray(),
                        File.ReadAllBytes(nativePath), 0.04, page);
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            Directory.Delete(directory);
        }
    }

