    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    [InlineData(4)]
    public void OtherVerticalTextAlignmentsSurviveBothDocRoutes(int alignmentCode)
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        var value = alignmentCode switch
        {
            1 => VerticalTextAlignmentValues.Center,
            3 => VerticalTextAlignmentValues.Bottom,
            4 => VerticalTextAlignmentValues.Auto,
            _ => throw new InvalidDataException()
        };
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleId?.Value == "MirroredBody");
            style.StyleParagraphProperties!.AddChild(new TextAlignment { Val = value }, true);
            main.StyleDefinitionsPart.Styles.Save();
            var paragraphs = main.Document.Body!.Elements<Paragraph>()
                .Concat(main.HeaderParts.SelectMany(x => x.Header!.Elements<Paragraph>()))
                .Concat(main.FooterParts.SelectMany(x => x.Footer!.Elements<Paragraph>()));
            foreach (var paragraph in paragraphs)
                paragraph.AppendChild(new Run(
                    new RunProperties(new RunFonts { Ascii = "Arial",
                        HighAnsi = "Arial" }, new FontSize { Val = "48" }),
                    new Text(" Tall")));
            main.Document.Save();
            foreach (var header in main.HeaderParts) header.Header!.Save();
            foreach (var footer in main.FooterParts) footer.Footer!.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] bytes, bool expectExplicit = true)
        {
            using (var index = new DocTextIndexWalker().Index(new MemoryStream(bytes)))
            {
                var style = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "Mirrored body");
                Assert.Equal(expectExplicit ? (short)alignmentCode : null,
                    style.ParagraphFormatting?.TextAlignmentCode);
            }
            var projected = DxpDocToDocx.Project(bytes);
            Assert.Empty(projected.Coverage.OmittedCharacters);
            using var document = WordprocessingDocument.Open(
                new MemoryStream(projected.DocxBytes), false);
            var styleNode = Assert.Single(document.MainDocumentPart!
                .StyleDefinitionsPart!.Styles!.Elements<Style>(), x =>
                x.StyleName?.Val?.Value == "Mirrored body");
            if (expectExplicit)
                Assert.Equal(value, styleNode.StyleParagraphProperties!
                    .TextAlignment!.Val!.Value);
            else
                Assert.Null(styleNode.StyleParagraphProperties?.TextAlignment);
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordPageRenderClose(source.ToArray(), generated, 0.065, 1);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.065, 2);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-text-alignment-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        var nativePath = Path.Combine(directory, "native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    Assert.Equal(alignmentCode, (int)document.Styles
                        .Item("Mirrored body").ParagraphFormat.BaseLineAlignment);
                    Assert.Equal(alignmentCode, (int)document.Paragraphs.Item(1)
                        .Range.ParagraphFormat.BaseLineAlignment);
                    Assert.Equal(alignmentCode, (int)document.Sections.Item(1)
                        .Headers.Item(1).Range.Paragraphs.Item(1).Range
                        .ParagraphFormat.BaseLineAlignment);
                    Assert.Equal(alignmentCode, (int)document.Sections.Item(1)
                        .Footers.Item(1).Range.Paragraphs.Item(1).Range
                        .ParagraphFormat.BaseLineAlignment);
                    if (path == sourcePath) document.SaveAs2(nativePath, 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(nativePath), alignmentCode != 4);
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
            Directory.Delete(directory);
        }
    }

    [Fact]
    public void AutomaticHyphenationChangesWordLineLayoutAfterDocRoundTrip()
    {
        var fixture = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "..", "..", "..", "..", "DocxportNet.Tests", "Fixtures",
            "Doc", "WordMirrorIndentsAllStories.docx"));
        using var source = new MemoryStream();
        source.Write(File.ReadAllBytes(fixture));
        using (var document = WordprocessingDocument.Open(source, true))
        {
            var main = document.MainDocumentPart!;
            var settings = main.DocumentSettingsPart ??
                main.AddNewPart<DocumentSettingsPart>();
            settings.Settings ??= new Settings();
            settings.Settings.AddChild(new AutoHyphenation(), true);
            settings.Settings.AddChild(new DoNotHyphenateCaps(), true);
            settings.Settings.Save();
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleId?.Value == "MirroredBody");
            style.StyleParagraphProperties!.AddChild(new SuppressAutoHyphens(), true);
            style.StyleParagraphProperties.GetFirstChild<Indentation>()!.Right = "5040";
            style.StyleParagraphProperties.GetFirstChild<MirrorIndents>()?.Remove();
            main.StyleDefinitionsPart.Styles.Save();
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            const string words = "Internationalization internationalization " +
                "internationalization internationalization " +
                "internationalization internationalization " +
                "internationalization internationalization";
            foreach (var paragraph in body.Take(2))
                paragraph.Descendants<Text>().First().Text = words;
            body[2].Descendants<Text>().First().Text = words.ToUpperInvariant();
            body[1].ParagraphProperties!.AddChild(
                new SuppressAutoHyphens { Val = false }, true);
            body[2].ParagraphProperties!.AddChild(
                new SuppressAutoHyphens { Val = false }, true);
            body[1].ParagraphProperties.GetFirstChild<MirrorIndents>()?.Remove();
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        using (var index = new DocTextIndexWalker().Index(new MemoryStream(generated)))
            Assert.True(index.AutoHyphenation);
        var projected = DxpDocToDocx.Project(generated);
        Assert.Empty(projected.Coverage.OmittedCharacters);
        using (var document = WordprocessingDocument.Open(
            new MemoryStream(projected.DocxBytes), false))
            Assert.Empty(new OpenXmlValidator().Validate(document));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-visible-hyphenation-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source.docx");
        var generatedPath = Path.Combine(directory, "generated.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            var layouts = new List<(int Suppressed, int Enabled, int Capitals)>();
            foreach (var path in new[] { sourcePath, generatedPath })
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    document.Repaginate();
                    layouts.Add((
                        (int)document.Paragraphs.Item(1).Range.ComputeStatistics(1),
                        (int)document.Paragraphs.Item(2).Range.ComputeStatistics(1),
                        (int)document.Paragraphs.Item(3).Range.ComputeStatistics(1)));
                    Assert.False((bool)document.HyphenateCaps);
                    document.HyphenateCaps = true;
                    document.Repaginate();
                    var capitalLinesWithHyphenation = (int)document.Paragraphs
                        .Item(3).Range.ComputeStatistics(1);
                    Assert.True(layouts[^1].Capitals > capitalLinesWithHyphenation,
                        $"Capital line counts: disabled={layouts[^1].Capitals}, " +
                        $"enabled={capitalLinesWithHyphenation}");
                }
                finally { document.Close(false); }
            }
            Assert.True(layouts[0].Suppressed > layouts[0].Enabled,
                $"Source line counts: {layouts[0]}");
            Assert.Equal(layouts[0], layouts[1]);
        }
        finally
        {
            word.Quit(false);
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            Directory.Delete(directory);
        }
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
        {
            AssertWordFirstPageRenderClose(source.ToArray(), generated, 0.09);
            AssertWordPageRenderClose(source.ToArray(), generated, 0.09, 2);
        }
    }

    [Fact]
    public void MirrorIndentsStyleAndDirectResetSurviveBothDocRoutes()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new Style(
                new StyleName { Val = "Mirrored body" },
                new StyleParagraphProperties(
                    new Indentation { Left = "720", Right = "1440" },
                    new MirrorIndents()))
            { Type = StyleValues.Paragraph, StyleId = "MirroredBody",
                CustomStyle = true });
            styles.Styles.Save();
            static Paragraph Styled(string text, bool reset = false,
                bool nextPage = false)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = "MirroredBody" });
                if (nextPage) properties.Append(new PageBreakBefore());
                if (reset) properties.Append(new MirrorIndents { Val = false });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Mirrored header"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Mirrored footer"));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                Styled("Mirrored body"), Styled("Reset body", true),
                Styled("Second-page mirrored body", nextPage: true),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        void AssertProjection(byte[] binary)
        {
            using (var input = new MemoryStream(binary))
            using (var index = new DocTextIndexWalker().Index(input))
            {
                var style = Assert.Single(index.StyleDefinitions, x =>
                    x.Name == "Mirrored body");
                Assert.True(style.ParagraphFormatting?.MirrorIndents);
                Assert.Contains(index.ParagraphStyles, x =>
                    x.Formatting?.MirrorIndents == false);
            }
            var result = DxpDocToDocx.Project(binary);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var document = WordprocessingDocument.Open(stream, false);
            var main = document.MainDocumentPart!;
            var styleNode = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Mirrored body");
            Assert.True(styleNode.StyleParagraphProperties!.MirrorIndents!.Val!.Value);
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.Equal(3, body.Length);
            Assert.False(body[1].ParagraphProperties!.MirrorIndents!.Val!.Value);
            Assert.Equal("Second-page mirrored body", body[2].InnerText);
            Assert.Contains(main.HeaderParts.SelectMany(part =>
                part.Header!.Elements<Paragraph>()), paragraph =>
                paragraph.InnerText == "Mirrored header");
            Assert.Contains(main.FooterParts.SelectMany(part =>
                part.Footer!.Elements<Paragraph>()), paragraph =>
                paragraph.InnerText == "Mirrored footer");
            Assert.Empty(new OpenXmlValidator().Validate(document));
        }
        var generated = DxpDocExport.Export(source.ToArray());
        AssertProjection(generated);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(generated).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") == "1")
            AssertWordPageRenderClose(source.ToArray(), generated, 0.04, 2);
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") != "1") return;
        var temporary = Path.Combine(Path.GetTempPath(),
            $"docxport-mirror-indents-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporary);
        var paths = new[]
        {
            Path.Combine(temporary, "source.docx"),
            Path.Combine(temporary, "generated.doc"),
            Path.Combine(temporary, "native.doc")
        };
        File.WriteAllBytes(paths[0], source.ToArray());
        File.WriteAllBytes(paths[1], generated);
        dynamic word = Activator.CreateInstance(
            Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var path in paths)
            {
                dynamic document = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try
                {
                    Assert.NotEqual(0, (int)document.Styles.Item("Mirrored body")
                        .ParagraphFormat.MirrorIndents);
                    Assert.Equal(0, (int)document.Paragraphs.Item(2)
                        .Range.ParagraphFormat.MirrorIndents);
                    Assert.NotEqual(0, (int)document.Paragraphs.Item(3)
                        .Range.ParagraphFormat.MirrorIndents);
                    Assert.NotEqual(0, (int)document.Sections.Item(1)
                        .Headers.Item(1).Range.Paragraphs.Item(1)
                        .Range.ParagraphFormat.MirrorIndents);
                    Assert.NotEqual(0, (int)document.Sections.Item(1)
                        .Footers.Item(1).Range.Paragraphs.Item(1)
                        .Range.ParagraphFormat.MirrorIndents);
                    if (path == paths[0]) document.SaveAs2(paths[2], 0);
                }
                finally { document.Close(false); }
            }
            AssertProjection(File.ReadAllBytes(paths[2]));
        }
        finally
        {
            word.Quit(false);
            foreach (var path in paths) File.Delete(path);
            Directory.Delete(temporary);
        }
    }

    [Fact]
    public void ContextualSpacingStyleAndDirectResetRenderInAllStories()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(
                new RunPropertiesDefault(new RunPropertiesBaseStyle(
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new FontSize { Val = "24" })),
                new ParagraphPropertiesDefault(new ParagraphPropertiesBaseStyle(
                    new SpacingBetweenLines { Before = "0", After = "0",
                        Line = "280", LineRule = LineSpacingRuleValues.Exact }))),
                new Style(new StyleName { Val = "Contextual body" },
                    new StyleParagraphProperties(new ContextualSpacing(),
                        new SpacingBetweenLines { Before = "240", After = "240" }))
                { Type = StyleValues.Paragraph, StyleId = "ContextualBody" });
            styles.Styles.Save();
            static Paragraph Styled(string text, bool reset = false)
            {
                var properties = new ParagraphProperties(
                    new ParagraphStyleId { Val = "ContextualBody" });
                if (reset) properties.AppendChild(new ContextualSpacing { Val = false });
                return new Paragraph(properties, new Run(new Text(text)));
            }
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(Styled("Header first"), Styled("Header second"));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(Styled("Footer first"), Styled("Footer second"));
            footer.Footer.Save();
            main.Document = new Document(new Body(
                Styled("Body first"), Styled("Body second"),
                Styled("Body reset", true), Styled("Body fourth"),
                new SectionProperties(
                    new HeaderReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(header) },
                    new FooterReference { Type = HeaderFooterValues.Default,
                        Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }
        void AssertProjection(byte[] binary)
        {
            var result = DxpDocToDocx.Project(binary);
            Assert.Empty(result.Coverage.OmittedCharacters);
            using var stream = new MemoryStream(result.DocxBytes);
            using var projected = WordprocessingDocument.Open(stream, false);
            var main = projected.MainDocumentPart!;
            var style = Assert.Single(main.StyleDefinitionsPart!.Styles!
                .Elements<Style>(), x => x.StyleName?.Val?.Value == "Contextual body");
            Assert.True(style.StyleParagraphProperties!.ContextualSpacing!.Val!.Value);
            var body = main.Document.Body!.Elements<Paragraph>().ToArray();
            Assert.Equal(4, body.Length);
            Assert.Equal("Body reset", body[2].InnerText);
            Assert.False(body[2].ParagraphProperties!.ContextualSpacing!.Val!.Value);
            Assert.Equal(2, main.HeaderParts.Single().Header!.Elements<Paragraph>().Count());
            Assert.Equal(2, main.FooterParts.Single().Footer!.Elements<Paragraph>().Count());
            Assert.Empty(new OpenXmlValidator().Validate(projected));
        }
        var binary = DxpDocExport.Export(source.ToArray());
        AssertProjection(binary);
        AssertProjection(DxpDocExport.Export(DxpDocToDocx.Project(binary).DocxBytes));
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD_RENDER") != "1")
            return;
        AssertWordPageRenderClose(source.ToArray(), binary, 0.04, 1);
        var sourcePath = Path.Combine(Path.GetTempPath(),
            $"docxport-contextual-spacing-{Guid.NewGuid():N}.docx");
        var generatedPath = Path.ChangeExtension(sourcePath, ".generated.doc");
        var nativePath = Path.ChangeExtension(sourcePath, ".native.doc");
        File.WriteAllBytes(sourcePath, source.ToArray());
        File.WriteAllBytes(generatedPath, binary);
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        dynamic? opened = null;
        try
        {
            foreach (var path in new[] { sourcePath, generatedPath, nativePath })
            {
                opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                Assert.True(Convert.ToBoolean(opened.Styles.Item("Contextual body")
                    .NoSpaceBetweenParagraphsOfSameStyle));
                opened.Repaginate();
                var positions = Enumerable.Range(1, 4).Select(i => Convert.ToDouble(
                    opened.Paragraphs.Item(i).Range.Information(6))).ToArray();
                Assert.All(positions, position => Assert.True(position >= 0));
                Assert.True(positions[3] - positions[2] >
                    positions[1] - positions[0] + 8,
                    $"{Path.GetFileName(path)}: {string.Join(", ", positions)}");
                if (path == sourcePath) opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
            }
            var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
            AssertProjection(File.ReadAllBytes(nativePath));
            AssertWordPageRenderClose(source.ToArray(), nativeProjection.DocxBytes,
                0.04, 1, ".docx");
        }
        finally
        {
            if (opened != null) opened.Close(false);
            word.Quit();
            File.Delete(sourcePath);
            File.Delete(generatedPath);
            File.Delete(nativePath);
        }
    }

    [Fact]
    public void DocRoundTripPreservesCharacterStyleAndDirectOverride()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(
                new Style(new StyleName { Val = "Accent" },
                    new StyleRunProperties(new RunFonts { Ascii = "Cambria",
                        HighAnsi = "Cambria", EastAsia = "MS Mincho" },
                        new Bold(), new SmallCaps(),
                        new Vanish { Val = false }, new Color { Val = "123456" },
                        new Spacing { Val = 40 },
                        new FontSize { Val = "26" },
                        new Underline { Val = UnderlineValues.Single },
                        new VerticalTextAlignment { Val = VerticalPositionValues.Baseline },
                        new Languages { Val = "en-US" }))
                { Type = StyleValues.Character, StyleId = "Accent" },
                new Style(new StyleName { Val = "Accent Strong" },
                    new BasedOn { Val = "Accent" },
                    new StyleRunProperties(new Italic(), new Caps { Val = false },
                        new Strike()))
                { Type = StyleValues.Character, StyleId = "AccentStrong" });
            styles.Styles.Save();
            var header = main.AddNewPart<HeaderPart>();
            header.Header = new Header(new Paragraph(new Run(
                new RunProperties(new RunStyle { Val = "Accent" }),
                new Text("Header"))));
            header.Header.Save();
            var footer = main.AddNewPart<FooterPart>();
            footer.Footer = new Footer(new Paragraph(new Run(
                new RunProperties(new RunFonts { Ascii = "Courier New" },
                    new Caps(), new SmallCaps { Val = false },
                    new Vanish(), new Color { Val = "auto" },
                    new Spacing { Val = 20 },
                    new Highlight { Val = HighlightColorValues.None },
                    new Underline { Val = UnderlineValues.Dotted },
                    new VerticalTextAlignment { Val = VerticalPositionValues.Subscript },
                    new Languages { Val = "fr-FR" }),
                new Text("Footer"))));
            footer.Footer.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(
                new RunProperties(new RunStyle { Val = "AccentStrong" },
                    new RunFonts { Ascii = "Arial", HighAnsi = "Arial" },
                    new Bold { Val = false }, new Strike { Val = false },
                    new Color { Val = "AA22CC" },
                    new Spacing { Val = -20 },
                    new Highlight { Val = HighlightColorValues.Red },
                    new Underline { Val = UnderlineValues.Double },
                    new VerticalTextAlignment { Val = VerticalPositionValues.Superscript },
                    new Languages { Val = "fr-CA", EastAsia = "ja-JP", Bidi = "ar-SA" }),
                new Text("Styled"))),
                new SectionProperties(new HeaderReference
                { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(header) },
                    new FooterReference
                    { Type = HeaderFooterValues.Default, Id = main.GetIdOfPart(footer) })));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        if (Environment.GetEnvironmentVariable("DOCXPORT_VERIFY_WORD") == "1")
        {
            if (!OperatingSystem.IsWindows())
                throw new PlatformNotSupportedException("Word automation requires Windows.");
            var path = Path.Combine(Path.GetTempPath(),
                "docxport-character-style-" + Guid.NewGuid().ToString("N") + ".doc");
            var sourcePath = Path.ChangeExtension(path, ".source.docx");
            var nativePath = Path.ChangeExtension(path, ".native.doc");
            File.WriteAllBytes(path, bytes);
            File.WriteAllBytes(sourcePath, source.ToArray());
            dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
            dynamic? opened = null;
            try
            {
                word.Visible = false;
                word.DisplayAlerts = 0;
                opened = word.Documents.Open(path, false, true);
                Assert.Equal(0, (int)opened.Paragraphs.Item(1).Range.Font.Bold);
                Assert.Equal(-1, (int)opened.Paragraphs.Item(1).Range.Font.Italic);
                Assert.Equal(-1, (int)opened.Sections.Item(1).Headers.Item(1)
                    .Range.Font.Bold);
                Assert.Equal(-1, (int)opened.Sections.Item(1).Footers.Item(1)
                    .Range.Font.Hidden);
                Assert.Equal(-1f, (float)opened.Paragraphs.Item(1).Range.Font.Spacing);
                Assert.Equal(3084, (int)opened.Paragraphs.Item(1).Range.LanguageID);
                opened.Close(false);
                opened = null;
                opened = word.Documents.Open(sourcePath, false, true);
                opened.SaveAs2(nativePath, 0);
                opened.Close(false);
                opened = null;
                using (var input = new MemoryStream(File.ReadAllBytes(nativePath)))
                using (var index = new DocTextIndexWalker().Index(input))
                {
                    var atoms = index.ReadStory("Main").Text.Paragraphs
                        .SelectMany(p => p.Atoms).ToArray();
                    Console.WriteLine("LEGACY ATOMS " + string.Join(";", atoms.Select(a =>
                        $"{a.CpStart}:{a.Kind}:{string.Join(",", a.Text.Select(c => ((int)c).ToString("X2")))}")));
                    Console.WriteLine("LEGACY FORMATS " + string.Join(";", index.CharacterFormatting
                        .Where(x => x.CpStart < 35).Select(x =>
                            $"{x.CpStart}-{x.CpEnd}:special={x.Formatting.Special}")));
                }                var nativeProjection = DxpDocToDocx.Project(File.ReadAllBytes(nativePath));
                using var nativeStream = new MemoryStream(nativeProjection.DocxBytes);
                using var native = WordprocessingDocument.Open(nativeStream, false);
                var nativeRun = native.MainDocumentPart!.Document!.Body!
                    .Elements<Paragraph>().First().Elements<Run>().First();
                Assert.Equal(-20, nativeRun.RunProperties?.Spacing?.Val?.Value);
                Assert.Equal("fr-CA", nativeRun.RunProperties?.Languages?.Val?.Value);
                Assert.Empty(new OpenXmlValidator().Validate(native));
            }
            finally
            {
                if (opened != null) opened.Close(false);
                word.Quit();
                File.Delete(path);
                File.Delete(sourcePath);
                if (File.Exists(nativePath)) File.Delete(nativePath);
            }
        }
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(6, index.Fonts.Count);
            Assert.Equal("Aptos", index.Fonts[0].Name);
            Assert.Contains(index.Fonts, x => x.Name == "Cordia New");
            Assert.Contains(index.Fonts, x => x.Name == "MS Mincho");
            var accent = Assert.Single(index.StyleDefinitions, x => x.Name == "Accent");
            var strong = Assert.Single(index.StyleDefinitions, x => x.Name == "Accent Strong");
            Assert.Equal(accent.Index, strong.BasedOnIndex);
            Assert.True(accent.CharacterFormatting.SmallCaps);
            Assert.False(accent.CharacterFormatting.Hidden);
            Assert.Equal((byte)1, accent.CharacterFormatting.UnderlineCode);
            Assert.Equal(0x00563412u, accent.CharacterFormatting.ColorRef);
            Assert.Equal("Cambria", accent.CharacterFormatting.AsciiFontName);
            Assert.Equal("Cambria", accent.CharacterFormatting.HighAnsiFontName);
            Assert.Equal("MS Mincho", accent.CharacterFormatting.EastAsiaFontName);
            Assert.Equal((byte)0, accent.CharacterFormatting.ScriptCode);
            Assert.Equal((short)40, accent.CharacterFormatting.CharacterSpacingTwips);
            Assert.Equal((ushort)1033, accent.CharacterFormatting.LanguageId);
            Assert.True(strong.CharacterFormatting.Strike);
            Assert.False(strong.CharacterFormatting.Caps);
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == 0 && x.Formatting.CharacterStyleIndex == strong.Index &&
                x.Formatting.Bold == false && x.Formatting.Strike == false &&
                x.Formatting.UnderlineCode == 3 &&
                x.Formatting.ColorRef == 0x00CC22AAu &&
                x.Formatting.HighlightCode == 6 && x.Formatting.ScriptCode == 1 &&
                x.Formatting.AsciiFontName == "Arial" &&
                x.Formatting.HighAnsiFontName == "Arial");
            Assert.Contains(index.CharacterFormatting, x => x.CpStart == 0 &&
                x.Formatting.CharacterSpacingTwips == -20 &&
                x.Formatting.LanguageId == 3084 &&
                x.Formatting.EastAsiaLanguageId == 1041 &&
                x.Formatting.ComplexScriptLanguageId == 1025);
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == index.HeaderStories[7].CpStart &&
                x.Formatting.CharacterStyleIndex == accent.Index);
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == index.HeaderStories[9].CpStart &&
                x.Formatting.Caps == true && x.Formatting.SmallCaps == false &&
                x.Formatting.Hidden == true && x.Formatting.UnderlineCode == 4 &&
                x.Formatting.ColorRef == 0xFF000000u &&
                x.Formatting.HighlightCode == 0 && x.Formatting.ScriptCode == 2 &&
                x.Formatting.AsciiFontName == "Courier New");
            Assert.Contains(index.CharacterFormatting, x =>
                x.CpStart == index.HeaderStories[9].CpStart &&
                x.Formatting.CharacterSpacingTwips == 20 &&
                x.Formatting.LanguageId == 1036);
        }

        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var main2 = projected.MainDocumentPart!;
        Assert.Equal("Aptos", main2.StyleDefinitionsPart!.Styles!
            .Elements<DocDefaults>().Single().Descendants<RunFonts>().Single().Ascii!.Value);
        var styles2 = main2.StyleDefinitionsPart!.Styles!.Elements<Style>().ToArray();
        var accent2 = Assert.Single(styles2, x => x.StyleName?.Val?.Value == "Accent");
        var strong2 = Assert.Single(styles2, x => x.StyleName?.Val?.Value == "Accent Strong");
        Assert.Equal(accent2.StyleId!.Value, strong2.BasedOn!.Val!.Value);
        Assert.True(accent2.StyleRunProperties!.SmallCaps!.Val!.Value);
        Assert.False(accent2.StyleRunProperties.Vanish!.Val!.Value);
        Assert.Equal(UnderlineValues.Single, accent2.StyleRunProperties.Underline!.Val!.Value);
        Assert.Equal("123456", accent2.StyleRunProperties.Color!.Val!.Value);
        Assert.Equal("Cambria", accent2.StyleRunProperties.RunFonts!.Ascii!.Value);
        Assert.Equal("MS Mincho", accent2.StyleRunProperties.RunFonts.EastAsia!.Value);
        Assert.Equal(VerticalPositionValues.Baseline,
            accent2.StyleRunProperties.VerticalTextAlignment!.Val!.Value);
        Assert.Equal(40, accent2.StyleRunProperties.Spacing!.Val!.Value);
        Assert.Equal("en-US", accent2.StyleRunProperties.Languages!.Val!.Value);
        Assert.True(strong2.StyleRunProperties!.Strike!.Val!.Value);
        Assert.False(strong2.StyleRunProperties.Caps!.Val!.Value);
        var bodyRun = main2.Document!.Body!.Elements<Paragraph>().Single().Elements<Run>().Single();
        Assert.Equal(strong2.StyleId!.Value, bodyRun.RunProperties!.RunStyle!.Val!.Value);
        Assert.False(bodyRun.RunProperties.Bold!.Val!.Value);
        Assert.False(bodyRun.RunProperties.Strike!.Val!.Value);
        Assert.Equal(UnderlineValues.Double, bodyRun.RunProperties.Underline!.Val!.Value);
        Assert.Equal("AA22CC", bodyRun.RunProperties.Color!.Val!.Value);
        Assert.Equal("Arial", bodyRun.RunProperties.RunFonts!.Ascii!.Value);
        Assert.Equal(HighlightColorValues.Red, bodyRun.RunProperties.Highlight!.Val!.Value);
        Assert.Equal(VerticalPositionValues.Superscript,
            bodyRun.RunProperties.VerticalTextAlignment!.Val!.Value);
        Assert.Equal(-20, bodyRun.RunProperties.Spacing!.Val!.Value);
        Assert.Equal("fr-CA", bodyRun.RunProperties.Languages!.Val!.Value);
        Assert.Equal("ja-JP", bodyRun.RunProperties.Languages.EastAsia!.Value);
        Assert.Equal("ar-SA", bodyRun.RunProperties.Languages.Bidi!.Value);
        var headerRun = main2.HeaderParts.Single().Header!.Elements<Paragraph>().Single()
            .Elements<Run>().Single();
        Assert.Equal(accent2.StyleId!.Value, headerRun.RunProperties!.RunStyle!.Val!.Value);
        var footerRun = main2.FooterParts.Single().Footer!.Elements<Paragraph>().Single()
            .Elements<Run>().Single();
        Assert.True(footerRun.RunProperties!.Caps!.Val!.Value);
        Assert.False(footerRun.RunProperties.SmallCaps!.Val!.Value);
        Assert.True(footerRun.RunProperties.Vanish!.Val!.Value);
        Assert.Equal(UnderlineValues.Dotted, footerRun.RunProperties.Underline!.Val!.Value);
        Assert.Equal("auto", footerRun.RunProperties.Color!.Val!.Value);
        Assert.Equal("Courier New", footerRun.RunProperties.RunFonts!.Ascii!.Value);
        Assert.Equal(HighlightColorValues.None, footerRun.RunProperties.Highlight!.Val!.Value);
        Assert.Equal(VerticalPositionValues.Subscript,
            footerRun.RunProperties.VerticalTextAlignment!.Val!.Value);
        Assert.Equal(20, footerRun.RunProperties.Spacing!.Val!.Value);
        Assert.Equal("fr-FR", footerRun.RunProperties.Languages!.Val!.Value);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void DocRoundTripPreservesExplicitDefaultRunFonts()
    {
        using var source = new MemoryStream();
        using (var document = WordprocessingDocument.Create(source,
            DocumentFormat.OpenXml.WordprocessingDocumentType.Document, true))
        {
            var main = document.AddMainDocumentPart();
            var styles = main.AddNewPart<StyleDefinitionsPart>();
            styles.Styles = new Styles(new DocDefaults(new RunPropertiesDefault(
                new RunPropertiesBaseStyle(new RunFonts
                {
                    Ascii = "Garamond", HighAnsi = "Garamond", EastAsia = "MS Mincho"
                }))));
            styles.Styles.Save();
            main.Document = new Document(new Body(new Paragraph(new Run(new Text("Default font")))));
            main.Document.Save();
        }

        var bytes = DxpDocExport.Export(source.ToArray());
        using (var input = new MemoryStream(bytes))
        using (var index = new DocTextIndexWalker().Index(input))
        {
            Assert.Equal(new[] { "Garamond", "MS Mincho" },
                index.Fonts.Select(x => x.Name));
            Assert.Equal("Garamond", index.DefaultCharacterFormatting.AsciiFontName);
            Assert.Equal("Garamond", index.DefaultCharacterFormatting.HighAnsiFontName);
            Assert.Equal("MS Mincho", index.DefaultCharacterFormatting.EastAsiaFontName);
            var normal = Assert.Single(index.StyleDefinitions);
            Assert.Equal("Normal", normal.Name);
            Assert.Equal((ushort)160, normal.ParagraphFormatting?.AfterTwips);
        }
        var projection = DxpDocToDocx.Project(bytes);
        using var stream = new MemoryStream(projection.DocxBytes);
        using var projected = WordprocessingDocument.Open(stream, false);
        var fonts = projected.MainDocumentPart!.StyleDefinitionsPart!.Styles!
            .Elements<DocDefaults>().Single().Descendants<RunFonts>().Single();
        Assert.Equal("Garamond", fonts.Ascii!.Value);
        Assert.Equal("Garamond", fonts.HighAnsi!.Value);
        Assert.Equal("MS Mincho", fonts.EastAsia!.Value);
        Assert.Equal("Default font", projected.MainDocumentPart.Document!.Body!
            .Elements<Paragraph>().Single().InnerText);
        Assert.Empty(new OpenXmlValidator().Validate(projected));
    }

    [Fact]
    public void ExportToFilesAcceptsBinaryDocPath()
    {
        using var input = CreateDocWithPieces(allMain: true);
        var inputPath = Path.Combine(Path.GetTempPath(), $"doc-merge-{Guid.NewGuid():N}.doc");
        var outputPath = Path.ChangeExtension(inputPath, ".txt");
        try
        {
            File.WriteAllBytes(inputPath, input.ToArray());
