    private sealed class NamedSkippingVisitor(string skipName) : IDocStructureVisitor
    {
        public List<string> Names { get; } = new();
        public IDisposable? Enter(DocStructureNode node, int depth)
        {
            Names.Add(node.Name);
            return node.Name == skipName ? null : DocxportNet.Core.DxpDisposable.Empty;
        }
    }

    private sealed class ScopeVisitor : IDocStructureVisitor
    {
        public List<string> Events { get; } = new();

        public IDisposable Enter(DocStructureNode node, int depth)
        {
            if (node.Name == "WordDocument")
            {
                Events.Add("enter:WordDocument");
                return DocxportNet.Core.DxpDisposable.Create(() => Events.Add("close:WordDocument"));
            }
            if (node.Kind == "FIB") throw new InvalidOperationException("Stop inside WordDocument");
            if (node.Name == "DOC")
            {
                Events.Add("enter:DOC");
                return DocxportNet.Core.DxpDisposable.Create(() => Events.Add("close:DOC"));
            }
            return DocxportNet.Core.DxpDisposable.Empty;
        }
    }

    private static void AssertGeneratedDocCellFlags(byte[] bytes,
        ushort firstFlags, ushort secondFlags)
    {
        using var input = new MemoryStream(bytes);
        using var structure = new DocStructureWalker().Accept(input,
            new DocStructurePrintVisitor(TextWriter.Null));
        static IEnumerable<DocStructureNode> Descendants(DocStructureNode node) =>
            node.Children.SelectMany(child => new[] { child }.Concat(Descendants(child)));
        var cells = Descendants(structure.Root).Where(x => x.Kind == "TC80")
            .ToArray();
        Assert.Equal(2, cells.Length);
        Assert.Equal(firstFlags, BinaryPrimitives.ReadUInt16LittleEndian(
            structure.ReadRange(cells[0].StreamName!, cells[0].Offset!.Value, 2)));
        Assert.Equal(secondFlags, BinaryPrimitives.ReadUInt16LittleEndian(
            structure.ReadRange(cells[1].StreamName!, cells[1].Offset!.Value, 2)));
    }

    private static double AssertWordFirstPageRenderClose(byte[] sourceDocx,
        byte[] generatedDoc, double maximumError)
        => AssertWordPageRenderClose(sourceDocx, generatedDoc, maximumError, 1);

    private static double AssertWordPageRenderClose(byte[] sourceDocx,
        byte[] generatedDoc, double maximumError, int pageNumber,
        string generatedExtension = ".doc", string sourceExtension = ".docx")
    {
        var directory = Path.Combine(Path.GetTempPath(),
            $"docxport-theme-alias-render-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var sourcePath = Path.Combine(directory, "source" + sourceExtension);
        var generatedPath = Path.Combine(directory, "generated" + generatedExtension);
        File.WriteAllBytes(sourcePath, sourceDocx);
        File.WriteAllBytes(generatedPath, generatedDoc);
        var ghostscript = Environment.GetEnvironmentVariable("DOCXPORT_GHOSTSCRIPT_PATH") ??
            @"C:\Program Files\gs\gs10.06.0\bin\gswin64c.exe";
        var imageMagick = Environment.GetEnvironmentVariable("DOCXPORT_IMAGEMAGICK_PATH") ??
            @"C:\Program Files\ImageMagick-7.1.2-Q16-HDRI\magick.exe";
        static string Run(string executable, params string[] arguments)
        {
            var start = new ProcessStartInfo(executable)
            {
                UseShellExecute = false, CreateNoWindow = true,
                RedirectStandardOutput = true, RedirectStandardError = true
            };
            foreach (var argument in arguments) start.ArgumentList.Add(argument);
            using var process = Process.Start(start)!;
            if (!process.WaitForExit(30000))
            {
                process.Kill();
                throw new TimeoutException($"Rendering timed out: {executable}");
            }
            var output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
            if (process.ExitCode != 0 && !Path.GetFileName(executable)
                .StartsWith("magick", StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException(output);
            return output;
        }
        dynamic word = Activator.CreateInstance(Type.GetTypeFromProgID("Word.Application")!)!;
        word.Visible = false;
        try
        {
            foreach (var (path, name) in new[] { (sourcePath, "source"),
                (generatedPath, "generated") })
            {
                dynamic opened = word.Documents.Open(path, ReadOnly: true,
                    AddToRecentFiles: false);
                try { opened.ExportAsFixedFormat(Path.Combine(directory, name + ".pdf"), 17); }
                finally { opened.Close(false); }
                Run(ghostscript, "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=png16m",
                    "-r96", "-dFirstPage=" + pageNumber, "-dLastPage=" + pageNumber,
                    "-sOutputFile=" + Path.Combine(directory, name + ".png"),
                    Path.Combine(directory, name + ".pdf"));
            }
            var metric = Run(imageMagick, "compare", "-metric", "RMSE",
                Path.Combine(directory, "source.png"),
                Path.Combine(directory, "generated.png"), "null:");
            var match = Regex.Match(metric, @"\(([0-9.]+)\)");
            Assert.True(match.Success, "ImageMagick did not report normalized RMSE: " + metric);
            var error = double.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture);
            Assert.True(error < maximumError,
                $"Theme alias page {pageNumber} renders RMSE {error}; files: {directory}");
            return error;
        }
        finally
        {
            word.Quit();
            if (Environment.GetEnvironmentVariable("DOCXPORT_KEEP_IMAGE_RENDER") != "1")
                Directory.Delete(directory, true);
        }
    }

    private static MemoryStream CreateDoc(bool tableOne, bool badEnvelopeOffset = false)
    {
        var output = new MemoryStream();
        using (var root = RootStorage.Create(output, OpenMcdf.Version.V3, StorageModeFlags.LeaveOpen))
        {
            var word = new byte[1200];
            BinaryPrimitives.WriteUInt16LittleEndian(word, 0xA5EC);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(2), 0x00C1);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(10), tableOne ? (ushort)0x0200 : (ushort)0);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(32), 14);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(62), 22);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(152), 108);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 31 * 8), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 31 * 8 + 4), 600);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 97 * 8), badEnvelopeOffset ? 10000u : 600u);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 97 * 8 + 4), 20);
            using (var stream = root.CreateStream("WordDocument")) stream.Write(word);
            var table = new byte[620];
            table[504] = 2;
            new Guid("0006F01A-0000-0000-C000-000000000046").ToByteArray().CopyTo(table, 600);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(616), 8);
            using (var stream = root.CreateStream(tableOne ? "1Table" : "0Table")) stream.Write(table);
            using (var stream = root.CreateStream("Unrelated")) stream.WriteByte(42);
            using (var stream = root.CreateStream("\u0005SummaryInformation")) stream.WriteByte(1);
        }
        output.Position = 0;
        return output;
    }

    private static MemoryStream CreateDocWithPieces(bool badClxTag = false, bool allMain = false,
        bool reverseStorage = false, bool splitParagraph = false, bool specialControls = false)
    {
        var output = new MemoryStream();
        using (var root = RootStorage.Create(output, OpenMcdf.Version.V3, StorageModeFlags.LeaveOpen))
        {
            var word = new byte[1200];
            BinaryPrimitives.WriteUInt16LittleEndian(word, 0xA5EC);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(2), 0x00C1);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(10), 0x0200);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(32), 14);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(62), 22);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(76), allMain ? 7u : 5u);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(80), allMain ? 0u : 1u);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(152), 108);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 31 * 8 + 4), 600);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 33 * 8), 600);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 33 * 8 + 4), 38);
            (specialControls
                ? new byte[] { (byte)'A', 0x09, 0x0B, 0x07, 0x0C }
                : new byte[] { (byte)'H', (byte)'e', (byte)'l', 0x97,
                    splitParagraph ? (byte)' ' : (byte)0x0D }).CopyTo(word, 1000);
            var secondTextOffset = reverseStorage ? 900 : 1010;
            System.Text.Encoding.Unicode.GetBytes(specialControls ? "\u0013\r" : "Ω\r")
                .CopyTo(word, secondTextOffset);
            using (var stream = root.CreateStream("WordDocument")) stream.Write(word);
            var table = new byte[638];
            table[600] = badClxTag ? (byte)0x7F : (byte)1;
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(601), 2);
            table[605] = 2;
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(606), 28);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(614), 5);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(618), 7);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(624), 0x40000000u | 2000u);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(632), (uint)secondTextOffset);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(636), 1);
            using (var stream = root.CreateStream("1Table")) stream.Write(table);
        }
        output.Position = 0;
        return output;
    }

    private static MemoryStream CreateDocWithSections(bool badSectionTable = false, byte[]? sectionModifiers = null)
    {
        var output = new MemoryStream();
        using (var root = RootStorage.Create(output, OpenMcdf.Version.V3, StorageModeFlags.LeaveOpen))
        {
            var word = new byte[1200];
            BinaryPrimitives.WriteUInt16LittleEndian(word, 0xA5EC);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(2), 0x00C1);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(10), 0x0200);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(32), 14);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(62), 22);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(76), 10);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(152), 108);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 6 * 8), 500);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 6 * 8 + 4), badSectionTable ? 35u : 36u);
            var sectionOffset = sectionModifiers == null ? 900 : 1100;
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(sectionOffset),
                checked((ushort)(sectionModifiers?.Length ?? 4)));
            if (sectionModifiers != null) sectionModifiers.CopyTo(word.AsSpan(sectionOffset + 2));
            using (var stream = root.CreateStream("WordDocument")) stream.Write(word);
            var table = new byte[600];
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(504), 5);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(508), 10);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(514), (uint)sectionOffset);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(526), uint.MaxValue);
            using (var stream = root.CreateStream("1Table")) stream.Write(table);
        }
        output.Position = 0;
        return output;
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void WalksRemainingBoundedNavigationRecords(bool tableSelection)
    {
        using var input = CreateDocWithRemainingNavigation(tableSelection);
        using var output = new StringWriter();
        using (var xml = new DocStructureXmlVisitor(output))
        using (new DocStructureWalker().Accept(input, xml)) { }
        var document = XDocument.Parse(output.ToString());
        foreach (var kind in new[]
        {
            "Selsf", "Sty", "Afd", "Hplxsdr", "XSDR", "SDTI", "SDTT",
            "FSDAP", "MDP", "FCKS", "FCKSOLD", "Fssd", "FssUnits", "Fsnk", "IScrollType",
            "FFM", "Kul", "UFEL",
            "CTBWRAPPER", "TBDelta", "TBC", "CTB", "OfficeArtWordDrawing",
            "OfficeArtClientAnchor", "OfficeArtClientData", "OfficeArtClientTextbox"
        })
            Assert.Single(document.Descendants(kind));
        Assert.Single(document.Descendants(tableSelection ? "TableSel" : "BlockSel"));
        Assert.Equal(2, document.Descendants("Customization").Count());
        Assert.Equal(2, document.Descendants("TIQ").Count());
        Assert.Equal(2, document.Descendants("NilPICFAndBinData").Count());
        foreach (var kind in new[] { "FFData", "FFDataBits", "HFD", "HFDBits" })
            Assert.Single(document.Descendants(kind));
    }

    [Theory]
    [InlineData(40u)]
    [InlineData(128u)]
    public void WalksEncryptedObjectHeaderWithPassword(uint keyBits)
    {
        using var encrypted = CreateEncryptedDocWithObject(keyBits);
        using var output = new StringWriter();
        using (var xml = new DocStructureXmlVisitor(output))
        using (var structure = new DocStructureWalker().Accept(encrypted, xml, "navigation-test"))
            Assert.Equal("RC4CryptoAPI", structure.Root.Attributes["sourceEncryption"]);
        var document = XDocument.Parse(output.ToString());
        Assert.Single(document.Descendants("FOBJH"));
    }

    [Fact]
    public void RejectsWrongCryptoApiPassword()
    {
        using var encrypted = CreateEncryptedDocWithObject(128);
        Assert.Throws<UnauthorizedAccessException>(() => new DocStructureWalker().Accept(encrypted,
            new DocStructurePrintVisitor(TextWriter.Null), "wrong-password"));
    }

    private static MemoryStream CreateEncryptedDocWithObject(uint keyBits)
    {
        using var plain = CreateDocWithRemainingNavigation(false);
        using var source = RootStorage.Open(plain, StorageModeFlags.LeaveOpen);
        static byte[] Read(Storage storage, string name)
        {
            using var stream = storage.OpenStream(name);
            using var copy = new MemoryStream();
            stream.CopyTo(copy);
            return copy.ToArray();
        }
        var word = Read(source, "WordDocument");
        var oldTable = Read(source, "1Table");
        var table = new byte[oldTable.Length + 128];
        Buffer.BlockCopy(oldTable, 0, table, 128, oldTable.Length);
        var data = Read(source, "Data");
        Array.Clear(data, 200, 85);
        BinaryPrimitives.WriteUInt16LittleEndian(data.AsSpan(200), 8);
        BinaryPrimitives.WriteInt32LittleEndian(data.AsSpan(204), 12);
        for (var i = 0; i < 164; i++)
        {
            var field = 154 + i * 8;
            if (BinaryPrimitives.ReadUInt32LittleEndian(word.AsSpan(field + 4)) == 0) continue;
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(field),
                BinaryPrimitives.ReadUInt32LittleEndian(word.AsSpan(field)) + 128);
        }
        BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(10), 0x0300);
        BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(14), 128);
        BinaryPrimitives.WriteUInt16LittleEndian(table, 4);
        BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2), 2);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(4), 4);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(8), 34);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(12), 4);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(20), 0x6801);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(24), 0x8004);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(28), keyBits);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(32), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(46), 16);
        var salt = Enumerable.Range(1, 16).Select(x => (byte)x).ToArray();
        salt.CopyTo(table, 50);
        var verifier = Enumerable.Range(20, 16).Select(x => (byte)x).ToArray();
        BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(82), 20);
        var check = verifier.Concat(SHA1.HashData(verifier)).ToArray();
        var seed = SHA1.HashData(salt.Concat(Encoding.Unicode.GetBytes("navigation-test")).ToArray());
        TestRc4(check, TestKey(seed, 0, keyBits));
        check.AsSpan(0, 16).CopyTo(table.AsSpan(66));
        check.AsSpan(16, 20).CopyTo(table.AsSpan(86));
        var wordPrefix = word.AsSpan(0, 68).ToArray();
        var tablePrefix = table.AsSpan(0, 128).ToArray();
        TestTransform(word, seed, keyBits);
        TestTransform(table, seed, keyBits);
        TestTransform(data, seed, keyBits);
        wordPrefix.CopyTo(word, 0);
        tablePrefix.CopyTo(table, 0);
        var output = new MemoryStream();
        using (var target = RootStorage.Create(output, OpenMcdf.Version.V3, StorageModeFlags.LeaveOpen))
        {
            using (var stream = target.CreateStream("WordDocument")) stream.Write(word);
            using (var stream = target.CreateStream("1Table")) stream.Write(table);
            using (var stream = target.CreateStream("Data")) stream.Write(data);
        }
        output.Position = 0;
        return output;
    }

    private static byte[] TestKey(byte[] seed, int block, uint keyBits)
    {
        var input = new byte[24];
        seed.CopyTo(input, 0);
        BinaryPrimitives.WriteInt32LittleEndian(input.AsSpan(20), block);
        var hash = SHA1.HashData(input);
        var key = new byte[16];
        Array.Copy(hash, key, keyBits == 40 ? 5 : 16);
        return key;
    }

    private static void TestTransform(byte[] bytes, byte[] seed, uint keyBits)
    {
        for (var offset = 0; offset < bytes.Length; offset += 512)
        {
            var block = bytes.AsSpan(offset, Math.Min(512, bytes.Length - offset)).ToArray();
            TestRc4(block, TestKey(seed, offset / 512, keyBits));
            block.CopyTo(bytes, offset);
        }
    }

    private static void TestRc4(byte[] bytes, byte[] key)
    {
        var state = Enumerable.Range(0, 256).Select(x => (byte)x).ToArray();
        var j = 0;
        for (var i = 0; i < 256; i++)
        {
            j = (j + state[i] + key[i % key.Length]) & 255;
            (state[i], state[j]) = (state[j], state[i]);
        }
        var a = 0;
        j = 0;
        for (var i = 0; i < bytes.Length; i++)
        {
            a = (a + 1) & 255;
            j = (j + state[a]) & 255;
            (state[a], state[j]) = (state[j], state[a]);
            bytes[i] ^= state[(state[a] + state[j]) & 255];
        }
    }

