    private static MemoryStream CreateDocWithStoryPlcs(bool badHeaderPlc = false,
        bool revisionStyle = false, bool revisionCharStyle = false,
        bool withPieceTable = false, bool compressedStoryPiece = false)
    {
        var output = new MemoryStream();
        using (var root = RootStorage.Create(output, OpenMcdf.Version.V3, StorageModeFlags.LeaveOpen))
        {
            var word = new byte[1500];
            BinaryPrimitives.WriteUInt16LittleEndian(word, 0xA5EC);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(2), 0x00C1);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(10), 0x0200);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(32), 14);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(62), 22);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(76), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(80), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(84), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(92), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(96), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(100), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(104), 4);
            BinaryPrimitives.WriteUInt16LittleEndian(word.AsSpan(152), 164);
            var entries = new[] { (1, 1000, revisionStyle || revisionCharStyle ? 80 : 70),
                (2, 400, 10), (3, 430, 12), (4, 540, 38),
                (8, 2000, 14), (9, 2020, 12), (82, 2040, 11),
                (96, 2060, 44), (98, 2110, 10), (132, 2130, 10),
                (137, 2200, 8), (138, 2220, 18), (139, 2250, 16),
                (141, 2280, 18), (142, 2310, 14), (143, 2340, 8),
                (144, 2360, 12),
                (5, 580, 12), (11, 460, 16), (31, 1200, 500), (40, 1120, 34),
                (52, 1900, 16), (53, 1920, 12), (71, 1940, 14), (72, 1960, 18),
                (15, 700, 7), (16, 710, 16), (21, 600, 16), (22, 630, 12), (23, 660, 8),
                (46, 490, 10), (47, 520, 12), (56, 850, 30), (58, 890, 30),
                (73, 750, 30), (74, 810, 24), (75, 930, 14), (76, 950, 14),
                (91, 1080, 6), (114, 1700, 20), (115, 1720, 14),
                (117, 1740, 12), (120, 1760, 28), (121, 1790, 14),
                (122, 1810, 12), (123, 1830, 10), (124, 1850, 12),
                (125, 1870, 8) };
            foreach (var (index, offset, length) in entries)
            {
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + index * 8), (uint)offset);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(158 + index * 8), (uint)length);
            }
            if (withPieceTable)
            {
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 33 * 8), 2380);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(158 + 33 * 8), 21);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 11 * 8), 2410);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(158 + 11 * 8), 56);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(154 + 6 * 8), 2470);
                BinaryPrimitives.WriteUInt32LittleEndian(word.AsSpan(158 + 6 * 8), 20);
                if (compressedStoryPiece)
                {
                    System.Text.Encoding.Latin1.GetBytes("Body").CopyTo(word, 1100);
                    System.Text.Encoding.Latin1.GetBytes("H\r\r").CopyTo(word, 1108);
                }
                else
                {
                    System.Text.Encoding.Unicode.GetBytes("Body").CopyTo(word, 1100);
                    System.Text.Encoding.Unicode.GetBytes("H\r\r").CopyTo(word, 1116);
                }
            }
            using (var stream = root.CreateStream("WordDocument")) stream.Write(word);
            var table = new byte[withPieceTable ? 2490 : 2400];
            if (withPieceTable)
            {
                table[2380] = 2;
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2381), 16);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2389), 29);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2395),
                    compressedStoryPiece ? 0x40000000u | 2200u : 1100u);
                for (var slot = 8; slot <= 12; slot++)
                    BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2410 + slot * 4), 3);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2474), 4);
                BinaryPrimitives.WriteInt32LittleEndian(table.AsSpan(2480), -1);
            }
            foreach (var offset in new[] { 400, 490 })
            {
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset), offset == 400 ? 1u : 2u);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 4), 4);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 8), 1);
            }
            foreach (var offset in new[] { 430, 520 })
            {
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset), 0);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 4), 3);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 8), 4);
            }
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(460), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(464), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(468), badHeaderPlc ? 5u : 3u);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(472), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(540), 3);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(544), 4);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(580), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(584), 3);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(588), 4);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(600), 0xFFFF);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(602), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(604), 0);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(606), 4);
            System.Text.Encoding.Unicode.GetBytes("Mark").CopyTo(table, 608);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(630), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(634), 5);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(638), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(660), 3);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(664), 5);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(700), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(702), 0);
            table[704] = 2;
            table[705] = 0xAA;
            table[706] = 0xBB;
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(710), 0);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(714), 2);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(718), 4);
            table[722] = 0x13;
            table[723] = 1;
            table[724] = 0x15;
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(750), 1);
            BinaryPrimitives.WriteInt32LittleEndian(table.AsSpan(752), 42);
            table[778] = 1;
            BinaryPrimitives.WriteInt32LittleEndian(table.AsSpan(810), 1);
            BinaryPrimitives.WriteInt32LittleEndian(table.AsSpan(814), 42);
            foreach (var offset in new[] { 850, 890, 930, 950 })
            {
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset), 0);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 4), 4);
            }
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1000), 18);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1002), 15);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1004), 10);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1048),
                revisionStyle || revisionCharStyle ? (ushort)30 : (ushort)20);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1052),
                revisionCharStyle ? (ushort)2 : (ushort)1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1054),
                revisionStyle ? (ushort)3 : (ushort)2);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1060), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1062), (ushort)'A');
            if (revisionStyle)
            {
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1070), 8);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1072), 6);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1078), 2);
            }
            if (revisionCharStyle)
            {
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1068), 10);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1070), 6);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1076), 2);
            }
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1080), 0xFFFF);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(1124), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(1128), 123);
            foreach (var offset in new[] { 1700, 1830 })
            {
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset), 0xFFFF);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 2), 1);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 6), 1);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 8), (ushort)'F');
            }
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1706), 6);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1760), 0xFFFF);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1762), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1766), 10);
            foreach (var offset in new[] { 1720, 1790, 1850 })
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 4), 1);
            foreach (var offset in new[] { 1740, 1810, 1870 })
            {
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset), 1);
                BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(offset + 4), 2);
            }
            foreach (var (offset, count, extra) in new[]
                { (1900, 1, 6), (1920, 1, 2), (1940, 2, 0), (1960, 1, 8) })
            {
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset), 0xFFFF);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 2), (ushort)count);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 4), (ushort)extra);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 6), 1);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 8), (ushort)'F');
            }
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1944), 0);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1950), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(1952), (ushort)'G');
            foreach (var (offset, extra) in new[] { (2000, 4), (2040, 1) })
            {
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset), 0xFFFF);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 2), 1);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 4), (ushort)extra);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 6), 1);
                BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(offset + 8), (ushort)'G');
            }
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2024), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2028), 2);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2060), 0xFFFF);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2062), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2066), 18);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2114), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2134), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2200), 0xFFFF);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2224), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2250), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2254), 2);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2280), 0xFFFF);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2282), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2286), 8);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2314), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2340), 1);
            BinaryPrimitives.WriteUInt32LittleEndian(table.AsSpan(2344), 2);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2360), 0xFFFF);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2362), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2364), 2);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2366), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(table.AsSpan(2368), (ushort)'U');
            using (var stream = root.CreateStream("1Table")) stream.Write(table);
        }
        output.Position = 0;
        return output;
    }
}
